export const dkSentences: Sentence[] = [
  {"id":"s_dk_1","chapterId":"ch_work_dk_1","textTraditional":"乾：元亨，利貞。","textSimplified":"乾：元亨，利贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_2","chapterId":"ch_work_dk_1","textTraditional":"大哉乾元，萬物資始，乃統天。雲行雨施，品物流形。大明始終，六位時成，時乘六龍以御天。乾道变化，各正性命，保合大和，乃利貞。首出庶物，萬國鹹寧。","textSimplified":"大哉乾元，万物资始，乃统天。云行雨施，品物流形。大明始终，六位时成，时乘六龙以御天。乾道变化，各正性命，保合大和，乃利贞。首出庶物，万国咸宁。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_3","chapterId":"ch_work_dk_1","textTraditional":"天行健，君子以自強不息。","textSimplified":"天行健，君子以自强不息。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_4","chapterId":"ch_work_dk_1","textTraditional":"初九：潛龍，勿用。","textSimplified":"初九：潜龙，勿用。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_5","chapterId":"ch_work_dk_1","textTraditional":"九二：見龍在田，利見大人。","textSimplified":"九二：见龙在田，利见大人。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_6","chapterId":"ch_work_dk_1","textTraditional":"九三：君子終日乾乾，夕惕若，厲，無咎。","textSimplified":"九三：君子终日乾乾，夕惕若，厉，无咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_7","chapterId":"ch_work_dk_1","textTraditional":"九四：或躍在淵，無咎。","textSimplified":"九四：或跃在渊，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_8","chapterId":"ch_work_dk_1","textTraditional":"九五：飛龍在天，利見大人。","textSimplified":"九五：飞龙在天，利见大人。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_9","chapterId":"ch_work_dk_1","textTraditional":"上九：亢龍有悔。","textSimplified":"上九：亢龙有悔。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_10","chapterId":"ch_work_dk_1","textTraditional":"用九：見群龍無首，吉。","textSimplified":"用九：见群龙无首，吉。","sentenceOrder":10,"paragraphGroup":4},
  {"id":"s_dk_11","chapterId":"ch_work_dk_1","textTraditional":"潛龍勿用，陽在下也。","textSimplified":"潜龙勿用，阳在下也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_12","chapterId":"ch_work_dk_1","textTraditional":"見龍在田，德施普也。","textSimplified":"见龙在田，德施普也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_13","chapterId":"ch_work_dk_1","textTraditional":"終日乾乾，反复道也。","textSimplified":"终日乾乾，反复道也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_14","chapterId":"ch_work_dk_1","textTraditional":"或躍在淵，進無咎也。","textSimplified":"或跃在渊，进无咎也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_15","chapterId":"ch_work_dk_1","textTraditional":"飛龍在天，大人造也。","textSimplified":"飞龙在天，大人造也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_16","chapterId":"ch_work_dk_1","textTraditional":"亢龍有悔，盈不可久也。","textSimplified":"亢龙有悔，盈不可久也。","sentenceOrder":16,"paragraphGroup":5},
  {"id":"s_dk_17","chapterId":"ch_work_dk_1","textTraditional":"用九，天德不可為首也。","textSimplified":"用九，天德不可为首也。","sentenceOrder":17,"paragraphGroup":5},
  {"id":"s_dk_18","chapterId":"ch_work_dk_2","textTraditional":"坤：元亨，利牝馬之貞。君子有攸往，先迷後得主，利西南得朋，東北丧朋。安貞，吉。","textSimplified":"坤：元亨，利牝马之贞。君子有攸往，先迷后得主，利西南得朋，东北丧朋。安贞，吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_19","chapterId":"ch_work_dk_2","textTraditional":"至哉坤元，萬物資生，乃順承天。坤厚載物，德合無疆。含弘光大，品物鹹亨。牝馬地類，行地無疆，柔順利貞。君子攸行，先迷失道，後順得常。西南得朋，乃與類行；東北丧朋，乃終有慶。安貞之吉，應地無疆。","textSimplified":"至哉坤元，万物资生，乃顺承天。坤厚载物，德合无疆。含弘光大，品物咸亨。牝马地类，行地无疆，柔顺利贞。君子攸行，先迷失道，后顺得常。西南得朋，乃与类行；东北丧朋，乃终有庆。安贞之吉，应地无疆。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_20","chapterId":"ch_work_dk_2","textTraditional":"地势坤，君子以厚德載物。","textSimplified":"地势坤，君子以厚德载物。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_21","chapterId":"ch_work_dk_2","textTraditional":"初六：履霜，堅冰至。","textSimplified":"初六：履霜，坚冰至。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_22","chapterId":"ch_work_dk_2","textTraditional":"六二：直，方，大，不習無不利。","textSimplified":"六二：直，方，大，不习无不利。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_23","chapterId":"ch_work_dk_2","textTraditional":"六三：含章可貞。或從王事，無成有終。","textSimplified":"六三：含章可贞。或从王事，无成有终。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_24","chapterId":"ch_work_dk_2","textTraditional":"六四：括囊；無咎，無譽。","textSimplified":"六四：括囊；无咎，无誉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_25","chapterId":"ch_work_dk_2","textTraditional":"六五：黃裳，元吉。","textSimplified":"六五：黄裳，元吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_26","chapterId":"ch_work_dk_2","textTraditional":"上六：龍戰於野，其血玄黃。","textSimplified":"上六：龙战于野，其血玄黄。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_27","chapterId":"ch_work_dk_2","textTraditional":"用六：利永貞。","textSimplified":"用六：利永贞。","sentenceOrder":10,"paragraphGroup":4},
  {"id":"s_dk_28","chapterId":"ch_work_dk_2","textTraditional":"履霜堅冰，陰始凝也。馴致其道，至堅冰也。","textSimplified":"履霜坚冰，阴始凝也。驯致其道，至坚冰也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_29","chapterId":"ch_work_dk_2","textTraditional":"六二之動，直以方也。不習無不利，地道光也。","textSimplified":"六二之动，直以方也。不习无不利，地道光也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_30","chapterId":"ch_work_dk_2","textTraditional":"含章可貞；以時發也。或從王事，知光大也","textSimplified":"含章可贞；以时发也。或从王事，知光大也","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_31","chapterId":"ch_work_dk_2","textTraditional":"括囊無咎，慎不害也。","textSimplified":"括囊无咎，慎不害也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_32","chapterId":"ch_work_dk_2","textTraditional":"黃裳元吉，文在中也。","textSimplified":"黄裳元吉，文在中也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_33","chapterId":"ch_work_dk_2","textTraditional":"戰龍於野，其道窮也。","textSimplified":"战龙于野，其道穷也。","sentenceOrder":16,"paragraphGroup":5},
  {"id":"s_dk_34","chapterId":"ch_work_dk_2","textTraditional":"用六永貞，以大終也。","textSimplified":"用六永贞，以大终也。","sentenceOrder":17,"paragraphGroup":5},
  {"id":"s_dk_35","chapterId":"ch_work_dk_3","textTraditional":"元亨，利貞，勿用有攸往，利建侯。","textSimplified":"元亨，利贞，勿用有攸往，利建侯。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_36","chapterId":"ch_work_dk_3","textTraditional":"屯，刚柔始交而難生，動乎险中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。","textSimplified":"屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_37","chapterId":"ch_work_dk_3","textTraditional":"雲，雷，屯；君子以經纶。","textSimplified":"云，雷，屯；君子以经纶。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_38","chapterId":"ch_work_dk_3","textTraditional":"初九：磐桓；利居貞，利建侯。","textSimplified":"初九：磐桓；利居贞，利建侯。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_39","chapterId":"ch_work_dk_3","textTraditional":"六二：屯如邅如，乘馬班如。匪寇婚媾，女子貞不字，十年乃字。","textSimplified":"六二：屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_40","chapterId":"ch_work_dk_3","textTraditional":"六三：即鹿無虞，惟入於林中，君子幾不如舍，往吝。","textSimplified":"六三：即鹿无虞，惟入于林中，君子几不如舍，往吝。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_41","chapterId":"ch_work_dk_3","textTraditional":"六四：乘馬班如，求婚媾，往吉，無不利。","textSimplified":"六四：乘马班如，求婚媾，往吉，无不利。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_42","chapterId":"ch_work_dk_3","textTraditional":"九五：屯其膏，小貞吉，大貞凶。","textSimplified":"九五：屯其膏，小贞吉，大贞凶。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_43","chapterId":"ch_work_dk_3","textTraditional":"上六：乘馬班如，泣血涟如。","textSimplified":"上六：乘马班如，泣血涟如。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_44","chapterId":"ch_work_dk_3","textTraditional":"雖磐桓，志行正也。以貴下賤，大得民也。","textSimplified":"虽磐桓，志行正也。以贵下贱，大得民也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_45","chapterId":"ch_work_dk_3","textTraditional":"六二之難，乘刚也。十年乃字，反常也。","textSimplified":"六二之难，乘刚也。十年乃字，反常也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_46","chapterId":"ch_work_dk_3","textTraditional":"即鹿無虞，以縱禽也。君子舍之，往吝窮也。","textSimplified":"即鹿无虞，以纵禽也。君子舍之，往吝穷也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_47","chapterId":"ch_work_dk_3","textTraditional":"求而往，明也。","textSimplified":"求而往，明也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_48","chapterId":"ch_work_dk_3","textTraditional":"屯其膏，施未光也。","textSimplified":"屯其膏，施未光也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_49","chapterId":"ch_work_dk_3","textTraditional":"泣血涟如，何可長也。","textSimplified":"泣血涟如，何可长也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_50","chapterId":"ch_work_dk_4","textTraditional":"蒙：亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎則不告。利貞。","textSimplified":"蒙：亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_51","chapterId":"ch_work_dk_4","textTraditional":"蒙，山下有险，险而止，蒙。蒙亨，以亨行時中也。匪我求童蒙，童蒙求我，志應也。初噬告，以刚中也。再三渎，渎則不告，渎蒙也。蒙以養正，聖功也。","textSimplified":"蒙，山下有险，险而止，蒙。蒙亨，以亨行时中也。匪我求童蒙，童蒙求我，志应也。初噬告，以刚中也。再三渎，渎则不告，渎蒙也。蒙以养正，圣功也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_52","chapterId":"ch_work_dk_4","textTraditional":"山下出泉，蒙；君子以果行育德。","textSimplified":"山下出泉，蒙；君子以果行育德。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_53","chapterId":"ch_work_dk_4","textTraditional":"初六：發蒙，利用刑人，用說桎梏，以往吝。","textSimplified":"初六：发蒙，利用刑人，用说桎梏，以往吝。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_54","chapterId":"ch_work_dk_4","textTraditional":"九二：包蒙吉；納婦吉；子克家。","textSimplified":"九二：包蒙吉；纳妇吉；子克家。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_55","chapterId":"ch_work_dk_4","textTraditional":"六三：勿用娶女；見金夫，不有躬，無攸利。","textSimplified":"六三：勿用娶女；见金夫，不有躬，无攸利。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_56","chapterId":"ch_work_dk_4","textTraditional":"六四：困蒙，吝。","textSimplified":"六四：困蒙，吝。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_57","chapterId":"ch_work_dk_4","textTraditional":"六五：童蒙，吉。","textSimplified":"六五：童蒙，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_58","chapterId":"ch_work_dk_4","textTraditional":"上九：击蒙；不利為寇，利御寇。","textSimplified":"上九：击蒙；不利为寇，利御寇。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_59","chapterId":"ch_work_dk_4","textTraditional":"利用刑人，以正法也。","textSimplified":"利用刑人，以正法也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_60","chapterId":"ch_work_dk_4","textTraditional":"子克家，刚柔接也。","textSimplified":"子克家，刚柔接也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_61","chapterId":"ch_work_dk_4","textTraditional":"勿用娶女，行不順也。","textSimplified":"勿用娶女，行不顺也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_62","chapterId":"ch_work_dk_4","textTraditional":"困蒙之吝，獨遠實也。","textSimplified":"困蒙之吝，独远实也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_63","chapterId":"ch_work_dk_4","textTraditional":"童蒙之吉，順以巽也。","textSimplified":"童蒙之吉，顺以巽也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_64","chapterId":"ch_work_dk_4","textTraditional":"利用御寇，上下順也。","textSimplified":"利用御寇，上下顺也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_65","chapterId":"ch_work_dk_5","textTraditional":"需：有孚，光亨，貞吉。利涉大川。","textSimplified":"需：有孚，光亨，贞吉。利涉大川。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_66","chapterId":"ch_work_dk_5","textTraditional":"需，須也；险在前也。刚健而不陷，其義不困窮矣。需有孚，光亨，貞吉。位乎天位，以正中也。利涉大川，往有功也。","textSimplified":"需，须也；险在前也。刚健而不陷，其义不困穷矣。需有孚，光亨，贞吉。位乎天位，以正中也。利涉大川，往有功也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_67","chapterId":"ch_work_dk_5","textTraditional":"雲上於天，需；君子以飲食宴樂。","textSimplified":"云上于天，需；君子以饮食宴乐。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_68","chapterId":"ch_work_dk_5","textTraditional":"初九：需於郊。利用恒，無咎。","textSimplified":"初九：需于郊。利用恒，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_69","chapterId":"ch_work_dk_5","textTraditional":"九二：需於沙。小有言，終吉。","textSimplified":"九二：需于沙。小有言，终吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_70","chapterId":"ch_work_dk_5","textTraditional":"九三：需於泥，致寇至。","textSimplified":"九三：需于泥，致寇至。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_71","chapterId":"ch_work_dk_5","textTraditional":"六四：需於血，出自穴。","textSimplified":"六四：需于血，出自穴。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_72","chapterId":"ch_work_dk_5","textTraditional":"九五：需於酒食，貞吉。","textSimplified":"九五：需于酒食，贞吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_73","chapterId":"ch_work_dk_5","textTraditional":"上六：入於穴，有不速之客三人來，敬之終吉。","textSimplified":"上六：入于穴，有不速之客三人来，敬之终吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_74","chapterId":"ch_work_dk_5","textTraditional":"需於郊，不犯難行也。利用恒，無咎；未失常也。","textSimplified":"需于郊，不犯难行也。利用恒，无咎；未失常也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_75","chapterId":"ch_work_dk_5","textTraditional":"需於沙，衍在中也。雖小有言，以終吉也。","textSimplified":"需于沙，衍在中也。虽小有言，以终吉也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_76","chapterId":"ch_work_dk_5","textTraditional":"需於泥，灾在外也。自我致寇，敬慎不败也。","textSimplified":"需于泥，灾在外也。自我致寇，敬慎不败也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_77","chapterId":"ch_work_dk_5","textTraditional":"需於血，順以聽也。","textSimplified":"需于血，顺以听也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_78","chapterId":"ch_work_dk_5","textTraditional":"酒食貞吉，以中正也。","textSimplified":"酒食贞吉，以中正也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_79","chapterId":"ch_work_dk_5","textTraditional":"不速之客來，敬之終吉。雖不當位，未大失也。","textSimplified":"不速之客来，敬之终吉。虽不当位，未大失也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_80","chapterId":"ch_work_dk_6","textTraditional":"訟：有孚，窒。惕中吉。終凶。利見大人，不利涉大川。","textSimplified":"讼：有孚，窒。惕中吉。终凶。利见大人，不利涉大川。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_81","chapterId":"ch_work_dk_6","textTraditional":"訟，上刚下险，险而健訟。訟有孚窒，惕中吉，刚來而得中也。終凶；訟不可成也。利見大人；尚中正也。不利涉大川；入於淵也。","textSimplified":"讼，上刚下险，险而健讼。讼有孚窒，惕中吉，刚来而得中也。终凶；讼不可成也。利见大人；尚中正也。不利涉大川；入于渊也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_82","chapterId":"ch_work_dk_6","textTraditional":"天與水违行，訟；君子以作事謀始。","textSimplified":"天与水违行，讼；君子以作事谋始。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_83","chapterId":"ch_work_dk_6","textTraditional":"初六：不永所事，小有言，終吉。","textSimplified":"初六：不永所事，小有言，终吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_84","chapterId":"ch_work_dk_6","textTraditional":"九二：不克訟，歸而逋，其邑人三百戶，無眚。","textSimplified":"九二：不克讼，归而逋，其邑人三百户，无眚。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_85","chapterId":"ch_work_dk_6","textTraditional":"六三：食舊德，貞厲，終吉，或從王事，無成。","textSimplified":"六三：食旧德，贞厉，终吉，或从王事，无成。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_86","chapterId":"ch_work_dk_6","textTraditional":"九四：不克訟，复即命渝，安貞吉。","textSimplified":"九四：不克讼，复即命渝，安贞吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_87","chapterId":"ch_work_dk_6","textTraditional":"九五：訟元吉。","textSimplified":"九五：讼元吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_88","chapterId":"ch_work_dk_6","textTraditional":"上九：或錫之鞶帶，終朝三褫之。","textSimplified":"上九：或锡之鞶带，终朝三褫之。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_89","chapterId":"ch_work_dk_6","textTraditional":"不永所事，訟不可長也。雖有小言，其辯明也。","textSimplified":"不永所事，讼不可长也。虽有小言，其辩明也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_90","chapterId":"ch_work_dk_6","textTraditional":"不克訟，歸而逋也。自下訟上，患至掇也。","textSimplified":"不克讼，归而逋也。自下讼上，患至掇也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_91","chapterId":"ch_work_dk_6","textTraditional":"食舊德，從上吉也。","textSimplified":"食旧德，从上吉也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_92","chapterId":"ch_work_dk_6","textTraditional":"复即命，渝安貞；不失也。","textSimplified":"复即命，渝安贞；不失也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_93","chapterId":"ch_work_dk_6","textTraditional":"訟元吉，以中正也。","textSimplified":"讼元吉，以中正也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_94","chapterId":"ch_work_dk_6","textTraditional":"以訟受服，亦不足敬也。","textSimplified":"以讼受服，亦不足敬也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_95","chapterId":"ch_work_dk_7","textTraditional":"貞，丈人，吉無咎。","textSimplified":"贞，丈人，吉无咎。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_96","chapterId":"ch_work_dk_7","textTraditional":"師，眾也，貞正也，能以眾正，可以王矣。刚中而應，行险而順，以此毒天下，而民從之，吉又何咎矣。","textSimplified":"师，众也，贞正也，能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，吉又何咎矣。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_97","chapterId":"ch_work_dk_7","textTraditional":"地中有水，師；君子以容民畜眾。","textSimplified":"地中有水，师；君子以容民畜众。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_98","chapterId":"ch_work_dk_7","textTraditional":"初六：師出以律，否臧凶。","textSimplified":"初六：师出以律，否臧凶。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_99","chapterId":"ch_work_dk_7","textTraditional":"九二：在師中吉，無咎，王三錫命。","textSimplified":"九二：在师中吉，无咎，王三锡命。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_100","chapterId":"ch_work_dk_7","textTraditional":"六三：師或舆尸，凶。","textSimplified":"六三：师或舆尸，凶。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_101","chapterId":"ch_work_dk_7","textTraditional":"六四：師左次，無咎。","textSimplified":"六四：师左次，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_102","chapterId":"ch_work_dk_7","textTraditional":"六五：田有禽，利執言，無咎。長子帥師，弟子舆尸，貞凶。","textSimplified":"六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_103","chapterId":"ch_work_dk_7","textTraditional":"上六：大君有命，开國承家，小人勿用。","textSimplified":"上六：大君有命，开国承家，小人勿用。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_104","chapterId":"ch_work_dk_7","textTraditional":"師出以律，失律凶也。","textSimplified":"师出以律，失律凶也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_105","chapterId":"ch_work_dk_7","textTraditional":"在師中吉，承天寵也。王三錫命，懷萬邦也。","textSimplified":"在师中吉，承天宠也。王三锡命，怀万邦也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_106","chapterId":"ch_work_dk_7","textTraditional":"師或舆尸，大無功也。","textSimplified":"师或舆尸，大无功也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_107","chapterId":"ch_work_dk_7","textTraditional":"左次無咎，未失常也。","textSimplified":"左次无咎，未失常也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_108","chapterId":"ch_work_dk_7","textTraditional":"長子帥師，以中行也。弟子舆尸，使不當也。","textSimplified":"长子帅师，以中行也。弟子舆尸，使不当也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_109","chapterId":"ch_work_dk_7","textTraditional":"大君有命，以正功也。小人勿用，必亂邦也。","textSimplified":"大君有命，以正功也。小人勿用，必乱邦也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_110","chapterId":"ch_work_dk_8","textTraditional":"吉。原筮元永貞，無咎。不寧方來，後夫凶。","textSimplified":"吉。原筮元永贞，无咎。不宁方来，后夫凶。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_111","chapterId":"ch_work_dk_8","textTraditional":"比，吉也，比，辅也，下順從也。原筮元永貞，無咎，以刚中也。不寧方來，上下應也。後夫凶，其道窮也。","textSimplified":"比，吉也，比，辅也，下顺从也。原筮元永贞，无咎，以刚中也。不宁方来，上下应也。后夫凶，其道穷也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_112","chapterId":"ch_work_dk_8","textTraditional":"地上有水，比；先王以建萬國，親諸侯。","textSimplified":"地上有水，比；先王以建万国，亲诸侯。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_113","chapterId":"ch_work_dk_8","textTraditional":"初六：有孚，比之，無咎。有孚盈缶，終來有他，吉。","textSimplified":"初六：有孚，比之，无咎。有孚盈缶，终来有他，吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_114","chapterId":"ch_work_dk_8","textTraditional":"六二：比之自內，貞吉。","textSimplified":"六二：比之自内，贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_115","chapterId":"ch_work_dk_8","textTraditional":"六三：比之匪人。","textSimplified":"六三：比之匪人。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_116","chapterId":"ch_work_dk_8","textTraditional":"六四：外比之，貞吉。","textSimplified":"六四：外比之，贞吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_117","chapterId":"ch_work_dk_8","textTraditional":"九五：顯比，王用三驅，失前禽。邑人不誡，吉。","textSimplified":"九五：显比，王用三驱，失前禽。邑人不诫，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_118","chapterId":"ch_work_dk_8","textTraditional":"上六：比之無首，凶。","textSimplified":"上六：比之无首，凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_119","chapterId":"ch_work_dk_8","textTraditional":"比之初六，有他吉也。","textSimplified":"比之初六，有他吉也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_120","chapterId":"ch_work_dk_8","textTraditional":"比之自內，不自失也。","textSimplified":"比之自内，不自失也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_121","chapterId":"ch_work_dk_8","textTraditional":"比之匪人，不亦傷乎！","textSimplified":"比之匪人，不亦伤乎！","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_122","chapterId":"ch_work_dk_8","textTraditional":"外比於賢，以從上也。","textSimplified":"外比于贤，以从上也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_123","chapterId":"ch_work_dk_8","textTraditional":"顯比之吉，位正中也。舍逆取順，失前禽也。邑人不誡，上使中也。","textSimplified":"显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_124","chapterId":"ch_work_dk_8","textTraditional":"比之無首，無所終也。","textSimplified":"比之无首，无所终也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_125","chapterId":"ch_work_dk_9","textTraditional":"小畜：亨。密雲不雨，自我西郊。","textSimplified":"小畜：亨。密云不雨，自我西郊。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_126","chapterId":"ch_work_dk_9","textTraditional":"小畜；柔得位，而上下應之，曰小畜。健而巽，刚中而志行，乃亨。密雲不雨，尚往也。自我西郊，施未行也。","textSimplified":"小畜；柔得位，而上下应之，曰小畜。健而巽，刚中而志行，乃亨。密云不雨，尚往也。自我西郊，施未行也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_127","chapterId":"ch_work_dk_9","textTraditional":"風行天上，小畜；君子以懿文德。","textSimplified":"风行天上，小畜；君子以懿文德。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_128","chapterId":"ch_work_dk_9","textTraditional":"初九：复自道，何其咎，吉。","textSimplified":"初九：复自道，何其咎，吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_129","chapterId":"ch_work_dk_9","textTraditional":"九二：牵复，吉。","textSimplified":"九二：牵复，吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_130","chapterId":"ch_work_dk_9","textTraditional":"九三：舆說輻，夫妻反目。","textSimplified":"九三：舆说辐，夫妻反目。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_131","chapterId":"ch_work_dk_9","textTraditional":"六四：有孚，血去惕出，無咎。","textSimplified":"六四：有孚，血去惕出，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_132","chapterId":"ch_work_dk_9","textTraditional":"九五：有孚挛如，富以其鄰。","textSimplified":"九五：有孚挛如，富以其邻。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_133","chapterId":"ch_work_dk_9","textTraditional":"上九：既雨既處，尚德載，婦貞厲。月幾望，君子征凶。","textSimplified":"上九：既雨既处，尚德载，妇贞厉。月几望，君子征凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_134","chapterId":"ch_work_dk_9","textTraditional":"复自道，其義吉也。","textSimplified":"复自道，其义吉也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_135","chapterId":"ch_work_dk_9","textTraditional":"牵复在中，亦不自失也。","textSimplified":"牵复在中，亦不自失也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_136","chapterId":"ch_work_dk_9","textTraditional":"夫妻反目，不能正室也。","textSimplified":"夫妻反目，不能正室也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_137","chapterId":"ch_work_dk_9","textTraditional":"有孚惕出，上合志也。","textSimplified":"有孚惕出，上合志也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_138","chapterId":"ch_work_dk_9","textTraditional":"有孚挛如，不獨富也。","textSimplified":"有孚挛如，不独富也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_139","chapterId":"ch_work_dk_9","textTraditional":"既雨既處，德積載也。君子征凶，有所疑也。","textSimplified":"既雨既处，德积载也。君子征凶，有所疑也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_140","chapterId":"ch_work_dk_10","textTraditional":"履虎尾，不咥人，亨。","textSimplified":"履虎尾，不咥人，亨。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_141","chapterId":"ch_work_dk_10","textTraditional":"履，柔履刚也。說而應乎乾，是以履虎尾，不咥人，亨。刚中正，履帝位而不疚，光明也。","textSimplified":"履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。刚中正，履帝位而不疚，光明也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_142","chapterId":"ch_work_dk_10","textTraditional":"上天下泽，履；君子以辨上下，安民志。","textSimplified":"上天下泽，履；君子以辨上下，安民志。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_143","chapterId":"ch_work_dk_10","textTraditional":"初九：素履，往無咎。","textSimplified":"初九：素履，往无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_144","chapterId":"ch_work_dk_10","textTraditional":"九二：履道坦坦，幽人貞吉。","textSimplified":"九二：履道坦坦，幽人贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_145","chapterId":"ch_work_dk_10","textTraditional":"六三：眇能视，跛能履，履虎尾，咥人，凶。武人為於大君。","textSimplified":"六三：眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_146","chapterId":"ch_work_dk_10","textTraditional":"九四：履虎尾，訴訴，終吉。","textSimplified":"九四：履虎尾，诉诉，终吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_147","chapterId":"ch_work_dk_10","textTraditional":"九五：夬履，貞厲。","textSimplified":"九五：夬履，贞厉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_148","chapterId":"ch_work_dk_10","textTraditional":"上九：视履考祥，其旋元吉。","textSimplified":"上九：视履考祥，其旋元吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_149","chapterId":"ch_work_dk_10","textTraditional":"素履之往，獨行願也。","textSimplified":"素履之往，独行愿也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_150","chapterId":"ch_work_dk_10","textTraditional":"幽人貞吉，中不自亂也。","textSimplified":"幽人贞吉，中不自乱也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_151","chapterId":"ch_work_dk_10","textTraditional":"眇能视；不足以有明也。跛能履；不足以與行也，咥人之凶；位不當也。武人為於大君；志刚也。","textSimplified":"眇能视；不足以有明也。跛能履；不足以与行也，咥人之凶；位不当也。武人为于大君；志刚也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_152","chapterId":"ch_work_dk_10","textTraditional":"訴訴終吉，志行也。","textSimplified":"诉诉终吉，志行也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_153","chapterId":"ch_work_dk_10","textTraditional":"夬履貞厲，位正當也。","textSimplified":"夬履贞厉，位正当也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_154","chapterId":"ch_work_dk_10","textTraditional":"元吉在上，大有慶也。","textSimplified":"元吉在上，大有庆也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_155","chapterId":"ch_work_dk_11","textTraditional":"泰：小往大來，吉亨。","textSimplified":"泰：小往大來，吉亨。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_156","chapterId":"ch_work_dk_11","textTraditional":"泰，小往大來，吉亨。則是天地交，而萬物通也；上下交，而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。","textSimplified":"泰，小往大來，吉亨。則是天地交，而萬物通也；上下交，而其志同也。內陽而外陰，內健而外順，內君子而外小人，君子道長，小人道消也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_157","chapterId":"ch_work_dk_11","textTraditional":"天地交泰，後以財成天地之道，輔相天地之宜，以左右民。","textSimplified":"天地交泰，后以財成天地之道，輔相天地之宜，以左右民。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_158","chapterId":"ch_work_dk_11","textTraditional":"初九：拔茅茹，以其彙，征吉。","textSimplified":"初九：拔茅茹，以其彙，征吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_159","chapterId":"ch_work_dk_11","textTraditional":"九二：包荒，用馮河，不遐遺，朋亡，得尚於中行。","textSimplified":"九二：包荒，用馮河，不遐遺，朋亡，得尚于中行。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_160","chapterId":"ch_work_dk_11","textTraditional":"九三：無平不陂，無往不復，艱貞無咎。勿恤其孚，於食有福。","textSimplified":"九三：无平不陂，无往不復，艱貞无咎。勿恤其孚，于食有福。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_161","chapterId":"ch_work_dk_11","textTraditional":"六四：翩翩，不富，以其鄰，不戒以孚。","textSimplified":"六四：翩翩，不富，以其鄰，不戒以孚。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_162","chapterId":"ch_work_dk_11","textTraditional":"六五：帝乙歸妹，以祉元吉。","textSimplified":"六五：帝乙歸妹，以祉元吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_163","chapterId":"ch_work_dk_11","textTraditional":"上六：城復於隍，勿用師。自邑告命，貞吝。","textSimplified":"上六：城復于隍，勿用師。自邑告命，貞吝。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_164","chapterId":"ch_work_dk_11","textTraditional":"拔茅征吉，志在外也。","textSimplified":"拔茅征吉，志在外也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_165","chapterId":"ch_work_dk_11","textTraditional":"包荒，得尚於中行，以光大也。","textSimplified":"包荒，得尚于中行，以光大也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_166","chapterId":"ch_work_dk_11","textTraditional":"無往不復，天地際也。","textSimplified":"无往不復，天地際也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_167","chapterId":"ch_work_dk_11","textTraditional":"翩翩不富，皆失實也。不戒以孚，中心願也。","textSimplified":"翩翩不富，皆失實也。不戒以孚，中心願也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_168","chapterId":"ch_work_dk_11","textTraditional":"以祉元吉，中以行願也。","textSimplified":"以祉元吉，中以行愿也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_169","chapterId":"ch_work_dk_11","textTraditional":"城復於隍，其命亂也。","textSimplified":"城復于隍，其命亂也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_170","chapterId":"ch_work_dk_12","textTraditional":"否之匪人，不利君子貞，大往小來。","textSimplified":"否之匪人，不利君子贞，大往小来。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_171","chapterId":"ch_work_dk_12","textTraditional":"否之匪人，不利君子貞。大往小來，則是天地不交，而萬物不通也；上下不交，而天下無邦也。內陰而外陽，內柔而外刚，內小人而外君子。小人道長，君子道消也。","textSimplified":"否之匪人，不利君子贞。大往小来，则是天地不交，而万物不通也；上下不交，而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子。小人道长，君子道消也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_172","chapterId":"ch_work_dk_12","textTraditional":"天地不交，否；君子以俭德辟難，不可榮以祿。","textSimplified":"天地不交，否；君子以俭德辟难，不可荣以禄。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_173","chapterId":"ch_work_dk_12","textTraditional":"初六：拔茅茹，以其匯，貞吉亨。","textSimplified":"初六：拔茅茹，以其汇，贞吉亨。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_174","chapterId":"ch_work_dk_12","textTraditional":"六二：包承。小人吉，大人否，亨。","textSimplified":"六二：包承。小人吉，大人否，亨。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_175","chapterId":"ch_work_dk_12","textTraditional":"六三：包羞。","textSimplified":"六三：包羞。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_176","chapterId":"ch_work_dk_12","textTraditional":"九四：有命，無咎，畴離祉。","textSimplified":"九四：有命，无咎，畴离祉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_177","chapterId":"ch_work_dk_12","textTraditional":"九五：休否，大人吉。其亡其亡，系於苞桑。","textSimplified":"九五：休否，大人吉。其亡其亡，系于苞桑。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_178","chapterId":"ch_work_dk_12","textTraditional":"上九：傾否，先否後喜。","textSimplified":"上九：倾否，先否后喜。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_179","chapterId":"ch_work_dk_12","textTraditional":"拔茅貞吉，志在君也。","textSimplified":"拔茅贞吉，志在君也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_180","chapterId":"ch_work_dk_12","textTraditional":"大人否亨，不亂群也。","textSimplified":"大人否亨，不乱群也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_181","chapterId":"ch_work_dk_12","textTraditional":"包羞，位不當也。","textSimplified":"包羞，位不当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_182","chapterId":"ch_work_dk_12","textTraditional":"有命無咎，志行也。","textSimplified":"有命无咎，志行也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_183","chapterId":"ch_work_dk_12","textTraditional":"大人之吉，位正當也。","textSimplified":"大人之吉，位正当也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_184","chapterId":"ch_work_dk_12","textTraditional":"否終則傾，何可長也。","textSimplified":"否终则倾，何可长也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_185","chapterId":"ch_work_dk_13","textTraditional":"同人於野，亨。利涉大川，利君子貞。","textSimplified":"同人于野，亨。利涉大川，利君子贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_186","chapterId":"ch_work_dk_13","textTraditional":"同人，柔得位得中，而應乎乾，曰同人。同人曰，同人於野，亨。利涉大川，乾行也。文明以健，中正而應，君子正也。唯君子為能通天下之志。","textSimplified":"同人，柔得位得中，而应乎乾，曰同人。同人曰，同人于野，亨。利涉大川，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_187","chapterId":"ch_work_dk_13","textTraditional":"天與火，同人；君子以類族辨物。","textSimplified":"天与火，同人；君子以类族辨物。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_188","chapterId":"ch_work_dk_13","textTraditional":"初九：同人於門，無咎。","textSimplified":"初九：同人于门，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_189","chapterId":"ch_work_dk_13","textTraditional":"六二：同人於宗，吝。","textSimplified":"六二：同人于宗，吝。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_190","chapterId":"ch_work_dk_13","textTraditional":"九三：伏戎於莽，升其高陵，三歲不興。","textSimplified":"九三：伏戎于莽，升其高陵，三岁不兴。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_191","chapterId":"ch_work_dk_13","textTraditional":"九四：乘其墉，弗克攻，吉。","textSimplified":"九四：乘其墉，弗克攻，吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_192","chapterId":"ch_work_dk_13","textTraditional":"九五：同人，先號啕而後笑。大師克相遇。","textSimplified":"九五：同人，先号啕而后笑。大师克相遇。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_193","chapterId":"ch_work_dk_13","textTraditional":"上九：同人於郊，無悔。","textSimplified":"上九：同人于郊，无悔。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_194","chapterId":"ch_work_dk_13","textTraditional":"出門同人，又誰咎也。","textSimplified":"出门同人，又谁咎也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_195","chapterId":"ch_work_dk_13","textTraditional":"同人於宗，吝道也。","textSimplified":"同人于宗，吝道也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_196","chapterId":"ch_work_dk_13","textTraditional":"伏戎於莽，敵刚也。三歲不興，安行也。","textSimplified":"伏戎于莽，敌刚也。三岁不兴，安行也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_197","chapterId":"ch_work_dk_13","textTraditional":"乘其墉，義弗克也，其吉，則困而反則也。  ","textSimplified":"乘其墉，义弗克也，其吉，则困而反则也。  ","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_198","chapterId":"ch_work_dk_13","textTraditional":"同人之先，以中直也。大師相遇，言相克也。","textSimplified":"同人之先，以中直也。大师相遇，言相克也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_199","chapterId":"ch_work_dk_13","textTraditional":"同人於郊，志未得也。","textSimplified":"同人于郊，志未得也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_200","chapterId":"ch_work_dk_14","textTraditional":"大有：元亨。","textSimplified":"大有：元亨。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_201","chapterId":"ch_work_dk_14","textTraditional":"大有，柔得尊位，大中而上下應之，曰大有。其德刚健而文明，應乎天而時行，是以元亨。","textSimplified":"大有，柔得尊位，大中而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_202","chapterId":"ch_work_dk_14","textTraditional":"火在天上，大有；君子以遏惡扬善，順天休命。","textSimplified":"火在天上，大有；君子以遏恶扬善，顺天休命。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_203","chapterId":"ch_work_dk_14","textTraditional":"初九：無交害，匪咎，艱則無咎。","textSimplified":"初九：无交害，匪咎，艰则无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_204","chapterId":"ch_work_dk_14","textTraditional":"六二：同人於宗，吝。","textSimplified":"六二：同人于宗，吝。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_205","chapterId":"ch_work_dk_14","textTraditional":"九三：公用亨於天子，小人弗克。","textSimplified":"九三：公用亨于天子，小人弗克。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_206","chapterId":"ch_work_dk_14","textTraditional":"九四：匪其彭，無咎。","textSimplified":"九四：匪其彭，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_207","chapterId":"ch_work_dk_14","textTraditional":"六五：厥孚交如，威如；吉。","textSimplified":"六五：厥孚交如，威如；吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_208","chapterId":"ch_work_dk_14","textTraditional":"上九：自天佑之，吉無不利。","textSimplified":"上九：自天佑之，吉无不利。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_209","chapterId":"ch_work_dk_14","textTraditional":"大有初九，無交害也。","textSimplified":"大有初九，无交害也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_210","chapterId":"ch_work_dk_14","textTraditional":"大車以載，積中不败也。","textSimplified":"大车以载，积中不败也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_211","chapterId":"ch_work_dk_14","textTraditional":"公用亨於天子，小人害也。","textSimplified":"公用亨于天子，小人害也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_212","chapterId":"ch_work_dk_14","textTraditional":"匪其彭，無咎；明辨晰也。","textSimplified":"匪其彭，无咎；明辨晰也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_213","chapterId":"ch_work_dk_14","textTraditional":"厥孚交如，信以發志也。威如之吉，易而無備也。","textSimplified":"厥孚交如，信以发志也。威如之吉，易而无备也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_214","chapterId":"ch_work_dk_14","textTraditional":"大有上吉，自天佑也。","textSimplified":"大有上吉，自天佑也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_215","chapterId":"ch_work_dk_15","textTraditional":"謙：亨，君子有終。","textSimplified":"谦：亨，君子有终。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_216","chapterId":"ch_work_dk_15","textTraditional":"謙，亨，天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道变盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可逾，君子之終也。","textSimplified":"谦，亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_217","chapterId":"ch_work_dk_15","textTraditional":"地中有山，謙；君子以裒多益寡，稱物平施。","textSimplified":"地中有山，谦；君子以裒多益寡，称物平施。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_218","chapterId":"ch_work_dk_15","textTraditional":"初六：謙謙君子，用涉大川，吉。","textSimplified":"初六：谦谦君子，用涉大川，吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_219","chapterId":"ch_work_dk_15","textTraditional":"六二：鳴謙，貞吉。","textSimplified":"六二：鸣谦，贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_220","chapterId":"ch_work_dk_15","textTraditional":"九三：勞謙，君子有終，吉。","textSimplified":"九三：劳谦，君子有终，吉。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_221","chapterId":"ch_work_dk_15","textTraditional":"六四：無不利，撝謙。","textSimplified":"六四：无不利，撝谦。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_222","chapterId":"ch_work_dk_15","textTraditional":"六五：不富，以其鄰，利用侵伐，無不利。","textSimplified":"六五：不富，以其邻，利用侵伐，无不利。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_223","chapterId":"ch_work_dk_15","textTraditional":"上六：鳴謙，利用行師，征邑國。","textSimplified":"上六：鸣谦，利用行师，征邑国。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_224","chapterId":"ch_work_dk_15","textTraditional":"謙謙君子，卑以自牧也。","textSimplified":"谦谦君子，卑以自牧也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_225","chapterId":"ch_work_dk_15","textTraditional":"鳴謙貞吉，中心得也。","textSimplified":"鸣谦贞吉，中心得也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_226","chapterId":"ch_work_dk_15","textTraditional":"勞謙君子，萬民服也。","textSimplified":"劳谦君子，万民服也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_227","chapterId":"ch_work_dk_15","textTraditional":"無不利，撝謙；不违則也。","textSimplified":"无不利，撝谦；不违则也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_228","chapterId":"ch_work_dk_15","textTraditional":"利用侵伐，征不服也。","textSimplified":"利用侵伐，征不服也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_229","chapterId":"ch_work_dk_15","textTraditional":"鳴謙，志未得也。可用行師，征邑國也。","textSimplified":"鸣谦，志未得也。可用行师，征邑国也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_230","chapterId":"ch_work_dk_16","textTraditional":"豫：利建侯，行師。","textSimplified":"豫：利建侯，行师。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_231","chapterId":"ch_work_dk_16","textTraditional":"豫，刚應而志行，順以動，豫。豫，順以動，故天地如之，而况建侯行師乎？天地以順動，故日月不過，而四時不忒；聖人以順動，則刑罰清而民服。豫之時義大矣哉！","textSimplified":"豫，刚应而志行，顺以动，豫。豫，顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过，而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_232","chapterId":"ch_work_dk_16","textTraditional":"雷出地奋，豫。先王以作樂崇德，殷荐之上帝，以配祖考。","textSimplified":"雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_233","chapterId":"ch_work_dk_16","textTraditional":"初六：鳴豫，凶。","textSimplified":"初六：鸣豫，凶。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_234","chapterId":"ch_work_dk_16","textTraditional":"六二：介於石，不終日，貞吉。","textSimplified":"六二：介于石，不终日，贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_235","chapterId":"ch_work_dk_16","textTraditional":"六三：盱豫，悔。遲有悔。","textSimplified":"六三：盱豫，悔。迟有悔。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_236","chapterId":"ch_work_dk_16","textTraditional":"九四：由豫，大有得。勿疑。朋盍簪。","textSimplified":"九四：由豫，大有得。勿疑。朋盍簪。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_237","chapterId":"ch_work_dk_16","textTraditional":"六五：貞疾，恒不死。","textSimplified":"六五：贞疾，恒不死。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_238","chapterId":"ch_work_dk_16","textTraditional":"上六：冥豫，成有渝，無咎。","textSimplified":"上六：冥豫，成有渝，无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_239","chapterId":"ch_work_dk_16","textTraditional":"初六鳴豫，志窮凶也。","textSimplified":"初六鸣豫，志穷凶也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_240","chapterId":"ch_work_dk_16","textTraditional":"不終日，貞吉；以中正也。","textSimplified":"不终日，贞吉；以中正也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_241","chapterId":"ch_work_dk_16","textTraditional":"盱豫有悔，位不當也。","textSimplified":"盱豫有悔，位不当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_242","chapterId":"ch_work_dk_16","textTraditional":"由豫，大有得；志大行也。","textSimplified":"由豫，大有得；志大行也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_243","chapterId":"ch_work_dk_16","textTraditional":"六五貞疾，乘刚也。恒不死，中未亡也。","textSimplified":"六五贞疾，乘刚也。恒不死，中未亡也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_244","chapterId":"ch_work_dk_16","textTraditional":"冥豫在上，何可長也。","textSimplified":"冥豫在上，何可长也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_245","chapterId":"ch_work_dk_17","textTraditional":"隨：元亨利貞，無咎。","textSimplified":"随：元亨利贞，无咎。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_246","chapterId":"ch_work_dk_17","textTraditional":"隨，刚來而下柔，動而說，隨。大亨貞，無咎，而天下隨時，隨之時義大矣哉！","textSimplified":"随，刚来而下柔，动而说，随。大亨贞，无咎，而天下随时，随之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_247","chapterId":"ch_work_dk_17","textTraditional":"泽中有雷，隨；君子以向晦入宴息。","textSimplified":"泽中有雷，随；君子以向晦入宴息。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_248","chapterId":"ch_work_dk_17","textTraditional":"初九：官有渝，貞吉。出門交有功。","textSimplified":"初九：官有渝，贞吉。出门交有功。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_249","chapterId":"ch_work_dk_17","textTraditional":"六二：系小子，失丈夫。","textSimplified":"六二：系小子，失丈夫。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_250","chapterId":"ch_work_dk_17","textTraditional":"六三：系丈夫，失小子。隨有求得，利居貞。","textSimplified":"六三：系丈夫，失小子。随有求得，利居贞。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_251","chapterId":"ch_work_dk_17","textTraditional":"九四：隨有獲，貞凶。有孚在道，以明，何咎。","textSimplified":"九四：随有获，贞凶。有孚在道，以明，何咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_252","chapterId":"ch_work_dk_17","textTraditional":"九五：孚於嘉，吉。","textSimplified":"九五：孚于嘉，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_253","chapterId":"ch_work_dk_17","textTraditional":"上六：拘系之，乃從維之。王用亨於西山。","textSimplified":"上六：拘系之，乃从维之。王用亨于西山。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_254","chapterId":"ch_work_dk_17","textTraditional":"官有渝，從正吉也。出門交有功，不失也。","textSimplified":"官有渝，从正吉也。出门交有功，不失也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_255","chapterId":"ch_work_dk_17","textTraditional":"系小子，弗兼與也。","textSimplified":"系小子，弗兼与也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_256","chapterId":"ch_work_dk_17","textTraditional":"系丈夫，志舍下也。","textSimplified":"系丈夫，志舍下也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_257","chapterId":"ch_work_dk_17","textTraditional":"隨有獲，其義凶也。有孚在道，明功也。","textSimplified":"随有获，其义凶也。有孚在道，明功也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_258","chapterId":"ch_work_dk_17","textTraditional":"孚於嘉，吉；位正中也。","textSimplified":"孚于嘉，吉；位正中也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_259","chapterId":"ch_work_dk_17","textTraditional":"拘系之，上窮也。","textSimplified":"拘系之，上穷也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_260","chapterId":"ch_work_dk_18","textTraditional":"蠱：元亨，利涉大川。先甲三日，後甲三日。","textSimplified":"蛊：元亨，利涉大川。先甲三日，后甲三日。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_261","chapterId":"ch_work_dk_18","textTraditional":"蠱，刚上而柔下，巽而止，蠱。蠱，元亨，而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。","textSimplified":"蛊，刚上而柔下，巽而止，蛊。蛊，元亨，而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_262","chapterId":"ch_work_dk_18","textTraditional":"山下有風，蠱；君子以振民育德。","textSimplified":"山下有风，蛊；君子以振民育德。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_263","chapterId":"ch_work_dk_18","textTraditional":"初六：幹父之蠱，有子，考無咎，厲終吉。","textSimplified":"初六：干父之蛊，有子，考无咎，厉终吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_264","chapterId":"ch_work_dk_18","textTraditional":"九二：幹母之蠱，不可貞。","textSimplified":"九二：干母之蛊，不可贞。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_265","chapterId":"ch_work_dk_18","textTraditional":"九三：幹父之蠱，小有悔，無大咎。","textSimplified":"九三：干父之蛊，小有悔，无大咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_266","chapterId":"ch_work_dk_18","textTraditional":"六四：裕父之蠱，往見吝。","textSimplified":"六四：裕父之蛊，往见吝。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_267","chapterId":"ch_work_dk_18","textTraditional":"六五：幹父之蠱，用譽。","textSimplified":"六五：干父之蛊，用誉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_268","chapterId":"ch_work_dk_18","textTraditional":"上九：不事王侯，高尚其事。","textSimplified":"上九：不事王侯，高尚其事。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_269","chapterId":"ch_work_dk_18","textTraditional":"幹父之蠱，意承考也。","textSimplified":"干父之蛊，意承考也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_270","chapterId":"ch_work_dk_18","textTraditional":"幹母之蠱，得中道也。","textSimplified":"干母之蛊，得中道也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_271","chapterId":"ch_work_dk_18","textTraditional":"幹父之蠱，終無咎也。","textSimplified":"干父之蛊，终无咎也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_272","chapterId":"ch_work_dk_18","textTraditional":"裕父之蠱，往未得也。","textSimplified":"裕父之蛊，往未得也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_273","chapterId":"ch_work_dk_18","textTraditional":"幹父之蠱；承以德也。","textSimplified":"干父之蛊；承以德也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_274","chapterId":"ch_work_dk_18","textTraditional":"不事王侯，志可則也。","textSimplified":"不事王侯，志可则也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_275","chapterId":"ch_work_dk_19","textTraditional":"臨：元，亨，利，貞。至於八月有凶。","textSimplified":"临：元，亨，利，贞。至于八月有凶。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_276","chapterId":"ch_work_dk_19","textTraditional":"臨，刚浸而長。說而順，刚中而應，大亨以正，天之道也。至於八月有凶，消不久也。","textSimplified":"临，刚浸而长。说而顺，刚中而应，大亨以正，天之道也。至于八月有凶，消不久也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_277","chapterId":"ch_work_dk_19","textTraditional":"泽上有地，臨；君子以教思無窮，容保民無疆。","textSimplified":"泽上有地，临；君子以教思无穷，容保民无疆。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_278","chapterId":"ch_work_dk_19","textTraditional":"初九：鹹臨，貞吉。","textSimplified":"初九：咸临，贞吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_279","chapterId":"ch_work_dk_19","textTraditional":"九二：鹹臨，吉無不利。","textSimplified":"九二：咸临，吉无不利。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_280","chapterId":"ch_work_dk_19","textTraditional":"六三：甘臨，無攸利。既忧之，無咎。","textSimplified":"六三：甘临，无攸利。既忧之，无咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_281","chapterId":"ch_work_dk_19","textTraditional":"六四：至臨，無咎。","textSimplified":"六四：至临，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_282","chapterId":"ch_work_dk_19","textTraditional":"六五：知臨，大君之宜，吉。","textSimplified":"六五：知临，大君之宜，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_283","chapterId":"ch_work_dk_19","textTraditional":"上六：敦臨，吉無咎。","textSimplified":"上六：敦临，吉无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_284","chapterId":"ch_work_dk_19","textTraditional":"鹹臨貞吉，志行正也。","textSimplified":"咸临贞吉，志行正也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_285","chapterId":"ch_work_dk_19","textTraditional":"鹹臨，吉無不利；未順命也。","textSimplified":"咸临，吉无不利；未顺命也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_286","chapterId":"ch_work_dk_19","textTraditional":"甘臨，位不當也。既忧之，咎不長也。","textSimplified":"甘临，位不当也。既忧之，咎不长也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_287","chapterId":"ch_work_dk_19","textTraditional":"至臨無咎，位當也。","textSimplified":"至临无咎，位当也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_288","chapterId":"ch_work_dk_19","textTraditional":"大君之宜，行中之謂也。","textSimplified":"大君之宜，行中之谓也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_289","chapterId":"ch_work_dk_19","textTraditional":"敦臨之吉，志在內也。","textSimplified":"敦临之吉，志在内也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_290","chapterId":"ch_work_dk_20","textTraditional":"觀：盥而不荐，有孚顒若。","textSimplified":"观：盥而不荐，有孚顒若。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_291","chapterId":"ch_work_dk_20","textTraditional":"大觀在上，順而巽，中正以觀天下。觀，盥而不荐，有孚顒若，下觀而化也。觀天之神道，而四時不忒，聖人以神道設教，而天下服矣。","textSimplified":"大观在上，顺而巽，中正以观天下。观，盥而不荐，有孚顒若，下观而化也。观天之神道，而四时不忒，圣人以神道设教，而天下服矣。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_292","chapterId":"ch_work_dk_20","textTraditional":"風行地上，觀；先王以省方，觀民設教。","textSimplified":"风行地上，观；先王以省方，观民设教。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_293","chapterId":"ch_work_dk_20","textTraditional":"初六：童觀，小人無咎，君子吝。","textSimplified":"初六：童观，小人无咎，君子吝。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_294","chapterId":"ch_work_dk_20","textTraditional":"六二：窥觀，利女貞。","textSimplified":"六二：窥观，利女贞。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_295","chapterId":"ch_work_dk_20","textTraditional":"六三：觀我生，進退。","textSimplified":"六三：观我生，进退。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_296","chapterId":"ch_work_dk_20","textTraditional":"六四：觀國之光，利用賓於王。","textSimplified":"六四：观国之光，利用宾于王。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_297","chapterId":"ch_work_dk_20","textTraditional":"九五：觀我生，君子無咎。","textSimplified":"九五：观我生，君子无咎。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_298","chapterId":"ch_work_dk_20","textTraditional":"上九：觀其生，君子無咎。","textSimplified":"上九：观其生，君子无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_299","chapterId":"ch_work_dk_20","textTraditional":"初六童觀，小人道也。","textSimplified":"初六童观，小人道也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_300","chapterId":"ch_work_dk_20","textTraditional":"窥觀女貞，亦可丑也。","textSimplified":"窥观女贞，亦可丑也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_301","chapterId":"ch_work_dk_20","textTraditional":"觀我生，進退；未失道也。","textSimplified":"观我生，进退；未失道也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_302","chapterId":"ch_work_dk_20","textTraditional":"觀國之光，尚賓也。","textSimplified":"观国之光，尚宾也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_303","chapterId":"ch_work_dk_20","textTraditional":"觀我生，觀民也。","textSimplified":"观我生，观民也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_304","chapterId":"ch_work_dk_20","textTraditional":"觀其生，志未平也。","textSimplified":"观其生，志未平也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_305","chapterId":"ch_work_dk_21","textTraditional":"噬嗑：亨。利用獄。","textSimplified":"噬嗑：亨。利用狱。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_306","chapterId":"ch_work_dk_21","textTraditional":"颐中有物，曰噬嗑，噬嗑而亨。刚柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。","textSimplified":"颐中有物，曰噬嗑，噬嗑而亨。刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，利用狱也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_307","chapterId":"ch_work_dk_21","textTraditional":"雷電噬嗑；先王以明罰敕法。","textSimplified":"雷电噬嗑；先王以明罚敕法。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_308","chapterId":"ch_work_dk_21","textTraditional":"初九：屦校滅趾，無咎。","textSimplified":"初九：屦校灭趾，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_309","chapterId":"ch_work_dk_21","textTraditional":"六二：噬膚滅鼻，無咎。","textSimplified":"六二：噬肤灭鼻，无咎。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_310","chapterId":"ch_work_dk_21","textTraditional":"六三：噬腊肉，遇毒；小吝，無咎。","textSimplified":"六三：噬腊肉，遇毒；小吝，无咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_311","chapterId":"ch_work_dk_21","textTraditional":"九四：噬乾胏，得金矢，利艱貞，吉。","textSimplified":"九四：噬乾胏，得金矢，利艰贞，吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_312","chapterId":"ch_work_dk_21","textTraditional":"六五：噬乾肉，得黃金，貞厲，無咎。","textSimplified":"六五：噬乾肉，得黄金，贞厉，无咎。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_313","chapterId":"ch_work_dk_21","textTraditional":"上九：何校滅耳，凶。","textSimplified":"上九：何校灭耳，凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_314","chapterId":"ch_work_dk_21","textTraditional":"屦校滅趾，不行也。","textSimplified":"屦校灭趾，不行也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_315","chapterId":"ch_work_dk_21","textTraditional":"噬膚滅鼻，乘刚也。","textSimplified":"噬肤灭鼻，乘刚也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_316","chapterId":"ch_work_dk_21","textTraditional":"遇毒，位不當也。","textSimplified":"遇毒，位不当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_317","chapterId":"ch_work_dk_21","textTraditional":"利艱貞吉，未光也。","textSimplified":"利艰贞吉，未光也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_318","chapterId":"ch_work_dk_21","textTraditional":"貞厲無咎，得當也。","textSimplified":"贞厉无咎，得当也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_319","chapterId":"ch_work_dk_21","textTraditional":"何校滅耳，聰不明也。","textSimplified":"何校灭耳，聪不明也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_320","chapterId":"ch_work_dk_22","textTraditional":"贲：亨。小利有攸往。","textSimplified":"贲：亨。小利有攸往。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_321","chapterId":"ch_work_dk_22","textTraditional":"贲，亨；柔來而文刚，故亨。分刚上而文柔，故小利有攸往。天文也；文明以止，人文也。觀乎天文，以察時变；觀乎人文，以化成天下。","textSimplified":"贲，亨；柔来而文刚，故亨。分刚上而文柔，故小利有攸往。天文也；文明以止，人文也。观乎天文，以察时变；观乎人文，以化成天下。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_322","chapterId":"ch_work_dk_22","textTraditional":"山下有火，贲；君子以明庶政，無敢折獄。","textSimplified":"山下有火，贲；君子以明庶政，无敢折狱。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_323","chapterId":"ch_work_dk_22","textTraditional":"初九：贲其趾，舍車而徒。","textSimplified":"初九：贲其趾，舍车而徒。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_324","chapterId":"ch_work_dk_22","textTraditional":"六二：贲其須。","textSimplified":"六二：贲其须。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_325","chapterId":"ch_work_dk_22","textTraditional":"九三：贲如濡如，永貞吉。","textSimplified":"九三：贲如濡如，永贞吉。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_326","chapterId":"ch_work_dk_22","textTraditional":"六四：贲如皤如，白馬翰如，匪寇婚媾。","textSimplified":"六四：贲如皤如，白马翰如，匪寇婚媾。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_327","chapterId":"ch_work_dk_22","textTraditional":"六五：贲於丘園，束帛戋戋，吝，終吉。","textSimplified":"六五：贲于丘园，束帛戋戋，吝，终吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_328","chapterId":"ch_work_dk_22","textTraditional":"上九：白贲，無咎。","textSimplified":"上九：白贲，无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_329","chapterId":"ch_work_dk_22","textTraditional":"舍車而徒，義弗乘也。","textSimplified":"舍车而徒，义弗乘也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_330","chapterId":"ch_work_dk_22","textTraditional":"贲其須，與上興也。","textSimplified":"贲其须，与上兴也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_331","chapterId":"ch_work_dk_22","textTraditional":"永貞之吉，終莫之陵也。","textSimplified":"永贞之吉，终莫之陵也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_332","chapterId":"ch_work_dk_22","textTraditional":"六四，當位疑也。匪寇婚媾，終無尤也。","textSimplified":"六四，当位疑也。匪寇婚媾，终无尤也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_333","chapterId":"ch_work_dk_22","textTraditional":"六五之吉，有喜也。","textSimplified":"六五之吉，有喜也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_334","chapterId":"ch_work_dk_22","textTraditional":"白贲無咎，上得志也。","textSimplified":"白贲无咎，上得志也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_335","chapterId":"ch_work_dk_23","textTraditional":"剝：不利有攸往。","textSimplified":"剥：不利有攸往。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_336","chapterId":"ch_work_dk_23","textTraditional":"剝，剝也，柔变刚也。不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。","textSimplified":"剥，剥也，柔变刚也。不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_337","chapterId":"ch_work_dk_23","textTraditional":"山附地上，剝；上以厚下，安宅。","textSimplified":"山附地上，剥；上以厚下，安宅。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_338","chapterId":"ch_work_dk_23","textTraditional":"初六：剝床以足，蔑貞凶。","textSimplified":"初六：剥床以足，蔑贞凶。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_339","chapterId":"ch_work_dk_23","textTraditional":"六二：剝床以辨，蔑貞凶。","textSimplified":"六二：剥床以辨，蔑贞凶。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_340","chapterId":"ch_work_dk_23","textTraditional":"六三：剝之，無咎。","textSimplified":"六三：剥之，无咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_341","chapterId":"ch_work_dk_23","textTraditional":"六四：剝床以膚，凶。","textSimplified":"六四：剥床以肤，凶。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_342","chapterId":"ch_work_dk_23","textTraditional":"六五：貫魚，以宮人寵，無不利。","textSimplified":"六五：贯鱼，以宫人宠，无不利。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_343","chapterId":"ch_work_dk_23","textTraditional":"上九：硕果不食，君子得舆，小人剝庐。","textSimplified":"上九：硕果不食，君子得舆，小人剥庐。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_344","chapterId":"ch_work_dk_23","textTraditional":"剝床以足，以滅下也。","textSimplified":"剥床以足，以灭下也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_345","chapterId":"ch_work_dk_23","textTraditional":"剝床以辨，未有與也。","textSimplified":"剥床以辨，未有与也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_346","chapterId":"ch_work_dk_23","textTraditional":"剝之無咎，失上下也。","textSimplified":"剥之无咎，失上下也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_347","chapterId":"ch_work_dk_23","textTraditional":"剝床以膚，切近灾也。","textSimplified":"剥床以肤，切近灾也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_348","chapterId":"ch_work_dk_23","textTraditional":"以宮人寵，終無尤也。","textSimplified":"以宫人宠，终无尤也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_349","chapterId":"ch_work_dk_23","textTraditional":"君子得舆，民所載也。小人剝庐，終不可用也。","textSimplified":"君子得舆，民所载也。小人剥庐，终不可用也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_350","chapterId":"ch_work_dk_24","textTraditional":"复：亨。出入無疾，朋來無咎。反复其道，七日來复，利有攸往。","textSimplified":"复：亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_351","chapterId":"ch_work_dk_24","textTraditional":"复亨；刚反，動而以順行，是以出入無疾，朋來無咎。反复其道，七日來复，天行也。利有攸往，刚長也。复其見天地之心乎？","textSimplified":"复亨；刚反，动而以顺行，是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复其见天地之心乎？","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_352","chapterId":"ch_work_dk_24","textTraditional":"雷在地中，复；先王以至日閉關，商旅不行，後不省方。","textSimplified":"雷在地中，复；先王以至日闭关，商旅不行，后不省方。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_353","chapterId":"ch_work_dk_24","textTraditional":"初九：不复遠，無祗悔，元吉。","textSimplified":"初九：不复远，无祗悔，元吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_354","chapterId":"ch_work_dk_24","textTraditional":"六二：休复，吉。","textSimplified":"六二：休复，吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_355","chapterId":"ch_work_dk_24","textTraditional":"六三：頻复，厲無咎。","textSimplified":"六三：频复，厉无咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_356","chapterId":"ch_work_dk_24","textTraditional":"六四：中行獨复。","textSimplified":"六四：中行独复。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_357","chapterId":"ch_work_dk_24","textTraditional":"六五：敦复，無悔。","textSimplified":"六五：敦复，无悔。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_358","chapterId":"ch_work_dk_24","textTraditional":"上六：迷复，凶，有灾眚。用行師，終有大败，以其國君，凶；至於十年，不克征。","textSimplified":"上六：迷复，凶，有灾眚。用行师，终有大败，以其国君，凶；至于十年，不克征。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_359","chapterId":"ch_work_dk_24","textTraditional":"不遠之复，以修身也。","textSimplified":"不远之复，以修身也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_360","chapterId":"ch_work_dk_24","textTraditional":"休复之吉，以下仁也。","textSimplified":"休复之吉，以下仁也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_361","chapterId":"ch_work_dk_24","textTraditional":"頻复之厲，義無咎也。","textSimplified":"频复之厉，义无咎也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_362","chapterId":"ch_work_dk_24","textTraditional":"中行獨复，以從道也。","textSimplified":"中行独复，以从道也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_363","chapterId":"ch_work_dk_24","textTraditional":"敦复無悔，中以自考也。","textSimplified":"敦复无悔，中以自考也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_364","chapterId":"ch_work_dk_24","textTraditional":"迷复之凶，反君道也。","textSimplified":"迷复之凶，反君道也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_365","chapterId":"ch_work_dk_25","textTraditional":"無妄：元亨，利貞。其匪正有眚，不利有攸往。","textSimplified":"无妄：元亨，利贞。其匪正有眚，不利有攸往。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_366","chapterId":"ch_work_dk_25","textTraditional":"無妄，刚自外來，而為主於內。動而健，刚中而應，大亨以正，天之命也。其匪正有眚，不利有攸往。無妄之往，何之矣？天命不佑，行矣哉？","textSimplified":"无妄，刚自外来，而为主于内。动而健，刚中而应，大亨以正，天之命也。其匪正有眚，不利有攸往。无妄之往，何之矣？天命不佑，行矣哉？","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_367","chapterId":"ch_work_dk_25","textTraditional":"天下雷行，物與無妄；先王以茂對時，育萬物。","textSimplified":"天下雷行，物与无妄；先王以茂对时，育万物。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_368","chapterId":"ch_work_dk_25","textTraditional":"初九：無妄，往吉。","textSimplified":"初九：无妄，往吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_369","chapterId":"ch_work_dk_25","textTraditional":"六二：不耕獲，不灾畲，則利有攸往。","textSimplified":"六二：不耕获，不灾畲，则利有攸往。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_370","chapterId":"ch_work_dk_25","textTraditional":"六三：無妄之灾，或系之牛，行人之得，邑人之灾。","textSimplified":"六三：无妄之灾，或系之牛，行人之得，邑人之灾。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_371","chapterId":"ch_work_dk_25","textTraditional":"九四：可貞，無咎。","textSimplified":"九四：可贞，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_372","chapterId":"ch_work_dk_25","textTraditional":"九五：無妄之疾，勿藥有喜。","textSimplified":"九五：无妄之疾，勿药有喜。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_373","chapterId":"ch_work_dk_25","textTraditional":"上九：無妄，行有眚，無攸利。","textSimplified":"上九：无妄，行有眚，无攸利。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_374","chapterId":"ch_work_dk_25","textTraditional":"無妄之往，得志也。","textSimplified":"无妄之往，得志也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_375","chapterId":"ch_work_dk_25","textTraditional":"不耕獲，未富也。","textSimplified":"不耕获，未富也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_376","chapterId":"ch_work_dk_25","textTraditional":"行人得牛，邑人灾也。","textSimplified":"行人得牛，邑人灾也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_377","chapterId":"ch_work_dk_25","textTraditional":"可貞無咎，固有之也。","textSimplified":"可贞无咎，固有之也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_378","chapterId":"ch_work_dk_25","textTraditional":"無妄之藥，不可试也。","textSimplified":"无妄之药，不可试也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_379","chapterId":"ch_work_dk_25","textTraditional":"無妄之行，窮之灾也。","textSimplified":"无妄之行，穷之灾也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_380","chapterId":"ch_work_dk_26","textTraditional":"大畜：利貞，不家食吉，利涉大川。","textSimplified":"大畜：利贞，不家食吉，利涉大川。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_381","chapterId":"ch_work_dk_26","textTraditional":"大畜，刚健篤實辉光，日新其德，刚上而尚賢。能止健，大正也。不家食吉，養賢也。利涉大川，應乎天也。","textSimplified":"大畜，刚健笃实辉光，日新其德，刚上而尚贤。能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_382","chapterId":"ch_work_dk_26","textTraditional":"天在山中，大畜；君子以多識前言往行，以畜其德。","textSimplified":"天在山中，大畜；君子以多识前言往行，以畜其德。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_383","chapterId":"ch_work_dk_26","textTraditional":"初九：有厲利已。","textSimplified":"初九：有厉利已。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_384","chapterId":"ch_work_dk_26","textTraditional":"九二：舆說輹。","textSimplified":"九二：舆说輹。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_385","chapterId":"ch_work_dk_26","textTraditional":"九三：良馬逐，利艱貞。曰閒舆衛，利有攸往。","textSimplified":"九三：良马逐，利艰贞。曰闲舆卫，利有攸往。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_386","chapterId":"ch_work_dk_26","textTraditional":"六四：童牛之牿，元吉。","textSimplified":"六四：童牛之牿，元吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_387","chapterId":"ch_work_dk_26","textTraditional":"六五：豶豕之牙，吉。","textSimplified":"六五：豶豕之牙，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_388","chapterId":"ch_work_dk_26","textTraditional":"上九：何天之衢，亨。","textSimplified":"上九：何天之衢，亨。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_389","chapterId":"ch_work_dk_26","textTraditional":"有厲利已，不犯灾也。","textSimplified":"有厉利已，不犯灾也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_390","chapterId":"ch_work_dk_26","textTraditional":"舆說輹，中無尤也。","textSimplified":"舆说輹，中无尤也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_391","chapterId":"ch_work_dk_26","textTraditional":"利有攸往，上合志也。","textSimplified":"利有攸往，上合志也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_392","chapterId":"ch_work_dk_26","textTraditional":"六四元吉，有喜也。","textSimplified":"六四元吉，有喜也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_393","chapterId":"ch_work_dk_26","textTraditional":"六五之吉，有慶也。","textSimplified":"六五之吉，有庆也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_394","chapterId":"ch_work_dk_26","textTraditional":"何天之衢，道大行也。","textSimplified":"何天之衢，道大行也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_395","chapterId":"ch_work_dk_27","textTraditional":"颐：貞吉。觀颐，自求口實。","textSimplified":"颐：贞吉。观颐，自求口实。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_396","chapterId":"ch_work_dk_27","textTraditional":"颐貞吉，養正則吉也。觀颐，觀其所養也；自求口實，觀其自養也。天地養萬物，聖人養賢，以及萬民；颐之時義大矣哉！","textSimplified":"颐贞吉，养正则吉也。观颐，观其所养也；自求口实，观其自养也。天地养万物，圣人养贤，以及万民；颐之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_397","chapterId":"ch_work_dk_27","textTraditional":"山下有雷，颐；君子以慎言語，節飲食。","textSimplified":"山下有雷，颐；君子以慎言语，节饮食。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_398","chapterId":"ch_work_dk_27","textTraditional":"初九：舍爾靈龟，觀我朵颐，凶。","textSimplified":"初九：舍尔灵龟，观我朵颐，凶。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_399","chapterId":"ch_work_dk_27","textTraditional":"六二：顛颐，拂經，於丘颐，征凶。","textSimplified":"六二：颠颐，拂经，于丘颐，征凶。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_400","chapterId":"ch_work_dk_27","textTraditional":"六三：拂颐，貞凶，十年勿用，無攸利。","textSimplified":"六三：拂颐，贞凶，十年勿用，无攸利。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_401","chapterId":"ch_work_dk_27","textTraditional":"六四：顛颐，吉，虎视眈眈，其欲逐逐，無咎。","textSimplified":"六四：颠颐，吉，虎视眈眈，其欲逐逐，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_402","chapterId":"ch_work_dk_27","textTraditional":"六五：拂經，居貞吉，不可涉大川。","textSimplified":"六五：拂经，居贞吉，不可涉大川。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_403","chapterId":"ch_work_dk_27","textTraditional":"上九：由颐，厲吉，利涉大川。","textSimplified":"上九：由颐，厉吉，利涉大川。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_404","chapterId":"ch_work_dk_27","textTraditional":"觀我朵颐，亦不足貴也。","textSimplified":"观我朵颐，亦不足贵也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_405","chapterId":"ch_work_dk_27","textTraditional":"六二征凶，行失類也。","textSimplified":"六二征凶，行失类也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_406","chapterId":"ch_work_dk_27","textTraditional":"十年勿用，道大悖也。","textSimplified":"十年勿用，道大悖也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_407","chapterId":"ch_work_dk_27","textTraditional":"顛颐之吉，上施光也。","textSimplified":"颠颐之吉，上施光也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_408","chapterId":"ch_work_dk_27","textTraditional":"居貞之吉，順以從上也。","textSimplified":"居贞之吉，顺以从上也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_409","chapterId":"ch_work_dk_27","textTraditional":"由颐厲吉，大有慶也。","textSimplified":"由颐厉吉，大有庆也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_410","chapterId":"ch_work_dk_28","textTraditional":"大過：棟桡，利有攸往，亨。","textSimplified":"大过：栋桡，利有攸往，亨。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_411","chapterId":"ch_work_dk_28","textTraditional":"大過，大者過也。棟桡，本末弱也。刚過而中，巽而說行，利有攸往，乃亨。大過之時義大矣哉！","textSimplified":"大过，大者过也。栋桡，本末弱也。刚过而中，巽而说行，利有攸往，乃亨。大过之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_412","chapterId":"ch_work_dk_28","textTraditional":"泽滅木，大過；君子以獨立不懼，遯世無悶。","textSimplified":"泽灭木，大过；君子以独立不惧，遯世无闷。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_413","chapterId":"ch_work_dk_28","textTraditional":"初六：藉用白茅，無咎。","textSimplified":"初六：藉用白茅，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_414","chapterId":"ch_work_dk_28","textTraditional":"九二：枯楊生稊，老夫得其女妻，無不利。","textSimplified":"九二：枯杨生稊，老夫得其女妻，无不利。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_415","chapterId":"ch_work_dk_28","textTraditional":"九三：棟桡，凶。","textSimplified":"九三：栋桡，凶。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_416","chapterId":"ch_work_dk_28","textTraditional":"九四：棟隆，吉；有它吝。","textSimplified":"九四：栋隆，吉；有它吝。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_417","chapterId":"ch_work_dk_28","textTraditional":"九五：枯楊生華，老婦得士夫，無咎無譽。","textSimplified":"九五：枯杨生华，老妇得士夫，无咎无誉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_418","chapterId":"ch_work_dk_28","textTraditional":"上六：過涉滅顶，凶，無咎。","textSimplified":"上六：过涉灭顶，凶，无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_419","chapterId":"ch_work_dk_28","textTraditional":"藉用白茅，柔在下也。","textSimplified":"藉用白茅，柔在下也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_420","chapterId":"ch_work_dk_28","textTraditional":"老夫女妻，過以相與也。","textSimplified":"老夫女妻，过以相与也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_421","chapterId":"ch_work_dk_28","textTraditional":"棟桡之凶，不可以有辅也。","textSimplified":"栋桡之凶，不可以有辅也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_422","chapterId":"ch_work_dk_28","textTraditional":"棟隆之吉，不桡乎下也。","textSimplified":"栋隆之吉，不桡乎下也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_423","chapterId":"ch_work_dk_28","textTraditional":"枯楊生華，何可久也。老婦士夫，亦可丑也。","textSimplified":"枯杨生华，何可久也。老妇士夫，亦可丑也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_424","chapterId":"ch_work_dk_28","textTraditional":"過涉之凶，不可咎也。","textSimplified":"过涉之凶，不可咎也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_425","chapterId":"ch_work_dk_29","textTraditional":"坎：習坎，有孚，維心亨，行有尚。","textSimplified":"坎：习坎，有孚，维心亨，行有尚。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_426","chapterId":"ch_work_dk_29","textTraditional":"習坎，重险也。水流而不盈，行险而不失其信。維心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也，王公設险以守其國，坎之時用大矣哉！","textSimplified":"习坎，重险也。水流而不盈，行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也，王公设险以守其国，坎之时用大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_427","chapterId":"ch_work_dk_29","textTraditional":"水洊至，習坎；君子以常德行，習教事。","textSimplified":"水洊至，习坎；君子以常德行，习教事。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_428","chapterId":"ch_work_dk_29","textTraditional":"初六：習坎，入於坎窞，凶。","textSimplified":"初六：习坎，入于坎窞，凶。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_429","chapterId":"ch_work_dk_29","textTraditional":"九二：坎有险，求小得。","textSimplified":"九二：坎有险，求小得。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_430","chapterId":"ch_work_dk_29","textTraditional":"六三：來之坎坎，险且枕，入於坎窞，勿用。","textSimplified":"六三：来之坎坎，险且枕，入于坎窞，勿用。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_431","chapterId":"ch_work_dk_29","textTraditional":"六四：樽酒簋貳，用缶，納約自牖，終無咎。","textSimplified":"六四：樽酒簋贰，用缶，纳约自牖，终无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_432","chapterId":"ch_work_dk_29","textTraditional":"九五：坎不盈，祗既平，無咎。","textSimplified":"九五：坎不盈，祗既平，无咎。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_433","chapterId":"ch_work_dk_29","textTraditional":"上六：系用徽纆，置於丛棘，三歲不得，凶。","textSimplified":"上六：系用徽纆，置于丛棘，三岁不得，凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_434","chapterId":"ch_work_dk_29","textTraditional":"習坎入坎，失道凶也。","textSimplified":"习坎入坎，失道凶也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_435","chapterId":"ch_work_dk_29","textTraditional":"求小得，未出中也。","textSimplified":"求小得，未出中也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_436","chapterId":"ch_work_dk_29","textTraditional":"來之坎坎，終無功也。","textSimplified":"来之坎坎，终无功也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_437","chapterId":"ch_work_dk_29","textTraditional":"樽酒簋貳，刚柔际也。","textSimplified":"樽酒簋贰，刚柔际也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_438","chapterId":"ch_work_dk_29","textTraditional":"坎不盈，中未大也。","textSimplified":"坎不盈，中未大也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_439","chapterId":"ch_work_dk_29","textTraditional":"上六失道，凶三歲也。","textSimplified":"上六失道，凶三岁也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_440","chapterId":"ch_work_dk_30","textTraditional":"離：利貞，亨。畜牝牛，吉。","textSimplified":"离：利贞，亨。畜牝牛，吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_441","chapterId":"ch_work_dk_30","textTraditional":"離，麗也；日月麗乎天，百穀草木麗乎土，重明以麗乎正，乃化成天下。柔麗乎中正，故亨；是以畜牝牛吉也。","textSimplified":"离，丽也；日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正，故亨；是以畜牝牛吉也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_442","chapterId":"ch_work_dk_30","textTraditional":"明兩作離，大人以繼明照於四方。","textSimplified":"明两作离，大人以继明照于四方。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_443","chapterId":"ch_work_dk_30","textTraditional":"初九：履错然，敬之無咎。","textSimplified":"初九：履错然，敬之无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_444","chapterId":"ch_work_dk_30","textTraditional":"六二：黃離，元吉。","textSimplified":"六二：黄离，元吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_445","chapterId":"ch_work_dk_30","textTraditional":"九三：日昃之離，不鼓缶而歌，則大耋之嗟，凶。","textSimplified":"九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_446","chapterId":"ch_work_dk_30","textTraditional":"九四：突如其來如，焚如，死如，弃如。","textSimplified":"九四：突如其来如，焚如，死如，弃如。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_447","chapterId":"ch_work_dk_30","textTraditional":"六五：出涕沱若，戚嗟若，吉。","textSimplified":"六五：出涕沱若，戚嗟若，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_448","chapterId":"ch_work_dk_30","textTraditional":"上九：王用出征，有嘉折首，獲匪其丑，無咎。","textSimplified":"上九：王用出征，有嘉折首，获匪其丑，无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_449","chapterId":"ch_work_dk_30","textTraditional":"履错之敬，以辟咎也。","textSimplified":"履错之敬，以辟咎也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_450","chapterId":"ch_work_dk_30","textTraditional":"黃離元吉，得中道也。","textSimplified":"黄离元吉，得中道也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_451","chapterId":"ch_work_dk_30","textTraditional":"日昃之離，何可久也。","textSimplified":"日昃之离，何可久也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_452","chapterId":"ch_work_dk_30","textTraditional":"突如其來如，無所容也。","textSimplified":"突如其来如，无所容也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_453","chapterId":"ch_work_dk_30","textTraditional":"六五之吉，離王公也。","textSimplified":"六五之吉，离王公也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_454","chapterId":"ch_work_dk_30","textTraditional":"王用出征，以正邦也。","textSimplified":"王用出征，以正邦也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_455","chapterId":"ch_work_dk_31","textTraditional":"鹹，亨，利貞，取女吉。","textSimplified":"咸，亨，利贞，取女吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_456","chapterId":"ch_work_dk_31","textTraditional":"鹹，感也。柔上而刚下，二氣感應以相與，止而說，男下女，是以亨利貞，取女吉也。天地感而萬物化生，聖人感人心而天下和平，觀其所感，而天地萬物之情可見矣。","textSimplified":"咸，感也。柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平，观其所感，而天地万物之情可见矣。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_457","chapterId":"ch_work_dk_31","textTraditional":"山上有泽，鹹，君子以虛受人。","textSimplified":"山上有泽，咸，君子以虚受人。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_458","chapterId":"ch_work_dk_31","textTraditional":"初六，鹹其拇。","textSimplified":"初六，咸其拇。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_459","chapterId":"ch_work_dk_31","textTraditional":"六二，鹹其腓，凶，居吉。","textSimplified":"六二，咸其腓，凶，居吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_460","chapterId":"ch_work_dk_31","textTraditional":"九三，鹹其股，執其隨，往吝。","textSimplified":"九三，咸其股，执其随，往吝。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_461","chapterId":"ch_work_dk_31","textTraditional":"九四，貞吉，悔亡，憧憧往來，朋從爾思。","textSimplified":"九四，贞吉，悔亡，憧憧往来，朋从尔思。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_462","chapterId":"ch_work_dk_31","textTraditional":"九五，鹹其脢，無悔。","textSimplified":"九五，咸其脢，无悔。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_463","chapterId":"ch_work_dk_31","textTraditional":"上六，鹹其辅頰舌。","textSimplified":"上六，咸其辅颊舌。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_464","chapterId":"ch_work_dk_31","textTraditional":"鹹其拇，志在外也。","textSimplified":"咸其拇，志在外也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_465","chapterId":"ch_work_dk_31","textTraditional":"雖凶居吉，順不害也。","textSimplified":"虽凶居吉，顺不害也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_466","chapterId":"ch_work_dk_31","textTraditional":"鹹其股，亦不處也。志在隨人，所執下也。","textSimplified":"咸其股，亦不处也。志在随人，所执下也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_467","chapterId":"ch_work_dk_31","textTraditional":"貞吉悔亡，未感害也。憧憧往來，未光大也。","textSimplified":"贞吉悔亡，未感害也。憧憧往来，未光大也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_468","chapterId":"ch_work_dk_31","textTraditional":"鹹其脢，志末也。","textSimplified":"咸其脢，志末也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_469","chapterId":"ch_work_dk_31","textTraditional":"鹹其辅頰舌，滕口說也。","textSimplified":"咸其辅颊舌，滕口说也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_470","chapterId":"ch_work_dk_32","textTraditional":"恒：亨，無咎，利貞，利有攸往。","textSimplified":"恒：亨，无咎，利贞，利有攸往。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_471","chapterId":"ch_work_dk_32","textTraditional":"恒，久也。刚上而柔下，雷風相與，巽而動，刚柔皆應，恒。恒亨無咎，利貞；久於其道也，天地之道，恒久而不已也。利有攸往，終則有始也。日月得天，而能久照，四時变化，而能久成，聖人久於其道，而天下化成；觀其所恒，而天地萬物之情可見矣！","textSimplified":"恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。恒亨无咎，利贞；久于其道也，天地之道，恒久而不已也。利有攸往，终则有始也。日月得天，而能久照，四时变化，而能久成，圣人久于其道，而天下化成；观其所恒，而天地万物之情可见矣！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_472","chapterId":"ch_work_dk_32","textTraditional":"雷風，恒；君子以立不易方。","textSimplified":"雷风，恒；君子以立不易方。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_473","chapterId":"ch_work_dk_32","textTraditional":"初六：浚恒，貞凶，無攸利。","textSimplified":"初六：浚恒，贞凶，无攸利。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_474","chapterId":"ch_work_dk_32","textTraditional":"九二：悔亡。","textSimplified":"九二：悔亡。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_475","chapterId":"ch_work_dk_32","textTraditional":"九三：不恒其德，或承之羞，貞吝。","textSimplified":"九三：不恒其德，或承之羞，贞吝。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_476","chapterId":"ch_work_dk_32","textTraditional":"九四：田無禽。","textSimplified":"九四：田无禽。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_477","chapterId":"ch_work_dk_32","textTraditional":"六五：恒其德，貞，婦人吉，夫子凶。","textSimplified":"六五：恒其德，贞，妇人吉，夫子凶。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_478","chapterId":"ch_work_dk_32","textTraditional":"上六：振恒，凶。","textSimplified":"上六：振恒，凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_479","chapterId":"ch_work_dk_32","textTraditional":"浚恒之凶，始求深也。","textSimplified":"浚恒之凶，始求深也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_480","chapterId":"ch_work_dk_32","textTraditional":"九二悔亡，能久中也。","textSimplified":"九二悔亡，能久中也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_481","chapterId":"ch_work_dk_32","textTraditional":"不恒其德，無所容也。","textSimplified":"不恒其德，无所容也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_482","chapterId":"ch_work_dk_32","textTraditional":"久非其位，安得禽也。","textSimplified":"久非其位，安得禽也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_483","chapterId":"ch_work_dk_32","textTraditional":"婦人貞吉，從一而終也。夫子製義，從婦凶也。","textSimplified":"妇人贞吉，从一而终也。夫子制义，从妇凶也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_484","chapterId":"ch_work_dk_32","textTraditional":"振恒在上，大無功也。","textSimplified":"振恒在上，大无功也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_485","chapterId":"ch_work_dk_33","textTraditional":"遯：亨，小利貞。","textSimplified":"遯：亨，小利贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_486","chapterId":"ch_work_dk_33","textTraditional":"遯亨，遯而亨也。刚當位而應，與時行也。小利貞，浸而長也。遯之時義大矣哉！","textSimplified":"遯亨，遯而亨也。刚当位而应，与时行也。小利贞，浸而长也。遯之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_487","chapterId":"ch_work_dk_33","textTraditional":"天下有山，遯；君子以遠小人，不惡而嚴。","textSimplified":"天下有山，遯；君子以远小人，不恶而严。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_488","chapterId":"ch_work_dk_33","textTraditional":"初六：遯尾，厲，勿用有攸往。","textSimplified":"初六：遯尾，厉，勿用有攸往。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_489","chapterId":"ch_work_dk_33","textTraditional":"六二：執之用黃牛之革，莫之勝說。","textSimplified":"六二：执之用黄牛之革，莫之胜说。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_490","chapterId":"ch_work_dk_33","textTraditional":"九三：系遯，有疾厲，畜臣妾吉。","textSimplified":"九三：系遯，有疾厉，畜臣妾吉。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_491","chapterId":"ch_work_dk_33","textTraditional":"九四：好遯，君子吉，小人否。","textSimplified":"九四：好遯，君子吉，小人否。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_492","chapterId":"ch_work_dk_33","textTraditional":"九五：嘉遯，貞吉。","textSimplified":"九五：嘉遯，贞吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_493","chapterId":"ch_work_dk_33","textTraditional":"上九：肥遯，無不利。","textSimplified":"上九：肥遯，无不利。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_494","chapterId":"ch_work_dk_33","textTraditional":"遯尾之厲，不往何灾也。","textSimplified":"遯尾之厉，不往何灾也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_495","chapterId":"ch_work_dk_33","textTraditional":"執用黃牛，固志也。","textSimplified":"执用黄牛，固志也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_496","chapterId":"ch_work_dk_33","textTraditional":"系遯之厲，有疾憊也。畜臣妾吉，不可大事也。","textSimplified":"系遯之厉，有疾惫也。畜臣妾吉，不可大事也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_497","chapterId":"ch_work_dk_33","textTraditional":"君子好遯，小人否也。","textSimplified":"君子好遯，小人否也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_498","chapterId":"ch_work_dk_33","textTraditional":"嘉遯貞吉，以正志也。","textSimplified":"嘉遯贞吉，以正志也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_499","chapterId":"ch_work_dk_33","textTraditional":"肥遯，無不利；無所疑也。","textSimplified":"肥遯，无不利；无所疑也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_500","chapterId":"ch_work_dk_34","textTraditional":"大壮：利貞","textSimplified":"大壮：利贞","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_501","chapterId":"ch_work_dk_34","textTraditional":"大壮，大者壮也。刚以動，故壮。大壮利貞；大者正也。正大而天地之情可見矣！","textSimplified":"大壮，大者壮也。刚以动，故壮。大壮利贞；大者正也。正大而天地之情可见矣！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_502","chapterId":"ch_work_dk_34","textTraditional":"雷在天上，大壮；君子以非禮勿履。","textSimplified":"雷在天上，大壮；君子以非礼勿履。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_503","chapterId":"ch_work_dk_34","textTraditional":"初九：壮於趾，征凶，有孚。","textSimplified":"初九：壮于趾，征凶，有孚。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_504","chapterId":"ch_work_dk_34","textTraditional":"九二：貞吉。","textSimplified":"九二：贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_505","chapterId":"ch_work_dk_34","textTraditional":"九三：小人用壮，君子用罔，貞厲。羝羊觸藩，羸其角。","textSimplified":"九三：小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_506","chapterId":"ch_work_dk_34","textTraditional":"九四：貞吉悔亡，藩决不羸，壮於大舆之輹。","textSimplified":"九四：贞吉悔亡，藩决不羸，壮于大舆之輹。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_507","chapterId":"ch_work_dk_34","textTraditional":"六五：丧羊於易，無悔。","textSimplified":"六五：丧羊于易，无悔。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_508","chapterId":"ch_work_dk_34","textTraditional":"上六：羝羊觸藩，不能退，不能遂，無攸利，艱則吉。","textSimplified":"上六：羝羊触藩，不能退，不能遂，无攸利，艰则吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_509","chapterId":"ch_work_dk_34","textTraditional":"壮於趾，其孚窮也。","textSimplified":"壮于趾，其孚穷也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_510","chapterId":"ch_work_dk_34","textTraditional":"九二貞吉，以中也。","textSimplified":"九二贞吉，以中也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_511","chapterId":"ch_work_dk_34","textTraditional":"小人用壮，君子罔也。","textSimplified":"小人用壮，君子罔也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_512","chapterId":"ch_work_dk_34","textTraditional":"藩决不羸，尚往也。","textSimplified":"藩决不羸，尚往也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_513","chapterId":"ch_work_dk_34","textTraditional":"丧羊於易，位不當也。","textSimplified":"丧羊于易，位不当也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_514","chapterId":"ch_work_dk_34","textTraditional":"不能退，不能遂，不祥也。艱則吉，咎不長也。","textSimplified":"不能退，不能遂，不祥也。艰则吉，咎不长也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_515","chapterId":"ch_work_dk_35","textTraditional":"晉：康侯用錫馬蕃庶，晝日三接。","textSimplified":"晋：康侯用锡马蕃庶，昼日三接。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_516","chapterId":"ch_work_dk_35","textTraditional":"晉，進也。明出地上，順而麗乎大明，柔進而上行。是以康侯用錫馬蕃庶，晝日三接也。","textSimplified":"晋，进也。明出地上，顺而丽乎大明，柔进而上行。是以康侯用锡马蕃庶，昼日三接也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_517","chapterId":"ch_work_dk_35","textTraditional":"明出地上，晉；君子以自昭明德。","textSimplified":"明出地上，晋；君子以自昭明德。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_518","chapterId":"ch_work_dk_35","textTraditional":"初六：晉如，摧如，貞吉。罔孚，裕無咎。","textSimplified":"初六：晋如，摧如，贞吉。罔孚，裕无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_519","chapterId":"ch_work_dk_35","textTraditional":"六二：晉如，愁如，貞吉。受茲介福，於其王母。","textSimplified":"六二：晋如，愁如，贞吉。受兹介福，于其王母。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_520","chapterId":"ch_work_dk_35","textTraditional":"六三：眾允，悔亡。","textSimplified":"六三：众允，悔亡。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_521","chapterId":"ch_work_dk_35","textTraditional":"九四：晉如硕鼠，貞厲。","textSimplified":"九四：晋如硕鼠，贞厉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_522","chapterId":"ch_work_dk_35","textTraditional":"六五：悔亡，失得勿恤，往吉，無不利。","textSimplified":"六五：悔亡，失得勿恤，往吉，无不利。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_523","chapterId":"ch_work_dk_35","textTraditional":"上九：晉其角，維用伐邑，厲吉無咎，貞吝。","textSimplified":"上九：晋其角，维用伐邑，厉吉无咎，贞吝。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_524","chapterId":"ch_work_dk_35","textTraditional":"晉如，摧如；獨行正也。裕無咎；未受命也。","textSimplified":"晋如，摧如；独行正也。裕无咎；未受命也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_525","chapterId":"ch_work_dk_35","textTraditional":"受之介福，以中正也。","textSimplified":"受之介福，以中正也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_526","chapterId":"ch_work_dk_35","textTraditional":"眾允之，志上行也。","textSimplified":"众允之，志上行也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_527","chapterId":"ch_work_dk_35","textTraditional":"硕鼠貞厲，位不當也。","textSimplified":"硕鼠贞厉，位不当也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_528","chapterId":"ch_work_dk_35","textTraditional":"失得勿恤，往有慶也。","textSimplified":"失得勿恤，往有庆也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_529","chapterId":"ch_work_dk_35","textTraditional":"維用伐邑，道未光也。","textSimplified":"维用伐邑，道未光也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_530","chapterId":"ch_work_dk_36","textTraditional":"明夷：利艱貞。","textSimplified":"明夷：利艰贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_531","chapterId":"ch_work_dk_36","textTraditional":"明入地中，明夷。內文明而外柔順，以蒙大難，文王以之。利艱貞，晦其明也，內難而能正其志，箕子以之。","textSimplified":"明入地中，明夷。内文明而外柔顺，以蒙大难，文王以之。利艰贞，晦其明也，内难而能正其志，箕子以之。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_532","chapterId":"ch_work_dk_36","textTraditional":"明入地中，明夷；君子以莅眾，用晦而明。","textSimplified":"明入地中，明夷；君子以莅众，用晦而明。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_533","chapterId":"ch_work_dk_36","textTraditional":"初九：明夷於飛，垂其翼。君子於行，三日不食，有攸往，主人有言。","textSimplified":"初九：明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_534","chapterId":"ch_work_dk_36","textTraditional":"六二：明夷，夷於左股，用拯馬壮，吉。","textSimplified":"六二：明夷，夷于左股，用拯马壮，吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_535","chapterId":"ch_work_dk_36","textTraditional":"九三：明夷於南狩，得其大首，不可疾貞。","textSimplified":"九三：明夷于南狩，得其大首，不可疾贞。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_536","chapterId":"ch_work_dk_36","textTraditional":"六四：入於左腹，獲明夷之心，出於門庭。","textSimplified":"六四：入于左腹，获明夷之心，出于门庭。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_537","chapterId":"ch_work_dk_36","textTraditional":"六五：箕子之明夷，利貞。","textSimplified":"六五：箕子之明夷，利贞。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_538","chapterId":"ch_work_dk_36","textTraditional":"上六：不明晦，初登於天，後入於地。","textSimplified":"上六：不明晦，初登于天，后入于地。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_539","chapterId":"ch_work_dk_36","textTraditional":"君子於行，義不食也。","textSimplified":"君子于行，义不食也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_540","chapterId":"ch_work_dk_36","textTraditional":"六二之吉，順以則也。","textSimplified":"六二之吉，顺以则也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_541","chapterId":"ch_work_dk_36","textTraditional":"南狩之志，乃大得也。","textSimplified":"南狩之志，乃大得也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_542","chapterId":"ch_work_dk_36","textTraditional":"入於左腹，獲心意也。","textSimplified":"入于左腹，获心意也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_543","chapterId":"ch_work_dk_36","textTraditional":"箕子之貞，明不可息也。","textSimplified":"箕子之贞，明不可息也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_544","chapterId":"ch_work_dk_36","textTraditional":"初登於天，照四國也。後入於地，失則也。","textSimplified":"初登于天，照四国也。后入于地，失则也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_545","chapterId":"ch_work_dk_37","textTraditional":"家人：利女貞。","textSimplified":"家人：利女贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_546","chapterId":"ch_work_dk_37","textTraditional":"家人，女正位乎內，男正位乎外，男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父，子子，兄兄，弟弟，夫夫，婦婦，而家道正；正家而天下定矣。","textSimplified":"家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正；正家而天下定矣。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_547","chapterId":"ch_work_dk_37","textTraditional":"風自火出，家人；君子以言有物，而行有恒。","textSimplified":"风自火出，家人；君子以言有物，而行有恒。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_548","chapterId":"ch_work_dk_37","textTraditional":"初九：閒有家，悔亡。","textSimplified":"初九：闲有家，悔亡。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_549","chapterId":"ch_work_dk_37","textTraditional":"六二：無攸遂，在中饋，貞吉。","textSimplified":"六二：无攸遂，在中馈，贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_550","chapterId":"ch_work_dk_37","textTraditional":"九三：家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。","textSimplified":"九三：家人嗃嗃，悔厉吉；妇子嘻嘻，终吝。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_551","chapterId":"ch_work_dk_37","textTraditional":"六四：富家，大吉。","textSimplified":"六四：富家，大吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_552","chapterId":"ch_work_dk_37","textTraditional":"九五：王假有家，勿恤，往吉。","textSimplified":"九五：王假有家，勿恤，往吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_553","chapterId":"ch_work_dk_37","textTraditional":"上九：有孚威如，終吉。","textSimplified":"上九：有孚威如，终吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_554","chapterId":"ch_work_dk_37","textTraditional":"閒有家，志未变也。","textSimplified":"闲有家，志未变也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_555","chapterId":"ch_work_dk_37","textTraditional":"六二之吉，順以巽也。","textSimplified":"六二之吉，顺以巽也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_556","chapterId":"ch_work_dk_37","textTraditional":"家人嗃嗃，未失也；婦子嘻嘻，失家節也。","textSimplified":"家人嗃嗃，未失也；妇子嘻嘻，失家节也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_557","chapterId":"ch_work_dk_37","textTraditional":"富家大吉，順在位也。","textSimplified":"富家大吉，顺在位也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_558","chapterId":"ch_work_dk_37","textTraditional":"王假有家，交相愛也。","textSimplified":"王假有家，交相爱也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_559","chapterId":"ch_work_dk_37","textTraditional":"威如之吉，反身之謂也。","textSimplified":"威如之吉，反身之谓也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_560","chapterId":"ch_work_dk_38","textTraditional":"睽：小事吉。","textSimplified":"睽：小事吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_561","chapterId":"ch_work_dk_38","textTraditional":"睽，火動而上，泽動而下；二女同居，其志不同行；說而麗乎明，柔進而上行，得中而應乎刚；是以小事吉。天地睽，而其事同也；男女睽，而其志通也；萬物睽，而其事類也；睽之時用大矣哉！","textSimplified":"睽，火动而上，泽动而下；二女同居，其志不同行；说而丽乎明，柔进而上行，得中而应乎刚；是以小事吉。天地睽，而其事同也；男女睽，而其志通也；万物睽，而其事类也；睽之时用大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_562","chapterId":"ch_work_dk_38","textTraditional":"上火下泽，睽；君子以同而異。","textSimplified":"上火下泽，睽；君子以同而异。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_563","chapterId":"ch_work_dk_38","textTraditional":"初九：悔亡，丧馬勿逐，自复；見惡人無咎。","textSimplified":"初九：悔亡，丧马勿逐，自复；见恶人无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_564","chapterId":"ch_work_dk_38","textTraditional":"九二：遇主於巷，無咎。","textSimplified":"九二：遇主于巷，无咎。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_565","chapterId":"ch_work_dk_38","textTraditional":"六三：見舆曳，其牛掣，其人天且劓，無初有終。","textSimplified":"六三：见舆曳，其牛掣，其人天且劓，无初有终。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_566","chapterId":"ch_work_dk_38","textTraditional":"九四：睽孤，遇元夫，交孚，厲無咎。","textSimplified":"九四：睽孤，遇元夫，交孚，厉无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_567","chapterId":"ch_work_dk_38","textTraditional":"六五：悔亡，厥宗噬膚，往何咎。","textSimplified":"六五：悔亡，厥宗噬肤，往何咎。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_568","chapterId":"ch_work_dk_38","textTraditional":"上九：睽孤，見豕負涂，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。","textSimplified":"上九：睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_569","chapterId":"ch_work_dk_38","textTraditional":"見惡人，以辟咎也。","textSimplified":"见恶人，以辟咎也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_570","chapterId":"ch_work_dk_38","textTraditional":"遇主於巷，未失道也。","textSimplified":"遇主于巷，未失道也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_571","chapterId":"ch_work_dk_38","textTraditional":"見舆曳，位不當也。無初有終，遇刚也。","textSimplified":"见舆曳，位不当也。无初有终，遇刚也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_572","chapterId":"ch_work_dk_38","textTraditional":"交孚無咎，志行也。","textSimplified":"交孚无咎，志行也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_573","chapterId":"ch_work_dk_38","textTraditional":"厥宗噬膚，往有慶也。","textSimplified":"厥宗噬肤，往有庆也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_574","chapterId":"ch_work_dk_38","textTraditional":"遇雨之吉，群疑亡也。","textSimplified":"遇雨之吉，群疑亡也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_575","chapterId":"ch_work_dk_39","textTraditional":"蹇：利西南，不利東北；利見大人，貞吉。","textSimplified":"蹇：利西南，不利东北；利见大人，贞吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_576","chapterId":"ch_work_dk_39","textTraditional":"蹇，難也，险在前也。見险而能止，知矣哉！蹇利西南，往得中也；不利東北，其道窮也。利見大人，往有功也。當位貞吉，以正邦也。蹇之時用大矣哉！","textSimplified":"蹇，难也，险在前也。见险而能止，知矣哉！蹇利西南，往得中也；不利东北，其道穷也。利见大人，往有功也。当位贞吉，以正邦也。蹇之时用大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_577","chapterId":"ch_work_dk_39","textTraditional":"山上有水，蹇；君子以反身修德。","textSimplified":"山上有水，蹇；君子以反身修德。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_578","chapterId":"ch_work_dk_39","textTraditional":"初六：往蹇，來譽。","textSimplified":"初六：往蹇，来誉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_579","chapterId":"ch_work_dk_39","textTraditional":"六二：王臣蹇蹇，匪躬之故。","textSimplified":"六二：王臣蹇蹇，匪躬之故。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_580","chapterId":"ch_work_dk_39","textTraditional":"九三：往蹇來反。","textSimplified":"九三：往蹇来反。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_581","chapterId":"ch_work_dk_39","textTraditional":"六四：往蹇來連。","textSimplified":"六四：往蹇来连。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_582","chapterId":"ch_work_dk_39","textTraditional":"九五：大蹇朋來。","textSimplified":"九五：大蹇朋来。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_583","chapterId":"ch_work_dk_39","textTraditional":"上六：往蹇來硕，吉；利見大人。","textSimplified":"上六：往蹇来硕，吉；利见大人。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_584","chapterId":"ch_work_dk_39","textTraditional":"往蹇來譽，宜待也。","textSimplified":"往蹇来誉，宜待也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_585","chapterId":"ch_work_dk_39","textTraditional":"王臣蹇蹇，終無尤也。","textSimplified":"王臣蹇蹇，终无尤也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_586","chapterId":"ch_work_dk_39","textTraditional":"往蹇來反，內喜之也。","textSimplified":"往蹇来反，内喜之也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_587","chapterId":"ch_work_dk_39","textTraditional":"往蹇來連，當位實也。","textSimplified":"往蹇来连，当位实也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_588","chapterId":"ch_work_dk_39","textTraditional":"大蹇朋來，以中節也。","textSimplified":"大蹇朋来，以中节也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_589","chapterId":"ch_work_dk_39","textTraditional":"往蹇來硕，志在內也。利見大人，以從貴也。","textSimplified":"往蹇来硕，志在内也。利见大人，以从贵也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_590","chapterId":"ch_work_dk_40","textTraditional":"解：利西南，無所往，其來复吉。有攸往，夙吉。","textSimplified":"解：利西南，无所往，其来复吉。有攸往，夙吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_591","chapterId":"ch_work_dk_40","textTraditional":"解，险以動，動而免乎险，解。解利西南，往得眾也。其來复吉，乃得中也。有攸往夙吉，往有功也。天地解，而雷雨作，雷雨作，而百果草木皆甲坼，解之時義大矣哉！","textSimplified":"解，险以动，动而免乎险，解。解利西南，往得众也。其来复吉，乃得中也。有攸往夙吉，往有功也。天地解，而雷雨作，雷雨作，而百果草木皆甲坼，解之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_592","chapterId":"ch_work_dk_40","textTraditional":"雷雨作，解；君子以赦過宥罪。","textSimplified":"雷雨作，解；君子以赦过宥罪。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_593","chapterId":"ch_work_dk_40","textTraditional":"初六：無咎。","textSimplified":"初六：无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_594","chapterId":"ch_work_dk_40","textTraditional":"九二：田獲三狐，得黃矢，貞吉。","textSimplified":"九二：田获三狐，得黄矢，贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_595","chapterId":"ch_work_dk_40","textTraditional":"六三：負且乘，致寇至，貞吝。","textSimplified":"六三：负且乘，致寇至，贞吝。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_596","chapterId":"ch_work_dk_40","textTraditional":"九四：解而拇，朋至斯孚。","textSimplified":"九四：解而拇，朋至斯孚。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_597","chapterId":"ch_work_dk_40","textTraditional":"六五：君子維有解，吉；有孚於小人。","textSimplified":"六五：君子维有解，吉；有孚于小人。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_598","chapterId":"ch_work_dk_40","textTraditional":"上六：公用射隼於高墉之上，獲之，無不利。","textSimplified":"上六：公用射隼于高墉之上，获之，无不利。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_599","chapterId":"ch_work_dk_40","textTraditional":"刚柔之际，義無咎也。","textSimplified":"刚柔之际，义无咎也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_600","chapterId":"ch_work_dk_40","textTraditional":"九二貞吉，得中道也。","textSimplified":"九二贞吉，得中道也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_601","chapterId":"ch_work_dk_40","textTraditional":"負且乘，亦可丑也，自我致戎，又誰咎也。","textSimplified":"负且乘，亦可丑也，自我致戎，又谁咎也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_602","chapterId":"ch_work_dk_40","textTraditional":"解而拇，未當位也。","textSimplified":"解而拇，未当位也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_603","chapterId":"ch_work_dk_40","textTraditional":"君子有解，小人退也。","textSimplified":"君子有解，小人退也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_604","chapterId":"ch_work_dk_40","textTraditional":"公用射隼，以解悖也。","textSimplified":"公用射隼，以解悖也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_605","chapterId":"ch_work_dk_41","textTraditional":"損：有孚，元吉，無咎，可貞，利有攸往。曷之用，二簋可用享。","textSimplified":"损：有孚，元吉，无咎，可贞，利有攸往。曷之用，二簋可用享。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_606","chapterId":"ch_work_dk_41","textTraditional":"損，損下益上，其道上行。損而有孚，元吉，無咎，可貞，利有攸往。曷之用？二簋可用享；二簋應有時。損刚益柔有時，損益盈虛，與時偕行。","textSimplified":"损，损下益上，其道上行。损而有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享；二簋应有时。损刚益柔有时，损益盈虚，与时偕行。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_607","chapterId":"ch_work_dk_41","textTraditional":"山下有泽，損；君子以懲忿窒欲。","textSimplified":"山下有泽，损；君子以惩忿窒欲。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_608","chapterId":"ch_work_dk_41","textTraditional":"初九：巳事遄往，無咎，酌損之。","textSimplified":"初九：巳事遄往，无咎，酌损之。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_609","chapterId":"ch_work_dk_41","textTraditional":"九二：利貞，征凶，弗損，益之。","textSimplified":"九二：利贞，征凶，弗损，益之。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_610","chapterId":"ch_work_dk_41","textTraditional":"六三：三人行，則損一人；一人行，則得其友。","textSimplified":"六三：三人行，则损一人；一人行，则得其友。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_611","chapterId":"ch_work_dk_41","textTraditional":"六四：損其疾，使遄有喜，無咎。","textSimplified":"六四：损其疾，使遄有喜，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_612","chapterId":"ch_work_dk_41","textTraditional":"六五：或益之，十朋之龟弗克违，元吉。","textSimplified":"六五：或益之，十朋之龟弗克违，元吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_613","chapterId":"ch_work_dk_41","textTraditional":"上九：弗損益之，無咎，貞吉，有攸往，得臣無家。","textSimplified":"上九：弗损益之，无咎，贞吉，有攸往，得臣无家。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_614","chapterId":"ch_work_dk_41","textTraditional":"巳事遄往，尚合志也。","textSimplified":"巳事遄往，尚合志也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_615","chapterId":"ch_work_dk_41","textTraditional":"九二利貞，中以為志也。","textSimplified":"九二利贞，中以为志也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_616","chapterId":"ch_work_dk_41","textTraditional":"一人行，三則疑也。","textSimplified":"一人行，三则疑也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_617","chapterId":"ch_work_dk_41","textTraditional":"損其疾，亦可喜也。","textSimplified":"损其疾，亦可喜也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_618","chapterId":"ch_work_dk_41","textTraditional":"六五元吉，自上佑也。","textSimplified":"六五元吉，自上佑也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_619","chapterId":"ch_work_dk_41","textTraditional":"弗損益之，大得志也。","textSimplified":"弗损益之，大得志也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_620","chapterId":"ch_work_dk_42","textTraditional":"益：利有攸往，利涉大川。","textSimplified":"益：利有攸往，利涉大川。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_621","chapterId":"ch_work_dk_42","textTraditional":"益，損上益下，民說無疆，自上下下，其道大光。利有攸往，中正有慶。利涉大川，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。","textSimplified":"益，损上益下，民说无疆，自上下下，其道大光。利有攸往，中正有庆。利涉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_622","chapterId":"ch_work_dk_42","textTraditional":"風雷，益；君子以見善則遷，有過則改。","textSimplified":"风雷，益；君子以见善则迁，有过则改。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_623","chapterId":"ch_work_dk_42","textTraditional":"初九：利用為大作，元吉，無咎。","textSimplified":"初九：利用为大作，元吉，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_624","chapterId":"ch_work_dk_42","textTraditional":"六二：或益之，十朋之龟弗克违，永貞吉。王用享於帝，吉。","textSimplified":"六二：或益之，十朋之龟弗克违，永贞吉。王用享于帝，吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_625","chapterId":"ch_work_dk_42","textTraditional":"六三：益之用凶事，無咎。有孚中行，告公用圭。","textSimplified":"六三：益之用凶事，无咎。有孚中行，告公用圭。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_626","chapterId":"ch_work_dk_42","textTraditional":"六四：中行，告公從。利用為依遷國。","textSimplified":"六四：中行，告公从。利用为依迁国。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_627","chapterId":"ch_work_dk_42","textTraditional":"九五：有孚惠心，勿問元吉。有孚惠我德。","textSimplified":"九五：有孚惠心，勿问元吉。有孚惠我德。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_628","chapterId":"ch_work_dk_42","textTraditional":"上九：莫益之，或击之，立心勿恒，凶。","textSimplified":"上九：莫益之，或击之，立心勿恒，凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_629","chapterId":"ch_work_dk_42","textTraditional":"元吉無咎，下不厚事也。","textSimplified":"元吉无咎，下不厚事也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_630","chapterId":"ch_work_dk_42","textTraditional":"或益之，自外來也。","textSimplified":"或益之，自外来也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_631","chapterId":"ch_work_dk_42","textTraditional":"益用凶事，固有之也。","textSimplified":"益用凶事，固有之也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_632","chapterId":"ch_work_dk_42","textTraditional":"告公從，以益志也。","textSimplified":"告公从，以益志也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_633","chapterId":"ch_work_dk_42","textTraditional":"有孚惠心，勿問之矣。惠我德，大得志也。","textSimplified":"有孚惠心，勿问之矣。惠我德，大得志也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_634","chapterId":"ch_work_dk_42","textTraditional":"莫益之，偏辭也。或击之，自外來也。","textSimplified":"莫益之，偏辞也。或击之，自外来也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_635","chapterId":"ch_work_dk_43","textTraditional":"夬：扬於王庭，孚號，有厲，告自邑，不利即戎，利有攸往。","textSimplified":"夬：扬于王庭，孚号，有厉，告自邑，不利即戎，利有攸往。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_636","chapterId":"ch_work_dk_43","textTraditional":"夬，决也，刚决柔也。健而說，决而和，扬於王庭，柔乘五刚也。孚號有厲，其危乃光也。告自邑，不利即戎，所尚乃窮也。利有攸往，刚長乃終也。","textSimplified":"夬，决也，刚决柔也。健而说，决而和，扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_637","chapterId":"ch_work_dk_43","textTraditional":"泽上於天，夬；君子以施祿及下，居德則忌。","textSimplified":"泽上于天，夬；君子以施禄及下，居德则忌。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_638","chapterId":"ch_work_dk_43","textTraditional":"初九：壮於前趾，往不勝為咎。","textSimplified":"初九：壮于前趾，往不胜为咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_639","chapterId":"ch_work_dk_43","textTraditional":"九二：惕號，莫夜有戎，勿恤。","textSimplified":"九二：惕号，莫夜有戎，勿恤。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_640","chapterId":"ch_work_dk_43","textTraditional":"九三：壮於頄，有凶。君子夬夬，獨行，遇雨，若濡，有慍，無咎。   ","textSimplified":"九三：壮于頄，有凶。君子夬夬，独行，遇雨，若濡，有愠，无咎。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_641","chapterId":"ch_work_dk_43","textTraditional":"九四：臀無膚，其行次且。牵羊悔亡，聞言不信。","textSimplified":"九四：臀无肤，其行次且。牵羊悔亡，闻言不信。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_642","chapterId":"ch_work_dk_43","textTraditional":"九五：苋陆夬夬，中行無咎。","textSimplified":"九五：苋陆夬夬，中行无咎。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_643","chapterId":"ch_work_dk_43","textTraditional":"上六：無號，終有凶。","textSimplified":"上六：无号，终有凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_644","chapterId":"ch_work_dk_43","textTraditional":"不勝而往，咎也。","textSimplified":"不胜而往，咎也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_645","chapterId":"ch_work_dk_43","textTraditional":"莫夜有戎，得中道也。","textSimplified":"莫夜有戎，得中道也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_646","chapterId":"ch_work_dk_43","textTraditional":"君子夬夬，終無咎也。","textSimplified":"君子夬夬，终无咎也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_647","chapterId":"ch_work_dk_43","textTraditional":"其行次且，位不當也。聞言不信，聰不明也。","textSimplified":"其行次且，位不当也。闻言不信，聪不明也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_648","chapterId":"ch_work_dk_43","textTraditional":"中行無咎，中未光也。","textSimplified":"中行无咎，中未光也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_649","chapterId":"ch_work_dk_43","textTraditional":"無號之凶，終不可長也。","textSimplified":"无号之凶，终不可长也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_650","chapterId":"ch_work_dk_44","textTraditional":"姤：女壮，勿用取女。","textSimplified":"姤：女壮，勿用取女。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_651","chapterId":"ch_work_dk_44","textTraditional":"姤，遇也，柔遇刚也。勿用取女，不可與長也。天地相遇，品物鹹章也。刚遇中正，天下大行也。姤之時義大矣哉！","textSimplified":"姤，遇也，柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_652","chapterId":"ch_work_dk_44","textTraditional":"天下有風，姤；後以施命誥四方。","textSimplified":"天下有风，姤；后以施命诰四方。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_653","chapterId":"ch_work_dk_44","textTraditional":"初六：系於金柅，貞吉，有攸往，見凶，羸豕孚踟躅。","textSimplified":"初六：系于金柅，贞吉，有攸往，见凶，羸豕孚踟躅。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_654","chapterId":"ch_work_dk_44","textTraditional":"九二：包有魚，無咎，不利賓。","textSimplified":"九二：包有鱼，无咎，不利宾。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_655","chapterId":"ch_work_dk_44","textTraditional":"九三：臀無膚，其行次且，厲，無大咎。   ","textSimplified":"九三：臀无肤，其行次且，厉，无大咎。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_656","chapterId":"ch_work_dk_44","textTraditional":"九四：包無魚，起凶。","textSimplified":"九四：包无鱼，起凶。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_657","chapterId":"ch_work_dk_44","textTraditional":"九五：以杞包瓜，含章，有陨自天。九五：以杞包瓜，含章，有陨自天。","textSimplified":"九五：以杞包瓜，含章，有陨自天。九五：以杞包瓜，含章，有陨自天。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_658","chapterId":"ch_work_dk_44","textTraditional":"上九：姤其角，吝，無咎。","textSimplified":"上九：姤其角，吝，无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_659","chapterId":"ch_work_dk_44","textTraditional":"系於金柅，柔道牵也。","textSimplified":"系于金柅，柔道牵也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_660","chapterId":"ch_work_dk_44","textTraditional":"包有魚，義不及賓也。","textSimplified":"包有鱼，义不及宾也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_661","chapterId":"ch_work_dk_44","textTraditional":"其行次且，行未牵也。","textSimplified":"其行次且，行未牵也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_662","chapterId":"ch_work_dk_44","textTraditional":"無魚之凶，遠民也。","textSimplified":"无鱼之凶，远民也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_663","chapterId":"ch_work_dk_44","textTraditional":"九五含章，中正也。有陨自天，志不舍命也。","textSimplified":"九五含章，中正也。有陨自天，志不舍命也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_664","chapterId":"ch_work_dk_44","textTraditional":"姤其角，上窮吝也。","textSimplified":"姤其角，上穷吝也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_665","chapterId":"ch_work_dk_45","textTraditional":"萃：亨。王假有廟，利見大人，亨，利貞。用大牲吉，利有攸往。","textSimplified":"萃：亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_666","chapterId":"ch_work_dk_45","textTraditional":"萃，聚也；順以說，刚中而應，故聚也。王假有廟，致孝享也。利見大人亨，聚以正也。用大牲吉，利有攸往，順天命也。觀其所聚，而天地萬物之情可見矣。","textSimplified":"萃，聚也；顺以说，刚中而应，故聚也。王假有庙，致孝享也。利见大人亨，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_667","chapterId":"ch_work_dk_45","textTraditional":"泽上於地，萃；君子以除戎器，戒不虞。","textSimplified":"泽上于地，萃；君子以除戎器，戒不虞。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_668","chapterId":"ch_work_dk_45","textTraditional":"初六：有孚不終，乃亂乃萃，若號一握為笑，勿恤，往無咎。","textSimplified":"初六：有孚不终，乃乱乃萃，若号一握为笑，勿恤，往无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_669","chapterId":"ch_work_dk_45","textTraditional":"六二：引吉，無咎，孚乃利用禴。","textSimplified":"六二：引吉，无咎，孚乃利用禴。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_670","chapterId":"ch_work_dk_45","textTraditional":"六三：萃如，嗟如，無攸利，往無咎，小吝。   ","textSimplified":"六三：萃如，嗟如，无攸利，往无咎，小吝。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_671","chapterId":"ch_work_dk_45","textTraditional":"九四：大吉，無咎。","textSimplified":"九四：大吉，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_672","chapterId":"ch_work_dk_45","textTraditional":"九五：萃有位，無咎。匪孚，元永貞，悔亡。","textSimplified":"九五：萃有位，无咎。匪孚，元永贞，悔亡。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_673","chapterId":"ch_work_dk_45","textTraditional":"上六：赍咨涕洟，無咎。","textSimplified":"上六：赍咨涕洟，无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_674","chapterId":"ch_work_dk_45","textTraditional":"乃亂乃萃，其志亂也。","textSimplified":"乃乱乃萃，其志乱也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_675","chapterId":"ch_work_dk_45","textTraditional":"引吉無咎，中未变也。","textSimplified":"引吉无咎，中未变也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_676","chapterId":"ch_work_dk_45","textTraditional":"往無咎，上巽也。","textSimplified":"往无咎，上巽也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_677","chapterId":"ch_work_dk_45","textTraditional":"大吉無咎，位不當也。","textSimplified":"大吉无咎，位不当也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_678","chapterId":"ch_work_dk_45","textTraditional":"萃有位，志未光也。","textSimplified":"萃有位，志未光也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_679","chapterId":"ch_work_dk_45","textTraditional":"赍咨涕洟，未安上也。","textSimplified":"赍咨涕洟，未安上也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_680","chapterId":"ch_work_dk_46","textTraditional":"升：元亨，用見大人，勿恤，南征吉。","textSimplified":"升：元亨，用见大人，勿恤，南征吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_681","chapterId":"ch_work_dk_46","textTraditional":"柔以時升，巽而順，刚中而應，是以大亨。用見大人，勿恤；有慶也。南征吉，志行也。","textSimplified":"柔以时升，巽而顺，刚中而应，是以大亨。用见大人，勿恤；有庆也。南征吉，志行也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_682","chapterId":"ch_work_dk_46","textTraditional":"地中生木，升；君子以順德，積小以高大。","textSimplified":"地中生木，升；君子以顺德，积小以高大。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_683","chapterId":"ch_work_dk_46","textTraditional":"初六：允升，大吉。","textSimplified":"初六：允升，大吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_684","chapterId":"ch_work_dk_46","textTraditional":"九二：孚乃利用禴，無咎。","textSimplified":"九二：孚乃利用禴，无咎。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_685","chapterId":"ch_work_dk_46","textTraditional":"九三：升虛邑。   ","textSimplified":"九三：升虚邑。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_686","chapterId":"ch_work_dk_46","textTraditional":"六四：王用亨於岐山，吉無咎。","textSimplified":"六四：王用亨于岐山，吉无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_687","chapterId":"ch_work_dk_46","textTraditional":"六五：貞吉，升階。","textSimplified":"六五：贞吉，升阶。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_688","chapterId":"ch_work_dk_46","textTraditional":"上六：冥升，利於不息之貞。","textSimplified":"上六：冥升，利于不息之贞。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_689","chapterId":"ch_work_dk_46","textTraditional":"允升大吉，上合志也。","textSimplified":"允升大吉，上合志也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_690","chapterId":"ch_work_dk_46","textTraditional":"九二之孚，有喜也。","textSimplified":"九二之孚，有喜也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_691","chapterId":"ch_work_dk_46","textTraditional":"升虛邑，無所疑也。","textSimplified":"升虚邑，无所疑也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_692","chapterId":"ch_work_dk_46","textTraditional":"王用亨於岐山，順事也。","textSimplified":"王用亨于岐山，顺事也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_693","chapterId":"ch_work_dk_46","textTraditional":"貞吉升階，大得志也。","textSimplified":"贞吉升阶，大得志也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_694","chapterId":"ch_work_dk_46","textTraditional":"冥升在上，消不富也。","textSimplified":"冥升在上，消不富也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_695","chapterId":"ch_work_dk_47","textTraditional":"困：亨，貞，大人吉，無咎，有言不信。","textSimplified":"困：亨，贞，大人吉，无咎，有言不信。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_696","chapterId":"ch_work_dk_47","textTraditional":"困，刚掩也。险以說，困而不失其所，亨；其唯君子乎？貞大人吉，以刚中也。有言不信，尚口乃窮也。","textSimplified":"困，刚掩也。险以说，困而不失其所，亨；其唯君子乎？贞大人吉，以刚中也。有言不信，尚口乃穷也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_697","chapterId":"ch_work_dk_47","textTraditional":"泽無水，困；君子以致命遂志。","textSimplified":"泽无水，困；君子以致命遂志。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_698","chapterId":"ch_work_dk_47","textTraditional":"初六：臀困於株木，入於幽穀，三歲不觌。","textSimplified":"初六：臀困于株木，入于幽谷，三岁不觌。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_699","chapterId":"ch_work_dk_47","textTraditional":"九二：困於酒食，朱绂方來，利用享祀，征凶，無咎。","textSimplified":"九二：困于酒食，朱绂方来，利用享祀，征凶，无咎。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_700","chapterId":"ch_work_dk_47","textTraditional":"六三：困於石，據於蒺藜，入於其宮，不見其妻，凶。   ","textSimplified":"六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_701","chapterId":"ch_work_dk_47","textTraditional":"九四：來徐徐，困於金車，吝，有終。","textSimplified":"九四：来徐徐，困于金车，吝，有终。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_702","chapterId":"ch_work_dk_47","textTraditional":"九五：劓刖，困於赤绂，乃徐有說，利用祭祀。","textSimplified":"九五：劓刖，困于赤绂，乃徐有说，利用祭祀。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_703","chapterId":"ch_work_dk_47","textTraditional":"上六：困於葛藟，於臲卼，曰動悔。有悔，征吉。","textSimplified":"上六：困于葛藟，于臲卼，曰动悔。有悔，征吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_704","chapterId":"ch_work_dk_47","textTraditional":"入於幽穀，幽不明也。","textSimplified":"入于幽谷，幽不明也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_705","chapterId":"ch_work_dk_47","textTraditional":"困於酒食，中有慶也。","textSimplified":"困于酒食，中有庆也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_706","chapterId":"ch_work_dk_47","textTraditional":"據於蒺藜，乘刚也。入於其宮，不見其妻，不祥也。","textSimplified":"据于蒺藜，乘刚也。入于其宫，不见其妻，不祥也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_707","chapterId":"ch_work_dk_47","textTraditional":"來徐徐，志在下也。雖不當位，有與也。","textSimplified":"来徐徐，志在下也。虽不当位，有与也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_708","chapterId":"ch_work_dk_47","textTraditional":"劓刖，志未得也。乃徐有說，以中直也。利用祭祀，受福也。","textSimplified":"劓刖，志未得也。乃徐有说，以中直也。利用祭祀，受福也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_709","chapterId":"ch_work_dk_47","textTraditional":"困於葛藟，未當也。動悔，有悔吉，行也。","textSimplified":"困于葛藟，未当也。动悔，有悔吉，行也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_710","chapterId":"ch_work_dk_48","textTraditional":"井：改邑不改井，無丧無得，往來井井。汔至，亦未繘井，羸其瓶，凶。","textSimplified":"井：改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_711","chapterId":"ch_work_dk_48","textTraditional":"巽乎水而上水，井；井養而不窮也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。","textSimplified":"巽乎水而上水，井；井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_712","chapterId":"ch_work_dk_48","textTraditional":"木上有水，井；君子以勞民勸相。","textSimplified":"木上有水，井；君子以劳民劝相。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_713","chapterId":"ch_work_dk_48","textTraditional":"初六：井泥不食，舊井無禽。","textSimplified":"初六：井泥不食，旧井无禽。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_714","chapterId":"ch_work_dk_48","textTraditional":"九二：井穀射鲋，瓮敝漏。","textSimplified":"九二：井谷射鲋，瓮敝漏。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_715","chapterId":"ch_work_dk_48","textTraditional":"九三：井渫不食，為我心惻，可用汲，王明，併受其福。   ","textSimplified":"九三：井渫不食，为我心恻，可用汲，王明，并受其福。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_716","chapterId":"ch_work_dk_48","textTraditional":"六四：井甃，無咎。","textSimplified":"六四：井甃，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_717","chapterId":"ch_work_dk_48","textTraditional":"九五：井冽，寒泉食。","textSimplified":"九五：井冽，寒泉食。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_718","chapterId":"ch_work_dk_48","textTraditional":"上六：井收勿幕，有孚元吉。","textSimplified":"上六：井收勿幕，有孚元吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_719","chapterId":"ch_work_dk_48","textTraditional":"井泥不食，下也。舊井無禽，時舍也。","textSimplified":"井泥不食，下也。旧井无禽，时舍也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_720","chapterId":"ch_work_dk_48","textTraditional":"井穀射鲋，無與也。","textSimplified":"井谷射鲋，无与也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_721","chapterId":"ch_work_dk_48","textTraditional":"井渫不食，行惻也。求王明，受福也。","textSimplified":"井渫不食，行恻也。求王明，受福也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_722","chapterId":"ch_work_dk_48","textTraditional":"井甃無咎，修井也。","textSimplified":"井甃无咎，修井也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_723","chapterId":"ch_work_dk_48","textTraditional":"寒泉之食，中正也。","textSimplified":"寒泉之食，中正也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_724","chapterId":"ch_work_dk_48","textTraditional":"元吉在上，大成也。","textSimplified":"元吉在上，大成也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_725","chapterId":"ch_work_dk_49","textTraditional":"革：巳日乃孚，元亨利貞，悔亡。","textSimplified":"革：巳日乃孚，元亨利贞，悔亡。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_726","chapterId":"ch_work_dk_49","textTraditional":"革，水火相息，二女同居，其志不相得，曰革。巳日乃孚；革而信也。文明以說，大亨以正，革而當，其悔乃亡。天地革而四時成，湯武革命，順乎天而應乎人，革之時義大矣哉！","textSimplified":"革，水火相息，二女同居，其志不相得，曰革。巳日乃孚；革而信也。文明以说，大亨以正，革而当，其悔乃亡。天地革而四时成，汤武革命，顺乎天而应乎人，革之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_727","chapterId":"ch_work_dk_49","textTraditional":"泽中有火，革；君子以治歷明時。","textSimplified":"泽中有火，革；君子以治历明时。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_728","chapterId":"ch_work_dk_49","textTraditional":"初九：巩用黃牛之革。","textSimplified":"初九：巩用黄牛之革。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_729","chapterId":"ch_work_dk_49","textTraditional":"六二：巳日乃革之，征吉，無咎。","textSimplified":"六二：巳日乃革之，征吉，无咎。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_730","chapterId":"ch_work_dk_49","textTraditional":"九三：征凶，貞厲，革言三就，有孚。   ","textSimplified":"九三：征凶，贞厉，革言三就，有孚。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_731","chapterId":"ch_work_dk_49","textTraditional":"九四：悔亡，有孚改命，吉。","textSimplified":"九四：悔亡，有孚改命，吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_732","chapterId":"ch_work_dk_49","textTraditional":"九五：大人虎变，未占有孚。","textSimplified":"九五：大人虎变，未占有孚。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_733","chapterId":"ch_work_dk_49","textTraditional":"上六：君子豹变，小人革面，征凶，居貞吉。","textSimplified":"上六：君子豹变，小人革面，征凶，居贞吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_734","chapterId":"ch_work_dk_49","textTraditional":"巩用黃牛，不可以有為也。","textSimplified":"巩用黄牛，不可以有为也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_735","chapterId":"ch_work_dk_49","textTraditional":"巳日革之，行有嘉也。","textSimplified":"巳日革之，行有嘉也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_736","chapterId":"ch_work_dk_49","textTraditional":"革言三就，又何之矣。","textSimplified":"革言三就，又何之矣。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_737","chapterId":"ch_work_dk_49","textTraditional":"改命之吉，信志也。","textSimplified":"改命之吉，信志也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_738","chapterId":"ch_work_dk_49","textTraditional":"大人虎变，其文炳也。","textSimplified":"大人虎变，其文炳也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_739","chapterId":"ch_work_dk_49","textTraditional":"君子豹变，其文蔚也。小人革面，順以從君也。","textSimplified":"君子豹变，其文蔚也。小人革面，顺以从君也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_740","chapterId":"ch_work_dk_50","textTraditional":"鼎：元吉，亨。","textSimplified":"鼎：元吉，亨。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_741","chapterId":"ch_work_dk_50","textTraditional":"鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎刚，是以元亨。","textSimplified":"鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_742","chapterId":"ch_work_dk_50","textTraditional":"木上有火，鼎；君子以正位凝命。","textSimplified":"木上有火，鼎；君子以正位凝命。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_743","chapterId":"ch_work_dk_50","textTraditional":"初六：鼎顛趾，利出否，得妾以其子，無咎。","textSimplified":"初六：鼎颠趾，利出否，得妾以其子，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_744","chapterId":"ch_work_dk_50","textTraditional":"九二：鼎有實，我仇有疾，不我能即，吉。","textSimplified":"九二：鼎有实，我仇有疾，不我能即，吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_745","chapterId":"ch_work_dk_50","textTraditional":"九三：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。   ","textSimplified":"九三：鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_746","chapterId":"ch_work_dk_50","textTraditional":"九四：鼎折足，覆公餗，其形渥，凶。","textSimplified":"九四：鼎折足，覆公餗，其形渥，凶。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_747","chapterId":"ch_work_dk_50","textTraditional":"六五：鼎黃耳，金铉，利貞。","textSimplified":"六五：鼎黄耳，金铉，利贞。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_748","chapterId":"ch_work_dk_50","textTraditional":"上九：鼎玉铉，大吉，無不利。","textSimplified":"上九：鼎玉铉，大吉，无不利。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_749","chapterId":"ch_work_dk_50","textTraditional":"鼎顛趾，未悖也。利出否，以從貴也。","textSimplified":"鼎颠趾，未悖也。利出否，以从贵也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_750","chapterId":"ch_work_dk_50","textTraditional":"鼎有實，慎所之也。我仇有疾，終無尤也。","textSimplified":"鼎有实，慎所之也。我仇有疾，终无尤也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_751","chapterId":"ch_work_dk_50","textTraditional":"鼎耳革，失其義也。","textSimplified":"鼎耳革，失其义也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_752","chapterId":"ch_work_dk_50","textTraditional":"覆公餗，信如何也。","textSimplified":"覆公餗，信如何也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_753","chapterId":"ch_work_dk_50","textTraditional":"鼎黃耳，中以為實也。","textSimplified":"鼎黄耳，中以为实也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_754","chapterId":"ch_work_dk_50","textTraditional":"玉铉在上，刚柔節也。","textSimplified":"玉铉在上，刚柔节也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_755","chapterId":"ch_work_dk_51","textTraditional":"震：亨。震來虩虩，笑言哑哑。震驚百里，不丧匕鬯。","textSimplified":"震：亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_756","chapterId":"ch_work_dk_51","textTraditional":"震，亨。震來虩虩，恐致福也。笑言哑哑，後有則也。震驚百里，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。","textSimplified":"震，亨。震来虩虩，恐致福也。笑言哑哑，后有则也。震惊百里，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_757","chapterId":"ch_work_dk_51","textTraditional":"虩雷，震；君子以恐懼修身。","textSimplified":"虩雷，震；君子以恐惧修身。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_758","chapterId":"ch_work_dk_51","textTraditional":"初九：震來虩虩，後笑言哑哑，吉。","textSimplified":"初九：震来虩虩，后笑言哑哑，吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_759","chapterId":"ch_work_dk_51","textTraditional":"六二：震來厲，亿丧貝，跻於九陵，勿逐，七日得。","textSimplified":"六二：震来厉，亿丧贝，跻于九陵，勿逐，七日得。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_760","chapterId":"ch_work_dk_51","textTraditional":"六三：震蘇蘇，震行無眚。   ","textSimplified":"六三：震苏苏，震行无眚。   ","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_761","chapterId":"ch_work_dk_51","textTraditional":"九四：震遂泥。","textSimplified":"九四：震遂泥。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_762","chapterId":"ch_work_dk_51","textTraditional":"六五：震往來厲，亿無丧，有事。","textSimplified":"六五：震往来厉，亿无丧，有事。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_763","chapterId":"ch_work_dk_51","textTraditional":"上六：震索索，视矍矍，征凶。震不於其躬，於其鄰，無咎。婚媾有言。","textSimplified":"上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_764","chapterId":"ch_work_dk_51","textTraditional":"震來虩虩，恐致福也。笑言哑哑，後有則也。","textSimplified":"震来虩虩，恐致福也。笑言哑哑，后有则也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_765","chapterId":"ch_work_dk_51","textTraditional":"震來厲，乘刚也。","textSimplified":"震来厉，乘刚也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_766","chapterId":"ch_work_dk_51","textTraditional":"震蘇蘇，位不當也。","textSimplified":"震苏苏，位不当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_767","chapterId":"ch_work_dk_51","textTraditional":"震遂泥，未光也。","textSimplified":"震遂泥，未光也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_768","chapterId":"ch_work_dk_51","textTraditional":"震往來厲，危行也。其事在中，大無丧也。","textSimplified":"震往来厉，危行也。其事在中，大无丧也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_769","chapterId":"ch_work_dk_51","textTraditional":"震索索，中未得也。雖凶無咎，畏鄰戒也。","textSimplified":"震索索，中未得也。虽凶无咎，畏邻戒也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_770","chapterId":"ch_work_dk_52","textTraditional":"艮：艮其背，不獲其身，行其庭，不見其人，無咎。","textSimplified":"艮：艮其背，不获其身，行其庭，不见其人，无咎。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_771","chapterId":"ch_work_dk_52","textTraditional":"艮，止也。時止則止，時行則行，動靜不失其時，其道光明。艮其止，止其所也。上下敵應，不相與也。是以不獲其身，行其庭不見其人，無咎也。","textSimplified":"艮，止也。时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也。是以不获其身，行其庭不见其人，无咎也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_772","chapterId":"ch_work_dk_52","textTraditional":"兼山，艮；君子以思不出其位。","textSimplified":"兼山，艮；君子以思不出其位。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_773","chapterId":"ch_work_dk_52","textTraditional":"初六：艮其趾，無咎，利永貞。","textSimplified":"初六：艮其趾，无咎，利永贞。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_774","chapterId":"ch_work_dk_52","textTraditional":"六二：艮其腓，不拯其隨，其心不快。","textSimplified":"六二：艮其腓，不拯其随，其心不快。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_775","chapterId":"ch_work_dk_52","textTraditional":"九三：艮其限，列其夤，厲薰心。","textSimplified":"九三：艮其限，列其夤，厉薰心。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_776","chapterId":"ch_work_dk_52","textTraditional":"六四：艮其身，無咎。","textSimplified":"六四：艮其身，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_777","chapterId":"ch_work_dk_52","textTraditional":"六五：艮其辅，言有序，悔亡。","textSimplified":"六五：艮其辅，言有序，悔亡。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_778","chapterId":"ch_work_dk_52","textTraditional":"上九：敦艮，吉。","textSimplified":"上九：敦艮，吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_779","chapterId":"ch_work_dk_52","textTraditional":"艮其趾，未失正也。","textSimplified":"艮其趾，未失正也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_780","chapterId":"ch_work_dk_52","textTraditional":"不拯其隨，未退聽也。","textSimplified":"不拯其随，未退听也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_781","chapterId":"ch_work_dk_52","textTraditional":"艮其限，危薰心也。","textSimplified":"艮其限，危薰心也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_782","chapterId":"ch_work_dk_52","textTraditional":"艮其身，止諸躬也。","textSimplified":"艮其身，止诸躬也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_783","chapterId":"ch_work_dk_52","textTraditional":"艮其辅，以中正也。","textSimplified":"艮其辅，以中正也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_784","chapterId":"ch_work_dk_52","textTraditional":"敦艮之吉，以厚終也。","textSimplified":"敦艮之吉，以厚终也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_785","chapterId":"ch_work_dk_53","textTraditional":"漸：女歸吉，利貞。","textSimplified":"渐：女归吉，利贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_786","chapterId":"ch_work_dk_53","textTraditional":"漸之進也，女歸吉也。進得位，往有功也。進以正，可以正邦也。其位刚，得中也。止而巽，動不窮也。","textSimplified":"渐之进也，女归吉也。进得位，往有功也。进以正，可以正邦也。其位刚，得中也。止而巽，动不穷也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_787","chapterId":"ch_work_dk_53","textTraditional":"山上有木，漸；君子以居賢德，善俗。","textSimplified":"山上有木，渐；君子以居贤德，善俗。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_788","chapterId":"ch_work_dk_53","textTraditional":"初六：鸿漸於幹，小子厲，有言，無咎。","textSimplified":"初六：鸿渐于干，小子厉，有言，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_789","chapterId":"ch_work_dk_53","textTraditional":"六二：鸿漸於磐，飲食衎衎，吉。","textSimplified":"六二：鸿渐于磐，饮食衎衎，吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_790","chapterId":"ch_work_dk_53","textTraditional":"九三：鸿漸於陆，夫征不复，婦孕不育，凶；利御寇。","textSimplified":"九三：鸿渐于陆，夫征不复，妇孕不育，凶；利御寇。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_791","chapterId":"ch_work_dk_53","textTraditional":"六四：鸿漸於木，或得其桷，無咎。","textSimplified":"六四：鸿渐于木，或得其桷，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_792","chapterId":"ch_work_dk_53","textTraditional":"九五：鸿漸於陵，婦三歲不孕，終莫之勝，吉。","textSimplified":"九五：鸿渐于陵，妇三岁不孕，终莫之胜，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_793","chapterId":"ch_work_dk_53","textTraditional":"上九：鸿漸於陆，其羽可用為儀，吉。","textSimplified":"上九：鸿渐于陆，其羽可用为仪，吉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_794","chapterId":"ch_work_dk_53","textTraditional":"小子之厲，義無咎也。","textSimplified":"小子之厉，义无咎也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_795","chapterId":"ch_work_dk_53","textTraditional":"飲食衎衎，吉，不素飽也。","textSimplified":"饮食衎衎，吉，不素饱也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_796","chapterId":"ch_work_dk_53","textTraditional":"夫征不复，離群丑也。婦孕不育，失其道也。利用御寇，順相保也。","textSimplified":"夫征不复，离群丑也。妇孕不育，失其道也。利用御寇，顺相保也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_797","chapterId":"ch_work_dk_53","textTraditional":"或得其桷，順以巽也。","textSimplified":"或得其桷，顺以巽也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_798","chapterId":"ch_work_dk_53","textTraditional":"終莫之勝，吉；得所願也。","textSimplified":"终莫之胜，吉；得所愿也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_799","chapterId":"ch_work_dk_53","textTraditional":"其羽可用為儀，吉；不可亂也。","textSimplified":"其羽可用为仪，吉；不可乱也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_800","chapterId":"ch_work_dk_54","textTraditional":"歸妹：征凶，無攸利。","textSimplified":"归妹：征凶，无攸利。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_801","chapterId":"ch_work_dk_54","textTraditional":"歸妹，天地之大義也。天地不交，而萬物不興，歸妹人之終始也。說以動，所歸妹也。征凶，位不當也。無攸利，柔乘刚也。","textSimplified":"归妹，天地之大义也。天地不交，而万物不兴，归妹人之终始也。说以动，所归妹也。征凶，位不当也。无攸利，柔乘刚也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_802","chapterId":"ch_work_dk_54","textTraditional":"泽上有雷，歸妹；君子以永終知敝。","textSimplified":"泽上有雷，归妹；君子以永终知敝。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_803","chapterId":"ch_work_dk_54","textTraditional":"初九：歸妹以娣，跛能履，征吉。","textSimplified":"初九：归妹以娣，跛能履，征吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_804","chapterId":"ch_work_dk_54","textTraditional":"九二：眇能视，利幽人之貞。","textSimplified":"九二：眇能视，利幽人之贞。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_805","chapterId":"ch_work_dk_54","textTraditional":"六三：歸妹以須，反歸以娣。","textSimplified":"六三：归妹以须，反归以娣。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_806","chapterId":"ch_work_dk_54","textTraditional":"九四：歸妹愆期，遲歸有時。","textSimplified":"九四：归妹愆期，迟归有时。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_807","chapterId":"ch_work_dk_54","textTraditional":"六五：帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。","textSimplified":"六五：帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_808","chapterId":"ch_work_dk_54","textTraditional":"上六：女承筐無實，士刲羊無血，無攸利。","textSimplified":"上六：女承筐无实，士刲羊无血，无攸利。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_809","chapterId":"ch_work_dk_54","textTraditional":"歸妹以娣，以恒也。跛能履吉，相承也。","textSimplified":"归妹以娣，以恒也。跛能履吉，相承也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_810","chapterId":"ch_work_dk_54","textTraditional":"利幽人之貞，未变常也。","textSimplified":"利幽人之贞，未变常也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_811","chapterId":"ch_work_dk_54","textTraditional":"歸妹以須，未當也。","textSimplified":"归妹以须，未当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_812","chapterId":"ch_work_dk_54","textTraditional":"愆期之志，有待而行也。","textSimplified":"愆期之志，有待而行也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_813","chapterId":"ch_work_dk_54","textTraditional":"帝乙歸妹，不如其娣之袂良也。其位在中，以貴行也。","textSimplified":"帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_814","chapterId":"ch_work_dk_54","textTraditional":"上六無實，承虛筐也。","textSimplified":"上六无实，承虚筐也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_815","chapterId":"ch_work_dk_55","textTraditional":"丰：亨，王假之，勿忧，宜日中。","textSimplified":"丰：亨，王假之，勿忧，宜日中。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_816","chapterId":"ch_work_dk_55","textTraditional":"丰，大也。明以動，故丰。王假之，尚大也。勿忧宜日中，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而况人於人乎？况於鬼神乎？","textSimplified":"丰，大也。明以动，故丰。王假之，尚大也。勿忧宜日中，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况人于人乎？况于鬼神乎？","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_817","chapterId":"ch_work_dk_55","textTraditional":"雷電皆至，丰；君子以折獄致刑。","textSimplified":"雷电皆至，丰；君子以折狱致刑。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_818","chapterId":"ch_work_dk_55","textTraditional":"初九：遇其配主，雖旬無咎，往有尚。","textSimplified":"初九：遇其配主，虽旬无咎，往有尚。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_819","chapterId":"ch_work_dk_55","textTraditional":"六二：丰其蔀，日中見斗，往得疑疾，有孚發若，吉。","textSimplified":"六二：丰其蔀，日中见斗，往得疑疾，有孚发若，吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_820","chapterId":"ch_work_dk_55","textTraditional":"九三：丰其沛，日中見沫，折其右肱，無咎。","textSimplified":"九三：丰其沛，日中见沫，折其右肱，无咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_821","chapterId":"ch_work_dk_55","textTraditional":"九四：丰其蔀，日中見斗，遇其夷主，吉。","textSimplified":"九四：丰其蔀，日中见斗，遇其夷主，吉。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_822","chapterId":"ch_work_dk_55","textTraditional":"六五：來章，有慶譽，吉。","textSimplified":"六五：来章，有庆誉，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_823","chapterId":"ch_work_dk_55","textTraditional":"上六：丰其屋，蔀其家，闚其戶，阒其無人，三歲不觌，凶。","textSimplified":"上六：丰其屋，蔀其家，闚其户，阒其无人，三岁不觌，凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_824","chapterId":"ch_work_dk_55","textTraditional":"雖旬無咎，過旬灾也。","textSimplified":"虽旬无咎，过旬灾也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_825","chapterId":"ch_work_dk_55","textTraditional":"有孚發若，信以發志也。","textSimplified":"有孚发若，信以发志也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_826","chapterId":"ch_work_dk_55","textTraditional":"丰其沛，不可大事也。折其右肱，終不可用也。","textSimplified":"丰其沛，不可大事也。折其右肱，终不可用也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_827","chapterId":"ch_work_dk_55","textTraditional":"丰其蔀，位不當也。日中見斗，幽不明也。遇其夷主，吉；行也。","textSimplified":"丰其蔀，位不当也。日中见斗，幽不明也。遇其夷主，吉；行也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_828","chapterId":"ch_work_dk_55","textTraditional":"六五之吉，有慶也。","textSimplified":"六五之吉，有庆也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_829","chapterId":"ch_work_dk_55","textTraditional":"丰其屋，天际翔也。闚其戶，阒其無人，自藏也。","textSimplified":"丰其屋，天际翔也。闚其户，阒其无人，自藏也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_830","chapterId":"ch_work_dk_56","textTraditional":"旅：小亨，旅貞吉。","textSimplified":"旅：小亨，旅贞吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_831","chapterId":"ch_work_dk_56","textTraditional":"旅，小亨，柔得中乎外，而順乎刚，止而麗乎明，是以小亨，旅貞吉也。旅之時義大矣哉！","textSimplified":"旅，小亨，柔得中乎外，而顺乎刚，止而丽乎明，是以小亨，旅贞吉也。旅之时义大矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_832","chapterId":"ch_work_dk_56","textTraditional":"山上有火，旅；君子以明慎用刑，而不留獄。","textSimplified":"山上有火，旅；君子以明慎用刑，而不留狱。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_833","chapterId":"ch_work_dk_56","textTraditional":"初六：旅琐琐，斯其所取灾。","textSimplified":"初六：旅琐琐，斯其所取灾。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_834","chapterId":"ch_work_dk_56","textTraditional":"六二：旅即次，懷其資，得童仆貞。","textSimplified":"六二：旅即次，怀其资，得童仆贞。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_835","chapterId":"ch_work_dk_56","textTraditional":"九三：旅焚其次，丧其童仆，貞厲。","textSimplified":"九三：旅焚其次，丧其童仆，贞厉。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_836","chapterId":"ch_work_dk_56","textTraditional":"九四：旅於處，得其資斧，我心不快。","textSimplified":"九四：旅于处，得其资斧，我心不快。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_837","chapterId":"ch_work_dk_56","textTraditional":"六五：射雉一矢亡，終以譽命。","textSimplified":"六五：射雉一矢亡，终以誉命。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_838","chapterId":"ch_work_dk_56","textTraditional":"上九：鳥焚其巢，旅人先笑後號啕。丧牛於易，凶。","textSimplified":"上九：鸟焚其巢，旅人先笑后号啕。丧牛于易，凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_839","chapterId":"ch_work_dk_56","textTraditional":"旅琐琐，志窮灾也。","textSimplified":"旅琐琐，志穷灾也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_840","chapterId":"ch_work_dk_56","textTraditional":"得童仆貞，終無尤也。","textSimplified":"得童仆贞，终无尤也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_841","chapterId":"ch_work_dk_56","textTraditional":"旅焚其次，亦以傷矣。以旅與下，其義丧也。","textSimplified":"旅焚其次，亦以伤矣。以旅与下，其义丧也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_842","chapterId":"ch_work_dk_56","textTraditional":"旅於處，未得位也。得其資斧，心未快也。","textSimplified":"旅于处，未得位也。得其资斧，心未快也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_843","chapterId":"ch_work_dk_56","textTraditional":"終以譽命，上逮也。","textSimplified":"终以誉命，上逮也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_844","chapterId":"ch_work_dk_56","textTraditional":"以旅在上，其義焚也。丧牛於易，終莫之聞也。","textSimplified":"以旅在上，其义焚也。丧牛于易，终莫之闻也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_845","chapterId":"ch_work_dk_57","textTraditional":"巽：小亨，利攸往，利見大人。","textSimplified":"巽：小亨，利攸往，利见大人。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_846","chapterId":"ch_work_dk_57","textTraditional":"重巽以申命，刚巽乎中正而志行。柔皆順乎刚，是以小亨，利有攸往，利見大人。","textSimplified":"重巽以申命，刚巽乎中正而志行。柔皆顺乎刚，是以小亨，利有攸往，利见大人。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_847","chapterId":"ch_work_dk_57","textTraditional":"隨風，巽；君子以申命行事。","textSimplified":"随风，巽；君子以申命行事。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_848","chapterId":"ch_work_dk_57","textTraditional":"初六：進退，利武人之貞。","textSimplified":"初六：进退，利武人之贞。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_849","chapterId":"ch_work_dk_57","textTraditional":"九二：巽在床下，用史巫紛若，吉，無咎。","textSimplified":"九二：巽在床下，用史巫纷若，吉，无咎。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_850","chapterId":"ch_work_dk_57","textTraditional":"九三：頻巽，吝。","textSimplified":"九三：频巽，吝。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_851","chapterId":"ch_work_dk_57","textTraditional":"六四：悔亡，田獲三品。","textSimplified":"六四：悔亡，田获三品。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_852","chapterId":"ch_work_dk_57","textTraditional":"九五：貞吉悔亡，無不利。無初有終，先庚三日，後庚三日，吉。","textSimplified":"九五：贞吉悔亡，无不利。无初有终，先庚三日，后庚三日，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_853","chapterId":"ch_work_dk_57","textTraditional":"上九：巽在床下，丧其資斧，貞凶。","textSimplified":"上九：巽在床下，丧其资斧，贞凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_854","chapterId":"ch_work_dk_57","textTraditional":"進退，志疑也。利武人之貞，志治也。","textSimplified":"进退，志疑也。利武人之贞，志治也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_855","chapterId":"ch_work_dk_57","textTraditional":"紛若之吉，得中也。","textSimplified":"纷若之吉，得中也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_856","chapterId":"ch_work_dk_57","textTraditional":"頻巽之吝，志窮也。","textSimplified":"频巽之吝，志穷也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_857","chapterId":"ch_work_dk_57","textTraditional":"田獲三品，有功也。","textSimplified":"田获三品，有功也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_858","chapterId":"ch_work_dk_57","textTraditional":"九五之吉，位正中也。","textSimplified":"九五之吉，位正中也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_859","chapterId":"ch_work_dk_57","textTraditional":"巽在床下，上窮也。丧其資斧，正乎凶也。","textSimplified":"巽在床下，上穷也。丧其资斧，正乎凶也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_860","chapterId":"ch_work_dk_58","textTraditional":"兑：亨，利貞。","textSimplified":"兑：亨，利贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_861","chapterId":"ch_work_dk_58","textTraditional":"兑，說也。刚中而柔外，說以利貞，是以順乎天，而應乎人。說以先民，民忘其勞；說以犯難，民忘其死；說之大，民勸矣哉！","textSimplified":"兑，说也。刚中而柔外，说以利贞，是以顺乎天，而应乎人。说以先民，民忘其劳；说以犯难，民忘其死；说之大，民劝矣哉！","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_862","chapterId":"ch_work_dk_58","textTraditional":"麗泽，兑；君子以朋友講習。","textSimplified":"丽泽，兑；君子以朋友讲习。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_863","chapterId":"ch_work_dk_58","textTraditional":"初九：和兑，吉。","textSimplified":"初九：和兑，吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_864","chapterId":"ch_work_dk_58","textTraditional":"九二：孚兑，吉，悔亡。","textSimplified":"九二：孚兑，吉，悔亡。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_865","chapterId":"ch_work_dk_58","textTraditional":"六三：來兑，凶。","textSimplified":"六三：来兑，凶。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_866","chapterId":"ch_work_dk_58","textTraditional":"九四：商兑，未寧，介疾有喜。","textSimplified":"九四：商兑，未宁，介疾有喜。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_867","chapterId":"ch_work_dk_58","textTraditional":"九五：孚於剝，有厲。","textSimplified":"九五：孚于剥，有厉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_868","chapterId":"ch_work_dk_58","textTraditional":"上六：引兑。","textSimplified":"上六：引兑。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_869","chapterId":"ch_work_dk_58","textTraditional":"和兑之吉，行未疑也。","textSimplified":"和兑之吉，行未疑也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_870","chapterId":"ch_work_dk_58","textTraditional":"孚兑之吉，信志也。","textSimplified":"孚兑之吉，信志也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_871","chapterId":"ch_work_dk_58","textTraditional":"來兑之凶，位不當也。","textSimplified":"来兑之凶，位不当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_872","chapterId":"ch_work_dk_58","textTraditional":"九四之喜，有慶也。","textSimplified":"九四之喜，有庆也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_873","chapterId":"ch_work_dk_58","textTraditional":"孚於剝，位正當也。","textSimplified":"孚于剥，位正当也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_874","chapterId":"ch_work_dk_58","textTraditional":"上六引兑，未光也。","textSimplified":"上六引兑，未光也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_875","chapterId":"ch_work_dk_59","textTraditional":"涣：亨。王假有廟，利涉大川，利貞。","textSimplified":"涣：亨。王假有庙，利涉大川，利贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_876","chapterId":"ch_work_dk_59","textTraditional":"涣，亨。刚來而不窮，柔得位乎外而上同。王假有廟，王乃在中也。利涉大川，乘木有功也。","textSimplified":"涣，亨。刚来而不穷，柔得位乎外而上同。王假有庙，王乃在中也。利涉大川，乘木有功也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_877","chapterId":"ch_work_dk_59","textTraditional":"風行水上，涣；先王以享於帝立廟。","textSimplified":"风行水上，涣；先王以享于帝立庙。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_878","chapterId":"ch_work_dk_59","textTraditional":"初六：用拯馬壮，吉。","textSimplified":"初六：用拯马壮，吉。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_879","chapterId":"ch_work_dk_59","textTraditional":"九二：涣奔其機，悔亡。","textSimplified":"九二：涣奔其机，悔亡。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_880","chapterId":"ch_work_dk_59","textTraditional":"六三：涣其躬，無悔。","textSimplified":"六三：涣其躬，无悔。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_881","chapterId":"ch_work_dk_59","textTraditional":"六四：涣其群，元吉。涣有丘，匪夷所思。","textSimplified":"六四：涣其群，元吉。涣有丘，匪夷所思。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_882","chapterId":"ch_work_dk_59","textTraditional":"九五：涣汗其大號，涣王居，無咎。","textSimplified":"九五：涣汗其大号，涣王居，无咎。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_883","chapterId":"ch_work_dk_59","textTraditional":"上九：涣其血，去逖出，無咎。","textSimplified":"上九：涣其血，去逖出，无咎。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_884","chapterId":"ch_work_dk_59","textTraditional":"初六之吉，順也。","textSimplified":"初六之吉，顺也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_885","chapterId":"ch_work_dk_59","textTraditional":"涣奔其機，得願也。","textSimplified":"涣奔其机，得愿也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_886","chapterId":"ch_work_dk_59","textTraditional":"涣其躬，志在外也。","textSimplified":"涣其躬，志在外也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_887","chapterId":"ch_work_dk_59","textTraditional":"涣其群，元吉；光大也。","textSimplified":"涣其群，元吉；光大也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_888","chapterId":"ch_work_dk_59","textTraditional":"王居無咎，正位也。","textSimplified":"王居无咎，正位也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_889","chapterId":"ch_work_dk_59","textTraditional":"涣其血，遠害也。","textSimplified":"涣其血，远害也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_890","chapterId":"ch_work_dk_60","textTraditional":"節：亨。苦節，不可貞。","textSimplified":"节：亨。苦节，不可贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_891","chapterId":"ch_work_dk_60","textTraditional":"節，亨，刚柔分，而刚得中。苦節不可貞，其道窮也。說以行险，當位以節，中正以通。天地節而四時成，節以製度，不傷财，不害民。","textSimplified":"节，亨，刚柔分，而刚得中。苦节不可贞，其道穷也。说以行险，当位以节，中正以通。天地节而四时成，节以制度，不伤财，不害民。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_892","chapterId":"ch_work_dk_60","textTraditional":"泽上有水，節；君子以製數度，議德行。","textSimplified":"泽上有水，节；君子以制数度，议德行。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_893","chapterId":"ch_work_dk_60","textTraditional":"初九：不出戶庭，無咎。","textSimplified":"初九：不出户庭，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_894","chapterId":"ch_work_dk_60","textTraditional":"九二：不出門庭，凶。","textSimplified":"九二：不出门庭，凶。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_895","chapterId":"ch_work_dk_60","textTraditional":"六三：不節若，則嗟若，無咎。","textSimplified":"六三：不节若，则嗟若，无咎。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_896","chapterId":"ch_work_dk_60","textTraditional":"六四：安節，亨。","textSimplified":"六四：安节，亨。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_897","chapterId":"ch_work_dk_60","textTraditional":"九五：甘節，吉；往有尚。","textSimplified":"九五：甘节，吉；往有尚。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_898","chapterId":"ch_work_dk_60","textTraditional":"上六：苦節，貞凶，悔亡。","textSimplified":"上六：苦节，贞凶，悔亡。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_899","chapterId":"ch_work_dk_60","textTraditional":"不出戶庭，知通塞也。","textSimplified":"不出户庭，知通塞也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_900","chapterId":"ch_work_dk_60","textTraditional":"不出門庭，失時極也。","textSimplified":"不出门庭，失时极也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_901","chapterId":"ch_work_dk_60","textTraditional":"不節之嗟，又誰咎也。","textSimplified":"不节之嗟，又谁咎也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_902","chapterId":"ch_work_dk_60","textTraditional":"安節之亨，承上道也。","textSimplified":"安节之亨，承上道也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_903","chapterId":"ch_work_dk_60","textTraditional":"甘節之吉，居位中也。","textSimplified":"甘节之吉，居位中也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_904","chapterId":"ch_work_dk_60","textTraditional":"苦節貞凶，其道窮也。","textSimplified":"苦节贞凶，其道穷也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_905","chapterId":"ch_work_dk_61","textTraditional":"中孚：豚魚吉，利涉大川，利貞。","textSimplified":"中孚：豚鱼吉，利涉大川，利贞。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_906","chapterId":"ch_work_dk_61","textTraditional":"中孚，柔在內而刚得中。說而巽，孚，乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。","textSimplified":"中孚，柔在内而刚得中。说而巽，孚，乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_907","chapterId":"ch_work_dk_61","textTraditional":"泽上有風，中孚；君子以議獄缓死。","textSimplified":"泽上有风，中孚；君子以议狱缓死。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_908","chapterId":"ch_work_dk_61","textTraditional":"初九：虞吉，有它不燕。","textSimplified":"初九：虞吉，有它不燕。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_909","chapterId":"ch_work_dk_61","textTraditional":"九二：鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。","textSimplified":"九二：鸣鹤在阴，其子和之，我有好爵，吾与尔靡之。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_910","chapterId":"ch_work_dk_61","textTraditional":"六三：得敵，或鼓或罢，或泣或歌。","textSimplified":"六三：得敌，或鼓或罢，或泣或歌。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_911","chapterId":"ch_work_dk_61","textTraditional":"六四：月幾望，馬匹亡，無咎。","textSimplified":"六四：月几望，马匹亡，无咎。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_912","chapterId":"ch_work_dk_61","textTraditional":"九五：有孚挛如，無咎。","textSimplified":"九五：有孚挛如，无咎。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_913","chapterId":"ch_work_dk_61","textTraditional":"上九：翰音登於天，貞凶。","textSimplified":"上九：翰音登于天，贞凶。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_914","chapterId":"ch_work_dk_61","textTraditional":"初九虞吉，志未变也。","textSimplified":"初九虞吉，志未变也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_915","chapterId":"ch_work_dk_61","textTraditional":"其子和之，中心願也。","textSimplified":"其子和之，中心愿也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_916","chapterId":"ch_work_dk_61","textTraditional":"可鼓或罢，位不當也。","textSimplified":"可鼓或罢，位不当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_917","chapterId":"ch_work_dk_61","textTraditional":"馬匹亡，絕類上也。","textSimplified":"马匹亡，绝类上也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_918","chapterId":"ch_work_dk_61","textTraditional":"有孚挛如，位正當也。","textSimplified":"有孚挛如，位正当也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_919","chapterId":"ch_work_dk_61","textTraditional":"翰音登於天，何可長也。","textSimplified":"翰音登于天，何可长也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_920","chapterId":"ch_work_dk_62","textTraditional":"小過：亨，利貞，可小事，不可大事。飛鳥遺之音，不宜上，宜下，大吉。","textSimplified":"小过：亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上，宜下，大吉。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_921","chapterId":"ch_work_dk_62","textTraditional":"小過，小者過而亨也。過以利貞，與時行也。柔得中，是以小事吉也。刚失位而不中，是以不可大事也。有飛鳥之象焉，有飛鳥遺之音，不宜上宜下，大吉；上逆而下順也。","textSimplified":"小过，小者过而亨也。过以利贞，与时行也。柔得中，是以小事吉也。刚失位而不中，是以不可大事也。有飞鸟之象焉，有飞鸟遗之音，不宜上宜下，大吉；上逆而下顺也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_922","chapterId":"ch_work_dk_62","textTraditional":"山上有雷，小過；君子以行過乎恭，丧過乎哀，用過乎俭。","textSimplified":"山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_923","chapterId":"ch_work_dk_62","textTraditional":"初六：飛鳥以凶。","textSimplified":"初六：飞鸟以凶。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_924","chapterId":"ch_work_dk_62","textTraditional":"六二：過其祖，遇其妣；不及其君，遇其臣；無咎。","textSimplified":"六二：过其祖，遇其妣；不及其君，遇其臣；无咎。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_925","chapterId":"ch_work_dk_62","textTraditional":"九三：弗過防之，從或戕之，凶。","textSimplified":"九三：弗过防之，从或戕之，凶。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_926","chapterId":"ch_work_dk_62","textTraditional":"九四：無咎，弗過遇之。往厲必戒，勿用永貞。","textSimplified":"九四：无咎，弗过遇之。往厉必戒，勿用永贞。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_927","chapterId":"ch_work_dk_62","textTraditional":"六五：密雲不雨，自我西郊，公弋取彼在穴。","textSimplified":"六五：密云不雨，自我西郊，公弋取彼在穴。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_928","chapterId":"ch_work_dk_62","textTraditional":"上六：弗遇過之，飛鳥離之，凶，是謂灾眚。","textSimplified":"上六：弗遇过之，飞鸟离之，凶，是谓灾眚。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_929","chapterId":"ch_work_dk_62","textTraditional":"飛鳥以凶，不可如何也。","textSimplified":"飞鸟以凶，不可如何也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_930","chapterId":"ch_work_dk_62","textTraditional":"不及其君，臣不可過也。","textSimplified":"不及其君，臣不可过也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_931","chapterId":"ch_work_dk_62","textTraditional":"從或戕之，凶如何也。","textSimplified":"从或戕之，凶如何也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_932","chapterId":"ch_work_dk_62","textTraditional":"弗過遇之，位不當也。往厲必戒，終不可長也。","textSimplified":"弗过遇之，位不当也。往厉必戒，终不可长也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_933","chapterId":"ch_work_dk_62","textTraditional":"密雲不雨，已上也。","textSimplified":"密云不雨，已上也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_934","chapterId":"ch_work_dk_62","textTraditional":"弗遇過之，已亢也。","textSimplified":"弗遇过之，已亢也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_935","chapterId":"ch_work_dk_63","textTraditional":"既濟：亨，小利貞，初吉終亂。","textSimplified":"既济：亨，小利贞，初吉终乱。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_936","chapterId":"ch_work_dk_63","textTraditional":"既濟，亨，小者亨也。利貞，刚柔正而位當也。初吉，柔得中也。終止則亂，其道窮也。","textSimplified":"既济，亨，小者亨也。利贞，刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_937","chapterId":"ch_work_dk_63","textTraditional":"水在火上，既濟；君子以思患而預防之。","textSimplified":"水在火上，既济；君子以思患而预防之。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_938","chapterId":"ch_work_dk_63","textTraditional":"初九：曳其輪，濡其尾，無咎。","textSimplified":"初九：曳其轮，濡其尾，无咎。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_939","chapterId":"ch_work_dk_63","textTraditional":"六二：婦丧其茀，勿逐，七日得。","textSimplified":"六二：妇丧其茀，勿逐，七日得。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_940","chapterId":"ch_work_dk_63","textTraditional":"九三：高宗伐鬼方，三年克之，小人勿用。","textSimplified":"九三：高宗伐鬼方，三年克之，小人勿用。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_941","chapterId":"ch_work_dk_63","textTraditional":"六四：繻有衣袽，終日戒。","textSimplified":"六四：繻有衣袽，终日戒。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_942","chapterId":"ch_work_dk_63","textTraditional":"九五：東鄰殺牛，不如西鄰之禴祭，實受其福。","textSimplified":"九五：东邻杀牛，不如西邻之禴祭，实受其福。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_943","chapterId":"ch_work_dk_63","textTraditional":"上六：濡其首，厲。","textSimplified":"上六：濡其首，厉。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_944","chapterId":"ch_work_dk_63","textTraditional":"曳其輪，義無咎也。","textSimplified":"曳其轮，义无咎也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_945","chapterId":"ch_work_dk_63","textTraditional":"七日得，以中道也。","textSimplified":"七日得，以中道也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_946","chapterId":"ch_work_dk_63","textTraditional":"三年克之，憊也。","textSimplified":"三年克之，惫也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_947","chapterId":"ch_work_dk_63","textTraditional":"終日戒，有所疑也。","textSimplified":"终日戒，有所疑也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_948","chapterId":"ch_work_dk_63","textTraditional":"東鄰殺牛，不如西鄰之時也；實受其福，吉大來也。","textSimplified":"东邻杀牛，不如西邻之时也；实受其福，吉大来也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_949","chapterId":"ch_work_dk_63","textTraditional":"濡其首厲，何可久也。","textSimplified":"濡其首厉，何可久也。","sentenceOrder":15,"paragraphGroup":5},
  {"id":"s_dk_950","chapterId":"ch_work_dk_64","textTraditional":"未濟：亨，小狐汔濟，濡其尾，無攸利。","textSimplified":"未济：亨，小狐汔济，濡其尾，无攸利。","sentenceOrder":1,"paragraphGroup":1},
  {"id":"s_dk_951","chapterId":"ch_work_dk_64","textTraditional":"未濟，亨；柔得中也。小狐汔濟，未出中也。濡其尾，無攸利；不續終也。雖不當位，刚柔應也。","textSimplified":"未济，亨；柔得中也。小狐汔济，未出中也。濡其尾，无攸利；不续终也。虽不当位，刚柔应也。","sentenceOrder":2,"paragraphGroup":2},
  {"id":"s_dk_952","chapterId":"ch_work_dk_64","textTraditional":"火在水上，未濟；君子以慎辨物居方。","textSimplified":"火在水上，未济；君子以慎辨物居方。","sentenceOrder":3,"paragraphGroup":3},
  {"id":"s_dk_953","chapterId":"ch_work_dk_64","textTraditional":"初六：濡其尾，吝。","textSimplified":"初六：濡其尾，吝。","sentenceOrder":4,"paragraphGroup":4},
  {"id":"s_dk_954","chapterId":"ch_work_dk_64","textTraditional":"九二：曳其輪，貞吉。","textSimplified":"九二：曳其轮，贞吉。","sentenceOrder":5,"paragraphGroup":4},
  {"id":"s_dk_955","chapterId":"ch_work_dk_64","textTraditional":"六三：未濟，征凶，利涉大川。","textSimplified":"六三：未济，征凶，利涉大川。","sentenceOrder":6,"paragraphGroup":4},
  {"id":"s_dk_956","chapterId":"ch_work_dk_64","textTraditional":"九四：貞吉，悔亡，震用伐鬼方，三年有賞於大國。","textSimplified":"九四：贞吉，悔亡，震用伐鬼方，三年有赏于大国。","sentenceOrder":7,"paragraphGroup":4},
  {"id":"s_dk_957","chapterId":"ch_work_dk_64","textTraditional":"六五：貞吉，無悔，君子之光，有孚，吉。","textSimplified":"六五：贞吉，无悔，君子之光，有孚，吉。","sentenceOrder":8,"paragraphGroup":4},
  {"id":"s_dk_958","chapterId":"ch_work_dk_64","textTraditional":"上九：有孚於飲酒，無咎，濡其首，有孚失是。","textSimplified":"上九：有孚于饮酒，无咎，濡其首，有孚失是。","sentenceOrder":9,"paragraphGroup":4},
  {"id":"s_dk_959","chapterId":"ch_work_dk_64","textTraditional":"濡其尾，亦不知極也。","textSimplified":"濡其尾，亦不知极也。","sentenceOrder":10,"paragraphGroup":5},
  {"id":"s_dk_960","chapterId":"ch_work_dk_64","textTraditional":"九二貞吉，中以行正也。","textSimplified":"九二贞吉，中以行正也。","sentenceOrder":11,"paragraphGroup":5},
  {"id":"s_dk_961","chapterId":"ch_work_dk_64","textTraditional":"未濟征凶，位不當也。","textSimplified":"未济征凶，位不当也。","sentenceOrder":12,"paragraphGroup":5},
  {"id":"s_dk_962","chapterId":"ch_work_dk_64","textTraditional":"貞吉悔亡，志行也。","textSimplified":"贞吉悔亡，志行也。","sentenceOrder":13,"paragraphGroup":5},
  {"id":"s_dk_963","chapterId":"ch_work_dk_64","textTraditional":"君子之光，其暉吉也。","textSimplified":"君子之光，其晖吉也。","sentenceOrder":14,"paragraphGroup":5},
  {"id":"s_dk_964","chapterId":"ch_work_dk_64","textTraditional":"飲酒濡首，亦不知節也。","textSimplified":"饮酒濡首，亦不知节也。","sentenceOrder":15,"paragraphGroup":5}
];

export const dkAnnotations: Annotation[] = [
  {"id":"an_dk_1","sentenceId":"s_dk_1","level":"sentence","content":"【乾卦】乾卦象征天，其卦辞“元亨，利贞”意味着事物的开始、亨通、利于坚持正道。元，表示万物之始，亨，表示通达顺利，利，表示适宜，贞，表示坚守正道。整体而言，乾卦的卦辞鼓励人们在行动时要像天一样刚健有力，积极进取，同时也要保持正直和坚定。"},
  {"id":"an_dk_2","sentenceId":"s_dk_2","level":"sentence","content":"【乾卦】乾卦的彖辞赞美了乾元的伟大，它是万物的起源，统领着天道。乾元的运行如同云行雨施，使万物得以生长和形成。乾元的光明始终不息，六个位置的时序得以完成，象征着乾元驾驭着六龙，掌控着天道的运行。乾道的变化使万物各得其正，保持了大和的状态，从而达到利贞的境界。乾元超越了万物，使万国得以安宁。这段彖辞强调了乾元的创造力、统领力和和谐性。"},
  {"id":"an_dk_3","sentenceId":"s_dk_3","level":"sentence","content":"【励志】这句话出自《周易》的乾卦象辞，意为天道运行刚健有力，君子应当效法天道，不断自我勉励，追求进步，永不停息。这句话常被用来鼓励人们要积极向上，坚持不懈地努力。"},
  {"id":"an_dk_4","sentenceId":"s_dk_4","level":"sentence","content":"【隱忍待時】初九爻辞“潜龙，勿用”意味着在事物发展的初期阶段，应当像潜藏的龙一样，保持低调，不急于表现自己，避免过早地采取行动。此时应当积蓄力量，等待时机成熟再行动。"},
  {"id":"an_dk_5","sentenceId":"s_dk_5","level":"sentence","content":"【陽爻】九二爻表示阳刚之德已经显现，如同龙出现在田野之中，象征着君子的德行开始在社会上展现。此时，适宜去见德高望重的大人物，可以获得指导和支持，有利于个人的发展和事业的推进。"},
  {"id":"an_dk_6","sentenceId":"s_dk_6","level":"sentence","content":"【勤勉謹慎】九三爻辞描述了君子应当终日保持勤奋和谨慎的态度，即使在晚上也要保持警惕，这样即使面临危险也能避免灾祸。这表明了在面对挑战和困难时，持续的努力和警觉是避免错误和危险的关键。"},
  {"id":"an_dk_7","sentenceId":"s_dk_7","level":"sentence","content":"【变動/潛在發展】九四爻辞“或跃在渊，无咎”意味着在当前的情境下，虽然存在潜在的发展机会或变化，但需要谨慎行事。如同在深渊中跃起，虽然有风险，但如果时机和条件成熟，采取行动也不会有咎害。这提示我们在面对不确定性和潜在机遇时，应当审时度势，把握时机，但同时也要保持警惕，避免盲目行动。"},
  {"id":"an_dk_8","sentenceId":"s_dk_8","level":"sentence","content":"【吉祥】九五爻辞表示飞龙在天，象征着君子或贤人处于高位，能够发挥其才能和影响力，对国家和人民都有利。此时，见到大人（即贤明的领导者）是有利的，意味着可以得到支持和指导，共同成就大事。"},
  {"id":"an_dk_9","sentenceId":"s_dk_9","level":"sentence","content":"【上九】位于最上方的阳爻，象征着事物发展到了极点，如同龙飞得过高，超过了适宜的高度，可能会遭遇挫折或后悔。这表示事物发展到极端，就会产生负面的结果，应当警惕。"},
  {"id":"an_dk_10","sentenceId":"s_dk_10","level":"sentence","content":"【吉祥】用九爻辞表示的是所有阳爻都变爻的情况，象征着最高的阳刚之气。\"见群龙无首\"意味着众多的强者或领导者没有一个明确的首领，暗示着在这种情况下，每个人都可以发挥自己的作用，没有一个人会独占鳌头，这样的状态是吉祥的。这通常被解释为在集体中，每个人都能发挥自己的作用，没有一个人会独占鳌头，这样的状态是吉祥的，也意味着在没有明确领导的情况下，每个人都能发挥自己的作用，共同完成任务。"},
  {"id":"an_dk_11","sentenceId":"s_dk_11","level":"sentence","content":"【初爻】此句出自《周易》乾卦的初九爻辞，意为龙在潜伏阶段，不宜有所作为，因为阳刚之气尚处于萌芽状态，力量还不够强大，需要积累和等待时机。"},
  {"id":"an_dk_12","sentenceId":"s_dk_12","level":"sentence","content":"【吉祥】此句出自《周易》乾卦的九二爻辞，意为龙出现在田野上，象征着有德行的人开始展现其才能和品德，对大众施以恩惠和教化，这是一种吉祥的征兆，表明有德者将得到广泛的支持和认可。"},
  {"id":"an_dk_13","sentenceId":"s_dk_13","level":"sentence","content":"【勤奋不懈】这句话出自《周易》乾卦的象辞，意为整天自强不息，不断努力，这是反复行走在正道上的表现。强调了持续努力、不断进取的重要性。"},
  {"id":"an_dk_14","sentenceId":"s_dk_14","level":"sentence","content":"【决策與行動】此句出自《易经》乾卦的九四爻辞，意为在关键时刻，应当审时度势，谨慎行动。若时机成熟，可以大胆跃进，即使面临深渊般的险境，只要行动得当，也能避免灾祸。此句强调了在关键时刻做出正确决策并付诸行动的重要性。"},
  {"id":"an_dk_15","sentenceId":"s_dk_15","level":"sentence","content":"【吉祥】此句出自《易经》乾卦的九五爻辞，意为龙飞于天，象征着君子或有德之人处于高位，能够施展才能，成就大事。这是一个非常吉祥的象征，表示事业顺利，功成名就。"},
  {"id":"an_dk_16","sentenceId":"s_dk_16","level":"sentence","content":"【警示】此句出自《周易》乾卦的上九爻辞，意为龙飞得过高，终将有悔。事物发展到极盛时，必然会有衰落，盈满的状态不可能长久维持。这是一条关于物极必反、盛极而衰的警示。"},
  {"id":"an_dk_17","sentenceId":"s_dk_17","level":"sentence","content":"【哲學】此句出自《周易》中的乾卦，用九爻辞。这里的“天德”指的是天的德性，即自然的法则和最高的道德标准。这句话的意思是说，天的德性是无法被人为地置于首位或领导地位的，因为天德是自然存在的，不依赖于人的意志。它强调了顺应自然、遵循天道的重要性，体现了中国古代哲学中“天人合一”的思想。"},
  {"id":"an_dk_18","sentenceId":"s_dk_18","level":"sentence","content":"【坤卦】坤卦象征大地，具有元始、亨通的特性，适宜于雌马的贞正。君子出行，如果走在前面会迷失方向，跟在后面则能找到主人。向西南方向行进会得到朋友的帮助，向东北方向则会失去朋友。保持贞正，吉祥。"},
  {"id":"an_dk_19","sentenceId":"s_dk_19","level":"sentence","content":"【坤卦】坤卦象征大地，是至高无上的女性原则。万物依赖坤元而生，大地顺承天道，承载万物，其德行广大无边。大地包容万物，光辉宏大，各种生物都能得到滋养和亨通。坤卦如同雌马，行走在大地上没有边界，柔顺而正直。君子应当效仿坤卦的德行，如果走在前面可能会迷失方向，而跟随在后则能顺应常道。在西南方向可以找到朋友，与同类同行；在东北方向可能会失去朋友，但最终会有吉祥。保持安定和正直，就能得到大地般的广阔和吉祥。"},
  {"id":"an_dk_20","sentenceId":"s_dk_20","level":"sentence","content":"【哲學】这句话出自《周易》的《象传》。\"地势坤，君子以厚德载物\"的意思是，大地的性质是柔顺，君子应该效仿大地，以宽厚的德行来承载万物。这里强调了君子应该具备的品德，即宽容、包容和承担社会责任。这种思想在中国传统文化中占有重要地位，体现了儒家的道德观念。"},
  {"id":"an_dk_21","sentenceId":"s_dk_21","level":"sentence","content":"【警示】此爻辞意在提醒人们，当看到地面上有霜时，应当意识到严冬将至，冰冻将更加坚硬。这象征着事物的发展变化是有迹可循的，小的征兆预示着未来可能出现的重大变化，因此要及早察觉并做好准备，以防患于未然。"},
  {"id":"an_dk_22","sentenceId":"s_dk_22","level":"sentence","content":"【德行】六二爻辞描述了正直、方正、宏大的品德，即使不经过特别的学习或修炼，也不会有不利的情况发生。这表明了拥有这些美德的人自然能够得到好的结果，体现了内在品质的重要性。"},
  {"id":"an_dk_23","sentenceId":"s_dk_23","level":"sentence","content":"【柔順中正】六三爻处于下卦之上，象征着柔顺中正的美德。\"含章可贞\"意味着内心蕴含着美好的德行，能够坚守正道。\"或从王事，无成有终\"则表示在参与国家大事时，虽然可能不会取得显著的成就，但最终能够善始善终，保持自己的品德和原则。整体而言，这一爻强调了在行动中保持内心的纯洁和正直，即使不求功名，也能获得好的结果。"},
  {"id":"an_dk_24","sentenceId":"s_dk_24","level":"sentence","content":"【謹慎】六四爻辞“括囊；无咎，无誉”意味着在这个位置上，应当像扎紧袋口一样谨慎行事，保持低调，不轻易发表意见或采取行动。这样可以避免灾祸，但也不会获得特别的赞誉。这反映了在特定情境下，保持沉默和谨慎的态度是最为适宜的选择。"},
  {"id":"an_dk_25","sentenceId":"s_dk_25","level":"sentence","content":"【吉祥】六五爻辞中的“黄裳，元吉”意味着穿着黄色的下衣，大为吉祥。黄色在中国传统文化中象征着中庸、大地与尊贵，而裳（下衣）则代表谦逊与内敛。此爻辞暗示处于尊位者应保持谦逊、中庸的态度，如此则能获得吉祥。"},
  {"id":"an_dk_26","sentenceId":"s_dk_26","level":"sentence","content":"【爭斗】上六爻辞描述了龙在旷野中进行激烈的战斗，其血液呈现深黑色与黄色，象征着最高层次的争斗与冲突，预示着事物发展到极端，阴阳两极的矛盾激化，可能会带来严重的后果。"},
  {"id":"an_dk_27","sentenceId":"s_dk_27","level":"sentence","content":"【吉兆】用六的爻辞表示在任何情况下都应坚持正道，保持贞洁和忠诚，这样就会得到好的结果。\"利永贞\"意味着长期坚持正道是有利的，能够带来吉祥和成功。"},
  {"id":"an_dk_28","sentenceId":"s_dk_28","level":"sentence","content":"【警示】此句出自《易经》坤卦的初六爻辞，意为走在霜上，预示着冰冻将至，阴寒之气开始凝结。如果继续沿着这条道路前行，最终会到达坚冰之地。这句话警示人们要对初期的细微征兆保持警觉，因为这些征兆可能会逐渐积累，最终导致严重的后果。"},
  {"id":"an_dk_29","sentenceId":"s_dk_29","level":"sentence","content":"【自然與德行】此句出自《周易》坤卦的爻辞，意为六二爻的变动，是正直而方正的。即使不刻意学习，也不会有不利，因为这是地道（大地的德行）的光辉所在。这里强调了自然的德行和正直的重要性，以及顺应自然规律的积极意义。"},
  {"id":"an_dk_30","sentenceId":"s_dk_30","level":"sentence","content":"【智慧與時機】这句话出自《周易》的象辞，意为内含美德可以守正，根据时机而行动。如果参与国家大事，能够展现智慧和远见，使光明得以发扬光大。这表明了在适当的时候采取行动的重要性，以及智慧和美德对于成就大事的关键作用。"},
  {"id":"an_dk_31","sentenceId":"s_dk_31","level":"sentence","content":"【謹慎】此句意为包容而谨慎行事，不会招致灾祸。强调了在行动和决策中保持谨慎态度的重要性，避免因鲁莽而带来的不利后果。"},
  {"id":"an_dk_32","sentenceId":"s_dk_32","level":"sentence","content":"【吉祥】此句出自《周易》坤卦的爻辞，意为穿着黄色裙裳的人会得到吉祥，因为黄色代表中和之色，象征着内在的美德和中庸之道。这里的“文在中”指的是内在的文德，即内在的修养和美德。整体而言，这句话表达了内在美德和中庸之道能够带来吉祥和好的结果。"},
  {"id":"an_dk_33","sentenceId":"s_dk_33","level":"sentence","content":"【困頓】此句出自《周易》中的卦辞，意为龙在旷野中战斗，象征着力量强大的一方陷入了困境，无法施展其应有的能力，处于穷途末路的状态。这通常表示当前的形势对主体不利，需要寻找出路。"},
  {"id":"an_dk_34","sentenceId":"s_dk_34","level":"sentence","content":"【吉兆】用六爻得到永贞的卦象，意味着最终会有一个大的结局或结果，象征着事情会有一个好的、圆满的结局。"},
  {"id":"an_dk_35","sentenceId":"s_dk_35","level":"sentence","content":"【乾卦】此卦辞出自《周易》乾卦。乾卦象征天，代表刚健、积极向上的力量。卦辞“元亨，利贞，勿用有攸往，利建侯”意为：大为亨通，利于守正，不宜有所行动，利于建立诸侯。这表明在当前形势下，应当保持正直、稳重的态度，不宜轻举妄动，而应积极培养和选拔人才，为未来的发展奠定基础。"},
  {"id":"an_dk_36","sentenceId":"s_dk_36","level":"sentence","content":"【初生艱難】屯卦象征事物初生时的艰难状态。刚柔始交，意味着阳刚与阴柔初次相遇，产生新的事物或局面，但同时也伴随着困难和挑战。动乎险中，表明在这种状态下行动充满风险。大亨贞，意味着在艰难中坚持正道，最终能够获得大的亨通。雷雨之动满盈，形容雷雨交加，充满力量，象征着新生事物的蓬勃生机。天造草昧，形容天地初开，万物初生，一片混沌。宜建侯而不宁，意味着在这种环境下，应当建立诸侯，但局势仍然不稳定，需要不断努力和调整。"},
  {"id":"an_dk_37","sentenceId":"s_dk_37","level":"sentence","content":"【自然與人文】此句大象辞出自《周易》屯卦，描述了自然界中云和雷的景象，象征着事物初生时的艰难与阻碍。同时，它也启示君子应当效法自然界的这种状态，在面对困难时，应有条不紊地进行筹划与治理，以智慧和勇气克服挑战，开创事业。"},
  {"id":"an_dk_38","sentenceId":"s_dk_38","level":"sentence","content":"【吉兆】初九爻辞中的“磐桓”意味着稳固而持久的状态，象征着事物处于稳定的基础之上。此爻辞建议在当前情况下，适宜保持坚定和稳定，不要轻举妄动。同时，“利居贞”表示在这样的环境中，保持正直和贞洁的品质是有利的。“利建侯”则意味着在这种稳固的基础上，建立或支持新的秩序、制度或领导是有利的。整体来看，这是一个积极的爻辞，预示着通过保持稳定和正直，可以为未来的发展奠定良好的基础。"},
  {"id":"an_dk_39","sentenceId":"s_dk_39","level":"sentence","content":"【婚姻】六二爻辞描述了一种艰难而徘徊不前的状态，象征着在婚姻或情感关系中遇到的阻碍和不确定性。爻辞中的“匪寇婚媾”表明，虽然外界的干扰不是来自敌对势力，但婚姻的进展仍然受到了阻碍。而“女子贞不字，十年乃字”则意味着女子在保持贞洁的同时，需要经历长时间的等待，最终才能获得婚姻的幸福。这反映了在面对困难时，保持坚定和耐心的重要性。"},
  {"id":"an_dk_40","sentenceId":"s_dk_40","level":"sentence","content":"【决策與行動】爻辞描述了在追逐鹿的过程中，没有向导（虞）的帮助，鹿逃入了森林中。对于君子来说，此时应当机智地判断形势，认识到继续追逐可能会带来不利的结果，不如放弃追逐。这反映了在面对困难或不确定的情况时，明智的选择是审时度势，适时放弃，避免更大的损失。"},
  {"id":"an_dk_41","sentenceId":"s_dk_41","level":"sentence","content":"【婚姻】六四爻辞描述了一种积极主动追求婚姻的情景，其中“乘马班如”象征着准备充分、态度庄重地去求婚，“求婚媾”直接表达了求婚的意愿。爻辞中的“往吉，无不利”则预示着求婚将会顺利，结果吉祥，没有任何不利的因素。整体来看，这一爻辞强调了在婚姻大事上，积极主动的态度和充分的准备能够带来好的结果。"},
  {"id":"an_dk_42","sentenceId":"s_dk_42","level":"sentence","content":"【中正難行】九五爻处于屯卦的君位，象征着领导或决策者在艰难时期中处于核心位置。\"屯其膏\"意味着资源或权力被囤积，未能有效流通或利用。\"小贞吉，大贞凶\"表示在这种情况下，小规模的、谨慎的行动是吉利的，而大规模的、激进的行动则可能带来危险。这反映了在资源有限、形势不明朗时，应采取保守策略，避免过度扩张或冒险。"},
  {"id":"an_dk_43","sentenceId":"s_dk_43","level":"sentence","content":"【困頓】上六爻辞描述了一种极度困顿和绝望的情境，乘马班如，意味着行动受阻，无法前进；泣血涟如，形容悲痛至极，泪如雨下，甚至泣血。整体表达了在困境中挣扎、痛苦不堪的状态。"},
  {"id":"an_dk_44","sentenceId":"s_dk_44","level":"sentence","content":"【品德】虽然处于困境，但志向和行为依然正直。以尊贵的身份谦卑待人，能够获得广泛民众的支持和爱戴。这体现了高尚的品德和正确的价值观。"},
  {"id":"an_dk_45","sentenceId":"s_dk_45","level":"sentence","content":"【困境與轉变】六二爻处于困难之中，是因为它位于刚爻之上，象征着柔弱者面对强硬的力量。经过十年的时间，最终能够得到解决或命名，这表明情况发生了逆转，回归到了正常的状态。这里的“十年乃字”意味着长时间的努力和等待，最终能够克服困难，实现转变。"},
  {"id":"an_dk_46","sentenceId":"s_dk_46","level":"sentence","content":"【决策與行動】此句出自《周易》中的小象辞，意为追逐鹿时没有虞人（古代掌管山泽的官）的引导，会导致放纵禽兽而难以捕获。君子应当放弃这种无虞的追逐，否则将会陷入困境和后悔。这说明在决策和行动时，应当谨慎行事，避免盲目追求而忽视了潜在的风险和困难。"},
  {"id":"an_dk_47","sentenceId":"s_dk_47","level":"sentence","content":"【求索】此句意为在追求目标的过程中，主动前行，能够使目标更加清晰明确。表明了积极进取、勇于探索的态度。"},
  {"id":"an_dk_48","sentenceId":"s_dk_48","level":"sentence","content":"【困頓】此句出自《周易》屯卦的爻辞，意为屯积其油脂，未能广泛施用。比喻处于困顿状态，资源虽有但未能有效利用，未能发挥其应有的光采和作用。"},
  {"id":"an_dk_49","sentenceId":"s_dk_49","level":"sentence","content":"【情感】这句话表达了极度悲伤和痛苦的情感，\"泣血涟如\"形容泪水如血般流淌，\"何可长也\"则表达了这种悲伤无法长久持续的愿望或无奈。整体上，这句话反映了人在面对巨大悲痛时的内心世界。"},
  {"id":"an_dk_50","sentenceId":"s_dk_50","level":"sentence","content":"【教育/啟蒙】蒙卦象征启蒙和教育。卦辞表明，教育应当是学生主动求知，而非教师强加。初次求教时应当给予指导，但如果反复求问而不思考，便是对教育的轻慢，此时不应再给予指导。卦辞还强调了坚守正道的重要性。"},
  {"id":"an_dk_51","sentenceId":"s_dk_51","level":"sentence","content":"【蒙卦】蒙卦象征着蒙昧、启蒙。卦象为山下有险，表示在险阻之下，人们容易陷入蒙昧的状态。但蒙卦也意味着亨通，通过适当的行动和时机，可以克服蒙昧，达到亨通。卦辞中提到“匪我求童蒙，童蒙求我”，表示启蒙者不应主动去求教于蒙昧者，而应等待蒙昧者主动求教，这样才能心志相应。初时的告诫是刚中之道，而反复的亵渎则会导致不再告诫，这是对蒙昧的警示。最终，通过正确的启蒙和教化，可以培养正直的品德，这是圣人的功绩。"},
  {"id":"an_dk_52","sentenceId":"s_dk_52","level":"sentence","content":"【象辭】此句出自《周易》蒙卦的象辞，意为山下有泉水涌出，象征着蒙昧中开始出现智慧的萌芽。君子应当效法此象，以果断的行动培养和提升自己的德行。"},
  {"id":"an_dk_53","sentenceId":"s_dk_53","level":"sentence","content":"【啟蒙】初六爻辞描述了启蒙的初始阶段，此时需要通过一定的约束和规范来引导和教育。\"发蒙\"意味着开始启蒙，\"利用刑人\"表示通过一定的规则和惩罚来教育人，\"用说桎梏\"则意味着通过言语和行为的规范来解除束缚，使被启蒙者能够逐渐摆脱愚昧。\"以往吝\"则提示，如果过于依赖过去的旧方法，将会导致不利的结果。整体而言，初六爻辞强调了在启蒙过程中，适当的规范和引导是必要的，但也要注意方法的灵活性和适时性。"},
  {"id":"an_dk_54","sentenceId":"s_dk_54","level":"sentence","content":"【吉兆】九二爻辞表示包容蒙昧可以获得吉祥，接纳妇人也能得到吉祥，儿子能够管理好家庭。这说明在这一爻中，包容、接纳和信任能够带来好的结果，家庭和事业都能得到良好的发展。"},
  {"id":"an_dk_55","sentenceId":"s_dk_55","level":"sentence","content":"【婚姻與人际關系】六三爻辞告诫人们不要急于娶妻，因为可能会遇到一个外表光鲜但内心不正直的人。爻辞中的“见金夫，不有躬”意味着此人虽然外表看起来富有、有魅力，但实际上可能品行不端，不可信赖。因此，爻辞认为在这种情况下娶妻是不利的，暗示在选择伴侣时应更加慎重，注重对方的内在品质而非外在条件。"},
  {"id":"an_dk_56","sentenceId":"s_dk_56","level":"sentence","content":"【困頓】处于六四位置的人，仍然处于蒙昧的状态，无法摆脱困境，这表明其处境艰难，需要谨慎行事，以免招致更多的困难。\"吝\"意味着此时的行动可能会受到限制，或者需要付出更多的努力才能取得进展。"},
  {"id":"an_dk_57","sentenceId":"s_dk_57","level":"sentence","content":"【啟蒙】此爻表示处于蒙昧状态，但如同孩童般纯真，易于接受教导和启发，因此吉祥。意味着在这一阶段，应保持谦逊和开放的心态，积极寻求指导和学习，以促进个人的成长和发展。"},
  {"id":"an_dk_58","sentenceId":"s_dk_58","level":"sentence","content":"【决策與行動】上九爻辞“击蒙；不利为寇，利御寇”意味着在面对蒙昧或混乱的情况时，采取主动出击的态度是必要的，但不应以侵略或攻击的方式行事，而应以防御的姿态来应对挑战。这表明在处理问题时，应当积极主动，但同时保持谨慎和防御性，避免不必要的冲突。"},
  {"id":"an_dk_59","sentenceId":"s_dk_59","level":"sentence","content":"【刑法】这句话的意思是通过惩罚犯罪的人来维护法律的公正和权威。这里的“刑人”指的是受到法律制裁的犯罪分子，“正法”则是指通过这种惩罚来达到法律的正确实施和维护社会秩序的目的。"},
  {"id":"an_dk_60","sentenceId":"s_dk_60","level":"sentence","content":"【家庭與人际關系】此句出自《周易》中的小象辞，意指儿子能够继承家业，刚强与柔和相互配合。这反映了家庭成员之间的和谐关系以及年轻一代对家族责任的承担。"},
  {"id":"an_dk_61","sentenceId":"s_dk_61","level":"sentence","content":"【婚姻】此句意指不宜娶妻，因为当前的行动或情况并不顺利，可能带来不利影响。在古代占卜中，这通常意味着在当前的时机下，进行婚姻大事可能会遇到阻碍或不顺，建议暂缓考虑。"},
  {"id":"an_dk_62","sentenceId":"s_dk_62","level":"sentence","content":"【困頓與迷茫】此句出自《周易》蒙卦的爻辞，意指在蒙昧或困惑的状态中，处于不利的位置，远离了真实和实质，独自承受着艰难和限制。这反映了在成长或求知的过程中，可能会遇到的孤立无援和难以突破的困境。"},
  {"id":"an_dk_63","sentenceId":"s_dk_63","level":"sentence","content":"【啟蒙】此句出自《周易》蒙卦的象辞，意为在启蒙教育的过程中，如果能够以柔和谦逊的态度去引导，就能获得吉祥的结果。这里强调了教育者应当以温和、顺应的方式进行教导，使受教者能够顺利接受并成长。"},
  {"id":"an_dk_64","sentenceId":"s_dk_64","level":"sentence","content":"【人际關系】这句话出自《易经》中的小象辞，意为在与人交往中，通过智慧和策略来应对和利用对方，可以使上下关系和谐顺畅。这里的“御寇”指的是应对和处理人际关系中的矛盾和冲突，而“上下顺也”则表示通过恰当的方法，可以使上下级关系或各种社会关系变得和谐。"},
  {"id":"an_dk_65","sentenceId":"s_dk_65","level":"sentence","content":"【等待與准備】需卦象征着等待与准备。卦辞中的“有孚，光亨，贞吉”意味着在等待的过程中，要保持诚信和光明正大的态度，坚守正道，最终会获得吉祥的结果。“利涉大川”则表示在做好充分准备后，可以顺利渡过难关或完成重大任务。"},
  {"id":"an_dk_66","sentenceId":"s_dk_66","level":"sentence","content":"【需卦】需卦象征等待和准备。卦辞中的“须也”表示需要等待时机，因为“险在前也”，意味着前方有危险或障碍。然而，由于卦象显示“刚健而不陷”，即内卦乾（天）象征刚健，外卦坎（水）象征险，整体上表现出刚健而不被险境所困，因此“其义不困穷矣”，即其意义在于不会陷入困境。需卦还强调“有孚，光亨，贞吉”，意味着在等待中保持诚信，光明正大，坚守正道，最终会吉祥。此外，“位乎天位，以正中也”表示需卦的上爻处于天位，象征着正直和中庸之道。最后，“利涉大川，往有功也”意味着在经过充分准备后，可以顺利渡过大河，前往远方，最终取得成功。"},
  {"id":"an_dk_67","sentenceId":"s_dk_67","level":"sentence","content":"【自然與人文】此句大象辞描述了自然界的景象与人文活动的结合。\"云上于天，需\"表示天空中云层聚集，预示着需要等待或准备的情况；\"君子以饮食宴乐\"则指君子在此时应当享受生活，进行饮食和娱乐活动。整体表达了在自然变化中，人们应当顺应时势，适时享受生活的哲学思想。"},
  {"id":"an_dk_68","sentenceId":"s_dk_68","level":"sentence","content":"【等待與准備】初九爻辞描述了在郊外等待的情景，强调了在行动之前需要有耐心和准备。\"利用恒\"意味着在这个阶段，保持恒心和持续的努力是非常重要的，这样可以避免错误和不利的情况发生。整体上，这一爻辞建议在面对挑战或机遇时，应当先做好充分的准备，保持耐心，不要急于求成。"},
  {"id":"an_dk_69","sentenceId":"s_dk_69","level":"sentence","content":"【等待】九二爻的爻辞“需于沙。小有言，终吉。”意味着在沙地上等待，虽然可能会有一些小的争议或言语上的冲突，但最终结果是吉祥的。这表明在面对困难或挑战时，保持耐心和冷静，不要急于求成，最终会迎来好的结果。"},
  {"id":"an_dk_70","sentenceId":"s_dk_70","level":"sentence","content":"【险阻】九三爻辞描述了处于困境中，如同在泥泞中挣扎，容易招致外来的侵害或麻烦。这表明在当前的情境下，行动受到了阻碍，且可能因为这种不利的位置而引发更多的问题。需要谨慎行事，避免不必要的冲突或危险。"},
  {"id":"an_dk_71","sentenceId":"s_dk_71","level":"sentence","content":"【凶险】此爻辞表示处于危险和困境之中，需要从艰难险恶的环境中脱身。\"需于血\"意味着遭遇了流血冲突或危险，\"出自穴\"则暗示需要从险境中寻找出路，摆脱困境。整体上，此爻辞提示在面对危机时要谨慎行事，寻找合适的时机和方法以摆脱困境。"},
  {"id":"an_dk_72","sentenceId":"s_dk_72","level":"sentence","content":"【吉兆】九五爻辞表示在酒食之间等待，坚守正道则吉祥。此爻象征在安逸环境中保持清醒与正直，能够获得好的结果。"},
  {"id":"an_dk_73","sentenceId":"s_dk_73","level":"sentence","content":"【凶险轉吉】此爻辞描述了一种从危险或困境中转危为安的情境。爻辞中的“入于穴”象征着陷入困境或危险之中；“有不速之客三人来”则意味着在最意想不到的时候，有三位不速之客到来，这三位客人可能代表着帮助或转机；“敬之终吉”则表示如果能够以恭敬的态度对待这些不速之客，最终会得到好的结果。整体而言，此爻辞传达了在面对困境时，保持谦逊和敬畏之心，积极应对，最终能够化险为夷的信息。"},
  {"id":"an_dk_74","sentenceId":"s_dk_74","level":"sentence","content":"【需卦】需卦象征等待和准备。卦辞“需于郊，不犯难行也”意味着在郊外等待，不急于行动，避免遇到困难。接着，“利用恒，无咎；未失常也”表示在这种情况下，保持恒心和常态，不会有过失。整体而言，需卦强调在面对困难时，应耐心等待时机，保持常态，不要轻举妄动。"},
  {"id":"an_dk_75","sentenceId":"s_dk_75","level":"sentence","content":"【吉凶】此辞意为在沙滩上需要有所行动，但行动要保持中庸之道。虽然可能会有小的争议或言语上的冲突，但最终结果是吉祥的。这表明在处理事情时，即使遇到小的阻碍，只要保持中庸和谨慎，最终仍能获得好的结果。"},
  {"id":"an_dk_76","sentenceId":"s_dk_76","level":"sentence","content":"【困境與警戒】这段小象辞描述了一种处于困境中的状态，需要在泥泞中前行，外部环境充满灾难和危险。同时，它也提醒人们，困境往往是由于自身的行为引起的，因此需要保持警觉和谨慎，以避免失败。这表明在面对困难时，自我反省和谨慎行事是非常重要的。"},
  {"id":"an_dk_77","sentenceId":"s_dk_77","level":"sentence","content":"【順應】这句话的意思是在强调在某些情况下，需要采取顺应的态度和行为。\"需于血\"意味着在某些艰难或危险的情况下，需要有牺牲或付出的决心；\"顺以听也\"则表示在这种情况下，应该保持谦逊，听从他人的意见或顺应环境的变化。整体上，这句话是在教导人们在面对困难时，要有顺应的态度，不要过于固执。"},
  {"id":"an_dk_78","sentenceId":"s_dk_78","level":"sentence","content":"【吉兆】此辞表示在饮酒和饮食方面保持中正的态度是吉祥的。意味着在享受生活的同时，要保持适度和正直，不要过度放纵。"},
  {"id":"an_dk_79","sentenceId":"s_dk_79","level":"sentence","content":"【人际關系】这段小象辞描述了对待不速之客的态度。虽然客人来得突然，但以礼相待，最终会带来吉祥的结果。即使自己处于不当的位置，也不会有大的损失。这表明在人际交往中，保持礼貌和尊重，即使在不利的情况下，也能获得好的结果。"},
  {"id":"an_dk_80","sentenceId":"s_dk_80","level":"sentence","content":"【冲突與解决】讼卦象征着争执、诉讼或冲突。卦辞中的“有孚，窒”表示在争执中，诚信受到阻碍，沟通不畅。而“惕中吉”则意味着在谨慎处理争执的过程中，保持中庸的态度可以获得吉祥的结果。然而，“终凶”提示如果争执持续下去，最终会导致不好的结果。卦辞还提到“利见大人，不利涉大川”，意味着在这种情况下，寻求有智慧和权威的人的帮助是有利的，但不宜冒险进行大的行动或决策，如跨越大河，象征着避免进行风险过大的项目或行动。"},
  {"id":"an_dk_81","sentenceId":"s_dk_81","level":"sentence","content":"【卦象與卦德】此彖辞描述了讼卦的卦象和卦德。讼卦的上卦为乾，象征刚健；下卦为坎，象征险陷。整体卦象呈现出上刚下险的特点，象征着在险境中仍能保持刚健的态度，但这种态度容易引发争讼。讼卦的卦德强调了诚信（孚）、警惕（惕）、中正（中）等品质，认为在争讼中保持这些品质是吉祥的。然而，讼卦最终的结果是凶险的，表明争讼本身是不可取的。彖辞还提到“利见大人”，意味着在争讼中寻求公正的裁决者是有利的，因为大人代表了中正和公正。最后，“不利涉大川”则比喻在争讼中不应冒险，否则会陷入更深的困境，如同落入深渊。"},
  {"id":"an_dk_82","sentenceId":"s_dk_82","level":"sentence","content":"【天水訟】此辞出自《周易》中的讼卦，天与水违行，象征着争讼、冲突。君子应当在做事之前深思熟虑，从源头上避免争端的发生，以谋始为要。"},
  {"id":"an_dk_83","sentenceId":"s_dk_83","level":"sentence","content":"【初爻】初六爻辞表示在事情的开始阶段，不要过于执着于当前的事务，可能会有一些小的批评或意见，但最终会有好的结果。这提示我们在面对新事物时，应保持开放和灵活的态度，不要固执己见，这样才能获得更好的发展。"},
  {"id":"an_dk_84","sentenceId":"s_dk_84","level":"sentence","content":"【退避】九二爻辞描述了在争讼中无法取胜，选择退避回家，甚至离开自己的居所以躲避争端。尽管如此，其领地内的三百户人家并未因此受到灾祸，表明这种退避的选择是明智的，避免了更大的损失。此爻辞强调了在不利情况下，适时退让以保全自身的重要性。"},
  {"id":"an_dk_85","sentenceId":"s_dk_85","level":"sentence","content":"【吉凶未定】六三爻辞的意思是，依靠旧有的德行和资源生活，坚守正道会有危险，但最终会吉祥。如果参与君王的事业，虽然不会取得个人的成功，但会为整体带来好的结果。这表明在当前的情境下，虽然存在一定的风险和挑战，但只要保持正直和谦逊的态度，最终能够获得好的结局。"},
  {"id":"an_dk_86","sentenceId":"s_dk_86","level":"sentence","content":"【爭訟與和解】九四爻辞描述了一种在争讼中未能取胜的情况，但随后能够回归正道，改变态度，最终在安定中获得吉祥。这表明在面对冲突和争执时，适时的退让和调整自己的立场，以顺应天命，是更为明智的选择。"},
  {"id":"an_dk_87","sentenceId":"s_dk_87","level":"sentence","content":"【吉兆】九五爻辞表示在争讼中处于最有利的位置，能够获得公正的裁决，大吉大利。这通常意味着在冲突或争议中，通过正当的途径和方法，最终能够得到好的结果。"},
  {"id":"an_dk_88","sentenceId":"s_dk_88","level":"sentence","content":"【凶险】上九爻辞描述了一种表面看似得到荣誉和奖赏（或锡之鞶带），但实际上这种荣誉并不稳固，甚至在一天之内就会三次被剥夺（终朝三褫之）。这暗示了高位不稳、荣宠难持久的情况，预示着可能会遭遇小人的陷害或自身行为不当导致的名誉受损。因此，此爻辞整体上带有凶险的意味，提醒人们在获得高位或荣誉时要保持谦逊谨慎，不可骄傲自满。"},
  {"id":"an_dk_89","sentenceId":"s_dk_89","level":"sentence","content":"【訟】此辞意指事情不宜长久拖延，争讼不可持续。即使有小的争执，最终也能明辨是非。表明在面对争端时，应当及时解决，避免长期纠缠，以免事态扩大。"},
  {"id":"an_dk_90","sentenceId":"s_dk_90","level":"sentence","content":"【爭訟】此辞意指在争讼中无法取胜，选择退避。从下位对上位提起争讼，将会招致祸患。这表明在面对强权或上级时，直接对抗往往会导致不利的后果，应当审时度势，避免不必要的冲突。"},
  {"id":"an_dk_91","sentenceId":"s_dk_91","level":"sentence","content":"【吉兆】这句话出自《周易》中的象辞，意为遵循旧有的德行，跟随在上的领导是吉祥的。这表明在当前的情境下，保持传统美德，服从上级的指导，将会带来好的结果。"},
  {"id":"an_dk_92","sentenceId":"s_dk_92","level":"sentence","content":"【变化與穩定】这句话意味着在变化中找到新的定位，同时保持内心的安定和贞正。即使环境发生变化，也要保持自己的原则和立场，不失本心。"},
  {"id":"an_dk_93","sentenceId":"s_dk_93","level":"sentence","content":"【吉凶】此句出自《周易》讼卦的卦辞，意为在争讼中能够获得大吉的结果，是因为行为中正，没有偏离正道。这表明在处理矛盾和冲突时，保持公正、中立的态度，遵循正道，可以得到好的结果。"},
  {"id":"an_dk_94","sentenceId":"s_dk_94","level":"sentence","content":"【爭訟】通过争讼获得的官职或荣誉，也不值得尊敬。这句小象辞告诫人们，通过诉讼或争执得到的东西，即使表面上看似光鲜，实际上并不值得骄傲或尊敬。"},
  {"id":"an_dk_95","sentenceId":"s_dk_95","level":"sentence","content":"【吉兆】此卦辞表明在进行决策或行动时，若能坚守正道，听取有智慧和经验的长者（丈人）的意见，将会吉祥且无任何灾祸。"},
  {"id":"an_dk_96","sentenceId":"s_dk_96","level":"sentence","content":"【卦辭】这段文字是《周易》中关于“师卦”的彖辞。师卦象征着军队或大众，强调的是正直和领导力。彖辞解释了师卦的含义，指出能够以正直领导大众的人，具备了成为王者的条件。卦象显示刚中而应，意味着领导者既有坚定的原则，又能得到民众的响应；行险而顺，表示在艰难险阻中仍能顺应时势。因此，即使面对困难，民众也会跟随这样的领导者，最终能够获得吉祥，不会有灾祸。"},
  {"id":"an_dk_97","sentenceId":"s_dk_97","level":"sentence","content":"【地水師】此句出自《周易》中的师卦，象征着大地中蕴含着水，意味着军队或集体的力量。君子应当效法大地的包容和水的滋养，容纳百姓，养育民众，以德服人，团结众人，共同进退。"},
  {"id":"an_dk_98","sentenceId":"s_dk_98","level":"sentence","content":"【軍队/紀律】初六爻辞表示军队出征必须遵守严格的纪律，如果纪律不严明，将会导致凶险的结果。这强调了在集体行动中，尤其是军事行动中，纪律的重要性。"},
  {"id":"an_dk_99","sentenceId":"s_dk_99","level":"sentence","content":"【軍队與領导】九二爻辞描述了在军队中担任领导角色的情景，能够得到吉祥的结果，没有灾难。这里的“王三锡命”意味着君王三次赐予命令或嘉奖，象征着领导者的才能和功绩得到了高度的认可和重视。这表明在团队或组织中，有能力的领导者能够带领团队取得成功，并获得上级的赏识和奖励。"},
  {"id":"an_dk_100","sentenceId":"s_dk_100","level":"sentence","content":"【凶险】六三爻辞描述了军队可能遭遇惨败，战车装载着尸体返回，预示着凶险的结果。这表明在行动中可能会遇到严重的失败和损失，需要谨慎行事，避免轻率的决策。"},
  {"id":"an_dk_101","sentenceId":"s_dk_101","level":"sentence","content":"【軍队/軍事行動】六四爻辞描述了军队在行动中采取了左侧的驻扎位置，但并没有因此而遭遇灾难或错误。这表明在军事行动中，即使采取了某些看似不利的行动，只要策略得当，仍然可以避免灾难。此爻也暗示在面对困难或挑战时，适当的调整和变通是必要的。"},
  {"id":"an_dk_102","sentenceId":"s_dk_102","level":"sentence","content":"【軍事行動】爻辞描述了在田地里发现禽兽，适宜采取行动捕捉，不会有过失。这象征着在军事行动中，如果由有经验的长者（长子）来领导军队，将会取得胜利；但如果由缺乏经验的年轻人（弟子）来指挥，将会导致失败和灾难。爻辞强调了在重要事务中选择合适的领导者的重要性。"},
  {"id":"an_dk_103","sentenceId":"s_dk_103","level":"sentence","content":"【吉凶未定】此爻辞表明，上六爻处于卦的最高位置，象征着最高权力的决策。爻辞中的“大君有命”意味着君主发布了重要的命令，而“开国承家”则表示这个命令关乎国家的建立和家族的传承。然而，“小人勿用”则警告在执行这些重要任务时，不可任用品行不端的小人。整体来看，此爻辞既有可能带来积极的结果，也存在因用人不当而导致的潜在风险，因此吉凶未定。"},
  {"id":"an_dk_104","sentenceId":"s_dk_104","level":"sentence","content":"【軍事】这句话出自《周易》中的师卦，意为军队出征必须有严格的纪律，如果失去了纪律，就会招致凶险。这强调了在军事行动中，纪律的重要性。"},
  {"id":"an_dk_105","sentenceId":"s_dk_105","level":"sentence","content":"【吉祥與榮譽】此辞意为在军队中吉祥，是因为得到了上天的宠爱。君王三次赐予命令，表达了对小象的重视和信任，也体现了君王胸怀万邦、治理天下的宏图大志。"},
  {"id":"an_dk_106","sentenceId":"s_dk_106","level":"sentence","content":"【凶】此句出自《周易》师卦的爻辞，意为军队出征，却可能遭遇失败，损失惨重，无法取得大的功绩。这预示着行动可能会以失败告终，因此属于不吉利的预测。"},
  {"id":"an_dk_107","sentenceId":"s_dk_107","level":"sentence","content":"【吉】此句意为在左侧辅助位置上行事没有过失，是因为没有偏离常规和正道。表明在辅助或次要的位置上，只要遵循正确的原则和方法，就能避免错误，获得吉祥的结果。"},
  {"id":"an_dk_108","sentenceId":"s_dk_108","level":"sentence","content":"【軍事】这段小象辞描述了两个不同的军事行动。\"长子帅师，以中行也\"意味着长子（可能是家族或国家的继承人）率领军队，采取了中庸之道，即行动既不过于激进也不过于保守，体现了稳健和谨慎的领导风格。\"弟子舆尸，使不当也\"则描述了弟子（可能是长子的副手或下属）在行动中失败，导致了惨重的损失（舆尸，即运送尸体），这表明弟子在执行任务时选择了不当的策略或方法。整体来看，这段小象辞强调了领导者的决策和行动方式对军事行动成败的影响。"},
  {"id":"an_dk_109","sentenceId":"s_dk_109","level":"sentence","content":"【政治】这段小象辞出自《周易》。大君（指君主或领导者）发布命令，是为了规范和奖励功绩，确保国家的正常秩序。而小人（指品德低下或能力不足的人）不能被任用，否则会扰乱国家的治理。这反映了古代对于领导者选贤任能、维护社会秩序的重视。"},
  {"id":"an_dk_110","sentenceId":"s_dk_110","level":"sentence","content":"【吉兆】此卦辞表示事情最终会吉祥。进行占卜，若能坚守正道，长久保持，便不会有灾祸。但若当前局势不稳定，后来者可能会遭遇凶险。"},
  {"id":"an_dk_111","sentenceId":"s_dk_111","level":"sentence","content":"【比卦】比卦象征着团结和互助，卦象显示吉祥。比，意味着相互辅助，下级顺从上级。通过占卜，可以得到长久的正道，没有灾难，因为刚毅处于中位。不安定的局面将会过去，上下相应，团结一致。但如果迟疑不决，将会遭遇凶险，因为道路已经走到尽头。"},
  {"id":"an_dk_112","sentenceId":"s_dk_112","level":"sentence","content":"【比卦】此句出自《周易》中的比卦。比卦象征着亲密、和谐与互助。卦辞描述了地上有水，水与地相接，象征着亲密无间的关系。古代的先王以此为启示，建立众多国家，并与诸侯建立亲密的关系，以达到国家的稳定与繁荣。比卦强调了团结合作、和睦相处的重要性。"},
  {"id":"an_dk_113","sentenceId":"s_dk_113","level":"sentence","content":"【人际關系】初六爻辞表示，以诚信待人，与人亲近，不会有灾祸。诚信如同满溢的瓦罐，最终会带来意想不到的好事，吉祥。这说明在人际交往中，诚信和友善是非常重要的，能够带来好的结果。"},
  {"id":"an_dk_114","sentenceId":"s_dk_114","level":"sentence","content":"【內部關系】六二爻辞表示，从内部建立良好的关系，保持正直和忠诚，将会带来吉祥的结果。这说明在处理人际关系时，内部的和谐与信任是非常重要的。"},
  {"id":"an_dk_115","sentenceId":"s_dk_115","level":"sentence","content":"【人际關系】此爻辞意指与不正之人交往或结盟，暗示在人际关系中可能遇到了不可靠或不良的人。告诫在选择合作伙伴或朋友时要谨慎，避免受到不良影响或损失。"},
  {"id":"an_dk_116","sentenceId":"s_dk_116","level":"sentence","content":"【外卦】六四爻位于外卦，象征着与外部环境或他人的关系。爻辞“外比之，贞吉”意味着在与外界交往时，保持正直和诚信的态度，能够获得吉祥的结果。这提示我们在处理外部关系时，应当坚持原则，真诚待人，这样才能得到他人的信任和支持，从而达到良好的合作效果。"},
  {"id":"an_dk_117","sentenceId":"s_dk_117","level":"sentence","content":"【吉兆】九五爻辞表示的是在显赫的地位上与人亲近，君王用三面包围的方式狩猎，前方的猎物得以逃脱。邑中的人们并不因此而感到惊慌或警戒，反而吉祥。这象征着在高位者能够以宽厚的态度对待他人，不追求绝对的控制，从而获得吉祥的结果。"},
  {"id":"an_dk_118","sentenceId":"s_dk_118","level":"sentence","content":"【凶险】上六爻辞“比之无首，凶”意味着在与人交往或结盟时，如果缺乏明确的领导或方向，将会导致凶险的局面。这提示我们在合作或结交时，需要有明确的领导者和目标，否则容易陷入混乱和危险之中。"},
  {"id":"an_dk_119","sentenceId":"s_dk_119","level":"sentence","content":"【吉兆】此句意为与初六相比，有其他的吉祥之兆。表明在当前的情境下，虽然与初六的情况有所不同，但出现了更为有利的吉兆，预示着事情的发展将更加顺利。"},
  {"id":"an_dk_120","sentenceId":"s_dk_120","level":"sentence","content":"【內部關系】这句话出自《易经》的象辞，意为在比较或交往中，保持内心的坚定和自我，不因外界的影响而失去自我。这里的“比之自内”指的是从内心出发，与他人建立关系或进行比较；“不自失也”则强调在这一过程中，要保持自我，不迷失自己。"},
  {"id":"an_dk_121","sentenceId":"s_dk_121","level":"sentence","content":"【人际關系】这句话出自《易经》中的比卦，意为与不正直的人交往，难道不是一种伤害吗？这反映了在人际交往中，选择合适的朋友和伙伴的重要性，以及避免与不良之人交往的必要性。"},
  {"id":"an_dk_122","sentenceId":"s_dk_122","level":"sentence","content":"【人际關系】这句话的意思是说，与贤德的人交往，以便能够追随和学习他们的高尚品德。这表明了在人际交往中，选择与品德高尚的人为伍，可以提升自己的道德水平和行为标准。"},
  {"id":"an_dk_123","sentenceId":"s_dk_123","level":"sentence","content":"【吉兆】此辞表示处于正中之位，得到吉祥的比附。选择顺从而舍弃逆反，如同狩猎时前方的禽兽自然落入网中。邑人无需警戒，因为上级的治理得当，体现了中庸之道。"},
  {"id":"an_dk_124","sentenceId":"s_dk_124","level":"sentence","content":"【凶】此句意为在比较中没有明确的领导者或方向，最终将无法达成目标或结局。比喻做事没有明确的领导或方向，容易导致失败。"},
  {"id":"an_dk_125","sentenceId":"s_dk_125","level":"sentence","content":"【蓄積待發】小畜卦象征着力量的积蓄和准备，但尚未达到爆发或行动的时机。卦辞中的“亨”表示亨通，但“密云不雨”则意味着虽然条件看似成熟，但时机尚未到来，需要耐心等待。从“自我西郊”可以看出，这种等待和准备是出于自身的选择和需要，而不是外界的强迫。整体而言，小畜卦提示我们在力量积蓄的过程中要保持耐心，等待最佳时机的到来。"},
  {"id":"an_dk_126","sentenceId":"s_dk_126","level":"sentence","content":"【卦象與卦辭】小畜卦的彖辞描述了柔爻得位，上下爻相应，象征着小规模的畜养或积累。卦象由下乾上巽组成，乾为健，巽为顺，表示刚健而能谦逊，刚中而志向得以实现，因此亨通。然而，由于条件尚未成熟，如同密云未雨，还需继续前行。从自我所在的西郊出发，表明施政或行动尚未展开。"},
  {"id":"an_dk_127","sentenceId":"s_dk_127","level":"sentence","content":"【卦辭】这是《周易》中“小畜卦”的卦辞。“风行天上，小畜”描述了风在天上运行，象征着小的积蓄或收敛。君子观此象，应当修养自己的文德，即内在的道德修养和外在的文化表现，以达到内外兼修的境界。"},
  {"id":"an_dk_128","sentenceId":"s_dk_128","level":"sentence","content":"【吉兆】初九爻辞表示，回归正道，有何咎害？吉祥。此爻象征着事物开始回归正道，没有过错，预示着吉祥的结果。"},
  {"id":"an_dk_129","sentenceId":"s_dk_129","level":"sentence","content":"【吉兆】九二爻辞“牵复，吉”意味着在这一爻的位置上，通过与他人合作或跟随他人的引导，能够回归正道，获得吉祥的结果。这表明在遇到困难或偏离正轨时，寻求他人的帮助和支持是明智的选择，能够带来积极的转变。"},
  {"id":"an_dk_130","sentenceId":"s_dk_130","level":"sentence","content":"【家庭與關系】九三爻辞描述了一种不和谐的家庭关系，其中“舆说辐”比喻家庭的正常运转出现了问题，而“夫妻反目”则直接指出了夫妻之间的矛盾和冲突。这表明在这一爻所代表的情境中，家庭成员之间的沟通和理解出现了障碍，需要通过调整和努力来恢复和谐。"},
  {"id":"an_dk_131","sentenceId":"s_dk_131","level":"sentence","content":"【吉凶】六四爻辞表示，心存诚信，可以化解争端，消除恐惧，从而避免灾祸。这里的“有孚”指的是内心充满诚信，“血去”意味着争端或冲突得以解决，“惕出”表示从恐惧中解脱出来，“无咎”则意味着没有灾祸。整体来看，这一爻辞强调了诚信和积极应对问题的重要性。"},
  {"id":"an_dk_132","sentenceId":"s_dk_132","level":"sentence","content":"【吉】九五爻辞表示诚信相连，与人关系密切，能够以自己的财富和资源惠及邻居，象征着领导者的德行和影响力，能够带动周围的人共同繁荣。此爻为吉，表明处于此位者应当发挥自己的影响力，积极行善，与人共享成果。"},
  {"id":"an_dk_133","sentenceId":"s_dk_133","level":"sentence","content":"【上九】上九爻辞描述了雨已经停止，但仍然需要承载高尚的品德。女性坚守正道会有危险。月亮接近满月时，君子出行会有凶险。这表明在事情已经完成或环境已经改变的情况下，仍需保持谨慎和高尚的品德，不可掉以轻心。女性在坚守正道时可能会遇到困难，而君子在接近成功或满月时出行则可能遭遇不测。"},
  {"id":"an_dk_134","sentenceId":"s_dk_134","level":"sentence","content":"【吉兆】此句意为返回到正道上，其含义是吉祥的。表明事物或人回归到正确的方向或状态，预示着好的结果或积极的变化。"},
  {"id":"an_dk_135","sentenceId":"s_dk_135","level":"sentence","content":"【中正】此句意为在牵挽复归的过程中，保持中庸和正直，不迷失自我。表明在行动中应保持内心的中正，不偏离正道，也不失去自己的本心。"},
  {"id":"an_dk_136","sentenceId":"s_dk_136","level":"sentence","content":"【家庭關系】这句话描述了夫妻之间出现了矛盾和冲突，导致家庭关系不和谐，无法维持正常的夫妻生活。"},
  {"id":"an_dk_137","sentenceId":"s_dk_137","level":"sentence","content":"【誠信與合作】此句意为在诚信的基础上，谨慎地采取行动，最终能够与上层或更高目标达成一致。这表明在处理事务时，保持诚信和警惕，能够获得他人的信任和支持，从而实现共同的目标。"},
  {"id":"an_dk_138","sentenceId":"s_dk_138","level":"sentence","content":"【合作共享】此句意为心中怀有诚信，彼此紧密相连，不独自享受财富，强调了合作与共享的重要性。"},
  {"id":"an_dk_139","sentenceId":"s_dk_139","level":"sentence","content":"【决策與行動】这段小象辞描述了在已经下雨并且雨势停止的情况下，君子应当积累德行，谨慎行事。如果君子在这样的情况下仍然贸然行动，可能会遭遇凶险，因为此时环境存在不确定性，需要保持警惕和审慎。"},
  {"id":"an_dk_140","sentenceId":"s_dk_140","level":"sentence","content":"【履卦】履卦象征着行走、行为、实践。卦辞“履虎尾，不咥人，亨”意味着在危险的情况下，能够谨慎行事，不被危险所伤，最终能够亨通。履虎尾，比喻人处在危险的环境中，但因为行为得当，没有被老虎咬，即没有受到伤害。这表示在处理事情时，要谨慎行事，遵守规则，才能避免灾祸，达到亨通的境地。"},
  {"id":"an_dk_141","sentenceId":"s_dk_141","level":"sentence","content":"【卦象與德行】此彖辞出自《周易》履卦，履卦的卦象为兑（泽）下乾（天）上，兑为柔，乾为刚，故曰“柔履刚也”。履卦象征着行为举止的适当与得体，强调在与人交往中应保持谦逊、和悦的态度，同时坚守正道。彖辞中提到“说而应乎乾”，意味着以和悦的态度回应刚健的原则，能够做到在险境中（如履虎尾）而不被伤害，象征着行事得当、亨通。进一步解释，“刚中正，履帝位而不疚，光明也”，表示内心刚毅中正，即使身处高位也能无愧于心，行事光明磊落。整体而言，履卦强调了在社会交往中应具备的德行与智慧。"},
  {"id":"an_dk_142","sentenceId":"s_dk_142","level":"sentence","content":"【卦辭】此句出自《周易》履卦的卦辞，履卦由上乾（天）下兑（泽）组成，象征天在上泽在下的自然秩序。君子观此卦象，应当明辨上下尊卑之分，以安定民心，维护社会秩序。"},
  {"id":"an_dk_143","sentenceId":"s_dk_143","level":"sentence","content":"【吉兆】初九爻辞中的“素履，往无咎”意味着以朴素、真诚的态度行事，前往任何地方都不会有灾祸。这表示在行动之初，保持本色，不加修饰，遵循正道，可以避免错误和灾难。"},
  {"id":"an_dk_144","sentenceId":"s_dk_144","level":"sentence","content":"【吉】九二爻辞表示走在正道上，道路宽广平坦，即使处于幽隐之地，也能保持正直，吉祥。这说明在顺境中保持谦逊，在逆境中保持坚定，都能获得好的结果。"},
  {"id":"an_dk_145","sentenceId":"s_dk_145","level":"sentence","content":"【凶险】六三爻辞描述了一个视力不佳却勉强能看，脚有残疾却勉强能走的人。这种状态下，他却去踩老虎的尾巴，结果被老虎咬伤，这是非常凶险的情况。爻辞最后提到“武人为于大君”，意味着一个武人试图担任重要的职位，但因其能力不足，可能会带来灾难性的后果。整体上，爻辞警示人们不要在自身条件不足的情况下贸然行动，否则可能会招致严重的危险。"},
  {"id":"an_dk_146","sentenceId":"s_dk_146","level":"sentence","content":"【謹慎行事】此爻辞意为在危险的情况下，如踩到老虎的尾巴，虽然会感到恐惧和不安，但只要保持警惕，谨慎行事，最终会得到吉祥的结果。这表明在面对困难和挑战时，保持冷静和谨慎的态度是非常重要的。"},
  {"id":"an_dk_147","sentenceId":"s_dk_147","level":"sentence","content":"【决策與行動】九五爻辞“夬履，贞厉”意味着在决策和行动上要果断坚定，但同时也要保持谨慎，以防可能的危险。夬履表示在履行职责或执行计划时要果敢决断，而贞厉则提醒在坚定的同时要警惕潜在的风险，保持警觉。这一爻辞强调了在关键时刻既要勇敢前行，也要审时度势，确保决策的正确性和行动的安全性。"},
  {"id":"an_dk_148","sentenceId":"s_dk_148","level":"sentence","content":"【吉兆】上九爻辞表示在行动的最后阶段，回顾并审视自己的行为，反省和总结过往的得失，能够获得吉祥的结果。这说明在完成一件事情后，进行反思和总结是非常重要的，有助于未来的成功。"},
  {"id":"an_dk_149","sentenceId":"s_dk_149","level":"sentence","content":"【个人修養】这句话出自《周易》履卦的初九爻辞，意为以朴素的态度前行，独自实践自己的志愿。这反映了一个人在行为上保持本真，不随波逐流，坚持自己的道路和理想，体现了个人的独立性和道德修养。"},
  {"id":"an_dk_150","sentenceId":"s_dk_150","level":"sentence","content":"【內心堅定】此句意指幽居之人能够保持内心的贞正吉祥，不因外界环境的影响而扰乱自己的内心，体现了在逆境中保持内心坚定与清明的品质。"},
  {"id":"an_dk_151","sentenceId":"s_dk_151","level":"sentence","content":"【卦象解釋】这段文字出自《周易》中的小象辞，是对某一卦象的具体解释。其中，“眇能视；不足以有明也”意味着眼睛虽能看见，但视力不足，无法看清事物，比喻能力有限，不足以明辨是非。“跛能履；不足以与行也”表示脚虽能行走，但步履蹒跚，无法远行，比喻行动不便，难以成事。“咥人之凶；位不当也”指出凶险是因为所处的位置不恰当，暗示身处不利的环境或地位。“武人为于大君；志刚也”则表示武人担任君主，是因为其志向刚强，有勇有谋，能够担当大任。整体上，这段文字通过具体的比喻，揭示了卦象所蕴含的哲理和警示。"},
  {"id":"an_dk_152","sentenceId":"s_dk_152","level":"sentence","content":"【吉】此辞表示最终的结果是吉祥的，意味着在经历了一番诉说或申诉之后，最终能够达到自己的志向或目标，行事顺利。"},
  {"id":"an_dk_153","sentenceId":"s_dk_153","level":"sentence","content":"【决策與行動】此句出自《周易》夬卦的爻辞，意为在行动和决策时要坚守正道，虽然可能会遇到困难和危险，但只要位置和行为正当，就能够克服困难，达到目标。这里的“夬履贞厉”强调了在关键时刻坚定地履行正道的重要性，“位正当也”则强调了行为的正当性和位置的适宜性。"},
  {"id":"an_dk_154","sentenceId":"s_dk_154","level":"sentence","content":"【吉兆】此句小象辞表示最上等的吉祥，意味着会有重大的喜庆之事发生，预示着事情的发展将非常顺利，结果极为美好。"},
  {"id":"an_dk_155","sentenceId":"s_dk_155","level":"sentence","content":"【吉祥亨通】泰卦象征着事物的通达与和谐，小的方面逐渐消退，大的方面逐渐增长，整体呈现出一种吉祥亨通的状态。此卦辞表明在当前的情境下，应当顺应这种积极向上的趋势，把握机会，促进事物的发展。"},
  {"id":"an_dk_156","sentenceId":"s_dk_156","level":"sentence","content":"【卦象與卦德】这段彖辞出自《周易》的泰卦。泰卦的卦象为地（坤）上天（乾）下，象征天地交感，万物得以畅通。从卦德上看，内卦为乾（阳），外卦为坤（阴），内刚健而外柔顺，内代表君子，外代表小人。这表明君子之道正在增长，小人之道正在消退，上下之间相互交流，志向一致，因此吉祥亨通。"},
  {"id":"an_dk_157","sentenceId":"s_dk_157","level":"sentence","content":"【天地】此句出自《周易·泰卦》的象辞，意为天地之气相交而形成和谐的状态，君主应当效法天地之道，通过合理的财政政策来辅助天地的适宜之气，以引导和帮助民众。天地交泰象征着上下沟通、内外和谐的局面。"},
  {"id":"an_dk_158","sentenceId":"s_dk_158","level":"sentence","content":"【团結合作】初九爻辞中的“拔茅茹，以其彙，征吉”意味着在行动或征途中，如果能够像拔茅草一样，连根带叶一起拔起，团结一致，共同进退，那么结果将会是吉祥的。这强调了团队合作的重要性，只有大家齐心协力，才能克服困难，取得成功。"},
  {"id":"an_dk_159","sentenceId":"s_dk_159","level":"sentence","content":"【吉】九二爻辞描述了一种包容宽广、勇于冒险但不失谨慎、不遗弃远方朋友、失去朋党但仍能获得中道支持的美德。此爻象征着在困难中保持正直和中庸之道，能够得到他人的认可和支持，是吉祥的预兆。"},
  {"id":"an_dk_160","sentenceId":"s_dk_160","level":"sentence","content":"【变化與循環】九三爻辞表达了事物变化的普遍规律，即没有平坦的道路不会变得崎岖，没有离去的事物不会返回。在艰难中保持正直，就不会有灾祸。不要忧虑，保持诚信，在生活中将会有福报。这说明了在面对困难和变化时，应保持坚定的信念和正直的品德，最终会迎来好的结果。"},
  {"id":"an_dk_161","sentenceId":"s_dk_161","level":"sentence","content":"【人际關系】爻辞描述了六四爻位的状况，象征着一个人或事物处于一种轻盈、自由的状态，但并不富有。然而，由于与邻居或周围人的良好关系，这种状态并没有带来戒备或猜疑，反而以诚信相待。这表明在处理人际关系时，诚信和信任比物质财富更为重要。"},
  {"id":"an_dk_162","sentenceId":"s_dk_162","level":"sentence","content":"【婚姻】此爻辞描述了帝乙将妹妹嫁出去的情景，象征着通过婚姻带来的福祉和大吉。在《周易》中，这通常意味着通过联姻或合作可以带来吉祥的结果，强调了和谐关系的重要性。"},
  {"id":"an_dk_163","sentenceId":"s_dk_163","level":"sentence","content":"【凶险】上六爻的爻辞描述了一种非常不利的局面。\"城復于隍\"意味着城墙倒塌，回到了护城河中，象征着防御体系的崩溃。\"勿用师\"表示在这种情况下，不应该采取军事行动，因为不会有好的结果。\"自邑告命\"意味着从自己的城市传来了不好的消息，可能是内部出现了问题。\"贞吝\"则表示即使保持正直，也会遭遇困难和阻碍。整体来看，这一爻辞预示着内外交困，不宜采取行动，需要谨慎应对。"},
  {"id":"an_dk_164","sentenceId":"s_dk_164","level":"sentence","content":"【進取】此句小象辞意为拔除茅草而前进是吉祥的，表明行动的方向和目标应当向外拓展，积极进取，不要局限于现状。"},
  {"id":"an_dk_165","sentenceId":"s_dk_165","level":"sentence","content":"【包容】此句意为能够包容荒诞不经之事，得到中庸之道的赞赏，从而达到光明正大的境界。这里的“包荒”指的是包容、接纳各种不同的事物和观点，而“得尚于中行”则表示这种包容的态度符合中庸之道，最终能够使自己变得更加光明正大。"},
  {"id":"an_dk_166","sentenceId":"s_dk_166","level":"sentence","content":"【循環往复】这句话出自《易经》的坤卦象辞，意为天地之间的运行规律是循环往复、周而复始的，没有一成不变的事物。任何事物发展到极致都会向相反的方向转化，体现了自然界和社会现象中普遍存在的对立统一和变化发展的哲学思想。"},
  {"id":"an_dk_167","sentenceId":"s_dk_167","level":"sentence","content":"【誠信】这段小象辞的意思是，行为轻浮不实，是因为失去了诚信。不以诚信来警戒自己，是因为内心真正所愿的并不是诚信。这反映了诚信在个人行为和内心意愿中的重要性。"},
  {"id":"an_dk_168","sentenceId":"s_dk_168","level":"sentence","content":"【吉祥】此句小象辞“以祉元吉，中以行愿也”意为通过福祉而达到大吉大利，是因为处于中正之位，能够实现自己的愿望。这里的“祉”指的是福泽、福祉，“元吉”则表示最大的吉祥。整句话强调了中正之道的重要性，即在行为和决策上保持中庸、正直，这样不仅能够获得福祉，还能实现个人的愿望。"},
  {"id":"an_dk_169","sentenceId":"s_dk_169","level":"sentence","content":"【國家動荡】城墙倒塌在护城河中，象征国家的根基动摇，政局混乱，命途多舛。"},
  {"id":"an_dk_170","sentenceId":"s_dk_170","level":"sentence","content":"【否卦】此卦辞表示当前的形势是不利的，处于一种闭塞、不通的状态。\"否之匪人\"意味着此时与人交往不顺利，人际关系不佳；\"不利君子贞\"则告诫君子在此时不宜固守正道，因为正道难以行得通；\"大往小来\"说明大的事物或好的机会正在离去，而小的事物或不利的情况正在到来。整体来看，这是一个需要谨慎行事、避免冒险的时期。"},
  {"id":"an_dk_171","sentenceId":"s_dk_171","level":"sentence","content":"【否卦】此卦辞描述了“否”卦的含义，表示事物处于闭塞、不通的状态。其中，“否之匪人，不利君子贞”意味着在这种状态下，正直的人难以得到好的结果，不宜固守正道。“大往小来”则表示大的力量或好的事物正在离去，而小的力量或不好的事物正在到来。从自然现象来看，这是天地不交，万物不通的状态；从社会现象来看，这是上下不交，国家将要衰败的状态。卦象显示内卦为坤（阴、柔、小人），外卦为乾（阳、刚、君子），象征着内部被阴柔的小人所控制，外部则被阳刚的君子所包围。这表明小人的势力正在增长，而君子的势力正在衰退。"},
  {"id":"an_dk_172","sentenceId":"s_dk_172","level":"sentence","content":"【困頓與節俭】此句出自《周易》的《否卦》。《否卦》象征天地之气不相交，万物生长受阻，社会环境恶劣，处于一种闭塞、不顺畅的状态。在这种情况下，君子应当保持节俭的美德，避免奢侈浪费，以减少不必要的麻烦和灾难。同时，君子不应追求荣华富贵，而应以道德修养为重，保持内心的宁静和坚定。"},
  {"id":"an_dk_173","sentenceId":"s_dk_173","level":"sentence","content":"【团結合作】初六爻辞中的“拔茅茹，以其汇”比喻人们应该像拔茅草一样，连根带叶一起拔起，团结一致，共同进退。只有这样，才能在正道上获得吉祥和亨通。此爻强调了团结合作的重要性，以及在行动中保持一致性的必要性。"},
  {"id":"an_dk_174","sentenceId":"s_dk_174","level":"sentence","content":"【吉凶】六二爻辞表示包容和承受。对于小人来说，这是吉祥的，因为他们能够得到他人的包容和帮助；但对于大人（指有德行、有地位的人）来说，这可能不是好事，因为过度的包容可能会导致原则的丧失。然而，整体上还是亨通的，意味着在适当的条件下，这种包容和承受的态度能够带来好的结果。"},
  {"id":"an_dk_175","sentenceId":"s_dk_175","level":"sentence","content":"【人际關系】六三爻辞“包羞”意味着在人际交往中，由于自己的不当行为或言辞，导致自己处于尴尬或羞愧的境地。这可能是因为过于自信、轻率行事，或是未能妥善处理与他人的关系，从而造成了不必要的麻烦。此爻提示我们，在与人交往时应保持谦逊谨慎，避免因自己的过失而陷入困境。"},
  {"id":"an_dk_176","sentenceId":"s_dk_176","level":"sentence","content":"【吉兆】九四爻辞表示得到了天命的指示，没有灾难，同类的人会因此而获得福祉。这说明在这一爻中，行动符合天意，能够得到好的结果，周围的人也会因此受益。"},
  {"id":"an_dk_177","sentenceId":"s_dk_177","level":"sentence","content":"【吉兆】九五爻辞表示在否卦中，此时出现了休止的迹象，象征着否极泰来。对于德高望重的大人来说，这是一个吉祥的征兆。然而，爻辞中“其亡其亡，系于苞桑”则提醒人们，虽然目前形势好转，但仍然要保持警惕，不可掉以轻心，要像把东西系在桑树上一样，牢牢把握住当前的机会，以防不测。整体而言，这是一个积极向上的爻辞，但同时也强调了谨慎和警觉的重要性。"},
  {"id":"an_dk_178","sentenceId":"s_dk_178","level":"sentence","content":"【轉折】上九爻的爻辞“倾否，先否后喜”意味着在经历了长时间的闭塞和不利之后，形势开始发生转变，最终否极泰来，迎来好的结果。这里的“倾否”表示否卦的局面开始倾覆，而“先否后喜”则说明了从不利到有利的转变过程。"},
  {"id":"an_dk_179","sentenceId":"s_dk_179","level":"sentence","content":"【吉兆】此辞意为拔除茅草而得吉祥，象征着忠诚于君主的心志能够带来好的结果。表明在为君主或上级服务时，保持正直和忠诚的态度，将会得到吉祥和好的回报。"},
  {"id":"an_dk_180","sentenceId":"s_dk_180","level":"sentence","content":"【群體與秩序】此句意指在大人（指德高望重或地位较高的人）的领导下，即使遇到不顺利的情况也能保持亨通，因为不会扰乱群体的秩序和稳定。这反映了在良好的领导和管理下，团队或社会能够维持和谐与秩序，避免混乱。"},
  {"id":"an_dk_181","sentenceId":"s_dk_181","level":"sentence","content":"【不利】此句意指处于不当的位置或环境，导致感到羞愧或不自在，暗示当前的处境并不利于个人的发展或表现。"},
  {"id":"an_dk_182","sentenceId":"s_dk_182","level":"sentence","content":"【吉】此辞表示虽然面临一定的命运或限制，但不会招致灾祸，能够按照自己的意志和目标前行。"},
  {"id":"an_dk_183","sentenceId":"s_dk_183","level":"sentence","content":"【吉兆】此句小象辞表示大人（指德高望重或地位显赫的人）得到吉祥的结果，是因为其所处的位置或所扮演的角色非常恰当，符合其身份和能力，因此能够获得好的结果。"},
  {"id":"an_dk_184","sentenceId":"s_dk_184","level":"sentence","content":"【否極泰來】这句话出自《易经》中的否卦。否卦象征闭塞、不顺利的状态，但物极必反，当闭塞达到极点时，就会向好的方向转变。\"否终则倾，何可长也\"的意思是，闭塞的状态到了尽头就会倾覆，不可能长久持续。这表达了事物发展到极端就会向相反方向转化的哲学思想。"},
  {"id":"an_dk_185","sentenceId":"s_dk_185","level":"sentence","content":"【同人卦】同人卦象征着团结和合作。卦辞“同人于野，亨。利涉大川，利君子贞。”意味着在广阔的天地中与人和谐相处，能够亨通顺利。有利于渡过大江大河，象征着克服重大困难。同时，对于君子而言，保持正直和坚定的品德是非常有利的。"},
  {"id":"an_dk_186","sentenceId":"s_dk_186","level":"sentence","content":"【同人卦】同人卦象征团结合作。柔爻（阴爻）处于适当的位置，与乾卦（阳刚）相应，表示和谐与合作。卦辞说“同人于野，亨”，意味着在广阔的天地中与人合作，可以亨通。又说“利涉大川”，表明在艰难险阻面前，通过合作可以顺利渡过。乾卦的刚健行动与离卦的文明光辉相结合，中正而相应，象征君子的行为。只有君子才能真正实现天下的志向，即通过正直和合作达到共同的目标。"},
  {"id":"an_dk_187","sentenceId":"s_dk_187","level":"sentence","content":"【象辭】此句出自《周易》同人卦的象辞。同人卦由下乾（天）上离（火）组成，象征天与火相依相融，如同人们团结一致。君子观此卦象，应当效法天与火的相融，以类聚群分的方式辨别事物，促进人际间的和谐与合作。"},
  {"id":"an_dk_188","sentenceId":"s_dk_188","level":"sentence","content":"【吉兆】初九爻辞表示在出门时与人相遇并结交，没有灾难。这象征着在开始阶段，与人合作或结交新朋友是顺利的，不会有不利的影响。"},
  {"id":"an_dk_189","sentenceId":"s_dk_189","level":"sentence","content":"【人际關系】六二爻辞“同人于宗，吝”意味着在与人交往时，过于局限于宗族或小圈子，这种狭隘的人际关系会导致遗憾和不利。爻辞提醒我们，应该扩大交往范围，与更多的人建立联系，而不是仅仅局限于自己的小圈子。"},
  {"id":"an_dk_190","sentenceId":"s_dk_190","level":"sentence","content":"【险阻】九三爻辞描述了一种处于险境的状态，意为在茂密的草木中埋伏着军队，登上高山观察，但长时间无法采取行动或振兴。这表明当前的形势非常艰难，需要谨慎行事，不可轻举妄动。"},
  {"id":"an_dk_191","sentenceId":"s_dk_191","level":"sentence","content":"【险中求安】九四爻辞描述了一种处于险境但最终能够化险为夷的情况。爻辞中的“乘其墉”意味着身处险境，如同站在城墙之上，面临着攻击或挑战；“弗克攻”则表示虽然面临攻击，但最终未能被攻破，保持了自身的安全；“吉”则表明最终的结果是吉祥的，意味着在险境中能够找到安全，化险为夷。这一爻辞提醒人们在面对困难和挑战时，要保持冷静和智慧，寻找转危为安的机会。"},
  {"id":"an_dk_192","sentenceId":"s_dk_192","level":"sentence","content":"【吉】九五爻辞描述了在与人合作的过程中，起初可能会遇到困难和挫折，甚至会感到悲伤和绝望，但最终会迎来成功和喜悦。这表明在面对挑战时，只要坚持努力，最终能够克服困难，实现目标。同时，“大师克相遇”意味着在关键时刻，能够得到贤明之人的帮助和支持，共同克服困难，达成共识。此爻辞预示着最终的结果是吉祥的。"},
  {"id":"an_dk_193","sentenceId":"s_dk_193","level":"sentence","content":"【同人卦】上九爻的爻辞表示在郊外与人相聚，没有悔恨。这表明在远离纷争和复杂人际关系的环境中，与人和谐相处，可以避免不必要的麻烦和冲突，保持内心的平和与宁静。"},
  {"id":"an_dk_194","sentenceId":"s_dk_194","level":"sentence","content":"【人际關系】此句意为出门与人交往，若能和睦相处，又有谁会责怪呢？表明在人际交往中，若能保持和谐友善的态度，通常能够避免不必要的矛盾和冲突。"},
  {"id":"an_dk_195","sentenceId":"s_dk_195","level":"sentence","content":"【人际關系】这句话出自《周易》同人卦，意为在宗族或团体内部寻求志同道合的人，但如果只局限于内部，不愿向外拓展，就会导致狭隘和吝啬的局面，不利于发展和进步。"},
  {"id":"an_dk_196","sentenceId":"s_dk_196","level":"sentence","content":"【隱忍待機】此辞意为在草莽中埋伏军队，是因为敌人强大，需要隐蔽力量，等待时机。三年不兴起，是因为需要保持稳定，不可轻举妄动，待时机成熟再行动。这反映了在面对强敌时，应采取隐忍的态度，积蓄力量，等待时机，不可急于求成。"},
  {"id":"an_dk_197","sentenceId":"s_dk_197","level":"sentence","content":"【困卦】此爻辞出自《周易》困卦的九四爻。爻辞的意思是，处于困境中的人，如果能够坚守正道，不被外界的诱惑所动摇，即使暂时处于不利的位置，也能够转危为安。\"乘其墉\"指的是处于高墙之上，比喻身处险境；\"义弗克也\"意味着坚守道义，不被困难所克服；\"其吉，则困而反则也\"表示在这种情况下，如果能够得到吉祥的结果，是因为在困境中能够回归正道。整体而言，爻辞强调了在逆境中保持正直和坚定的重要性。"},
  {"id":"an_dk_198","sentenceId":"s_dk_198","level":"sentence","content":"【人际關系】这段小象辞描述了在与人交往的过程中，应当首先保持中正和直率的态度。当遇到有影响力的人物时，言语之间可能会产生冲突或对抗。这提示我们在与他人，尤其是重要人物交往时，要保持真诚和正直，同时也要注意沟通的方式，避免不必要的矛盾。"},
  {"id":"an_dk_199","sentenceId":"s_dk_199","level":"sentence","content":"【未遂】此句意为与人同行至郊外，但志向尚未实现。表明行动虽已展开，目标却未达成，处于一种努力但未遂的状态。"},
  {"id":"an_dk_200","sentenceId":"s_dk_200","level":"sentence","content":"【吉兆】大有卦象征着丰收、富有和成功，\"元亨\"表示事物处于最亨通、最有利的状态，预示着大有可为，一切顺利。"},
  {"id":"an_dk_201","sentenceId":"s_dk_201","level":"sentence","content":"【大有卦】大有卦象征着大丰收、大富有。其卦象为离（火）上乾（天）下，表示光明与刚健并存。柔爻（六五）处于尊贵的位置，象征着谦逊而得高位，能够得到上下的响应和支持。其德性刚健而文明，顺应天道，适时而行，因此能够达到元始亨通的状态。"},
  {"id":"an_dk_202","sentenceId":"s_dk_202","level":"sentence","content":"【卦辭】这句话出自《周易》中的大有卦。大有卦的卦象是火在天上，象征着光明和盛大。君子应当效法这一卦象，抑制邪恶，弘扬善良，顺应天道，享受天命。这是对君子行为的一种指导和期望。"},
  {"id":"an_dk_203","sentenceId":"s_dk_203","level":"sentence","content":"【吉凶】初九爻辞表示在开始阶段，不要与人交恶，避免互相伤害，这样就不会有灾祸。如果处于艰难困苦之中，只要能够坚持下去，也不会有灾祸。这说明在困难时期，保持平和的心态，不与人争斗，是避免灾祸的关键。"},
  {"id":"an_dk_204","sentenceId":"s_dk_204","level":"sentence","content":"【人际關系】六二爻辞“同人于宗，吝”意味着在与人交往时，过于局限于宗族或小圈子，这种狭隘的人际关系会导致遗憾和不利。爻辞提醒我们，应该扩大交往范围，与更多的人建立联系，而不是仅仅局限于自己的小圈子。"},
  {"id":"an_dk_205","sentenceId":"s_dk_205","level":"sentence","content":"【官場/權力】九三爻辞描述的是一个高级官员（公）被天子（君主）赏识并赐予宴请，象征着得到上级的重用和认可。但同时也警告，如果是小人（品德不高的人）则不能胜任这样的职位，暗示了品德和能力对于担任高位的重要性。"},
  {"id":"an_dk_206","sentenceId":"s_dk_206","level":"sentence","content":"【吉凶悔吝】九四爻辞“匪其彭，无咎”意味着在这一爻的位置上，如果能够不自大、不膨胀，保持谦逊的态度，就不会有灾祸。这里的“匪其彭”指的是不要过分张扬或自满，而“无咎”则表示没有过失或灾难。这一爻强调了在高位时保持谦虚的重要性，避免因为骄傲自满而招致失败。"},
  {"id":"an_dk_207","sentenceId":"s_dk_207","level":"sentence","content":"【吉祥】六五爻辞表示以诚信相待，威信并重，最终能够获得吉祥的结果。此爻强调了诚信与威信在人际交往中的重要性，表明在处理事务时，既要保持诚信，也要树立威信，这样才能得到他人的信任与尊重，从而达到吉祥的境地。"},
  {"id":"an_dk_208","sentenceId":"s_dk_208","level":"sentence","content":"【天助人和】此爻辞表示处于最高位的上九，能够得到天的庇佑，意味着其行为符合天道，因此吉祥而无所不利。这不仅是对个人品德和行为的肯定，也预示着在未来的行动中将获得顺利和成功。在实际应用中，可以理解为当一个人的行为符合道德规范和社会期望时，将会得到广泛的支持和帮助。"},
  {"id":"an_dk_209","sentenceId":"s_dk_209","level":"sentence","content":"【吉兆】大有初九，表示事物开始时没有互相伤害，象征着良好的开端和和谐的局面，预示着未来的发展会顺利，不会有不利的冲突或损害。"},
  {"id":"an_dk_210","sentenceId":"s_dk_210","level":"sentence","content":"【吉兆】此辞意指用大车装载货物，能够承载重物且不会倾覆，象征着稳定和成功。在决策或行动中，能够承担重任，保持中正，不会失败，是一个吉祥的预兆。"},
  {"id":"an_dk_211","sentenceId":"s_dk_211","level":"sentence","content":"【政治】这句话出自《周易》中的象辞，意为在公共事务上，应当由天子（代表最高权力）来主持和享受，而小人如果掌权则会带来危害。这反映了古代社会对于权力分配和使用的一种理想状态，即权力应当集中在贤明的领导者手中，而非被品德低下的人所掌控。"},
  {"id":"an_dk_212","sentenceId":"s_dk_212","level":"sentence","content":"【無咎】此句意为，如果不是因为大的过失，就不会有灾祸；表明了在行为上要明辨是非，谨慎行事，避免大的错误，这样就能避免灾祸。"},
  {"id":"an_dk_213","sentenceId":"s_dk_213","level":"sentence","content":"【誠信與威嚴】此句小象辞表达了两个主要概念。一是“厥孚交如，信以发志也”，意味着通过诚信的交往，能够激发人们的志向和信任。二是“威如之吉，易而无备也”，表示威严带来的吉祥，是因为人们在威严面前容易放松警惕，从而达到无备的状态。整体上，这句话强调了诚信和威严在人际交往中的重要性。"},
  {"id":"an_dk_214","sentenceId":"s_dk_214","level":"sentence","content":"【吉祥】此句出自《易经》大有卦的爻辞，意为大有卦的上爻非常吉祥，是因为得到了天的保佑。这表示在顺天应人、正道直行的情况下，会得到上天的庇护和帮助，一切都会非常顺利。"},
  {"id":"an_dk_215","sentenceId":"s_dk_215","level":"sentence","content":"【謙卦】谦卦象征谦虚，卦辞“亨，君子有终”意味着谦虚能够带来亨通，君子如果能够保持谦虚的态度，最终会获得好的结果。"},
  {"id":"an_dk_216","sentenceId":"s_dk_216","level":"sentence","content":"【謙卦】谦卦象征谦虚，亨通。天道向下施济而光明，地道卑下而向上行。天道减少盈满而增益谦虚，地道改变盈满而流向谦虚，鬼神损害盈满而赐福谦虚，人道厌恶盈满而喜好谦虚。谦虚者虽尊贵却更加光明，虽卑微却不可逾越，这是君子的最终境界。"},
  {"id":"an_dk_217","sentenceId":"s_dk_217","level":"sentence","content":"【謙卦】此句出自《周易》谦卦的象辞，意为大地中包含着高山，象征着谦虚。君子应当效法这种谦虚的精神，减少自己的多余，增加他人的不足，公平地对待事物，使一切达到平衡和谐的状态。"},
  {"id":"an_dk_218","sentenceId":"s_dk_218","level":"sentence","content":"【謙卦】初六爻辞描述了一个谦虚的君子，他能够谨慎地处理大事，如渡过大河，最终会得到吉祥的结果。这表明在面对重大挑战时，保持谦逊和谨慎的态度是非常重要的。"},
  {"id":"an_dk_219","sentenceId":"s_dk_219","level":"sentence","content":"【謙遜】六二爻表示谦逊的美德得到了认可和响应，如同鸣响的谦德之声，坚守正道则吉祥。此爻强调了谦逊不仅是一种内在的美德，也是一种能够获得外界认同和响应的品质。在行为上保持谦逊，能够得到他人的支持与帮助，从而达到吉祥的结果。"},
  {"id":"an_dk_220","sentenceId":"s_dk_220","level":"sentence","content":"【勤奋謙遜】九三爻辞表示，一个人如果能够勤奋工作，同时保持谦逊的态度，那么作为君子，最终会获得吉祥的结果。这说明了在努力工作的同时，保持谦虚的态度是非常重要的，这样的人最终会得到好的回报。"},
  {"id":"an_dk_221","sentenceId":"s_dk_221","level":"sentence","content":"【吉兆】六四爻辞表示没有不利，应当广泛地施行谦逊。这表明在这一爻的位置上，保持谦逊的态度将会带来吉祥的结果。\"撝谦\"意味着广泛地、主动地表现出谦逊，不仅限于个人行为，还应当推广到更广泛的领域，如对待他人、处理事务等。这种态度能够获得他人的支持和帮助，从而达到成功。"},
  {"id":"an_dk_222","sentenceId":"s_dk_222","level":"sentence","content":"【戰爭與合作】此爻辞表明在六五的位置上，虽然自身并不富有，但能够与邻近的力量联合起来，共同对外进行侵伐，这样的行动将会无往不利。这反映了在资源有限的情况下，通过结盟和合作可以增强实力，达到共同的目标。"},
  {"id":"an_dk_223","sentenceId":"s_dk_223","level":"sentence","content":"【謙卦】上六爻辞表示在谦虚的德行中，通过表达谦逊的态度，可以有效地领导军队或进行征伐。这里的“鸣谦”意味着以谦逊的态度发声，得到他人的认同和支持。而“利用行师，征邑国”则表示在这种谦逊的态度下，进行军事行动或征伐地方，能够获得成功。整体而言，这一爻辞强调了谦逊在领导和行动中的重要性。"},
  {"id":"an_dk_224","sentenceId":"s_dk_224","level":"sentence","content":"【謙遜】这句话描述了一个谦虚谨慎、以谦卑的态度自我修养的人。\"谦谦君子\"指的是具有谦逊美德的君子，\"卑以自牧\"则表示他以谦卑的态度来约束和管理自己。"},
  {"id":"an_dk_225","sentenceId":"s_dk_225","level":"sentence","content":"【謙虛】这句话出自《周易》谦卦的爻辞，意为以谦虚的态度表达自己的意见，坚守正道则吉祥，因为这是内心真诚的体现。"},
  {"id":"an_dk_226","sentenceId":"s_dk_226","level":"sentence","content":"【品德】这句话出自《周易》谦卦的象辞，意思是说，勤劳而谦逊的君子，能够得到万民的敬服。这里强调的是君子的品德，特别是勤劳和谦逊，是获得他人尊重和信任的重要品质。"},
  {"id":"an_dk_227","sentenceId":"s_dk_227","level":"sentence","content":"【吉】此辞表示无论做什么事情都没有不利，通过发扬谦虚的美德，不会违背正确的原则和规则。说明在保持谦逊的态度下，行事将会顺利，符合正道。"},
  {"id":"an_dk_228","sentenceId":"s_dk_228","level":"sentence","content":"【戰爭】这句话的意思是通过军事行动来征服那些不顺从的势力或地区。这里的“利用侵伐”指的是采取侵略或讨伐的手段，“征不服”则是指征讨那些不愿意服从的势力。"},
  {"id":"an_dk_229","sentenceId":"s_dk_229","level":"sentence","content":"【謙卦】鸣谦，指的是谦虚的名声已经传播开来，但内心的目标尚未实现。在这种情况下，可以采取行动，如率领军队征伐城邑或国家，意味着在保持谦逊的同时，也可以积极进取，实现自己的目标。"},
  {"id":"an_dk_230","sentenceId":"s_dk_230","level":"sentence","content":"【吉】豫卦象征着愉悦和安乐，有利于建立诸侯，出兵征战。此卦提示在安定中要有所作为，积极进取，但也要注意不要过度放纵，保持警惕，以防乐极生悲。"},
  {"id":"an_dk_231","sentenceId":"s_dk_231","level":"sentence","content":"【卦辭】豫卦的彖辞阐述了豫卦的基本含义和作用。豫卦象征着愉悦、安乐。其结构为刚爻（阳爻）在下，柔爻（阴爻）在上，象征着刚强得到响应，志向得以实现，同时又顺应自然规律而行动，因此称为“豫”。豫卦强调顺应自然、顺应时势的重要性，认为天地万物都遵循这一原则运行，人类社会中的君主建立国家、统帅军队也应如此。天地因顺而动，所以日月运行不差，四季更替有序；圣人因顺而动，所以刑罚清明，人民信服。豫卦所体现的顺应时势的意义非常重大。"},
  {"id":"an_dk_232","sentenceId":"s_dk_232","level":"sentence","content":"【自然與人文】此句出自《周易》的豫卦，描述了雷从地中发出，象征着万物复苏、生机勃勃的景象，也象征着人们内心的愉悦和振奋。先王因此创作音乐来推崇美德，隆重地向上帝献祭，并与祖先相配享。这体现了古代先民对自然现象的敬畏和对人文精神的追求，以及通过音乐和祭祀活动来表达对天地、神明和祖先的敬仰之情。"},
  {"id":"an_dk_233","sentenceId":"s_dk_233","level":"sentence","content":"【凶险】初六爻辞“鸣豫，凶”意味着在享受安乐、满足的状态下发出声音，象征着过度的自满和自大，这种行为可能会招致凶险。在《周易》中，豫卦代表愉悦和安乐，但初六爻处于卦的最下方，根基不稳，如果在这种情况下过于放纵自己的情绪，可能会导致不利的后果。因此，此爻辞告诫人们在安乐之时要保持谦逊和谨慎，不可因一时的满足而忘乎所以。"},
  {"id":"an_dk_234","sentenceId":"s_dk_234","level":"sentence","content":"【堅守正道】六二爻辞中的“介于石，不终日，贞吉”意味着在困难或诱惑面前，能够像石头一样坚定，不为外界所动摇，保持内心的正直和纯洁。这种坚定和正直的态度不会持续太久，因为问题很快就会得到解决，最终会获得吉祥的结果。这里的“不终日”表示问题解决得非常迅速，不需要拖延太久。整体上，这一爻强调了在面对挑战时，保持坚定和正直的重要性。"},
  {"id":"an_dk_235","sentenceId":"s_dk_235","level":"sentence","content":"【警示】六三爻辞中的“盱豫，悔。迟有悔。”意味着在犹豫不决或拖延决策时会产生后悔。此爻告诫人们在面对决策时应果断行动，避免因过度犹豫而错失良机，导致后悔。"},
  {"id":"an_dk_236","sentenceId":"s_dk_236","level":"sentence","content":"【吉】九四爻辞表示，由于保持愉悦和谨慎的态度，将会获得大的收获。不要有任何怀疑，朋友们会聚集在一起，共同庆祝或合作。这是一条吉祥的爻辞，预示着在保持积极心态的同时，会有好的结果和收获。"},
  {"id":"an_dk_237","sentenceId":"s_dk_237","level":"sentence","content":"【健康與疾病】此爻辞表示在六五的位置上，虽然可能会遭遇疾病或不顺，但只要保持正直和坚定，就能够持续生存，不会因为困难而丧命。这暗示了在面对健康问题或逆境时，保持积极的心态和正确的态度是非常重要的。"},
  {"id":"an_dk_238","sentenceId":"s_dk_238","level":"sentence","content":"【警示】上六爻辞“冥豫，成有渝，无咎”意味着在极度安逸和满足的状态下，应当警惕可能出现的变故。虽然最终能够避免灾祸，但必须保持警觉，不可沉溺于当前的安逸之中，以免因疏忽而招致不测。此爻辞提醒人们在顺境中也要保持清醒的头脑，随时准备应对可能的变化。"},
  {"id":"an_dk_239","sentenceId":"s_dk_239","level":"sentence","content":"【凶险】初六爻的豫卦，象征着小象在初始阶段就表现出自满和安逸的态度，这种态度会导致志向和能力的枯竭，最终招致凶险。"},
  {"id":"an_dk_240","sentenceId":"s_dk_240","level":"sentence","content":"【吉兆】此辞意指在一天之内就能完成事情，且保持正直和中庸的态度，可以获得吉祥的结果。\"不终日\"表示事情进展迅速，\"贞吉\"意味着坚守正道则吉。\"以中正也\"强调了行为的中庸和正直是获得吉祥的关键。"},
  {"id":"an_dk_241","sentenceId":"s_dk_241","level":"sentence","content":"【不利】此句意指在不适当的位置上表现出犹豫和迟疑，可能会导致后悔。提示在做决策时，要审时度势，选择合适的时机和位置，避免因犹豫不决而造成不利后果。"},
  {"id":"an_dk_242","sentenceId":"s_dk_242","level":"sentence","content":"【吉兆】此辞表示事情进展顺利，会有大的收获；表明志向能够得到广泛的支持和实现。"},
  {"id":"an_dk_243","sentenceId":"s_dk_243","level":"sentence","content":"【健康與生存】此爻辞表示在六五的位置上，虽然处于不利的环境或面临疾病（贞疾），但因为位于刚爻之上（乘刚），象征着虽然遭遇困难但仍然坚强不屈。\"恒不死，中未亡也\"意味着尽管面临挑战，但生命力顽强，不会轻易消亡，中心位置的稳固性保证了其持续存在和发展的可能性。整体来看，这段爻辞强调了在逆境中保持坚韧和恒心的重要性。"},
  {"id":"an_dk_244","sentenceId":"s_dk_244","level":"sentence","content":"【警示】这句话出自《周易》中的豫卦。冥豫在上，意味着过度的安逸和享乐已经达到了顶点，这种情况不可能长久维持。它警示人们不要沉溺于安逸之中，应当居安思危，及时调整自己的状态，以免乐极生悲。"},
  {"id":"an_dk_245","sentenceId":"s_dk_245","level":"sentence","content":"【吉】随卦象征着顺从和随和，卦辞“元亨利贞，无咎”表示此卦大吉大利，亨通顺利，做事能够得到好的结果，且没有灾祸。在随卦的指引下，应当顺应时势，随和处事，坚守正道，这样就能获得吉祥。"},
  {"id":"an_dk_246","sentenceId":"s_dk_246","level":"sentence","content":"【隨卦】随卦的彖辞描述了刚强的阳爻来到下方，与柔顺的阴爻相配合，象征着行动与愉悦相结合，能够顺应时势。随卦强调了顺应自然规律和时势的重要性，认为在顺应时势的情况下，可以达到大亨通和正固的状态，没有灾咎。随卦的时义非常重大，意味着在适当的时机采取适当的行动，能够获得成功和吉祥。"},
  {"id":"an_dk_247","sentenceId":"s_dk_247","level":"sentence","content":"【自然與人文】此句出自《周易》的随卦象辞，描述了自然界中雷在泽中的景象，象征着事物的随和与顺应。对于君子而言，这句辞意味着在一天劳作之后，随着夜幕降临，应当适时休息，恢复精力，体现了顺应自然规律与生活节奏的智慧。"},
  {"id":"an_dk_248","sentenceId":"s_dk_248","level":"sentence","content":"【吉兆】此爻辞表示在初九的位置上，官府的政策或情况可能会有所改变，但只要坚守正道，就会吉祥。如果出门与人交往或办事，也会有所成就。这是一条预示着变化中蕴含着机遇的爻辞，提示人们在变化中要保持正直，积极应对，将会获得好的结果。"},
  {"id":"an_dk_249","sentenceId":"s_dk_249","level":"sentence","content":"【關系】此爻辞描述了一种人际关系的变化，六二爻处于下卦的中位，象征着柔顺与中正。爻辞中的“系小子，失丈夫”意味着与年轻或地位较低的人建立了紧密的关系，而与年长或地位较高的人产生了疏远。这可能暗示在处理人际关系时，需要谨慎选择交往的对象，避免因过于亲近不当之人而失去更有价值的联系。"},
  {"id":"an_dk_250","sentenceId":"s_dk_250","level":"sentence","content":"【人际關系】六三爻辞描述了一种在人际关系中的选择与取舍。\"系丈夫，失小子\"意味着在某些情况下，为了维护与重要人物（如丈夫）的关系，可能会失去一些次要的人或事物（如小子）。\"随有求得\"表示在这种选择之后，随着事情的发展，最终会有所收获。\"利居贞\"则建议在这种情况下，保持坚定和稳定的态度是有利的。整体而言，爻辞强调了在人际关系中做出明智选择的重要性，以及在变化中保持内心坚定的价值。"},
  {"id":"an_dk_251","sentenceId":"s_dk_251","level":"sentence","content":"【凶险與誠信】九四爻辞表示，在随从或追随的过程中可能会有所收获，但若固守不变则会有凶险。若能保持诚信，遵循正道，并且保持明智，那么就不会有灾祸。这说明在变化中要保持内心的正直和明智，才能避免凶险。"},
  {"id":"an_dk_252","sentenceId":"s_dk_252","level":"sentence","content":"【吉祥】九五爻辞表示诚信于美好的事物，将会带来吉祥的结果。此爻象征着处于尊贵位置的人，以诚信和正直的态度对待周围的人和事，能够获得好的结果和赞誉。"},
  {"id":"an_dk_253","sentenceId":"s_dk_253","level":"sentence","content":"【困卦】上六爻辞描述的是在困厄的环境中，被束缚和限制，但最终能够得到解脱和维系。君王在西山举行祭祀，象征着通过虔诚的祈祷和祭祀，可以得到神灵的保佑，从而摆脱困境。这里的“拘系之，乃从维之”意味着在困境中，虽然受到束缚，但通过顺应和调整，最终能够得到维系和解脱。而“王用亨于西山”则表达了通过祭祀和祈祷，可以得到神灵的帮助，从而摆脱困境。"},
  {"id":"an_dk_254","sentenceId":"s_dk_254","level":"sentence","content":"【官運】此辞意指官员可能会有变动，但只要遵循正道行事，结果就会吉祥。出门交往也会有所成就，不会有所损失。这表明在官场中保持正直和积极的人际交往是非常重要的。"},
  {"id":"an_dk_255","sentenceId":"s_dk_255","level":"sentence","content":"【人际關系】这句话出自《易经》中的小象辞，意思是小人物或地位低下的人，不能同时得到多方面的支持或帮助。在人际关系中，这提示我们不要期望在所有方面都能得到他人的支持，有时候需要有所取舍，专注于最重要的关系或目标。"},
  {"id":"an_dk_256","sentenceId":"s_dk_256","level":"sentence","content":"【家庭與婚姻】此句小象辞表达了丈夫的志向在于舍弃家庭的安逸，追求更高远的目标。这反映了在家庭与个人理想之间的抉择与权衡。"},
  {"id":"an_dk_257","sentenceId":"s_dk_257","level":"sentence","content":"【凶险與正道】此辞意为，在随从或追随的过程中虽然有所收获，但其背后隐藏着凶险。若能坚守诚信，遵循正道而行，则能彰显出光明的功绩。这表明在追求目标时，不仅要关注成果，更要注重过程中的道德与原则，才能真正实现价值。"},
  {"id":"an_dk_258","sentenceId":"s_dk_258","level":"sentence","content":"【吉祥】此句出自《易经》中的小象辞，意为信任和依赖美好的事物，将会带来吉祥的结果。其中“位正中也”表示处于正确的位置和状态，象征着行为和决策的正当性和适宜性。"},
  {"id":"an_dk_259","sentenceId":"s_dk_259","level":"sentence","content":"【困頓】此句小象辞意为被拘束限制，已经达到了极限，无法再进一步，处于极度困顿的状态。"},
  {"id":"an_dk_260","sentenceId":"s_dk_260","level":"sentence","content":"【亨通】蛊卦象征着事物的更新与变革，具有大亨通的意象，利于进行大的行动或决策，如渡过大河。卦辞中的“先甲三日，后甲三日”意味着在行动之前需要有充分的准备，在行动之后需要有适当的总结和调整，这样才能更好地把握时机，实现亨通。同时，这也暗示了在变革的过程中，需要有始有终，持续不断地努力。"},
  {"id":"an_dk_261","sentenceId":"s_dk_261","level":"sentence","content":"【卦象與卦辭】这段彖辞描述了蛊卦的卦象和卦辞。蛊卦的卦象是刚爻在上，柔爻在下，象征着巽（风）在上，艮（山）在下，风止于山，象征着事物的停滞和变革。卦辞“蛊，元亨，而天下治也”表示蛊卦象征着大亨通，天下因此而得到治理。接着，“利涉大川，往有事也”意味着在变革的过程中，虽然会遇到困难，但最终能够克服，前往有事之地。最后，“先甲三日，后甲三日，终则有始，天行也”表示在变革的过程中，要遵循天道，终而复始，不断循环。"},
  {"id":"an_dk_262","sentenceId":"s_dk_262","level":"sentence","content":"【自然與人文】此句出自《周易》的象辞，描述了山下有风的自然景象，象征着蛊卦。蛊卦代表了事物的腐败与变革，需要进行整治与更新。君子观此象，应当振作民众，培养德行，以推动社会的正向变革与发展。"},
  {"id":"an_dk_263","sentenceId":"s_dk_263","level":"sentence","content":"【家庭责任】初六爻辞描述了儿子继承并解决父亲留下的问题（蛊）的情景。有儿子能够承担起这个责任，父亲就不会有过失。虽然过程中可能会遇到危险和困难，但最终会得到好的结果。这表明在家庭中，后代有责任解决前人留下的问题，通过努力可以化险为夷，达成和谐。"},
  {"id":"an_dk_264","sentenceId":"s_dk_264","level":"sentence","content":"【家庭與责任】九二爻辞中的“干母之蛊，不可贞”意味着在处理家庭内部的问题时，尤其是涉及到母亲的事务，应当谨慎行事，不宜过于固执己见。这里的“干”有干预、参与之意，“蛊”则指代混乱或需要治理的状态。爻辞告诫人们在面对家庭内部的复杂情况时，应当灵活应对，避免因坚持己见而加剧矛盾。"},
  {"id":"an_dk_265","sentenceId":"s_dk_265","level":"sentence","content":"【家庭责任】九三爻辞表示承担父亲留下的责任或问题，虽然可能会遇到一些小的困难或后悔，但不会有大的过失。这说明在面对家庭责任时，即使有挑战，只要尽力而为，就能避免严重的后果。"},
  {"id":"an_dk_266","sentenceId":"s_dk_266","level":"sentence","content":"【家庭與责任】六四爻辞中的“裕父之蛊”意味着在处理父亲留下的问题或责任时，采取了过于宽松或放任的态度。这种态度可能导致问题无法得到妥善解决，甚至可能使情况变得更糟。“往见吝”则表示如果继续这样下去，将会遇到困难或不顺利的情况。这提示我们在面对家庭中的责任和问题时，应当谨慎行事，不可过于放任。"},
  {"id":"an_dk_267","sentenceId":"s_dk_267","level":"sentence","content":"【家庭與责任】六五爻辞中的“干父之蛊，用誉”意味着在处理家庭内部的问题或承担父亲留下的责任时，通过自己的努力和智慧，不仅能够解决问题，还能获得他人的赞誉和认可。这表明在面对家庭责任时，积极主动的态度和有效的行动能够带来正面的结果。"},
  {"id":"an_dk_268","sentenceId":"s_dk_268","level":"sentence","content":"【隱逸】此爻辞表达了上九爻的爻主不追求世俗的权力和地位，选择远离尘嚣，保持自身的高洁和独立。这种行为体现了隐逸的思想，即不与世俗同流合污，追求精神上的自由和高尚。"},
  {"id":"an_dk_269","sentenceId":"s_dk_269","level":"sentence","content":"【家庭责任】这句话出自《周易》的蛊卦，意指承担起父亲未完成的责任或改正父亲的过失，表达了对先辈的尊重和继承其遗志的决心。"},
  {"id":"an_dk_270","sentenceId":"s_dk_270","level":"sentence","content":"【家庭與倫理】这句话出自《周易》的卦辞，意为在处理母亲的家事（蛊）时，能够采取中庸之道，既不过分也不不足，体现了在家庭关系中保持平衡和和谐的重要性。"},
  {"id":"an_dk_271","sentenceId":"s_dk_271","level":"sentence","content":"【家庭责任】这句话出自《周易》中的蛊卦，意指承担起父亲的责任，即使在处理家庭事务中遇到困难，最终也不会有灾祸。这表明在家庭中履行应尽的职责，即使过程艰难，最终也会得到好的结果。"},
  {"id":"an_dk_272","sentenceId":"s_dk_272","level":"sentence","content":"【家庭與责任】这句话出自《易经》的卦辞，意指在处理父亲留下的问题或责任时，如果采取行动却未能成功，说明时机或方法可能不适宜。这反映了在家庭中承担和解决问题时，需要谨慎行事，考虑周全。"},
  {"id":"an_dk_273","sentenceId":"s_dk_273","level":"sentence","content":"【家庭责任】这句话出自《周易》的蛊卦，意为儿子应当承担起父亲留下的责任和使命，通过德行来继承和发扬。这里的“干父之蛊”指的是儿子要承担起父亲未完成的事业或责任，而“承以德也”则强调了在承担这些责任时，应当以德行作为基础和指导。"},
  {"id":"an_dk_274","sentenceId":"s_dk_274","level":"sentence","content":"【隱逸】这句话表达了不追求功名利禄，不侍奉王侯，而是选择保持自己的志向和原则，这种态度和行为可以作为他人的榜样。这通常与隐逸文化相关，即远离世俗纷扰，追求内心的平静和自由。"},
  {"id":"an_dk_275","sentenceId":"s_dk_275","level":"sentence","content":"【吉凶併存】临卦象征着面对、接近，卦辞中的“元，亨，利，贞”表示事物处于初始阶段，亨通有利，应当坚守正道。然而，“至于八月有凶”则预示着随着时间的推移，到了八月（即阴历的八月，代表秋季，万物开始凋零），可能会出现凶险的情况。整体来看，临卦既包含了积极向上的因素，也隐含了潜在的风险，提醒人们在顺境中要保持警惕，不可掉以轻心。"},
  {"id":"an_dk_276","sentenceId":"s_dk_276","level":"sentence","content":"【卦象與卦辭】临卦的彖辞描述了卦象的性质和变化趋势。临卦下坤上兑，兑为泽，坤为地，泽在地上，象征着水的滋润和大地的承载，故有“说而顺”之象。临卦的九二爻为阳爻，位于下卦之中，象征着阳刚之气正在逐渐增长，故有“刚浸而长”之象。同时，九二爻与六五爻相应，象征着刚中而应，即刚健中正而能应变，因此能够达到大亨通的状态，这是符合天道的。然而，彖辞中提到“至于八月有凶，消不久也”，意味着这种亨通的状态不会长久，到了八月（阴历的八月，即秋季），阳气将逐渐衰退，阴气开始增长，临卦的亨通局面将逐渐消失，预示着潜在的凶险。"},
  {"id":"an_dk_277","sentenceId":"s_dk_277","level":"sentence","content":"【上坤下兑】此句出自《周易》的临卦。临卦的卦象是泽上有地，上卦为坤（地），下卦为兑（泽）。君子观此卦象，应当效法大地的包容与泽润万物之德，思考如何无尽地教导和引导民众，使他们得到保护和安宁，这种德行和责任是没有边际的。"},
  {"id":"an_dk_278","sentenceId":"s_dk_278","level":"sentence","content":"【吉兆】初九爻辞“咸临，贞吉”意味着以真诚和感应的态度面对当前的情境，坚守正道，将会获得吉祥的结果。这里的“咸”有感应、真诚之意，“临”则表示面对或接近，整体表达了一种积极向善的态度。"},
  {"id":"an_dk_279","sentenceId":"s_dk_279","level":"sentence","content":"【吉兆】九二爻辞表示以感通的态度去面对和处理事情，将会得到吉祥的结果，没有任何不利的因素。这说明在当前的情境下，采取顺应自然、与人和谐相处的方式，能够获得好的结果。"},
  {"id":"an_dk_280","sentenceId":"s_dk_280","level":"sentence","content":"【忧患】六三爻辞表示处于甘美的环境中，但这种环境并不利于自身的发展。如果能够对这种不利的情况产生忧患意识，并采取相应的措施，就可以避免灾祸。这说明在顺境中也要保持警惕，不可掉以轻心。"},
  {"id":"an_dk_281","sentenceId":"s_dk_281","level":"sentence","content":"【吉凶判斷】六四爻辞“至临，无咎”意味着在这一爻的位置上，能够达到临卦所象征的亲临、莅临的状态，即能够积极主动地面对和处理问题，因此不会有过失或咎责。这表明在当前的情境下，采取积极主动的态度和行动是正确的选择，能够避免不利的情况发生。"},
  {"id":"an_dk_282","sentenceId":"s_dk_282","level":"sentence","content":"【智慧領导】此爻辞表示以智慧和明智的态度来领导，符合伟大君主的行为准则，能够带来吉祥的结果。表明领导者应当具备洞察力和智慧，以恰当的方式处理事务，这样才能获得好的结果。"},
  {"id":"an_dk_283","sentenceId":"s_dk_283","level":"sentence","content":"【上吉】上六爻辞“敦临，吉无咎”意味着在最高位时，能够保持谦逊和敦厚的态度，以真诚和宽广的胸怀对待他人，这样不仅能够获得吉祥，而且不会招致任何灾祸。这体现了在高位时仍需保持谦逊和真诚的重要性。"},
  {"id":"an_dk_284","sentenceId":"s_dk_284","level":"sentence","content":"【正直】此句小象辞“咸临贞吉，志行正也”意指在感应和来临之时，保持正直的品行和坚定的意志，能够获得吉祥的结果。这表明了在面对各种情况时，坚持正道、秉持正直之心的重要性。"},
  {"id":"an_dk_285","sentenceId":"s_dk_285","level":"sentence","content":"【吉祥】咸临表示感应和来临，意味着事物的感应和相互作用，吉无不利说明此时处于一个非常吉祥的状态，无论做什么事情都会顺利。未顺命也，表示虽然目前的状态很好，但还没有完全顺应天命，需要继续努力和调整，以达到更高的境界。"},
  {"id":"an_dk_286","sentenceId":"s_dk_286","level":"sentence","content":"【困境與轉变】此句出自《周易》中的小象辞，描述了一个处于不利位置的情境（位不当也），但通过积极应对和忧虑（既忧之），最终能够摆脱困境，避免长期的灾难或错误（咎不长也）。这表明在面对困难时，及时的警觉和行动可以带来积极的转变。"},
  {"id":"an_dk_287","sentenceId":"s_dk_287","level":"sentence","content":"【吉】此句出自《周易》临卦的爻辞，意为到达而没有灾难，是因为所处的位置恰当。说明在当前的情境下，行为得当，能够顺利达成目标，不会有不利的影响。"},
  {"id":"an_dk_288","sentenceId":"s_dk_288","level":"sentence","content":"【君道】此句意指君主应当遵循适宜之道，其行为应当符合中庸之理。君道即君主治国理政应遵循的原则和方法，强调君主的行为应当恰到好处，不偏不倚，以达到治国安邦的目的。"},
  {"id":"an_dk_289","sentenceId":"s_dk_289","level":"sentence","content":"【吉兆】此句出自《易经》中的临卦，意为以敦厚的态度面对临卦的情境是吉祥的，表明内心怀有真诚和善意，能够获得好的结果。\"志在内\"强调了内心的真诚和坚定的意志是关键。"},
  {"id":"an_dk_290","sentenceId":"s_dk_290","level":"sentence","content":"【觀卦】观卦的卦辞“盥而不荐，有孚顒若”意味着在进行祭祀或重要仪式时，虽然进行了初步的准备和清洁（盥），但还没有进行正式的献祭（不荐）。这表明了一种庄重、虔诚的态度，以及对仪式的尊重和期待。同时，“有孚顒若”表示内心充满诚信和敬仰，表现出一种真诚和敬畏的心态。整体而言，卦辞强调了在行动之前应保持内心的纯净和虔诚，以及对未来的期待和信心。"},
  {"id":"an_dk_291","sentenceId":"s_dk_291","level":"sentence","content":"【觀卦】观卦象征着观察和审视。卦象显示，上卦为巽（风），下卦为坤（地），风行于地上，象征着广泛地观察。卦辞中提到“大观在上，顺而巽，中正以观天下”，意味着以宽广的视野和谦逊的态度，公正地观察天下。接着，“观，盥而不荐，有孚顒若，下观而化也”，表示在观察时，要保持内心的纯净和真诚，通过观察来感化和教化民众。最后，“观天之神道，而四时不忒，圣人以神道设教，而天下服矣”，说明通过观察自然界的规律，圣人能够制定出符合天道的教化，使天下人信服。"},
  {"id":"an_dk_292","sentenceId":"s_dk_292","level":"sentence","content":"【觀象】此句出自《周易》的观卦，描述了风在地面上吹拂的情景，象征着观察和了解。古代的君王通过巡视各地，观察民情，从而设立合适的教化政策。这里的“观”不仅指观察自然现象，也指了解社会民情，以便更好地治理国家。"},
  {"id":"an_dk_293","sentenceId":"s_dk_293","level":"sentence","content":"【初爻】初六爻辞中的“童观”意味着以孩童般纯真的视角观察事物，这种态度对于普通人（小人）来说是无咎的，即不会带来灾祸；但对于有德行、有智慧的人（君子）来说，则显得不够成熟，可能会导致遗憾（吝）。这反映了在不同的社会角色和道德层次上，对于同一行为或态度的评价标准是不同的。"},
  {"id":"an_dk_294","sentenceId":"s_dk_294","level":"sentence","content":"【柔順】六二爻处于下卦之中，象征着柔顺和内观。爻辞中的“窥观”意味着从内部观察外部，或者说是通过细微的观察来了解事物的本质。对于女性而言，这种内观和柔顺的品质是有利的，因此爻辞说“利女贞”，即在这种情况下，女性保持贞洁和柔顺是有利的。整体而言，此爻强调了在特定情境下，保持谦逊、内省和柔顺的态度是明智的选择。"},
  {"id":"an_dk_295","sentenceId":"s_dk_295","level":"sentence","content":"【决策與行動】此爻辞意在提醒人们在观察自身情况时，要根据内外环境的变化，审时度势，决定是前进还是后退。在行动之前，需要深思熟虑，不可贸然行事。这表明在面对选择时，应当保持灵活的态度，根据实际情况做出最合适的决策。"},
  {"id":"an_dk_296","sentenceId":"s_dk_296","level":"sentence","content":"【觀卦】六四爻辞的意思是，观察国家的光辉，适宜作为王的宾客。这表示在这一爻的位置上，应该以谦逊的态度观察国家的状况，了解其文化和政治的光辉，从而获得智慧和启示。同时，这一爻也暗示了适宜担任辅佐君王的角色，为国家的发展做出贡献。"},
  {"id":"an_dk_297","sentenceId":"s_dk_297","level":"sentence","content":"【吉】九五爻辞表示观察自己的行为和德行，作为君子没有过失。此爻象征着处于尊位的人应当自我反省，保持正直和谨慎，这样就不会有灾祸。"},
  {"id":"an_dk_298","sentenceId":"s_dk_298","level":"sentence","content":"【上九】观察其行为，君子没有过失。此爻辞意在强调君子应当通过观察他人的行为来反思自身，以避免犯错。同时，也表达了君子的行为应当经得起他人的观察和评价，做到无愧于心。"},
  {"id":"an_dk_299","sentenceId":"s_dk_299","level":"sentence","content":"【初學者的视角】初六童观，小人道也，意味着从一个初学者或无知者的角度来看待事物，这种视角往往简单、直接，但可能缺乏深度和全面性。这提示我们在面对问题时，需要超越初学者的视角，寻求更深入的理解和更全面的视角。"},
  {"id":"an_dk_300","sentenceId":"s_dk_300","level":"sentence","content":"【婚姻】此句小象辞意为观察女子的贞洁，也可能发现其丑陋之处。在古代，这句话常用于占卜婚姻，暗示在婚姻中要谨慎，不要只看表面，要深入了解对方的品行。"},
  {"id":"an_dk_301","sentenceId":"s_dk_301","level":"sentence","content":"【决策與行動】此句出自《易经》观卦的爻辞，意为观察自己的行为，考虑是否应该前进或后退，但无论如何，都没有偏离正道。这表明在做决策时，要审时度势，根据实际情况灵活调整行动，但始终保持正确的方向和原则。"},
  {"id":"an_dk_302","sentenceId":"s_dk_302","level":"sentence","content":"【國家治理】这句话出自《周易·观卦》。\"观国之光\"指的是观察国家的光辉，即了解国家的治理状况和文化风貌；\"尚宾也\"则表示重视宾客，这里可以理解为国家治理中重视人才和外交。整体而言，这句话强调了国家治理中重视文化和人才的重要性。"},
  {"id":"an_dk_303","sentenceId":"s_dk_303","level":"sentence","content":"【觀察】此句出自《周易》观卦的爻辞，意为通过观察自己的行为和内心，来了解和指导民众的行为。这里强调了领导者应当以身作则，通过自身的言行来影响和引导民众。"},
  {"id":"an_dk_304","sentenceId":"s_dk_304","level":"sentence","content":"【人生哲理】这句话意味着观察一个人的生活状态，可以看出他的志向是否已经实现。如果一个人的生活状态显示出他仍然在努力奋斗，那么说明他的志向还未达成，内心仍存有不平之气。这里的“生”指的是生活状态，“志未平”则表示志向未达成，心中仍有追求。"},
  {"id":"an_dk_305","sentenceId":"s_dk_305","level":"sentence","content":"【决策與行動】噬嗑卦象征着通过坚定的决策和必要的行动来解决问题和障碍，从而达到亨通。利用狱意味着在处理问题时，需要采取严格的措施，甚至包括法律手段，以确保问题得到彻底解决。这卦提示我们在面对困难和挑战时，要果断行动，勇于承担责任，以实现目标。"},
  {"id":"an_dk_306","sentenceId":"s_dk_306","level":"sentence","content":"【噬嗑卦】此卦名为噬嗑，象征着解决纷争或障碍。卦象中，颐中有物，意味着口中含物，需要咬断或解决。噬嗑而亨，表示通过解决障碍可以达到亨通。刚柔分，动而明，雷电合而章，说明此卦中刚柔并济，动静结合，如同雷电相合，光明正大。柔得中而上行，虽不当位，利用狱也，意味着柔顺的力量处于中位并向上发展，虽然位置不正，但适宜处理诉讼或纷争。整体而言，此卦强调通过合理的方法解决矛盾，达到和谐与亨通。"},
  {"id":"an_dk_307","sentenceId":"s_dk_307","level":"sentence","content":"【法律與秩序】此大象辞“雷电噬嗑；先王以明罚敕法”出自《周易》噬嗑卦。噬嗑卦象征着咬合、刑罚和解决纷争。雷电象征着天威和迅速的行动，先王以雷电之威明示刑罚，整饬法律，以维护社会秩序和正义。这一卦象强调了法律的权威性和执行的必要性，以及领导者在制定和执行法律时应当具备的果断和公正。"},
  {"id":"an_dk_308","sentenceId":"s_dk_308","level":"sentence","content":"【初爻】初九爻辞中的“屦校灭趾，无咎”意味着在开始时，即使受到轻微的约束或限制（如鞋子束缚了脚趾），但只要能够谨慎行事，不急于求成，就不会有大的过失或灾难。这表明在事情的初始阶段，应当注意细节，避免轻率行动，以防止小问题演变成大问题。"},
  {"id":"an_dk_309","sentenceId":"s_dk_309","level":"sentence","content":"【凶险與警示】六二爻辞中的“噬肤灭鼻”形象地描述了一种危险的情境，意味着在处理问题时可能会遭受损失或伤害，但最终“无咎”，即如果能够谨慎行事，避免鲁莽，那么就不会有大的过失或灾难。此爻提示在面对困难和挑战时，需要保持警惕，谨慎应对，以避免不必要的损失。"},
  {"id":"an_dk_310","sentenceId":"s_dk_310","level":"sentence","content":"【困難與挑戰】六三爻辞描述了在处理问题时遇到了困难和挑战，如同咀嚼腊肉时意外中毒，虽然情况不理想，但只要谨慎应对，最终不会有大的过失。这提示我们在面对困境时，要保持冷静，妥善处理，避免因小失大。"},
  {"id":"an_dk_311","sentenceId":"s_dk_311","level":"sentence","content":"【吉凶】九四爻辞描述了在艰难的情况下，通过坚定的意志和正确的行动，最终能够获得吉祥的结果。\"噬乾胏，得金矢\"比喻在处理困难问题时，能够得到有力的支持或工具；\"利艰贞，吉\"则强调在面对艰难险阻时，保持坚定的信念和正确的态度，最终会迎来好的结果。整体上，这一爻辞传达了在逆境中坚持正道、积极应对的态度，预示着吉祥。"},
  {"id":"an_dk_312","sentenceId":"s_dk_312","level":"sentence","content":"【吉凶未定】六五爻辞描述了在处理困难或问题时（噬乾肉），虽然遇到了一些阻碍，但最终能够获得宝贵的成果（得黄金）。然而，这并不意味着可以掉以轻心，仍需保持谨慎的态度（贞厉），以避免可能出现的危险。只要能够坚持正道，最终将不会有过失（无咎）。此爻辞暗示在面对挑战时，虽然过程艰难，但只要坚持正确的方法，最终能够克服困难并取得成功。"},
  {"id":"an_dk_313","sentenceId":"s_dk_313","level":"sentence","content":"【凶险】上九爻辞描述了一种极其不利的情况，爻辞中的“何校灭耳”意味着重负压在耳朵上，几乎使人无法承受，象征着严重的灾祸或困境。这里的“凶”表示结果非常不吉利，预示着可能会遭遇重大的损失或灾难。"},
  {"id":"an_dk_314","sentenceId":"s_dk_314","level":"sentence","content":"【困頓】此句出自《周易》履卦的初九爻辞，意为脚上戴着刑具，连脚趾都被遮盖，象征着行动受到严重限制，无法正常行走。这表示在当前的处境中，行动受到了阻碍，应当谨慎行事，避免轻举妄动。"},
  {"id":"an_dk_315","sentenceId":"s_dk_315","level":"sentence","content":"【象辭】此句为《周易》中的一条象辞，意为以强硬的方式对待他人，甚至达到伤害他人的地步，是因为处于强硬的位置或环境之中。其中，“噬肤灭鼻”形象地描述了这种过度强硬的行为，而“乘刚也”则说明了这种行为的原因。"},
  {"id":"an_dk_316","sentenceId":"s_dk_316","level":"sentence","content":"【凶险】此句小象辞表示遇到了毒害，所处的位置不恰当，暗示当前的环境或情况对自身不利，可能面临危险或伤害。"},
  {"id":"an_dk_317","sentenceId":"s_dk_317","level":"sentence","content":"【艱難中守正則吉】在艰难困苦中坚持正道则吉祥，但目前形势尚未完全明朗或成功尚未完全展现。"},
  {"id":"an_dk_318","sentenceId":"s_dk_318","level":"sentence","content":"【吉凶】此辞意为在占卜中得到的征兆虽然有危险，但最终不会有灾难，是因为行为得当。说明在面对困难或危险时，只要处理得当，就能避免灾祸，转危为安。"},
  {"id":"an_dk_319","sentenceId":"s_dk_319","level":"sentence","content":"【智慧】这句话的意思是说，如果一个人被过多的外界事物所干扰，就像耳朵被东西遮盖住一样，就无法听清楚、理解清楚，也就无法真正地聪明和明智。这里的“何校灭耳”比喻被外界事物所干扰，而“聪不明也”则表示因此而无法真正地聪明和明智。这则小象辞提醒人们要保持内心的宁静，不要被外界的纷扰所迷惑，才能保持清晰的判断力和智慧。"},
  {"id":"an_dk_320","sentenceId":"s_dk_320","level":"sentence","content":"【吉祥】贲卦象征着文饰、美化。卦辞“亨。小利有攸往”意味着事情进展顺利，但只在小事上有所利，适合进行一些小规模的行动或决策。整体上是一个较为吉祥的卦象，但需注意不要过于追求表面的华丽，而忽视了实质内容。"},
  {"id":"an_dk_321","sentenceId":"s_dk_321","level":"sentence","content":"【卦辭】贲卦象征着装饰和文采，亨通。这是因为柔爻（阴爻）来到刚爻（阳爻）之上，以文饰刚，所以亨通。刚爻被分到上位，以文饰柔，所以小的行动有利。这是天的文采；文明而有所节制，这是人的文采。观察天的文采，可以了解时序的变化；观察人的文采，可以教化天下，使之形成良好的社会风气。"},
  {"id":"an_dk_322","sentenceId":"s_dk_322","level":"sentence","content":"【象辭】此句出自《周易》贲卦的象辞。贲卦的下卦为离，代表火；上卦为艮，代表山。因此，象辞描述为“山下有火，贲”。火在山下燃烧，象征着文饰、文明的兴起。君子观此象，应当明白治理政事应当光明正大，不可草率处理诉讼案件，应当谨慎、公正。"},
  {"id":"an_dk_323","sentenceId":"s_dk_323","level":"sentence","content":"【出行】初九爻辞描述了一个人装饰了他的脚，放弃了乘坐车辆而选择步行。这象征着在行动或出行时，选择了一种更为简朴和直接的方式，可能意味着回归本真，或是放弃一些外在的便利和舒适，以更加脚踏实地的态度面对事情。"},
  {"id":"an_dk_324","sentenceId":"s_dk_324","level":"sentence","content":"【外觀】六二爻辞“贲其须”意味着在修饰或装饰方面，注重外表的细节，如胡须的修饰。这象征着在个人形象或事物的外观上花费心思，追求完美和精致。同时，也暗示了在处理事情时，可能需要关注细节，以提升整体的品质和形象。"},
  {"id":"an_dk_325","sentenceId":"s_dk_325","level":"sentence","content":"【吉祥】九三爻的爻辞“贲如濡如，永贞吉”意味着事物的装饰或文饰达到了恰到好处的状态，如同被水润泽一般自然和谐。在这种状态下，保持长久的正直和坚定将会带来吉祥的结果。这提示我们在追求外在美化的同时，更应注重内在品质的提升，以达到内外兼修的境界。"},
  {"id":"an_dk_326","sentenceId":"s_dk_326","level":"sentence","content":"【婚姻】六四爻辞描述了一种婚姻的情景，其中“贲如皤如”表示婚礼的盛大和庄重，“白马翰如”象征着纯洁和高贵，而“匪寇婚媾”则强调了这场婚姻是出于双方的自愿，而非强迫。整体上，爻辞传达了对美好婚姻的祝福和期望。"},
  {"id":"an_dk_327","sentenceId":"s_dk_327","level":"sentence","content":"【吉凶併存】此爻辞描述了一种在丘园中进行装饰或祭祀的情景，所用的礼物（束帛）虽然微薄，但最终能够获得吉祥的结果。然而，在过程中可能会遇到一些困难或不顺（吝），这表明在追求目标的过程中需要谨慎行事，保持谦逊和节俭的态度，最终能够克服困难，达到吉祥的结局。"},
  {"id":"an_dk_328","sentenceId":"s_dk_328","level":"sentence","content":"【上九】上九爻的爻辞为“白贲，无咎”。白贲，指自然朴素之美，不加修饰的美。无咎，表示没有灾难，没有过失。整体含义为，保持自然本色，不刻意追求外在的装饰，这样就不会有过失或灾难。这在一定程度上强调了返璞归真、保持本真的重要性。"},
  {"id":"an_dk_329","sentenceId":"s_dk_329","level":"sentence","content":"【行為准則】这句话出自《易经》中的象辞，意思是放弃使用车辆而选择步行，表明在某些情况下，为了坚持道义或原则，宁愿选择更为艰难的方式，也不违背自己的信念。这里强调的是在面对选择时，应以道德和正义为先，即使这意味着要承受更多的辛苦。"},
  {"id":"an_dk_330","sentenceId":"s_dk_330","level":"sentence","content":"【外觀】贲其须，与上兴也。这句话出自《周易》贲卦的爻辞，贲卦象征着文饰、装饰。这里的“贲其须”指的是修饰胡须，象征着对外在形象的修饰和注重。而“与上兴也”则表示这种修饰是为了与上层社会的人交往，提升自己的社会地位和形象。整体而言，这句话强调了在社会交往中，通过修饰外在形象来提升自身的重要性。"},
  {"id":"an_dk_331","sentenceId":"s_dk_331","level":"sentence","content":"【吉祥】此辞意为永远保持正直和吉祥，最终不会被任何邪恶或不利之事所侵犯或超越。表明了一种持久的吉祥状态和坚定的正直品质。"},
  {"id":"an_dk_332","sentenceId":"s_dk_332","level":"sentence","content":"【婚姻】六四爻辞表示在适当的位置上有所疑虑。虽然有疑虑，但并不是因为有外来的侵害，而是关于婚姻的考虑。最终不会有大的过失或遗憾。"},
  {"id":"an_dk_333","sentenceId":"s_dk_333","level":"sentence","content":"【吉祥】六五爻的吉祥，是因为有喜庆之事发生。在《易经》中，六五爻通常代表中正、柔和的位置，能够得到上天的庇佑和人们的喜爱，因此会有吉祥和喜庆的事情发生。"},
  {"id":"an_dk_334","sentenceId":"s_dk_334","level":"sentence","content":"【吉祥】此句出自《易经》贲卦的上九爻辞，意为以朴素自然的态度处事，不会招致咎害，且能够达到上层或实现志向。表明保持本色、不加修饰的美德，最终会得到好的结果。"},
  {"id":"an_dk_335","sentenceId":"s_dk_335","level":"sentence","content":"【凶险】剥卦象征着事物的衰败和剥落，卦辞“不利有攸往”意味着在当前的形势下，不宜采取行动或前往他处，否则可能会遭遇不利的局面。这提示人们在面对困难和挑战时，应当保持谨慎，避免轻举妄动，以免造成更大的损失。"},
  {"id":"an_dk_336","sentenceId":"s_dk_336","level":"sentence","content":"【剝卦】剥卦象征着剥落、衰败，阴柔的力量正在侵蚀阳刚的力量。在这种情况下，不利于有所行动，因为小人的势力正在增长。顺应时势并适时停止行动，这是观察自然现象所得出的结论。君子应当懂得事物的消长、盈亏，这是天道的运行规律。"},
  {"id":"an_dk_337","sentenceId":"s_dk_337","level":"sentence","content":"【卦象】此句出自《周易》中的剥卦。剥卦的卦象是山（艮）附于地（坤）之上，象征着事物的表面或上层逐渐剥落，基础或下层逐渐显露。\"上以厚下，安宅\"意味着在剥落的过程中，应当注重巩固基础，使根基更加稳固，从而达到安定的状态。"},
  {"id":"an_dk_338","sentenceId":"s_dk_338","level":"sentence","content":"【凶险】初六爻辞描述了床脚被剥落的情景，象征着基础的动摇。这里的“蔑贞凶”意味着轻视正道或忽视根本会导致凶险。整体上，爻辞告诫人们要重视基础和根本，不可轻视或忽视，否则将招致不利。"},
  {"id":"an_dk_339","sentenceId":"s_dk_339","level":"sentence","content":"【凶险】六二爻的爻辞“剥床以辨，蔑贞凶”意味着事物的基础正在被侵蚀，已经到了可以明显辨识的地步，此时如果轻视或忽视这种危险，坚持错误的行为或立场，将会遭遇凶险。爻辞告诫人们要重视潜在的危机，不可掉以轻心。"},
  {"id":"an_dk_340","sentenceId":"s_dk_340","level":"sentence","content":"【剝卦】六三爻处于剥卦之中，表示事物正在遭受剥落或削弱的状态。然而，“无咎”意味着在这种不利的情况下，如果能够保持正直和谨慎，就不会有灾祸。这提示我们在面对困难和挑战时，应保持内心的坚定和行为的正当，以避免不必要的麻烦。"},
  {"id":"an_dk_341","sentenceId":"s_dk_341","level":"sentence","content":"【凶险】六四爻辞描述了一种非常不利的情况，\"剥床以肤\"意味着事物已经到了被剥削到最底层的状态，如同床被剥到皮肤一样，象征着事物的衰败已经到了极点，因此会有凶险。这提示我们，在面对问题时，要警惕事物的恶化，及时采取措施，避免事态进一步恶化。"},
  {"id":"an_dk_342","sentenceId":"s_dk_342","level":"sentence","content":"【吉祥】此爻辞表示如同鱼儿贯穿而行，宫人受到宠爱，一切皆顺利，没有不利。意味着在团队或组织中，成员能够有序地协作，得到领导的赏识和宠爱，从而带来吉祥的结果。"},
  {"id":"an_dk_343","sentenceId":"s_dk_343","level":"sentence","content":"【吉凶未定】此爻辞描述了上九爻的状况，硕大的果实未能被食用，象征着事物已经成熟但未能得到利用或享受。君子得到车舆，意味着有德行的人会得到支持和帮助；而小人剥庐，意味着无德之人则会失去庇护，遭受损失。整体来看，这一爻辞反映了君子与小人在不同情境下的不同命运，强调了德行的重要性。同时，也暗示了当前局面处于一种不确定的状态，需要根据实际情况作出正确的判断和选择。"},
  {"id":"an_dk_344","sentenceId":"s_dk_344","level":"sentence","content":"【剝卦】此句出自《周易》剥卦的爻辞，意为床脚被剥落，象征着基础或根基的削弱。剥卦象征着剥落、削弱、衰败，此爻辞强调了从下部开始的衰败，意味着事物的根基正在逐渐丧失，需要警惕和及时补救。"},
  {"id":"an_dk_345","sentenceId":"s_dk_345","level":"sentence","content":"【凶险】此句出自《周易》剥卦的爻辞，意为床的基础被剥蚀而需要辨别，但还没有人来帮助。这象征着根基受损，孤立无援的危险处境。"},
  {"id":"an_dk_346","sentenceId":"s_dk_346","level":"sentence","content":"【变卦】此句出自《周易》中的剥卦。剥卦象征着事物的剥落、衰败。\"剥之无咎，失上下也\"的意思是，在剥卦中，如果能够顺应变化，不固守旧有的上下等级关系，就不会有咎害。这表明在事物衰败或变革时期，应当灵活应对，不必拘泥于传统的上下秩序，以避免更大的损失。"},
  {"id":"an_dk_347","sentenceId":"s_dk_347","level":"sentence","content":"【凶险】此句出自《周易》剥卦的爻辞，意为床被剥蚀到皮肤，形容危险已经非常接近，情况十分危急。剥卦象征着事物的衰败和损失，此爻辞警示人们要警惕潜在的危机，不可掉以轻心。"},
  {"id":"an_dk_348","sentenceId":"s_dk_348","level":"sentence","content":"【人际關系】这句话的意思是，通过在宫廷中得到宠幸，最终不会有什么过失。这反映了在特定环境中，通过与他人的良好关系和得到他人的支持，可以避免不利的后果。"},
  {"id":"an_dk_349","sentenceId":"s_dk_349","level":"sentence","content":"【吉凶】君子得到车舆，象征得到民众的支持和拥戴，这是吉祥的象征。小人剥庐，意味着小人破坏了居所，失去了根本，最终是不可用的，这是凶险的象征。整体上，这句话表达了君子得民心则昌，小人失民心则亡的道理。"},
  {"id":"an_dk_350","sentenceId":"s_dk_350","level":"sentence","content":"【复卦】复卦象征着回复、复兴。卦辞中的“亨”表示亨通顺利，意味着事物经过一段时间的沉寂后，将重新焕发生机。\"出入无疾\"表示出门和回家都不会遇到灾祸，一切平安。\"朋来无咎\"则表示朋友来访不会带来麻烦，人际关系和谐。\"反复其道，七日来复\"意味着事物的发展会有一个周期性的循环，七天为一个周期，事物会在这个周期内恢复到原来的状态。\"利有攸往\"则表示在这个时候采取行动是有利的，可以达到预期的目标。整体来看，复卦是一个积极向上的卦象，预示着事情将有好的转机。"},
  {"id":"an_dk_351","sentenceId":"s_dk_351","level":"sentence","content":"【复卦】复卦象征着恢复和回归。卦象显示阳刚之气从下而上返回，象征着事物的运动遵循自然规律，因此行动顺畅，没有阻碍，朋友前来也不会有灾难。事物的循环往复，如同七天一个周期，这是自然界的运行法则。适宜有所行动，因为阳刚之气正在增长。复卦还体现了天地间的核心精神，即万物皆有回归本源的倾向。"},
  {"id":"an_dk_352","sentenceId":"s_dk_352","level":"sentence","content":"【自然與社會秩序】此大象辞描述了自然界与社会秩序的和谐统一。雷在地中，象征着自然界的恢复与更新，即“复”。先王在至日（冬至或夏至）时关闭城门，停止商业活动和旅行，君主也不巡视四方，体现了对自然规律的尊重和顺应，以及社会秩序的调整与恢复。这反映了古代社会对自然界的敬畏和顺应自然规律的生活方式。"},
  {"id":"an_dk_353","sentenceId":"s_dk_353","level":"sentence","content":"【吉兆】初九爻辞表示，事情不会反复无常，不会有大的悔恨，大为吉祥。这说明在开始阶段，行动果断，方向正确，能够避免远大的错误，从而获得良好的结果。"},
  {"id":"an_dk_354","sentenceId":"s_dk_354","level":"sentence","content":"【吉兆】六二爻辞“休复，吉”意味着在回归正道或恢复常态的过程中，能够得到休息和调整，最终结果吉祥。这表明在遇到困难或偏离正轨时，及时调整方向，回归初心或正道，将会带来好的结果。"},
  {"id":"an_dk_355","sentenceId":"s_dk_355","level":"sentence","content":"【反复/危险/無咎】六三爻表示反复回归正道，虽然处于危险之中，但最终不会有灾难。此爻暗示在困难和挑战中，只要能够不断调整和回归正确的方向，就能够避免灾祸。"},
  {"id":"an_dk_356","sentenceId":"s_dk_356","level":"sentence","content":"【复卦】六四爻位于复卦之中，象征着在回归正道的过程中，能够保持中庸之道，独自坚定地返回到正确的道路上。这表示在面对困难和诱惑时，能够保持内心的清明，不随波逐流，坚持自己的正确方向。"},
  {"id":"an_dk_357","sentenceId":"s_dk_357","level":"sentence","content":"【复卦】六五爻位于复卦之中，象征着回归本源、恢复正道的过程。\"敦复\"意味着以敦厚、诚恳的态度回归正道，这样就不会有悔恨。此爻强调了在回归的过程中，保持内心的真诚与坚定，能够避免错误和遗憾。"},
  {"id":"an_dk_358","sentenceId":"s_dk_358","level":"sentence","content":"【凶险】上六爻辞描述了一种迷失方向、无法回归正道的凶险状态。这种状态下，不仅会有灾难和不祥之事发生，而且如果在这种状态下进行军事行动，最终会导致惨重的失败。甚至影响到国家的君主，带来严重的凶险。这种不利的局面可能会持续很长时间，长达十年之久，都无法恢复正常的征伐能力。这说明在迷失方向、背离正道的情况下，不仅个人会遭遇不幸，还会给国家和社会带来长期的负面影响。"},
  {"id":"an_dk_359","sentenceId":"s_dk_359","level":"sentence","content":"【自我修養】这句话出自《易经》复卦的象辞，意为在不远的地方就能返回正道，这是通过修身养性来实现的。强调了个人应当注重内在修养，及时纠正自己的行为，回归正道。"},
  {"id":"an_dk_360","sentenceId":"s_dk_360","level":"sentence","content":"【吉】此句出自《周易》中的卦辞，意为在休止之后恢复行动是吉祥的，因为这是遵循了仁德的原则。这里的“休”指的是休息或停止，“复”则是指恢复或回归。整个句子强调了在适当的时候停止，然后在合适的时机重新开始，这种行为是符合仁德的，因此是吉祥的。"},
  {"id":"an_dk_361","sentenceId":"s_dk_361","level":"sentence","content":"【無咎】虽然频繁地面临危险或困难，但因为行为正当，最终不会招致灾祸。"},
  {"id":"an_dk_362","sentenceId":"s_dk_362","level":"sentence","content":"【中庸】此句出自《周易·复卦》的象辞，意为在复卦中，唯有中行（即处于中位的爻）能够独自复归，因为它遵循了中庸之道。中庸之道强调的是在行为和思想上保持适中、平衡，避免走极端，是一种理想的行为准则。"},
  {"id":"an_dk_363","sentenceId":"s_dk_363","level":"sentence","content":"【內省】这句话出自《周易》复卦的象辞，意为敦厚地回归正道而无悔，是因为能够通过内心的自我反省和检讨来保持中正。这反映了一个人在行为上能够回归正道，同时在内心深处进行自我反省，以确保自己的行为符合道德和正道。"},
  {"id":"an_dk_364","sentenceId":"s_dk_364","level":"sentence","content":"【凶险】此句出自《周易》中的卦辞，意为迷失而反复的凶险，是因为违背了君主应有的正道。这里的“反君道”指的是行为或决策违背了正确的领导原则或道德规范，导致了不好的结果。"},
  {"id":"an_dk_365","sentenceId":"s_dk_365","level":"sentence","content":"【正道】无妄卦象征着无妄之福，即不妄求、不妄为，遵循正道而行。卦辞中的“元亨，利贞”意味着大为亨通，利于坚守正道。而“其匪正有眚，不利有攸往”则告诫人们，如果行为不正，则会有灾祸，不利于前往。因此，无妄卦强调了遵循正道的重要性，不可偏离正轨，不可妄想妄为。"},
  {"id":"an_dk_366","sentenceId":"s_dk_366","level":"sentence","content":"【卦象與天命】这段彖辞出自《周易》中的无妄卦。无妄卦的卦象是由震（雷）下乾（天）上组成，象征着刚健之气从外而来，成为内在的主导力量。卦辞中提到“动而健，刚中而应”，意味着行动刚健，中正相应，因此能够大亨通而正直，这是天命所赋予的。然而，如果行为不正，则会有灾祸，不利于前行。无妄卦强调了遵循天命、保持正直的重要性，告诫人们在行动之前要深思熟虑，不可妄动。"},
  {"id":"an_dk_367","sentenceId":"s_dk_367","level":"sentence","content":"【自然與人文】这段大象辞描述了自然界中雷声隆隆、万物生长的景象，同时也反映了先王顺应时令、养育万物的治国理念。其中，“天下雷行”象征着自然界的强大力量和普遍规律，“物与无妄”则强调了万物生长的自然状态，没有虚妄和虚假。而“先王以茂对时，育万物”则体现了古代君主顺应自然规律、促进万物生长的治国之道。整体上，这段大象辞将自然现象与人文理念相结合，表达了人与自然和谐共生的美好愿景。"},
  {"id":"an_dk_368","sentenceId":"s_dk_368","level":"sentence","content":"【吉兆】初九爻辞表示在没有妄想、不抱有不切实际的期望的情况下，前行是吉祥的。这提示人们在行动之前，应当保持心态平和，不被虚幻的幻想所迷惑，脚踏实地地去追求目标，这样就能获得好的结果。"},
  {"id":"an_dk_369","sentenceId":"s_dk_369","level":"sentence","content":"【農業與收獲】六二爻辞表达了在农业活动中，不急于求成，不盲目耕种与收获，而是遵循自然规律，适时休耕，保持土地的肥沃与可持续利用，这样反而有利于长远的发展与收获。爻辞中的“不耕获，不灾畲”意味着在适当的时机不进行耕种或收获，避免过度开发土地，从而达到“利有攸往”的效果，即对未来的行动和发展是有利的。"},
  {"id":"an_dk_370","sentenceId":"s_dk_370","level":"sentence","content":"【凶险】此爻辞描述了一种无妄之灾的情况，即无缘无故的灾祸。爻辞中提到的“或系之牛，行人之得，邑人之灾”形象地说明了这种灾祸的发生是不可预测的，就像一头牛被拴住，行人却意外得到了它，而邑人却因此遭受了损失。这表明在无妄之灾面前，人们很难预料到灾祸的发生，也很难避免其带来的损失。因此，此爻辞的标签为“凶险”。"},
  {"id":"an_dk_371","sentenceId":"s_dk_371","level":"sentence","content":"【吉凶】九四爻辞表示在这一爻的位置上，如果能够坚守正道，就可以避免灾祸。\"可贞\"意味着可以保持正直和坚定，\"无咎\"则表示没有过失或灾难。这一爻强调了在面对困难或挑战时，保持正直和坚定的重要性。"},
  {"id":"an_dk_372","sentenceId":"s_dk_372","level":"sentence","content":"【吉】九五爻辞表示，虽然遭遇了无妄之灾（即意外的、没有原因的灾祸），但不必过分担忧，即使不采取药物治疗，最终也会有好的结果。这说明了在面对突如其来的困难时，保持平和的心态，顺其自然，往往能够化险为夷。"},
  {"id":"an_dk_373","sentenceId":"s_dk_373","level":"sentence","content":"【凶险】上九爻辞表示在无妄卦中，行动会有灾眚，没有任何利益。这表明在当前的情境下，任何主动的行动都可能带来不利的结果，应当保持谨慎，避免轻举妄动。"},
  {"id":"an_dk_374","sentenceId":"s_dk_374","level":"sentence","content":"【吉】无妄之往，得志也，意味着在没有虚妄、不切实际的期望下前行，最终能够实现自己的志向。这表示行动基于真实和实际的情况，因此能够获得成功和满足。"},
  {"id":"an_dk_375","sentenceId":"s_dk_375","level":"sentence","content":"【農業】这句话出自《易经》中的小象辞，意为不耕种就期望收获，是不可能变得富裕的。这里强调了勤劳耕作的重要性，没有付出就没有收获，反映了古代农业社会对劳动价值的重视。"},
  {"id":"an_dk_376","sentenceId":"s_dk_376","level":"sentence","content":"【凶】此辞意为行人得到了一头牛，但对邑人来说却是一场灾难。这预示着某人的得利可能会导致他人的损失，整体上是一个不吉利的兆头。"},
  {"id":"an_dk_377","sentenceId":"s_dk_377","level":"sentence","content":"【吉】此辞意为“可以守正而无咎害，是因为本来就有这样的德性”。表明事物或人本身具备良好的基础和本质，只要保持正直和稳定，就能避免灾祸，获得吉祥。"},
  {"id":"an_dk_378","sentenceId":"s_dk_378","level":"sentence","content":"【警示】这句话意味着不应该尝试那些没有经过验证或可能带来不良后果的方法或药物。它强调了在面对未知或未经证实的事物时，应当保持谨慎，避免盲目尝试，以免造成不必要的伤害或损失。"},
  {"id":"an_dk_379","sentenceId":"s_dk_379","level":"sentence","content":"【凶险】此句小象辞意为，无妄之行，即行为不合常理或过于轻率，最终会导致穷困或灾难。这表明了行为不当会带来不好的后果，预示着凶险。"},
  {"id":"an_dk_380","sentenceId":"s_dk_380","level":"sentence","content":"【吉兆】大畜卦象征着积累和储备，卦辞中的“利贞”意味着在积累过程中要保持正直和坚定。\"不家食吉\"表示不依赖家庭的供养，能够自立更生，这是吉祥的。\"利涉大川\"则意味着在面对重大挑战或困难时，能够顺利渡过，取得成功。整体来看，这是一个积极向上的卦辞，预示着通过个人努力和正直的品质，可以克服困难，实现目标。"},
  {"id":"an_dk_381","sentenceId":"s_dk_381","level":"sentence","content":"【大畜卦】大畜卦象征着积累和储存，其卦象由下乾上艮组成，乾为天，象征刚健；艮为山，象征笃实。整个卦象呈现出一种刚健而笃实、光辉灿烂的景象，象征着日新月异的品德和才能不断增长。刚健的力量位于上方，象征着尊崇贤能之人。大畜卦还表达了能够制止过度的刚健，达到一种大正的状态。卦辞中的“不家食吉”意味着贤能之人不应只满足于家庭的安逸，而应被国家和社会所用，得到应有的供养。而“利涉大川”则表示在面对重大困难和挑战时，应顺应天道，勇往直前，最终能够克服困难，实现目标。"},
  {"id":"an_dk_382","sentenceId":"s_dk_382","level":"sentence","content":"【象辭】此句出自《周易》大畜卦的象辞，意为天位于山中，象征着大畜（积累、储藏）。君子应当广泛学习前人的言论和行为，以此来培养和积累自己的德行。"},
  {"id":"an_dk_383","sentenceId":"s_dk_383","level":"sentence","content":"【凶险】初九爻辞表示当前处境存在危险，但若能及时停止行动，不再贸然前进，则可以避免不利的后果。这里的“有厉”指的是面临险境，“利已”则意味着停止行动对自己有利。"},
  {"id":"an_dk_384","sentenceId":"s_dk_384","level":"sentence","content":"【出行】九二爻辞中的“舆说輹”意为车轮脱落，象征着出行或计划中出现了阻碍或问题，需要停下来检查和调整。在《周易》中，这一爻辞通常提示人们在行动过程中要关注细节，防止因小失大，确保计划顺利进行。"},
  {"id":"an_dk_385","sentenceId":"s_dk_385","level":"sentence","content":"【行動與决策】九三爻辞描述了一匹优良的马在追逐中，虽然面临困难，但仍然有利于坚持正道。爻辞提到“曰闲舆卫”，意味着在闲暇时也要准备好车马和护卫，以应对可能的挑战。整体来看，这一爻辞强调在行动和决策时，要具备良好的准备和坚定的意志，这样才能顺利前行，达到目标。"},
  {"id":"an_dk_386","sentenceId":"s_dk_386","level":"sentence","content":"【吉祥】六四爻辞中的“童牛之牿，元吉”意味着对初生之牛加以牿（即用木架限制其角，防止它伤人），象征着对事物在萌芽阶段进行适当的引导和约束，可以带来大的吉祥。这表明在处理问题时，应当及时采取措施，防患于未然，以达到最好的结果。"},
  {"id":"an_dk_387","sentenceId":"s_dk_387","level":"sentence","content":"【吉祥】此爻辞意为，像阉割过的公猪的牙齿一样，虽然看似有威胁，但实际上已经没有了攻击性，象征着危险已经被化解，局面变得吉祥。六五爻处于尊位，能够以柔克刚，化解矛盾，因此结果是吉祥的。"},
  {"id":"an_dk_388","sentenceId":"s_dk_388","level":"sentence","content":"【吉兆】上九爻辞“何天之衢，亨”意味着处于极高的位置，如同天上的大道一样畅通无阻，象征着大吉大利，一切事情都能顺利进行。此爻预示着在最高点或最有利的位置上，能够得到天助，亨通无阻。"},
  {"id":"an_dk_389","sentenceId":"s_dk_389","level":"sentence","content":"【吉凶】此句意为虽然有危险，但只要能够自我克制，就不会招致灾难。表明在面临险境时，保持谨慎和自制是非常重要的，这样可以避免不利的后果。"},
  {"id":"an_dk_390","sentenceId":"s_dk_390","level":"sentence","content":"【無咎】这句话出自《周易》中的小象辞，意为车的辐条脱落，但处于中位，没有过失。这里“舆说輹”比喻事物出现了一些问题或困难，但因为处于中正的位置，所以不会有过失或咎责。整体上表示虽然遇到了一些小问题，但因为位置得当，不会受到责备。"},
  {"id":"an_dk_391","sentenceId":"s_dk_391","level":"sentence","content":"【吉】此句意为前往有利，上方与之志向相合。表明行动得到支持，方向正确，结果吉祥。"},
  {"id":"an_dk_392","sentenceId":"s_dk_392","level":"sentence","content":"【吉祥】六四爻辞表示大吉大利，预示着有喜庆之事发生。在《易经》中，此爻辞通常意味着事情进展顺利，会带来好的结果或消息。"},
  {"id":"an_dk_393","sentenceId":"s_dk_393","level":"sentence","content":"【吉祥】六五爻的吉祥，是因为有喜庆之事发生。在《易经》中，六五爻通常代表中正、柔和的位置，能够得到上天的保佑和人们的拥戴，因此会有吉祥和喜庆的结果。"},
  {"id":"an_dk_394","sentenceId":"s_dk_394","level":"sentence","content":"【吉兆】此句小象辞意为天之大道畅通无阻，象征着行事将大有可为，前景光明，是吉祥的预兆。"},
  {"id":"an_dk_395","sentenceId":"s_dk_395","level":"sentence","content":"【養生/自給自足】颐卦象征着养生和自给自足。\"贞吉\"意味着坚守正道则吉祥。\"观颐，自求口实\"则表示通过观察颐养之道，人们应当自食其力，自己寻求生活的来源和精神的满足。这不仅是物质上的自给自足，更是精神上的独立与自主。"},
  {"id":"an_dk_396","sentenceId":"s_dk_396","level":"sentence","content":"【卦辭-颐卦】颐卦的卦辞为“颐贞吉，养正则吉也”。这表示在颐卦的情境下，保持正直和正道的修养是吉祥的。接着，“观颐，观其所养也；自求口实，观其自养也”意味着观察颐卦，可以了解一个人的修养和生活方式，以及他如何自我供养。最后，“天地养万物，圣人养贤，以及万民；颐之时义大矣哉！”强调了天地养育万物、圣人养育贤人和民众的重要性，说明颐卦在特定时势下的意义非常重大。"},
  {"id":"an_dk_397","sentenceId":"s_dk_397","level":"sentence","content":"【象辭】此句出自《周易》的象辞部分，描述的是颐卦的象征意义。颐卦的下卦为震（雷），上卦为艮（山），象征着山下有雷。君子观此卦象，应当效法颐卦的含义，谨慎自己的言语，节制自己的饮食，以培养自身的德行和健康。"},
  {"id":"an_dk_398","sentenceId":"s_dk_398","level":"sentence","content":"【凶险】初九爻辞中的“舍尔灵龟，观我朵颐”意味着放弃了自己的智慧和判断（灵龟象征智慧），而去关注他人的表面享受（朵颐象征口腹之欲）。这种行为会导致凶险，因为忽视了内在的智慧和直觉，而被外界的诱惑所迷惑，可能会做出错误的决策。"},
  {"id":"an_dk_399","sentenceId":"s_dk_399","level":"sentence","content":"【凶险】六二爻辞描述了一种不正常的依赖关系，即“颠颐”，意味着上下颠倒，本末倒置的供养或依赖。接着，“拂经”表示违背常规或常理。在“于丘颐”中，丘象征着高处或群体，颐则指养活或依赖，整体表达了一种在高处或群体中寻求供养的状态，但这种状态是不稳定的，容易导致危险。最后，“征凶”明确指出，如果在这种状态下贸然行动，将会遭遇凶险。因此，此爻辞整体上表达了在不正常、不稳定的关系中寻求依赖或供养是危险的，应当避免。"},
  {"id":"an_dk_400","sentenceId":"s_dk_400","level":"sentence","content":"【凶险】六三爻辞表示行为违背了颐养之道，坚守正道也会遭遇凶险，长时间内都不会有好的机会或转机，一切行动都不利于发展。这说明在当前的环境下，应该保持谨慎，避免冒险，等待时机。"},
  {"id":"an_dk_401","sentenceId":"s_dk_401","level":"sentence","content":"【吉凶】六四爻辞描述了一种看似颠倒却吉祥的状态，象征着在逆境中找到生机。其中“虎视眈眈，其欲逐逐”形容了在追求目标时的专注与坚定，这种态度能够帮助克服困难，最终达到无咎的境地。整体上，此爻辞鼓励在面对挑战时保持积极的心态和不懈的努力。"},
  {"id":"an_dk_402","sentenceId":"s_dk_402","level":"sentence","content":"【中正柔順】六五爻处于上卦之中，象征着中正柔顺的德行。爻辞中的“拂经”意味着违背常规或常理，但因为六五爻居中得正，所以能够保持贞正，吉祥。然而，由于其柔弱的性质，不宜进行大的冒险或跨越大的障碍，如“不可涉大川”。这提示在面对重大决策或挑战时，应保持谨慎，避免鲁莽行事。"},
  {"id":"an_dk_403","sentenceId":"s_dk_403","level":"sentence","content":"【上九】上九爻辞表示，通过颐养之道，虽然面临危险但最终吉祥，适宜进行大的行动或渡过难关。这里强调了在困难中坚持正道，通过自我修养和智慧来克服挑战，最终能够获得成功。"},
  {"id":"an_dk_404","sentenceId":"s_dk_404","level":"sentence","content":"【謙遜】这句话出自《易经》的观卦。\"观我朵颐，亦不足贵也\"的意思是，即使看到我丰盛的食物，也不值得炫耀或自满。这表达了一个人即使在物质上有所成就，也应该保持谦逊的态度，不以物质的丰富来衡量自己的价值。"},
  {"id":"an_dk_405","sentenceId":"s_dk_405","level":"sentence","content":"【凶险】六二爻辞表示如果出征会有凶险，这是因为行动中失去了同类的支持或配合。在《周易》中，\"行失类\"意味着在行动过程中，失去了与自己性质相同或相近的伙伴，导致孤立无援，从而可能遭遇不利。"},
  {"id":"an_dk_406","sentenceId":"s_dk_406","level":"sentence","content":"【不利】此句意为在十年之内不宜采取行动，因为所处的环境或形势与大道相违背，此时行动难以成功，甚至可能招致不利。"},
  {"id":"an_dk_407","sentenceId":"s_dk_407","level":"sentence","content":"【吉祥】此句出自《周易》颐卦的爻辞，意为通过调整和改善颐养的方式而获得吉祥的结果。其中，“颠颐”指的是改变颐养的方式或状态，“上施光”则表示这种改变是由上位者（如君主或领导者）所实施，并且这种改变带来了光明和积极的影响。整体而言，这句话强调了正确的领导和积极的变革能够带来吉祥的结果。"},
  {"id":"an_dk_408","sentenceId":"s_dk_408","level":"sentence","content":"【吉兆】处于贞正的位置而获得吉祥，是因为能够顺应并服从上级。这表示在当前的情境下，保持正直、顺从的态度将会带来好的结果。"},
  {"id":"an_dk_409","sentenceId":"s_dk_409","level":"sentence","content":"【吉兆】此辞意为在颐养之时虽有危险但最终吉祥，将会迎来大的喜庆。表明在经历了一段艰难的时期后，将会迎来好的转机，预示着吉祥和喜庆。"},
  {"id":"an_dk_410","sentenceId":"s_dk_410","level":"sentence","content":"【吉凶未定】大过卦象征着过度或极端的情况，卦辞中的“栋桡”意味着事物已经达到了极限，如同梁柱弯曲，结构不稳定。然而，“利有攸往，亨”则表示在这种情况下，采取适当的行动是有利的，可以通达。整体来看，大过卦提示我们在面对极端或危机时，需要审时度势，采取果断而恰当的措施，才能转危为安，化险为夷。"},
  {"id":"an_dk_411","sentenceId":"s_dk_411","level":"sentence","content":"【卦象解析】大过卦象征着“大者过也”，即事物超过了常规的限度。其中“栋桡”表示栋梁弯曲，暗示基础或根本力量薄弱。而“刚过而中”则指刚强过度但能保持中正，巽（顺）而说（悦）行，意味着顺应时势、愉悦前行，有利于有所作为，最终达到亨通。大过卦所体现的时代意义非常重大。"},
  {"id":"an_dk_412","sentenceId":"s_dk_412","level":"sentence","content":"【象辭】此句出自《周易》中的大象传，描述的是大过卦的象辞。大过卦的卦象是泽（兑）在上，木（巽）在下，象征着泽水淹没树木，这是一种非常态的现象，故称为“大过”。君子观此卦象，应当效法其独立自主、不畏艰难的精神，即使身处逆境，也能保持内心的宁静与坚定，不为世俗所困扰，隐退于世而不感到郁闷。"},
  {"id":"an_dk_413","sentenceId":"s_dk_413","level":"sentence","content":"【吉兆】初六爻辞中的“藉用白茅，无咎”意味着在进行某种仪式或行动时，使用了白茅这种象征纯洁和尊重的物品，因此能够避免灾祸，得到吉祥的结果。这表明在处理事情时，如果能够保持恭敬和谨慎的态度，就能够避免错误和不幸。"},
  {"id":"an_dk_414","sentenceId":"s_dk_414","level":"sentence","content":"【吉兆】九二爻辞描述了一种看似不可能的新生与结合，枯萎的杨树重新长出嫩芽，年老的丈夫得到了年轻的妻子，这象征着事物在衰败之后能够重新焕发生机，预示着新的希望和机遇。此爻辞表明在困境中仍有可能出现转机，只要保持积极的心态，就能迎来好的结果。"},
  {"id":"an_dk_415","sentenceId":"s_dk_415","level":"sentence","content":"【凶险】九三爻辞中的“栋桡，凶”意味着栋梁弯曲，象征着事物的基础或核心部分出现严重的问题，预示着凶险。在实际应用中，这可能表示决策失误、管理不善或结构上的缺陷，需要及时调整和修正，以避免更大的损失。"},
  {"id":"an_dk_416","sentenceId":"s_dk_416","level":"sentence","content":"【吉凶併存】九四爻辞描述了一种既有利又有弊的情况。\"栋隆，吉\"意味着房屋的栋梁高耸，象征着事物处于一种上升、发展的良好状态，预示着吉祥。然而，\"有它吝\"则表示在这种良好的状态下，如果出现其他不利因素或不当行为，就会导致遗憾或损失。整体来看，九四爻辞提醒人们在顺境中也要保持警惕，防止因疏忽大意而带来的负面影响。"},
  {"id":"an_dk_417","sentenceId":"s_dk_417","level":"sentence","content":"【吉凶未定】九五爻辞描述了一种看似矛盾但又充满生机的情境。枯萎的杨树重新开花，象征着衰败中出现的希望和生机；老妇人得到了年轻丈夫，象征着晚年的幸福或意外的机遇。然而，这种变化虽然没有带来灾难（无咎），但也未能获得赞誉（无誉），表明这种变化虽然没有负面影响，但也没有带来显著的正面效果。整体上，这一爻辞暗示在特定情境下，虽然能够避免不利的结果，但也不应期望过高，保持平和的心态为宜。"},
  {"id":"an_dk_418","sentenceId":"s_dk_418","level":"sentence","content":"【凶险】上六爻辞描述了一种过度冒险、超越自身能力范围的行为，最终导致了严重的后果，如“过涉灭顶”，即涉水过深以至于淹没了头顶。这种行为本身是凶险的，但爻辞最后说“无咎”，意味着如果能够从中吸取教训，认识到自己的错误并改正，就不会有真正的灾祸。这反映了《周易》中“过而能改，善莫大焉”的思想。"},
  {"id":"an_dk_419","sentenceId":"s_dk_419","level":"sentence","content":"【象征】此句出自《周易》中的小象辞，意为用白茅草来铺垫，象征着柔顺和谦卑的态度。这里的“柔在下”表示柔顺的品质处于低位，象征着谦逊和谨慎的态度，是一种美德。"},
  {"id":"an_dk_420","sentenceId":"s_dk_420","level":"sentence","content":"【人际關系】这句话描述的是一种不寻常的婚姻关系，即年老的丈夫和年轻的妻子之间的关系。这种关系可能因为年龄差异而产生各种问题和矛盾，但同时也强调了两人之间的相互扶持和陪伴。在古代社会，这种关系可能被视为一种特殊的社会现象。"},
  {"id":"an_dk_421","sentenceId":"s_dk_421","level":"sentence","content":"【凶险】栋梁弯曲导致的凶险，意味着基础或核心部分出现问题，无法得到有效的支持或帮助，暗示在当前情况下，寻求外援或合作也无法改变不利的局面。"},
  {"id":"an_dk_422","sentenceId":"s_dk_422","level":"sentence","content":"【吉祥】此句意为在高位上能够保持稳固和繁荣的吉祥，是因为没有在低位时屈服或动摇。这表达了在面对困难和挑战时，保持坚定和正直的重要性。"},
  {"id":"an_dk_423","sentenceId":"s_dk_423","level":"sentence","content":"【衰败與不和諧】这段小象辞描述了一种表面看似繁荣但实际上已经衰败的情景，如枯萎的杨树重新开花，这种景象虽然美丽，但无法持久。同时，它还提到了老妇与士夫的结合，暗示了不和谐或不适宜的匹配，这种关系可能会带来丑陋的结果。整体上，这段话表达了对虚假繁荣和不适当关系的警示。"},
  {"id":"an_dk_424","sentenceId":"s_dk_424","level":"sentence","content":"【凶险】此句意为在过度涉险的情况下遭遇凶险，但这种结果不应归咎于他人或外在因素，而是因为自身行为超出了安全的界限。提醒人们在行动时要量力而行，不可盲目冒险。"},
  {"id":"an_dk_425","sentenceId":"s_dk_425","level":"sentence","content":"【险難】坎卦象征着险难和挑战，但通过内心的诚信和坚定，可以克服困难，亨通前行。在行动上，这种坚定和诚信会受到推崇和赞赏。"},
  {"id":"an_dk_426","sentenceId":"s_dk_426","level":"sentence","content":"【卦辭】这段文字是《周易》中坎卦的彖辞。坎卦象征着险难，两个坎卦相重，表示险难重重。但水在流动中不会盈满，即使在险难中也能保持诚信。内心通达，是因为刚毅中正。行动受到推崇，前往会有功绩。天的险难无法攀登，地的险难有山川丘陵，王公设置险阻来守护国家。坎卦的时用非常重大。"},
  {"id":"an_dk_427","sentenceId":"s_dk_427","level":"sentence","content":"【自然與人文】此句出自《周易》坎卦的象辞，描述了水不断积累、逐渐浸润的情景，象征着困难和挑战的持续存在。君子应当像水一样，保持恒常的德行，不断学习和实践教化之事，以应对各种挑战。这里体现了自然现象与人文精神的结合，强调了在逆境中坚持道德修养和教育实践的重要性。"},
  {"id":"an_dk_428","sentenceId":"s_dk_428","level":"sentence","content":"【凶险】初六爻辞描述了一种陷入困境的状态，\"习坎\"意味着习惯于险境，\"入于坎窞\"则表示进一步深陷其中，无法自拔，结果自然是凶险的。这提示人们在面对困难时，不应习以为常，而应积极寻求解决之道，避免陷入更深的困境。"},
  {"id":"an_dk_429","sentenceId":"s_dk_429","level":"sentence","content":"【险中求小利】处于险境中，但能够通过谨慎行动获得小的收获或成功。这表明虽然面临困难和挑战，但通过智慧和努力，仍有可能达到有限的目标。"},
  {"id":"an_dk_430","sentenceId":"s_dk_430","level":"sentence","content":"【凶险】六三爻辞描述了一种极其危险的境地，\"来之坎坎\"意味着行进在重重险阻之中，\"险且枕\"形容危险如同枕木一般压迫着，\"入于坎窞\"则是指陷入了更深的险境，无法自拔。\"勿用\"则是在这种情况下，应当停止行动，避免进一步的损失或伤害。整体来看，六三爻辞强调了在面临极大风险时，应当谨慎行事，避免轻举妄动。"},
  {"id":"an_dk_431","sentenceId":"s_dk_431","level":"sentence","content":"【吉凶：無咎】六四爻辞描述了一种简约而诚挚的待客之道。用简陋的器皿（缶）盛装酒和食物（樽酒簋贰），通过窗户（牖）递送，表达了主人的诚意和谦逊。这种态度最终不会招致灾祸（终无咎）。这表明在人际交往中，真诚和谦逊比奢华的物质更重要。"},
  {"id":"an_dk_432","sentenceId":"s_dk_432","level":"sentence","content":"【吉凶】九五爻辞表示处于险境但尚未充满危险，只要保持谨慎，危险就会平息，不会有灾祸。此爻象征在困难中保持冷静和谨慎的态度，能够避免更大的灾难，最终达到平安无事的境地。"},
  {"id":"an_dk_433","sentenceId":"s_dk_433","level":"sentence","content":"【困厄】上六爻辞描述了一种极度困厄的状态，被束缚并置于险恶的环境中，长时间无法解脱，预示着凶险。徽纆指束缚用的绳索，丛棘象征险恶的环境，三岁不得表示长时间无法摆脱困境。"},
  {"id":"an_dk_434","sentenceId":"s_dk_434","level":"sentence","content":"【凶险】此句出自《周易》坎卦的爻辞，意为在险难中又遇到险难，迷失了正确的道路，将会遭遇凶险。这表明在面对困难时，如果处理不当，可能会使情况变得更加糟糕。"},
  {"id":"an_dk_435","sentenceId":"s_dk_435","level":"sentence","content":"【小象辭】此句出自《周易》中的小象辞，意为求得的小成果或小收获，尚未超出中等的范围。说明事物的发展还处于初级阶段，虽有收获但还不够显著。"},
  {"id":"an_dk_436","sentenceId":"s_dk_436","level":"sentence","content":"【困難】此句小象辞描述了一种艰难前行但最终未能成功的状态。\"来之坎坎\"表示行进过程中遇到了重重困难，\"终无功也\"则表明尽管努力尝试，最终还是没有达到预期的目标或成效。这反映了在面对挑战时，有时即使付出努力也可能无法改变结果的情况。"},
  {"id":"an_dk_437","sentenceId":"s_dk_437","level":"sentence","content":"【卦象】此句出自《周易》中的小象辞，描述的是《噬嗑》卦的上九爻。其中，“樽酒簋贰”指的是用樽盛酒，簋盛食，二者皆为古代祭祀或宴飨时的重要礼器，象征着礼仪和秩序。“刚柔际也”则表示刚与柔的交界处，即阳爻与阴爻相接的地方，象征着事物变化的关键点。整体而言，此句小象辞意在说明在处理重要事务时，应当注重礼仪和秩序，同时关注事物变化的关键点。"},
  {"id":"an_dk_438","sentenceId":"s_dk_438","level":"sentence","content":"【未完成】此句出自《易经》中的坎卦，意指事物尚未达到盈满或完成的状态，中间的力量或条件还不够强大或成熟。这表明在当前阶段，事情还在发展中，需要更多的积累和努力才能达到目标。"},
  {"id":"an_dk_439","sentenceId":"s_dk_439","level":"sentence","content":"【凶险】上六爻处于卦的最高位置，象征着偏离正道、失去方向。爻辞中的“失道”意味着行为或决策偏离了正确的道路，导致了严重的后果。“凶三岁”则表示这种凶险的状态将持续三年，暗示了长期的不利影响。整体来看，这一爻辞告诫人们要坚守正道，避免偏离正确的方向，否则将面临长期的困境和危险。"},
  {"id":"an_dk_440","sentenceId":"s_dk_440","level":"sentence","content":"【卦辭·離卦】离卦象征着附着、光明。此卦辞表示利于坚守正道，亨通。畜养母牛，吉祥。这表明在坚持正道的同时，保持柔顺和积累力量是吉祥的。"},
  {"id":"an_dk_441","sentenceId":"s_dk_441","level":"sentence","content":"【自然與人文】这段彖辞出自《周易》的离卦。离卦象征着附着、美丽，如日月附着于天空，百谷草木附着于大地。离卦由两个相同的离卦重叠而成，象征着光明与美丽附着于正道，从而化育万物，成就天下。柔顺而中正，因此亨通；畜养母牛吉祥，象征着柔顺之美德能够带来吉祥。这段彖辞强调了自然界的和谐与人文社会的正道之间的关系，以及柔顺中正的重要性。"},
  {"id":"an_dk_442","sentenceId":"s_dk_442","level":"sentence","content":"【象辭】此句出自《周易》离卦的象辞，意为离卦由两个相同的离卦组成，象征光明。离卦的象是火，火能发光，故有光明之意。大人应当效法离卦的光明之德，持续不断地将光明普照四方，使光明和智慧惠及天下。"},
  {"id":"an_dk_443","sentenceId":"s_dk_443","level":"sentence","content":"【初爻】在开始行动时，可能会出现一些错误或混乱，但只要保持敬畏之心，谨慎行事，就可以避免灾祸。"},
  {"id":"an_dk_444","sentenceId":"s_dk_444","level":"sentence","content":"【吉祥】六二爻辞中的“黄离，元吉”意味着处于中正之位，能够保持内心的纯正与平和，因此大为吉祥。黄色在中国传统文化中象征着大地与中心，离卦则代表光明与文明，二者结合，表明此爻象征着内心光明、行为中正，能够获得吉祥的结果。"},
  {"id":"an_dk_445","sentenceId":"s_dk_445","level":"sentence","content":"【凶险】此爻辞描述了日暮时分的离卦，象征着事物发展到了衰落的阶段。如果在这个时候不以乐观的态度面对，比如不鼓缶而歌，反而像老年人一样哀叹，就会招致凶险。这说明在困难或衰落时期，保持积极乐观的心态是非常重要的。"},
  {"id":"an_dk_446","sentenceId":"s_dk_446","level":"sentence","content":"【凶险】九四爻辞描述了一种突如其来的灾难，如火灾般迅速蔓延，导致死亡和被遗弃的惨状。这表明当前的形势非常凶险，可能会遭受突如其来的打击或损失，需要提高警惕，谨慎应对。"},
  {"id":"an_dk_447","sentenceId":"s_dk_447","level":"sentence","content":"【情感】此爻辞描述了一种情感上的释放与转变。\"出涕沱若，戚嗟若\"表示情感的极度悲痛与哀伤，如泪水如雨下，悲痛哀叹。然而，\"吉\"则预示着这种情感的宣泄之后，将会带来积极的结果或转机，意味着通过情感的释放，可以达到心灵的净化与解脱，从而获得吉祥。"},
  {"id":"an_dk_448","sentenceId":"s_dk_448","level":"sentence","content":"【戰爭與征服】上九爻辞描述了一位君王出征的情景，他成功地征服了敌人，斩杀了敌方的首领，俘虏了非同一般的俘虏，最终没有招致灾祸。这表明在正义的战争中，通过智慧和勇气取得胜利，可以避免灾难。同时，也暗示了在处理重大事务时，应当果断而明智，以达到预期的目标。"},
  {"id":"an_dk_449","sentenceId":"s_dk_449","level":"sentence","content":"【行為指导】在行为上要谨慎小心，以避免招致灾祸。这句话强调了在行动时应保持敬畏之心，遵循正确的道路，以防止因错误的行为而带来不良后果。"},
  {"id":"an_dk_450","sentenceId":"s_dk_450","level":"sentence","content":"【吉祥】此句出自《易经》离卦的爻辞，意为处于光明正大的位置，遵循中庸之道，可以获得吉祥。黄为中色，象征中庸；离为光明，象征文明。元吉，大吉之意，表示事物发展处于最佳状态，得到中道，即遵循了正确的道路。"},
  {"id":"an_dk_451","sentenceId":"s_dk_451","level":"sentence","content":"【時間與变化】这句话出自《易经》离卦的爻辞，意为太阳偏西的时候，光明逐渐消退，这种情况不可能长久持续。比喻事物发展到鼎盛阶段后，必然会有衰落的趋势，强调了时间的流逝和事物变化的自然规律。"},
  {"id":"an_dk_452","sentenceId":"s_dk_452","level":"sentence","content":"【变化】这句话描述了一种突然发生、无法预料的情况，让人感到措手不及，没有足够的空间或时间去适应或应对。这种突如其来的变化往往让人感到无所适从，难以找到合适的应对方式。"},
  {"id":"an_dk_453","sentenceId":"s_dk_453","level":"sentence","content":"【吉祥】六五爻的吉祥，是因为它远离了王公的高位，避免了权力中心的纷争和危险，处于一个相对安全和宁静的位置。这表明在某些情况下，退一步、远离权力中心反而能够获得吉祥和平安。"},
  {"id":"an_dk_454","sentenceId":"s_dk_454","level":"sentence","content":"【國家治理】这句话出自《周易》的象辞，意思是君王出征是为了匡正国家。这反映了古代君主通过军事行动来维护国家秩序和正义的理念。在这里，“王用出征”强调了君主在国家治理中的权威和责任，“以正邦也”则表明了出征的目的在于纠正国家内部的混乱或外部的威胁，以达到国家的稳定和繁荣。"},
  {"id":"an_dk_455","sentenceId":"s_dk_455","level":"sentence","content":"【婚姻】咸卦象征感应与和谐，卦辞“亨，利贞，取女吉”表明在婚姻或男女关系中，双方能够相互感应、和谐相处，婚姻美满，适宜结婚。"},
  {"id":"an_dk_456","sentenceId":"s_dk_456","level":"sentence","content":"【感應】此卦辞描述了“咸”卦的含义，强调了感应与相互作用的重要性。在“咸”卦中，阴柔之爻位于上方，阳刚之爻位于下方，象征着阴阳二气相互感应、相互配合。这种感应关系带来了和谐与愉悦，象征着男性对女性的尊重与谦逊，因此卦辞中提到“亨利贞，取女吉”。进一步地，卦辞将感应的概念扩展到天地万物，指出天地之间的感应产生了万物的化生，而圣人通过感化人心，可以实现天下的和平。通过观察感应的现象，可以洞察天地万物的本质与情感。"},
  {"id":"an_dk_457","sentenceId":"s_dk_457","level":"sentence","content":"【自然與人文】此句出自《周易》咸卦的象辞，意为山上有泽，象征着咸卦的自然景象。君子观此象，应当效法山之静默与泽之包容，以谦虚的态度接纳他人，体现了一种自然与人文相融合的哲理。"},
  {"id":"an_dk_458","sentenceId":"s_dk_458","level":"sentence","content":"【感應/初動】初六爻辞“咸其拇”意味着感应刚刚开始，如同脚大拇指微微动了一下，象征着事物的初始阶段，感应的力量还很微弱，但已经开始有了初步的反应。此时应当谨慎行事，不可急躁，应静待时机，逐步发展。"},
  {"id":"an_dk_459","sentenceId":"s_dk_459","level":"sentence","content":"【爻辭】六二爻的爻辞表示，感应到小腿部位，有凶险，但若能安居则吉祥。此爻暗示在行动上要谨慎，避免轻举妄动，保持内心的宁静和稳定，才能转危为安。"},
  {"id":"an_dk_460","sentenceId":"s_dk_460","level":"sentence","content":"【行動與决策】九三爻辞描述了一种行动上的迟疑和跟随的状态。\"咸其股\"意味着行动受到了阻碍，\"执其随\"则表示在跟随他人或事物时显得过于执着或被动。\"往吝\"则预示着如果继续这种状态，将会遇到困难或不利。整体来看，这一爻辞提醒人们在行动和决策时要主动、果断，避免过于依赖或跟随他人，否则可能会陷入不利的局面。"},
  {"id":"an_dk_461","sentenceId":"s_dk_461","level":"sentence","content":"【吉兆】九四爻辞表示坚守正道则吉祥，悔恨将消失。爻辞中的“憧憧往来，朋从尔思”描绘了一幅人们来来往往，朋友顺从你心意的画面，象征着在坚持正道的基础上，人际关系和谐，朋友众多，能够得到他人的支持与帮助。整体而言，这是一个积极向上的爻辞，预示着在正确的道路上，可以克服困难，实现目标。"},
  {"id":"an_dk_462","sentenceId":"s_dk_462","level":"sentence","content":"【感應】九五爻辞表示感应到了背部的肌肉，意味着在这一阶段，个人能够感受到来自他人的支持和帮助，但同时也需要保持自身的独立性和自主性，不因外界的影响而失去自我。由于九五爻处于尊位，象征着领导或决策者的位置，因此这一爻辞也暗示着在领导或决策过程中，应当注重与他人的沟通和协作，但同时也要保持清晰的判断力，避免盲目从众。做到这一点，就可以无悔。"},
  {"id":"an_dk_463","sentenceId":"s_dk_463","level":"sentence","content":"【感應/言語】上六爻的爻辞“咸其辅颊舌”意味着感应或影响集中在口舌、言语上。这可以理解为通过言语交流来产生感应，或者是在言语表达中体现出某种感应的作用。在实际应用中，可以理解为在沟通、谈判、演讲等场合中，通过恰当的言语表达，可以达到影响他人、达成共识的效果。同时，也提醒人们在言语上要谨慎，避免因言语不当而引发不必要的矛盾或误解。"},
  {"id":"an_dk_464","sentenceId":"s_dk_464","level":"sentence","content":"【初六】咸卦的初六爻辞“咸其拇，志在外也”意味着感应刚刚开始，如同脚大拇指微微动了一下，表示有向外行动的意愿，但行动尚未真正开始。这表明在事物的初始阶段，人们可能会有向外发展的志向或冲动，但还需要谨慎行事，不可轻举妄动。"},
  {"id":"an_dk_465","sentenceId":"s_dk_465","level":"sentence","content":"【吉凶】此句意为即使处于凶险的环境中，只要能够顺应天时、地利、人和，保持内心的平和与正直，就不会受到伤害。说明在不利的情况下，通过自身的调整和顺应，仍然可以达到吉祥的结果。"},
  {"id":"an_dk_466","sentenceId":"s_dk_466","level":"sentence","content":"【行動與追隨】此句小象辞描述了一种积极主动但又处于从属地位的状态。\"咸其股，亦不处也\"意味着行动起来，不再停留；\"志在随人，所执下也\"则表明这种行动是出于跟随他人的意愿，自己处于较低的位置。整体上，这反映了一个人在关系中愿意跟随他人，积极参与，但同时也表明其在关系中的地位较低，需要依附于他人。"},
  {"id":"an_dk_467","sentenceId":"s_dk_467","level":"sentence","content":"【吉凶】此辞表示占卜的结果是吉祥的，不会有悔恨和灾害。但是，由于心中还有许多纷扰和犹豫（憧憧往来），所以还没有达到光明正大的境界。这说明虽然目前的情况是好的，但还需要进一步的修养和努力，以达到更高的境界。"},
  {"id":"an_dk_468","sentenceId":"s_dk_468","level":"sentence","content":"【身體部位】这句话出自《易经》咸卦的爻辞，其中“脢”指的是背部的肉。整句的意思是说，感应到了背部的肉，这象征着感应到了身体的末端，即“志末也”。这里的“志末”可以理解为心意的末端，意味着事情已经到了接近尾声的阶段，或者是对事物的表面有所感应，但未能深入核心。"},
  {"id":"an_dk_469","sentenceId":"s_dk_469","level":"sentence","content":"【言語】此句小象辞描述的是口舌活动，咸卦的这一爻辞强调了言语的表达和交流，其中“辅颊舌”指的是口部的动作，“滕口说也”则表示言语的流通和传播。整体上，这一爻辞反映了言语在人际交往中的重要性。"},
  {"id":"an_dk_470","sentenceId":"s_dk_470","level":"sentence","content":"【穩定與持久】恒卦象征着恒常与持久，卦辞“亨，无咎，利贞，利有攸往”意味着在保持恒心和毅力的情况下，事情会顺利进行，没有灾难，有利于坚守正道，也利于有所作为。恒卦提醒人们在追求目标时要持之以恒，不可半途而废。"},
  {"id":"an_dk_471","sentenceId":"s_dk_471","level":"sentence","content":"【恒卦】恒卦象征恒久。其结构为阳刚在上，阴柔在下，雷与风相互配合，表现出柔和而能动的特性，刚柔相济，形成恒久的状态。恒卦亨通无咎，利于坚守正道；这是因为它能够长久地遵循其内在的法则，就像天地的运行一样，恒久不息。利于有所前往，因为终结之后会有新的开始。日月运行于天，能够长久地照耀；四季变化，能够长久地形成万物；圣人长久地遵循其道，天下因此而得以教化。通过观察恒久不变的事物，可以洞察天地万物的真相。"},
  {"id":"an_dk_472","sentenceId":"s_dk_472","level":"sentence","content":"【恒心與堅持】雷风恒卦象征着恒心与坚持。君子应当像恒卦所显示的那样，坚定不移地站在自己的立场上，不轻易改变自己的方向和原则。这表明了在面对困难和挑战时，保持坚定的意志和恒心的重要性。"},
  {"id":"an_dk_473","sentenceId":"s_dk_473","level":"sentence","content":"【凶险】初六爻辞“浚恒，贞凶，无攸利”意味着在恒卦的初始阶段，如果采取过度深入或急功近利的行动，将会导致凶险的结果，且不会有任何好处。此爻告诫人们在事情的开始阶段应当谨慎行事，不可轻举妄动，否则容易陷入困境。"},
  {"id":"an_dk_474","sentenceId":"s_dk_474","level":"sentence","content":"【吉凶悔吝】九二爻的爻辞“悔亡”意味着在这一爻的位置上，原本可能存在的悔恨或不利情况已经消失或被化解。这通常表示在面临困难或错误时，通过正确的行动或态度调整，可以避免不利后果，转危为安。这一爻辞多为吉兆，表明事情有好转的迹象。"},
  {"id":"an_dk_475","sentenceId":"s_dk_475","level":"sentence","content":"【德行】九三爻辞表示，如果不能恒久保持德行，可能会遭受羞辱，占问结果为吝啬。这说明了在行为和品德上需要持之以恒，否则可能会带来不好的后果。"},
  {"id":"an_dk_476","sentenceId":"s_dk_476","level":"sentence","content":"【不利】九四爻辞“田无禽”意味着在狩猎时一无所获，象征着努力没有得到预期的成果，行动未能达到目的。此爻暗示当前的行动或策略可能需要调整，以避免徒劳无功。"},
  {"id":"an_dk_477","sentenceId":"s_dk_477","level":"sentence","content":"【中正柔順】六五爻处于上卦之中，具有中正之德，但其性质为阴爻居阳位，象征柔顺。此爻辞表示坚守恒常的德行，保持正直，对于柔顺的妇人来说是吉祥的，但对于刚强的夫子来说则可能遭遇凶险。这反映了在不同角色和性格背景下，同样的行为可能会产生不同的结果。"},
  {"id":"an_dk_478","sentenceId":"s_dk_478","level":"sentence","content":"【凶险】上六爻辞“振恒，凶”意味着在恒久不变的情况下强行振动或改变，将会带来凶险。这提示人们在稳定的状态中不应轻举妄动，否则可能会招致不利的后果。"},
  {"id":"an_dk_479","sentenceId":"s_dk_479","level":"sentence","content":"【風险】浚恒之凶，始求深也，意味着在追求深入或深层次的发展时，可能会遇到危险或不利的情况。这提示我们在探索未知或追求更深层次的目标时，需要谨慎行事，注意潜在的风险。"},
  {"id":"an_dk_480","sentenceId":"s_dk_480","level":"sentence","content":"【吉】九二爻辞表示悔恨消失，能够长久保持中庸之道。这说明在这一爻的位置上，行为得当，能够避免过失，保持长久的中正之道，因此是吉祥的。"},
  {"id":"an_dk_481","sentenceId":"s_dk_481","level":"sentence","content":"【道德】这句话出自《易经》中的小象辞，意为如果一个人不能坚持自己的道德原则，那么他就无法在社会中找到自己的位置，也不会被他人所接纳。这里强调了坚持道德的重要性。"},
  {"id":"an_dk_482","sentenceId":"s_dk_482","level":"sentence","content":"【困境】这句话的意思是“长时间不在适合自己的位置上，怎么能获得成功或收获呢？”这表示一个人如果长期处于不适合自己的环境或职位，很难有所成就或获得满意的结果。"},
  {"id":"an_dk_483","sentenceId":"s_dk_483","level":"sentence","content":"【婚姻】这段小象辞描述了妇人和夫子在婚姻中的行为准则。妇人贞吉，意味着妇人应保持贞洁，忠诚于丈夫，这样才会吉祥。从一而终，强调了妇人应一生忠于一个丈夫。夫子制义，意味着夫子应制定合理的道德规范，指导家庭成员的行为。从妇凶也，表示如果夫子盲目听从妇人的意见，可能会导致凶险的结果。这段小象辞反映了古代社会对婚姻中男女角色的期望。"},
  {"id":"an_dk_484","sentenceId":"s_dk_484","level":"sentence","content":"【卦象】此句出自《周易》中的卦辞，意为在“恒卦”中，上爻的阳刚之气过于强盛，导致无法实现大的功业。这表明在事物发展过程中，如果过于刚强而不懂得变通，可能会适得其反，难以达到预期的目标。"},
  {"id":"an_dk_485","sentenceId":"s_dk_485","level":"sentence","content":"【遁卦】遁卦象征退隐、避让。卦辞“亨，小利贞”意味着在退隐或避让的情况下，事情可以顺利进行，但只适合做小事，不宜进行大的行动或决策。在这一卦中，强调的是在不利的环境中，适时退避以保全自己，等待时机。"},
  {"id":"an_dk_486","sentenceId":"s_dk_486","level":"sentence","content":"【遁卦】遁卦象征隐退，卦辞说“遁亨”，意味着隐退是通达的。这是因为刚爻（代表阳刚、积极的力量）处于适当的位置，并且有相应的柔爻（代表阴柔、顺应的力量）相配合，能够随着时势的变化而行动。卦辞中的“小利贞”表示在隐退的过程中，小的正固是有利的，暗示着事物的发展会逐渐壮大。最后，“遯之时义大矣哉”强调了在适当的时候选择隐退具有深远的意义。"},
  {"id":"an_dk_487","sentenceId":"s_dk_487","level":"sentence","content":"【君子處世】此句出自《周易·遯卦》。遯卦象征隐退、避让。天下有山，象征着君子应当像山一样稳重、高洁，懂得适时退隐，远离小人。君子对待小人，虽然保持距离，但不表现出厌恶，而是以一种严肃、庄重的态度，保持内心的清明与高洁。这体现了君子在处理人际关系时的智慧与原则。"},
  {"id":"an_dk_488","sentenceId":"s_dk_488","level":"sentence","content":"【隱退】初六爻辞“遯尾，厉，勿用有攸往”意味着在隐退的过程中，处于不利的位置，如同落在队伍的最后，面临危险。此时不宜有所行动，应当保持低调，避免招致更大的风险。"},
  {"id":"an_dk_489","sentenceId":"s_dk_489","level":"sentence","content":"【固守】此爻辞意为用黄牛的皮革紧紧束缚住，没有人能够解开。象征着在困难或挑战面前，应当坚定立场，保持内心的稳定和坚持，不被外界所动摇。黄牛之革坚固耐用，比喻固守正道，坚持原则，不轻易改变自己的立场和信念。"},
  {"id":"an_dk_490","sentenceId":"s_dk_490","level":"sentence","content":"【凶险與調適】九三爻辞描述了一种处于困境中但仍需坚持的情况。\"系遯\"意味着在退隐或逃避的过程中被束缚，无法自由行动。\"有疾厉\"表示此时可能会遭遇疾病或危险，处境艰难。然而，\"畜臣妾吉\"则提示在这种情况下，如果能够妥善管理和照顾下属或家庭成员，将会带来吉祥的结果。整体而言，此爻辞强调在不利条件下，通过合理的人际关系管理和自我调适，可以转危为安。"},
  {"id":"an_dk_491","sentenceId":"s_dk_491","level":"sentence","content":"【吉凶】九四爻辞表示在退隐或避让的时候，君子能够保持良好的态度和行为，因此吉祥；而小人则可能因为私心或短视而不能做到这一点，所以不吉。这反映了在处理退让或避让的问题上，君子与小人的不同态度和结果。"},
  {"id":"an_dk_492","sentenceId":"s_dk_492","level":"sentence","content":"【吉兆】九五爻辞表示处于尊位的人能够以美好的方式隐退，坚守正道则吉祥。这象征着在适当的时候，以合适的方式退出或隐退，不仅不会带来损失，反而会得到好的结果。"},
  {"id":"an_dk_493","sentenceId":"s_dk_493","level":"sentence","content":"【吉兆】上九爻辞“肥遯，无不利”意味着在退隐或避让的过程中，能够获得丰厚的收获和利益，没有任何不利之处。这表明在适当的时机选择退隐，不仅不会带来损失，反而能够得到更好的结果。"},
  {"id":"an_dk_494","sentenceId":"s_dk_494","level":"sentence","content":"【凶险】此句意为，小象处于退避的末尾，面临危险，若不主动前往寻求解决之道，将会遭受灾祸。说明在面对困境时，不应消极逃避，而应积极应对，否则将自招祸患。"},
  {"id":"an_dk_495","sentenceId":"s_dk_495","level":"sentence","content":"【行為准則】此句意为“使用黄牛来执劳，是因为其性情固执而坚定”。在古代，黄牛因其勤劳、耐劳和固执的特性，常被用来象征坚定的意志和执着的精神。这里“执用黄牛”比喻人应该像黄牛一样，坚定自己的志向，持之以恒地去追求目标。"},
  {"id":"an_dk_496","sentenceId":"s_dk_496","level":"sentence","content":"【隱退】此卦象显示了隐退或避世的趋势，处于这种状态的人可能会感到身心疲惫，如同生病一般。在这种情况下，保持低调，管理好身边的人（如仆人或下属）是吉利的，但不适合进行重大的决策或行动。"},
  {"id":"an_dk_497","sentenceId":"s_dk_497","level":"sentence","content":"【君子與小人】此句意为君子能够适时隐退，而小人则不能。在《周易》中，“遯”卦象征隐退、避让。君子懂得在适当的时候退隐，以保持自身的清高和品德；而小人则往往不能做到这一点，容易陷入争斗和纷争之中。这句话反映了君子与小人在处世态度上的根本区别。"},
  {"id":"an_dk_498","sentenceId":"s_dk_498","level":"sentence","content":"【吉兆】此辞意为嘉美的隐退，正固吉祥，是因为心志端正。表明在适当的时候选择隐退，保持内心的正直和纯洁，是一种吉祥的行为。"},
  {"id":"an_dk_499","sentenceId":"s_dk_499","level":"sentence","content":"【隱退】此卦象表明，选择隐退或远离纷争是明智之举，这样做不会有任何不利。同时，内心应保持坚定，无需有任何疑虑。"},
  {"id":"an_dk_500","sentenceId":"s_dk_500","level":"sentence","content":"【陽刚壮盛】大壮卦象征着阳刚之气达到鼎盛，事物处于强大、壮健的状态。在此时，应当坚守正道，保持谦逊，不可因力量强大而骄傲自满或轻举妄动，否则容易招致灾祸。卦辞“利贞”意味着在大壮之时，利于坚守正道，保持中正，才能获得吉祥。"},
  {"id":"an_dk_501","sentenceId":"s_dk_501","level":"sentence","content":"【卦象解釋】大壮卦象征着强大和壮大。其内卦为震（雷），外卦为乾（天），震为动，乾为刚，刚而能动，所以象征着强大。大壮卦利于坚守正道；这里的大者指的是正道。当正道得以弘扬，天地间的自然法则和情感也就清晰可见了。"},
  {"id":"an_dk_502","sentenceId":"s_dk_502","level":"sentence","content":"【自然與行為規范】此大象辞描述了雷在天上的自然现象，象征着强大的力量和威严，对应卦象“大壮”，意味着事物处于壮盛、强大的状态。对于君子而言，应当以此为警示，遵循礼仪规范，不做不合礼法之事，保持自身的品德和行为的端正。"},
  {"id":"an_dk_503","sentenceId":"s_dk_503","level":"sentence","content":"【凶险】初九爻辞描述了行动过于草率，只注重表面的力量而忽视了内在的实质，这种情况下贸然行动会有凶险，但内心还是诚实可信的。提示人们在行动之前要深思熟虑，不可轻举妄动。"},
  {"id":"an_dk_504","sentenceId":"s_dk_504","level":"sentence","content":"【吉兆】九二爻辞“贞吉”意味着在坚守正道的情况下，将会获得吉祥的结果。此爻提示人们在面对选择时，应保持内心的正直与诚实，遵循正确的原则和道德规范，如此才能得到好的结局。"},
  {"id":"an_dk_505","sentenceId":"s_dk_505","level":"sentence","content":"【警示】此爻辞意在警示人们，小人可能会凭借自己的力量逞强，而君子则应避免使用蛮力，坚守正道。若固执己见，可能会像公羊触碰篱笆，角被缠住一样，陷入困境。因此，占得此爻者应当谨慎行事，避免鲁莽，以防不测。"},
  {"id":"an_dk_506","sentenceId":"s_dk_506","level":"sentence","content":"【吉兆】九四爻辞表示坚守正道则吉祥，悔恨将消失。藩篱被冲破而不再受束缚，力量强大如同加固了大车的轮轴。这象征着在困难中坚持正道，最终能够克服障碍，获得成功。"},
  {"id":"an_dk_507","sentenceId":"s_dk_507","level":"sentence","content":"【損失與無咎】在六五爻的位置上，象征着在交易或变动中失去了羊，但最终不会有悔恨。这表示虽然在过程中可能会遭受一些损失，但最终的结果并不会带来遗憾或咎责。这可能是因为损失是在不可避免的情况下发生的，或者是因为损失之后能够得到更好的补偿或结果。"},
  {"id":"an_dk_508","sentenceId":"s_dk_508","level":"sentence","content":"【困頓】上六爻辞描述了一只公羊触碰到了藩篱，既不能后退，也无法前进，处于进退两难的困境之中，无论做什么都不利于它。然而，在这种艰难的情况下，如果能够保持坚韧不拔的态度，最终会迎来吉祥的结果。这表明在面临困境时，应当保持坚定的意志，不轻言放弃，才能转危为安。"},
  {"id":"an_dk_509","sentenceId":"s_dk_509","level":"sentence","content":"【凶】此句意为脚趾强壮，但其信任或信用却因此而穷尽。比喻小有才力或小有所成便骄傲自满，最终导致信用丧失，处境艰难。这是一个不吉利的卦辞，提示人们不要因小成就而自满，应保持谦逊。"},
  {"id":"an_dk_510","sentenceId":"s_dk_510","level":"sentence","content":"【中正】九二爻辞中的“贞吉，以中也”意味着在保持中庸、正直的态度下，可以获得吉祥的结果。这里的“中”不仅指位置上的中间，更重要的是指行为和态度上的中庸之道，即不偏不倚，恰到好处。"},
  {"id":"an_dk_511","sentenceId":"s_dk_511","level":"sentence","content":"【人事】此句出自《周易》的象辞，意为小人会利用自己的力量去争强好胜，而君子则不会这样做。这里强调了小人与君子在行为上的区别，反映了对人事关系和道德品质的考量。"},
  {"id":"an_dk_512","sentenceId":"s_dk_512","level":"sentence","content":"【决策與行動】此句意指在面临决策时，即使环境或条件看似不利（藩决不羸），仍应积极向前（尚往也）。这表达了在困难面前不退缩，勇于进取的态度。"},
  {"id":"an_dk_513","sentenceId":"s_dk_513","level":"sentence","content":"【凶】此句出自《周易》中的卦辞，意为在“易”（即变化、交易）的过程中失去了羊，象征着在不适当的位置或时机上发生了损失或失误。这里的“位不当”指的是所处的位置或时机不合适，导致了不利的结果。整体来看，这是一个不吉利的卦象，预示着可能会有损失或不顺利的事情发生。"},
  {"id":"an_dk_514","sentenceId":"s_dk_514","level":"sentence","content":"【困境與轉变】这段小象辞描述了一种进退两难的困境，但同时也暗示了在艰难中坚持下去会有吉祥的结果，且困境不会长久。这表明在面对困难时，不应轻易放弃，而应坚韧不拔，最终会迎来转机。"},
  {"id":"an_dk_515","sentenceId":"s_dk_515","level":"sentence","content":"【晉升/發展】此卦辞出自《周易》中的晋卦，晋有前进、晋升之意。康侯，指健康、安泰的侯爵，象征着一位贤明的领导者。用锡马蕃庶，表示得到赏赐，马匹众多，象征着财富和资源的丰富。昼日三接，意味着一天之内多次受到接见，象征着受到重视和频繁的交流。整体来看，此卦辞预示着事业上的顺利发展，得到上级的赏识和支持，资源丰富，人际关系良好。"},
  {"id":"an_dk_516","sentenceId":"s_dk_516","level":"sentence","content":"【卦象與卦辭】此彖辞出自《周易》中的晋卦。晋卦象征着进步和晋升。卦象显示太阳从地平线上升起，象征光明和希望。此卦的下卦为坤（地），上卦为离（火、光明），表示光明从地上升起，象征着事物的发展和进步。坤卦的性质为顺从，离卦的性质为美丽和光明，因此晋卦的整体含义是柔顺地追求光明和进步。彖辞中的“康侯用锡马蕃庶，昼日三接”意指康侯因顺应天时、地利、人和而受到赏赐，象征着君主对贤臣的重视和信任，也表达了晋卦所蕴含的积极向上、光明磊落的意象。"},
  {"id":"an_dk_517","sentenceId":"s_dk_517","level":"sentence","content":"【象辭】此句出自《周易》晋卦的象辞，意为太阳从地平线上升起，象征着晋卦的光明与进步。君子应当效法这一自然现象，通过自身的努力和修养，使自己的德行如同日出一般光明磊落，昭示于人。"},
  {"id":"an_dk_518","sentenceId":"s_dk_518","level":"sentence","content":"【初爻】初六爻辞描述了在晋升的过程中遇到了挫折，但只要坚守正道，最终会吉祥。虽然目前还没有得到信任和支持，但保持宽裕的心态，不会有过失。这表明在面对困难和挑战时，保持正直和从容的态度是非常重要的。"},
  {"id":"an_dk_519","sentenceId":"s_dk_519","level":"sentence","content":"【吉凶】六二爻辞描述了一种进退两难的境地，但最终会得到吉祥的结果。爻辞中的“晋如，愁如”表示前进时遇到了困难和忧虑，但“贞吉”则意味着只要坚守正道，就能获得吉祥。而“受兹介福，于其王母”则表示会受到长辈或权威人物的庇护和祝福，这里的“王母”可以理解为尊贵的女性长辈，象征着一种来自上层或长辈的支持和帮助。整体来看，这一爻辞传达了在困难中保持正直和耐心，最终会得到好的结果的信息。"},
  {"id":"an_dk_520","sentenceId":"s_dk_520","level":"sentence","content":"【群體認同】此爻辞表示在六三的位置上，得到了众人的认同和支持，因此先前的悔恨或遗憾得以消除。这说明在处理事务时，如果能够获得大多数人的支持和理解，就能够克服困难，化解矛盾，达到和谐的局面。"},
  {"id":"an_dk_521","sentenceId":"s_dk_521","level":"sentence","content":"【凶险】九四爻辞描述了晋升如同硕大的老鼠，虽然有一定的地位和权力，但行为不端，贪婪成性，这样的晋升是危险的。占卜的结果显示，如果继续这样的行为，将会遭遇凶险。"},
  {"id":"an_dk_522","sentenceId":"s_dk_522","level":"sentence","content":"【吉兆】此爻辞表示处于六五位置的人，悔恨将会消失，不必过于忧虑得失，前行将会吉祥，一切都会顺利。这表明在当前的情境下，应当保持积极乐观的态度，不必过分担心结果，勇敢地向前迈进，将会获得好的结果。"},
  {"id":"an_dk_523","sentenceId":"s_dk_523","level":"sentence","content":"【上九】上九爻辞表示事物发展到了极点，如同角尖锐而突出，需要采取果断的行动，如征伐叛乱的小邑。虽然形势险峻，但只要行动果断，结果吉祥而无咎。然而，从长远来看，这种极端的状态并不理想，需要谨慎对待，避免过度使用武力或强硬手段，否则可能会带来不利的后果。"},
  {"id":"an_dk_524","sentenceId":"s_dk_524","level":"sentence","content":"【進展與挑戰】此辞意指在前进的过程中会遇到阻碍和困难，但只要坚持正道，独自前行，保持内心的宽裕和从容，便不会有过失。然而，目前尚未得到天命或时机未到，需要耐心等待。"},
  {"id":"an_dk_525","sentenceId":"s_dk_525","level":"sentence","content":"【吉祥】受到的福泽，是因为处于中正的位置或状态，意味着行为或决策符合正道，因此能够得到好的结果或祝福。"},
  {"id":"an_dk_526","sentenceId":"s_dk_526","level":"sentence","content":"【群體認同】这句话的意思是众人同意和支持，志向或行动能够向上发展。这表示在得到群体的认可和支持后，个人或集体的目标和行动能够顺利进行，取得积极的进展。"},
  {"id":"an_dk_527","sentenceId":"s_dk_527","level":"sentence","content":"【凶险】此句意指如若像大老鼠般贪婪不义，坚守正道也会遭遇危险，所处的位置并不恰当，暗示当前环境或处境不利，需谨慎行事。"},
  {"id":"an_dk_528","sentenceId":"s_dk_528","level":"sentence","content":"【吉】失去或得到都不必过于忧虑，前往会有喜庆之事。此辞意在宽慰人心，表明不必过分在意得失，未来会有好的结果。"},
  {"id":"an_dk_529","sentenceId":"s_dk_529","level":"sentence","content":"【决策與行動】此句意指在进行重大决策或行动（如征伐城邑）时，应当谨慎行事，因为此时的道路尚未完全明朗，可能存在未知的风险和挑战。"},
  {"id":"an_dk_530","sentenceId":"s_dk_530","level":"sentence","content":"【艱難時世】明夷卦象征着光明受到伤害，处于艰难困苦的环境中。卦辞“利艰贞”意味着在这样的时世中，应当坚守正道，保持内心的光明与坚定，只有通过艰难的考验，才能迎来转机。"},
  {"id":"an_dk_531","sentenceId":"s_dk_531","level":"sentence","content":"【明夷】光明陷入地中，象征着明夷卦。内心保持文明，外表柔顺，以此蒙受大难，文王就是这样做的。在艰难中利于坚守正道，隐藏自己的光明，面对内难而能端正自己的志向，箕子就是这样做的。"},
  {"id":"an_dk_532","sentenceId":"s_dk_532","level":"sentence","content":"【象辭】此句出自《周易》明夷卦的象辞，意为光明进入地中，象征着光明被遮蔽，处于不利的环境之中。君子在这样的环境中领导众人，应当以低调、内敛的方式行事，通过隐藏自己的锋芒来保护自己，最终达到明辨是非、化险为夷的目的。"},
  {"id":"an_dk_533","sentenceId":"s_dk_533","level":"sentence","content":"【隱忍前行】此爻辞描述了在遭遇困难和挫折时，君子应当像受伤的鸟儿一样，虽然翅膀下垂，但仍要努力飞翔。在艰难的环境中，君子可能会面临物质上的匮乏，甚至连续多日无法进食，但仍然要坚持前行。当君子前往某个地方时，可能会受到主人的责备或批评，但这正是考验其意志和品德的时刻。此爻强调在逆境中保持低调、隐忍和坚持，以待时机的到来。"},
  {"id":"an_dk_534","sentenceId":"s_dk_534","level":"sentence","content":"【困頓與救援】此爻表示处于困境中，但有力量和机会得到救援。具体来说，“明夷”意味着光明受到伤害或遮蔽，象征着遭遇困难或挫折。“夷于左股”比喻在困境中受到伤害，但不是致命的。“用拯马壮”意味着借助外力或自身的力量（如强壮的马）来摆脱困境，最终能够获得吉祥的结果。整体上，此爻提示在面对困难时，应积极寻求帮助和支持，以克服挑战。"},
  {"id":"an_dk_535","sentenceId":"s_dk_535","level":"sentence","content":"【凶险與機遇併存】此爻辞描述了在南方狩猎时遭遇了明夷（光明被遮蔽，象征着困难或逆境），但最终捕获了大首领，意味着在困境中取得了重要的胜利。然而，“不可疾贞”则告诫不可急于求成，需要保持谨慎，不可轻举妄动，以免因急躁而招致新的灾祸。整体来看，此爻既包含了危机，也预示着转机，但行动时需审时度势，不可鲁莽。"},
  {"id":"an_dk_536","sentenceId":"s_dk_536","level":"sentence","content":"【內省與轉变】此爻辞描述了一种深入内心的过程，通过“入于左腹”象征着深入个人的内在世界，探索隐藏的情感或思想。\"获明夷之心\"意味着在这个过程中，发现了某种被压抑或隐藏的智慧或真理，这种智慧可能是在逆境中获得的。\"出于门庭\"则表示经过内心的探索和转变后，重新以新的姿态面对外界，走出困境，恢复光明。整体上，这一爻强调了通过内省来实现个人成长和转变的重要性。"},
  {"id":"an_dk_537","sentenceId":"s_dk_537","level":"sentence","content":"【困頓中的智慧】此爻辞描述了箕子在遭遇困顿和逆境时，仍然保持明智和正直。箕子是古代的一位贤人，他在面对困难时，能够坚守正道，不改其志。这表明在逆境中保持清醒的头脑和坚定的意志是非常重要的。对于个人而言，这是一条关于在困境中保持智慧和正直的建议。"},
  {"id":"an_dk_538","sentenceId":"s_dk_538","level":"sentence","content":"【变化無常】此爻辞描述了一种从光明到黑暗、从高处跌落至低处的变化过程，象征着事物的发展并非一帆风顺，可能会经历由盛转衰的转变。告诫人们要对事物的发展保持清醒的认识，不可因一时的成功而得意忘形，同时也要有面对困难和挫折的心理准备。"},
  {"id":"an_dk_539","sentenceId":"s_dk_539","level":"sentence","content":"【道德修養】这句话出自《礼记·檀弓下》，意思是君子在行动上，坚持道义，不会为了个人利益而违背道德原则，即使在困顿中也不会做不义之事以求生存。这里强调了君子应当具备的道德操守和行为准则。"},
  {"id":"an_dk_540","sentenceId":"s_dk_540","level":"sentence","content":"【吉祥】六二爻的吉祥，是因为它顺应了正确的规则和原则。在《易经》中，六二爻通常代表柔顺中正的位置，能够顺应天道、遵循法则，因此能够获得吉祥的结果。"},
  {"id":"an_dk_541","sentenceId":"s_dk_541","level":"sentence","content":"【吉兆】此辞意指向南方出征或探索的志向将会获得重大收获和成功，象征着目标的实现和愿望的达成，是一个非常积极和有利的预兆。"},
  {"id":"an_dk_542","sentenceId":"s_dk_542","level":"sentence","content":"【身體部位】此句描述的是小象辞中的一种象征，意为通过进入左侧腹部，能够获得内心的意愿或满足。左侧腹部在古代占卜和象征体系中，可能与情感、直觉或内在愿望有关。"},
  {"id":"an_dk_543","sentenceId":"s_dk_543","level":"sentence","content":"【智慧與堅持】这句话出自《易经》中的卦辞，箕子之贞，指的是箕子保持其贞正的品德和智慧。\"明不可息\"意味着光明和智慧是不能被熄灭的，强调了智慧和正直的重要性，以及在任何情况下都应坚持自己的原则和信念。"},
  {"id":"an_dk_544","sentenceId":"s_dk_544","level":"sentence","content":"【变化】此辞描述了一种从高到低、从得至失的变化过程。初登于天，象征着事物的兴起或达到顶峰，其光辉照耀四方，意味着影响力广泛；后入于地，失则也，表示事物由盛转衰，失去了原有的规则或秩序，可能暗示着失败或挫折。整体来看，这段辞反映了事物发展过程中可能出现的起伏变化。"},
  {"id":"an_dk_545","sentenceId":"s_dk_545","level":"sentence","content":"【家庭與婚姻】此卦辞表示在家庭和婚姻中，女性的贞洁和品德尤为重要，强调女性在家庭中的作用和地位，以及保持良好家庭关系的重要性。同时，也暗示了在处理家庭事务时，应遵循正道，保持贞洁和忠诚。"},
  {"id":"an_dk_546","sentenceId":"s_dk_546","level":"sentence","content":"【家庭倫理】这段彖辞强调了家庭中男女各自应处的位置和角色，即女性在内主内，男性在外主外，这是天地间的大义。家庭中应有严格的规矩，父母是家庭的领导者。每个家庭成员都应履行好自己的角色和职责，如父亲要像父亲，儿子要像儿子，兄长要像兄长，弟弟要像弟弟，丈夫要像丈夫，妻子要像妻子，这样家庭才能和谐有序。家庭秩序的正直是社会稳定和国家安定的基础。"},
  {"id":"an_dk_547","sentenceId":"s_dk_547","level":"sentence","content":"【家庭與道德】此句出自《周易》的家人卦，意为风从火中生出，象征家庭内部的和谐与秩序。君子应当言行一致，说话要有根据，做事要有恒心，以此来维护家庭和社会的稳定与和谐。"},
  {"id":"an_dk_548","sentenceId":"s_dk_548","level":"sentence","content":"【家庭與婚姻】初九爻辞中的“闲有家，悔亡”意味着在家庭或婚姻中，通过适当的约束和管理，可以避免后悔。这里的“闲”可以理解为约束、管理，而“有家”则指拥有家庭或婚姻关系。爻辞提示人们在家庭生活中应当保持适度的约束和管理，以维护和谐的家庭关系，避免因疏忽或不当行为而产生的后悔。"},
  {"id":"an_dk_549","sentenceId":"s_dk_549","level":"sentence","content":"【中正柔順】六二爻处于下卦之中，象征柔顺中正的德行。爻辞中的“无攸遂”意味着不要有过度的追求或行动，保持平和的心态；“在中馈”则表示在家中主持内务，履行妇道，保持家庭的和谐与稳定；“贞吉”则强调坚守正道，最终会得到吉祥的结果。整体而言，此爻辞鼓励人们在日常生活中保持中庸之道，不要过分追求外在的事物，而是要注重内心的平和与家庭的和谐。"},
  {"id":"an_dk_550","sentenceId":"s_dk_550","level":"sentence","content":"【家庭與教化】九三爻辞描述了家庭内部的两种不同状态。一方面，家人之间相互约束，保持严肃的态度，虽然可能会有悔恨和严厉，但最终会带来吉祥的结果。另一方面，如果家庭成员之间过于放纵，缺乏约束，虽然表面上看起来和谐快乐，但最终会导致遗憾和不利的局面。这反映了家庭中需要有适当的规矩和教化，以维持良好的家庭秩序。"},
  {"id":"an_dk_551","sentenceId":"s_dk_551","level":"sentence","content":"【财富與吉祥】此爻辞表示在家庭或个人的财富积累上取得了显著的成就，达到了富裕的状态，同时伴随着吉祥的好兆头，预示着未来的运势将更加顺利。在实际应用中，可以理解为通过正当手段积累财富，不仅能够使自己受益，还能惠及家人，带来和谐与幸福。"},
  {"id":"an_dk_552","sentenceId":"s_dk_552","level":"sentence","content":"【吉祥】九五爻辞表示君王能够以德治家，家庭和睦，无需忧虑，前往会有吉祥。此爻象征着领导者的德行和家庭的和谐，预示着积极向上的发展趋势。"},
  {"id":"an_dk_553","sentenceId":"s_dk_553","level":"sentence","content":"【吉兆】上九爻辞表示诚信和威严并存，最终会带来吉祥的结果。这说明在处理事务时，保持诚信和树立威严是非常重要的，能够赢得他人的尊重和信任，从而达到成功和吉祥的结局。"},
  {"id":"an_dk_554","sentenceId":"s_dk_554","level":"sentence","content":"【家庭與志向】这句话表达的是一个人虽然目前处于闲适的状态，有家可归，但他的志向和初心并没有改变。这反映了个体在生活状态变化时，仍然保持着对未来的追求和目标。"},
  {"id":"an_dk_555","sentenceId":"s_dk_555","level":"sentence","content":"【吉祥】六二爻的吉祥，是因为它能够顺应并且谦逊地行动。在《易经》中，巽卦象征着顺从和谦逊，而六二爻处于下巽卦之中，能够很好地体现巽卦的特性，因此吉祥。"},
  {"id":"an_dk_556","sentenceId":"s_dk_556","level":"sentence","content":"【家庭】家庭内部应当保持一定的秩序和规矩。家人之间虽然可能会有争执和严厉的言语，但只要不失去彼此之间的关爱和支持，家庭的根基就不会动摇。相反，如果家庭成员之间过于放纵，缺乏必要的约束，尤其是妻子和孩子过于轻浮、嬉笑无度，那么家庭的纪律和规矩就会被破坏，导致家庭失去应有的和谐与稳定。"},
  {"id":"an_dk_557","sentenceId":"s_dk_557","level":"sentence","content":"【吉兆】此句小象辞表示处于富贵之家，一切顺利，大吉大利，象征着当前的处境非常有利，应当继续保持和珍惜。"},
  {"id":"an_dk_558","sentenceId":"s_dk_558","level":"sentence","content":"【家庭和諧】这句话出自《周易》的卦辞，意为君王以身作则，建立和睦的家庭，家人之间互相爱护、尊重，体现了家庭内部的和谐与团结。"},
  {"id":"an_dk_559","sentenceId":"s_dk_559","level":"sentence","content":"【內省】此句意指威严而吉祥的状态，是通过反躬自省、自我约束而达到的。强调了内在修养和自我反省的重要性。"},
  {"id":"an_dk_560","sentenceId":"s_dk_560","level":"sentence","content":"【决策】睽卦象征着事物之间的分离、分歧或矛盾。在面对小事时，如果能够妥善处理，就能够获得吉祥的结果。这提示我们在处理小问题时要细心谨慎，避免因小失大，同时也要注意沟通和协调，以减少分歧和矛盾。"},
  {"id":"an_dk_561","sentenceId":"s_dk_561","level":"sentence","content":"【卦象與哲理】这段彖辞出自《周易》中的睽卦。睽卦的卦象为火（离）上泽（兑）下，象征着火向上燃烧，泽水向下流淌，两者方向相反，象征着分离、分歧。然而，尽管方向不同，但两者之间仍存在相互吸引和依存的关系。卦辞中提到“二女同居，其志不同行”，比喻两个人虽然同处一室，但志向和行为却不同，强调了分歧和矛盾的存在。然而，卦辞进一步指出，这种分歧并非不可调和，而是可以通过沟通和理解达到和谐。例如，“说而丽乎明，柔进而上行，得中而应乎刚”，意味着通过柔和的方式和明智的态度，可以达到和谐的状态。最终，卦辞总结道：“睽之时用大矣哉”，强调在处理分歧和矛盾时，正确的方法和时机非常重要，能够带来积极的结果。"},
  {"id":"an_dk_562","sentenceId":"s_dk_562","level":"sentence","content":"【卦象】此句出自《周易》中的睽卦。睽卦的卦象是上为火（离），下为泽（兑）。火向上燃烧，泽向下润泽，二者方向相反，象征着事物之间的差异和矛盾。然而，尽管存在差异，君子应当在差异中寻求共同点，即“以同而异”，在不同的意见和立场中找到可以合作和沟通的基础，从而达到和谐。"},
  {"id":"an_dk_563","sentenceId":"s_dk_563","level":"sentence","content":"【吉凶未定】此爻辞表示初九爻位，悔恨可以消除，丢失的马不必去追赶，它会自己回来；遇到恶人也不会有灾祸。整体来看，虽然有小的损失或困扰，但最终不会有大的危害，事情会自然好转。但需要注意的是，这并不意味着可以完全放松警惕，仍需谨慎行事。"},
  {"id":"an_dk_564","sentenceId":"s_dk_564","level":"sentence","content":"【吉兆】九二爻辞表示在小巷中遇到了主人或贵人，这象征着在不经意间得到了重要的帮助或机遇，结果是吉祥的，没有灾祸。"},
  {"id":"an_dk_565","sentenceId":"s_dk_565","level":"sentence","content":"【困頓與轉变】六三爻辞描述了一种困顿的局面，但最终能够有所转变。爻辞中的“见舆曳，其牛掣”比喻行动受阻，如同车被拖住，牛也被牵制，无法前进。而“其人天且劓”则形容人处于极端的困境中，甚至遭受了极大的侮辱和伤害。然而，尽管开始时遭遇了重重困难，但最终还是能够克服，达到“无初有终”的局面，意味着虽然起初不顺利，但最终能够获得好的结果。这提示我们在面对困境时，不要轻易放弃，坚持下去，终将有所收获。"},
  {"id":"an_dk_566","sentenceId":"s_dk_566","level":"sentence","content":"【人际關系】九四爻辞描述了一个人处于孤独的状态，但遇到了一位德高望重的长者或朋友，通过真诚的交流和信任，化解了危机，避免了灾祸。这表明在遇到困难时，与他人建立良好的关系和信任是非常重要的。"},
  {"id":"an_dk_567","sentenceId":"s_dk_567","level":"sentence","content":"【吉凶悔吝】此爻辞表示悔恨消失，与同宗之人关系亲密如同咬合的肌肤，前往不会有咎害。意指在这一爻的位置上，与同宗或同类的人关系和睦，能够得到支持和帮助，前行不会有大的障碍。"},
  {"id":"an_dk_568","sentenceId":"s_dk_568","level":"sentence","content":"【爻辭】上九爻的爻辞描述了一种非常奇特的景象，即一个人孤独地处于睽违的状态中，突然看到一只猪身上沾满了泥，还有一车的鬼魂。起初，他紧张地拉满了弓准备射击，但随后又放松了弓弦。这并不是因为遇到了敌人，而是因为遇到了前来求婚的人。如果前往，遇到雨天则吉祥。这段爻辞通过一系列象征性的意象，表达了在面对未知和恐惧时，应当保持冷静和理性，不要轻易做出判断，而应当根据实际情况做出正确的选择。同时，雨天的出现象征着困境中的转机，暗示着在困难中也可能会有好的结果。"},
  {"id":"an_dk_569","sentenceId":"s_dk_569","level":"sentence","content":"【避凶】见到恶人，是为了避开灾祸。这句话表达了一种避凶趋吉的思想，即通过远离或警惕恶人，来避免可能的灾难或不利影响。"},
  {"id":"an_dk_570","sentenceId":"s_dk_570","level":"sentence","content":"【吉】在巷中遇到主人，但并未迷失方向，表示虽然遇到了一些小的波折或意外，但整体上仍然在正确的道路上，有贵人相助，能够顺利解决问题。"},
  {"id":"an_dk_571","sentenceId":"s_dk_571","level":"sentence","content":"【困頓與轉变】此辞描述了一种初始状态不佳，但最终能够有所转变的情况。\"见舆曳，位不当也\"意味着当前处境不利，如同车辆被拖拽，位置不正。\"无初有终，遇刚也\"则表示虽然开始时遇到困难，但最终会遇到刚强的力量或机遇，从而有所改观。整体来看，这段辞语提示在不利的环境中，通过坚持和努力，最终能够克服困难，实现转变。"},
  {"id":"an_dk_572","sentenceId":"s_dk_572","level":"sentence","content":"【誠信】交孚无咎，志行也，意味着在交往中保持诚信，没有欺骗和隐瞒，因此不会招致灾祸。这是出于内心真诚的愿望和行为，体现了诚信的价值。"},
  {"id":"an_dk_573","sentenceId":"s_dk_573","level":"sentence","content":"【吉兆】此句意为宗族中的长者或重要人物能够和睦相处，如同噬咬柔软的皮肤一般轻松和谐，前往会有吉祥和喜庆之事。"},
  {"id":"an_dk_574","sentenceId":"s_dk_574","level":"sentence","content":"【自然與環境】此句小象辞意为在遇到雨水时能够获得吉祥，所有的疑虑和困惑都会随之消散。这反映了自然界的雨水能够带来好运和解决困难的象征意义。"},
  {"id":"an_dk_575","sentenceId":"s_dk_575","level":"sentence","content":"【吉凶】蹇卦象征着艰难险阻，但卦辞中提到“利西南，不利东北”，意味着在西南方向行动有利，而在东北方向则不利。同时，“利见大人，贞吉”则表示此时适宜寻求有德行、有地位的人的帮助，坚守正道则会有吉祥的结果。整体来看，蹇卦虽然预示着当前处于困境之中，但只要采取正确的行动，仍然可以化险为夷，获得好的结果。"},
  {"id":"an_dk_576","sentenceId":"s_dk_576","level":"sentence","content":"【卦辭】蹇卦象征着困难和阻碍，前方充满了险阻。能够看到险阻而及时停止，这是明智的表现。蹇卦利于向西南方向行动，因为这样可以得到中正之道；不利于向东北方向行动，因为那里的道路已经到了尽头。利于见到有德行的君子，因为前往会有功绩。当处于蹇卦的时位时，坚守正道会带来吉祥，因为这样可以治理国家。蹇卦在特定时机下的运用意义重大。"},
  {"id":"an_dk_577","sentenceId":"s_dk_577","level":"sentence","content":"【自然與德行】此句出自《周易》蹇卦的象辞，意为山上有水，象征着行进中的困难和阻碍（蹇）。在这种情况下，君子应当反省自身，修养品德，以应对困境。这里的“山上有水”形象地描绘了自然界的景象，同时也隐喻了人生道路上的艰难险阻，而“君子以反身修德”则强调了在面对困难时，个人应当通过自我反省和道德修养来克服挑战。"},
  {"id":"an_dk_578","sentenceId":"s_dk_578","level":"sentence","content":"【出行】初六爻辞“往蹇，来誉”意味着出行时会遇到困难和阻碍，但返回时会受到赞誉和好评。这表明在行动之初可能会遭遇不利，但最终结果是积极的。建议在面对困难时保持耐心，不要轻易放弃，适时调整策略，最终会获得好的结果。"},
  {"id":"an_dk_579","sentenceId":"s_dk_579","level":"sentence","content":"【困境與忠誠】此爻辞描述了君王的臣子处于艰难的境地，但仍然忠心耿耿，不因个人的原因而改变其忠诚的态度。这表明在面对困难时，臣子依然能够坚守职责，表现出高尚的品德。"},
  {"id":"an_dk_580","sentenceId":"s_dk_580","level":"sentence","content":"【困難與退守】此爻辞表示在前进的道路上遇到了困难，应当暂时退回原地，避免强行推进导致更大的损失。\"往蹇\"指的是前进时遭遇阻碍，\"来反\"则意味着返回或退守，以待时机。这提示我们在面对困境时，有时需要采取保守策略，等待形势好转再行动。"},
  {"id":"an_dk_581","sentenceId":"s_dk_581","level":"sentence","content":"【困難與合作】六四爻辞“往蹇来连”意味着在前进的道路上会遇到困难（往蹇），但通过与他人合作或联合（来连），可以共同克服这些困难。这提示我们在面对挑战时，寻求合作和支持是非常重要的。"},
  {"id":"an_dk_582","sentenceId":"s_dk_582","level":"sentence","content":"【吉】九五爻辞“大蹇朋来”意味着在艰难困苦中，得到了朋友的帮助和支持。蹇卦象征着艰难险阻，而九五爻处于君位，表明在困境中能够得到广泛的支持和帮助，预示着困难将逐渐化解，事情会向好的方向发展。此爻辞为吉兆，提示在面对困难时，应积极寻求合作与支持，共同克服难关。"},
  {"id":"an_dk_583","sentenceId":"s_dk_583","level":"sentence","content":"【吉兆】上六爻辞表示，虽然前行的路上充满困难（往蹇），但若能返回并寻求帮助或指导（来硕），则会得到吉祥的结果。此时，适宜去见德高望重的人（利见大人），他们能够提供帮助和支持，使你渡过难关。这是一条预示着在困境中寻求智慧和帮助将带来好运的爻辞。"},
  {"id":"an_dk_584","sentenceId":"s_dk_584","level":"sentence","content":"【等待】此句意为前行会遇到困难，而归来则会受到赞誉，适宜等待时机。表明在当前情况下，不宜贸然行动，应耐心等待，待时机成熟再做决定。"},
  {"id":"an_dk_585","sentenceId":"s_dk_585","level":"sentence","content":"【忠臣】这句话出自《周易》蹇卦的象辞，意为王的臣子虽然处于艰难困苦之中，但仍然忠心耿耿、勤勉尽责，最终不会有过失或咎责。这体现了臣子对君主的忠诚和责任感。"},
  {"id":"an_dk_586","sentenceId":"s_dk_586","level":"sentence","content":"【內卦】此句小象辞“往蹇来反，内喜之也”意指在前进时遇到困难（蹇），但返回时内心感到喜悦。这反映了内卦（下卦）的性质或状态，表明在面对外部的艰难险阻时，内心能够回归到一种平和或愉悦的状态。"},
  {"id":"an_dk_587","sentenceId":"s_dk_587","level":"sentence","content":"【困境與合作】此句出自《易经》蹇卦的爻辞，意为在前进时遇到困难（往蹇），回来时需要与人连结合作（来连）。这表明在当前的位置或情况下，个人的力量是有限的，需要寻求他人的帮助和支持，共同面对困难。同时，“当位实也”意味着处于正确的位置，拥有实际的力量或资源，但仍然需要谨慎行事，与他人合作以克服障碍。"},
  {"id":"an_dk_588","sentenceId":"s_dk_588","level":"sentence","content":"【吉】此句小象辞意为在艰难困苦中，朋友前来相助，是因为能够秉持中庸之道，行事得当。表明在困境中能够得到他人的帮助，是因为自身行为符合中正的原则，故为吉。"},
  {"id":"an_dk_589","sentenceId":"s_dk_589","level":"sentence","content":"【吉】此辞意为前往会有困难，但归来则会有所收获，内心有着坚定的志向。适宜见到有德行的贵人，以获得支持和帮助。整体上是一个吉利的卦象，表明虽然会遇到一些阻碍，但最终能够得到好的结果。"},
  {"id":"an_dk_590","sentenceId":"s_dk_590","level":"sentence","content":"【解卦】解卦象征着解决困难和危机。卦辞中的“利西南”意味着在处理问题时，采取柔和、包容的态度更为有利。\"无所往，其来复吉\"表示如果当前没有明确的方向或目标，最好先退一步，回归初心，这样会有好的结果。\"有攸往，夙吉\"则意味着如果有明确的目标和方向，应尽早行动，这样也会得到吉祥的结果。总的来说，解卦强调了在面对困难时，适时的退让与积极的行动同样重要，关键在于根据实际情况灵活应对。"},
  {"id":"an_dk_591","sentenceId":"s_dk_591","level":"sentence","content":"【解卦】解卦象征着解脱和解决困难。卦象显示，面对险境时，通过积极行动可以摆脱危险，从而获得解脱。解卦利于向西南方向行动，因为这样可以获得众人的支持。如果能够回归正道，就会吉祥，因为这样符合中庸之道。如果有所行动且及时，就会吉祥，因为这样可以取得成功。天地之间的矛盾得以化解，就会产生雷雨，雷雨之后，百果草木都会破壳而出，展现出生命力。解卦所代表的时机和意义非常重大。"},
  {"id":"an_dk_592","sentenceId":"s_dk_592","level":"sentence","content":"【自然現象與人文响應】此辞描述了雷雨天气的自然现象，象征着一种释放和解脱的过程。君子从中得到启示，应当宽恕他人的过失和罪行，展现出宽容和仁慈的美德。"},
  {"id":"an_dk_593","sentenceId":"s_dk_593","level":"sentence","content":"【吉凶】初六爻辞“无咎”意味着在这一爻的位置上，行为没有过失，不会招致灾祸。这是对初六爻位置的一种积极评价，表明在这一阶段或状态下，只要保持谨慎和正直，就可以避免不利的情况发生。"},
  {"id":"an_dk_594","sentenceId":"s_dk_594","level":"sentence","content":"【吉祥】九二爻辞描述了在田猎中捕获了三只狐狸，并得到了黄色的箭矢，这象征着在行动中获得了意外的收获和吉祥的预兆。黄色在中国传统文化中代表着中正、尊贵和吉祥，箭矢则象征着目标明确、行动有力。整体上，这一爻辞预示着在坚持正道的前提下，将会获得成功和吉祥。"},
  {"id":"an_dk_595","sentenceId":"s_dk_595","level":"sentence","content":"【凶险】六三爻辞描述了一种不适当的行为，即“负且乘”，意味着背着东西却还乘车，象征着身份地位与行为不相称，容易招致小人的嫉妒和攻击，即“致寇至”。在这种情况下，即使坚持正道（贞），也会遭遇困难和不利（吝）。整体上，爻辞警示人们要量力而行，避免因行为不当而招致不必要的麻烦。"},
  {"id":"an_dk_596","sentenceId":"s_dk_596","level":"sentence","content":"【解卦】九四爻辞的意思是，解除脚大拇指的束缚，朋友到来时才能获得信任。这里“解而拇”象征着解除个人的束缚或障碍，使自己能够自由行动；“朋至斯孚”则表示当朋友到来时，因为自己已经解除了束缚，所以能够得到朋友的信任和支持。整体上，这一爻辞强调了自我解放和信任建立的重要性。"},
  {"id":"an_dk_597","sentenceId":"s_dk_597","level":"sentence","content":"【吉兆】六五爻辞表示君子能够得到解脱，这是吉祥的预兆；同时，君子对小人也持有诚信和宽容的态度。这说明在处理人际关系时，保持诚信和宽容是非常重要的，能够带来吉祥的结果。"},
  {"id":"an_dk_598","sentenceId":"s_dk_598","level":"sentence","content":"【吉兆】上六爻辞描述了一位公爵在高墙上射中了隼，象征着在高位者能够准确地解决问题或战胜困难，结果非常顺利，没有任何不利。这表明在面对挑战时，如果能够采取正确的策略和行动，就能取得成功。"},
  {"id":"an_dk_599","sentenceId":"s_dk_599","level":"sentence","content":"【柔刚相濟】此句出自《周易》中的象辞，意指在刚强与柔和之间找到平衡，行事合乎道义，自然不会有过失。在处理事务时，既要有坚定的原则，也要有灵活的态度，这样才能达到和谐的状态。"},
  {"id":"an_dk_600","sentenceId":"s_dk_600","level":"sentence","content":"【中正】九二爻辞中的“贞吉，得中道也”意味着在处理事务时，能够坚守正道，保持中庸，不偏不倚，因此能够获得吉祥的结果。这里的“中道”强调的是行为和决策的平衡与适中，避免走极端。"},
  {"id":"an_dk_601","sentenceId":"s_dk_601","level":"sentence","content":"【凶】此辞意为，背着东西乘车，这是很不体面的事情。由于自己的行为招致了战争，又能怪谁呢？这表示由于自身不当的行为导致了不好的结果，是凶险的预兆。"},
  {"id":"an_dk_602","sentenceId":"s_dk_602","level":"sentence","content":"【調整】此句意为解开束缚在大拇指上的绳索，但位置尚未恰当。比喻在解决问题或调整关系时，虽然采取了初步行动，但尚未达到理想的状态，需要进一步调整和改善。"},
  {"id":"an_dk_603","sentenceId":"s_dk_603","level":"sentence","content":"【人际關系】这句话意味着在君子展现出理解和宽容时，小人会因为感到自身的不足或不被接纳而选择退避。这反映了在和谐与理性的环境中，不良的行为或态度会自然地被边缘化。"},
  {"id":"an_dk_604","sentenceId":"s_dk_604","level":"sentence","content":"【解卦】此句出自《周易》解卦的象辞，意为在公共场合射中隼鸟，象征着解决问题或消除障碍的行为。这里的“公用射隼”比喻采取公开、正大的行动来解决问题，而“以解悖也”则表示这样做可以化解矛盾和悖乱。"},
  {"id":"an_dk_605","sentenceId":"s_dk_605","level":"sentence","content":"【吉卦】此卦辞表示在损卦的情境下，若能保持诚信（有孚），则会有大吉（元吉），不会招致灾祸（无咎），可以坚守正道（可贞），并且有利于前往他处（利有攸往）。至于如何运用，即使是简单的祭品（二簋）也足以表达敬意（可用享）。整体而言，这是一个积极向上的卦象，强调了诚信与简朴的重要性。"},
  {"id":"an_dk_606","sentenceId":"s_dk_606","level":"sentence","content":"【損卦】损卦象征着减少或牺牲，但这种减少是为了更大的利益。损卦的彖辞描述了损下益上的道理，即通过减少下面的部分来增加上面的部分，这种做法符合天道的运行规律。损而有孚，意味着在减少的过程中保持诚信，这样可以获得大吉，没有灾难，可以坚守正道，有利于前往。曷之用？二簋可用享；二簋应有时。这表示在适当的时机，即使是简单的祭品也能表达诚意。损刚益柔有时，损益盈虚，与时偕行，意味着刚强与柔弱之间的转换，盈满与空虚之间的变化，都需要顺应时势，与时代同步。"},
  {"id":"an_dk_607","sentenceId":"s_dk_607","level":"sentence","content":"【卦象】此句出自《周易》的损卦。损卦的卦象是山（艮）下有泽（兑），象征着减少、减损。君子观此卦象，应当以此为戒，抑制自己的愤怒，节制自己的欲望，以达到内心的平和与外在的和谐。"},
  {"id":"an_dk_608","sentenceId":"s_dk_608","level":"sentence","content":"【行動與調整】初九爻辞表示在事情已经发生或决定后，应迅速采取行动，不要犹豫，这样可以避免灾祸。同时，根据实际情况适当调整自己的行为或计划，以达到更好的效果。这里的“酌损之”意味着在行动过程中，要根据具体情境做出适当的减损或调整，以保持平衡。"},
  {"id":"an_dk_609","sentenceId":"s_dk_609","level":"sentence","content":"【吉凶】九二爻辞表示在这一爻的位置上，适宜保持正直和坚定，如果贸然行动则会有凶险。但是，如果能够不损害自身或他人的利益，而是通过增加或补充的方式来解决问题，则可以获得好的结果。整体来看，这一爻辞强调了在行动前要审时度势，保持谨慎，同时也要善于寻找解决问题的方法，以达到互利共赢的目的。"},
  {"id":"an_dk_610","sentenceId":"s_dk_610","level":"sentence","content":"【人际關系】此爻辞描述了人际关系中的变化与选择。当三个人一起行动时，可能会因为意见不合或利益冲突导致其中一人离开；而当一个人独自行动时，却可能遇到志同道合的朋友。这反映了在不同的社交环境中，人与人之间的关系会发生变化，同时也提示我们在处理人际关系时要谨慎选择伙伴，保持开放的心态。"},
  {"id":"an_dk_611","sentenceId":"s_dk_611","level":"sentence","content":"【損卦】六四爻辞的意思是，在损卦的情境下，如果能够减少自身的疾病或问题，那么很快就会有好的结果出现，这样做是没有咎害的。这里的“损其疾”指的是去除不好的因素，“使遄有喜”则是指因此而迅速带来好的变化或消息。整体上，这一爻辞鼓励人们积极面对问题，及时采取措施改善现状，从而获得好的结果。"},
  {"id":"an_dk_612","sentenceId":"s_dk_612","level":"sentence","content":"【吉兆】此爻辞表示在六五的位置上，可能会得到增益，这种增益是如此之大，以至于价值十朋的宝龟也无法违背其吉祥的预兆，意味着将会有非常大的好运或收获，是大吉之兆。"},
  {"id":"an_dk_613","sentenceId":"s_dk_613","level":"sentence","content":"【上九】在最高位的爻，表示不减损也不增加，没有灾难，占卜结果吉祥。如果有所行动，将会得到没有家室牵绊的臣子。这爻象征着在高位者应当保持中庸之道，不偏不倚，才能获得吉祥和忠诚的辅佐。"},
  {"id":"an_dk_614","sentenceId":"s_dk_614","level":"sentence","content":"【行動迅速】此句意为事情需要迅速前往处理，这样才符合双方的意愿和目标。表明在面对需要及时解决的问题时，应当迅速行动，以达到预期的效果。"},
  {"id":"an_dk_615","sentenceId":"s_dk_615","level":"sentence","content":"【吉兆】九二爻辞表示利于坚守正道，以中庸之道作为自己的志向和行为准则，这样能够获得吉祥的结果。"},
  {"id":"an_dk_616","sentenceId":"s_dk_616","level":"sentence","content":"【人际關系】这句小象辞表达的是在独自行走时，内心是明确和坚定的；但当有三个人一起时，就可能产生猜疑和不信任。这反映了在人际交往中，随着人数的增加，沟通和信任的难度也会相应增加。"},
  {"id":"an_dk_617","sentenceId":"s_dk_617","level":"sentence","content":"【健康】这句话的意思是，减少疾病，也是值得高兴的事情。这表明在健康方面有所改善或疾病有所减轻，是一个积极的、令人愉悦的变化。"},
  {"id":"an_dk_618","sentenceId":"s_dk_618","level":"sentence","content":"【吉祥】六五爻辞表示大吉大利，这是因为得到了上天的保佑。在《周易》中，六五爻通常处于君位，象征着领导者的地位。这里的“元吉”意味着最吉祥的状态，而“自上佑”则表明这种吉祥是由于得到了来自上天或更高力量的庇护和帮助。"},
  {"id":"an_dk_619","sentenceId":"s_dk_619","level":"sentence","content":"【吉】此句意为在不损害自身的情况下获得增益，能够实现大的志向和目标，象征着顺利和吉祥。"},
  {"id":"an_dk_620","sentenceId":"s_dk_620","level":"sentence","content":"【吉】此卦辞表示事情有利于向前发展，适宜进行大的行动或计划，如涉过大河，象征着克服困难，取得成功。益卦象征着增益、利益，意味着在行动中会得到帮助和支持，是一个吉祥的卦象。"},
  {"id":"an_dk_621","sentenceId":"s_dk_621","level":"sentence","content":"【益卦】益卦象征着增益和利益。卦辞中提到“损上益下”，意味着减少上层的利益而增加下层的利益，这样可以使民众得到无尽的喜悦。从上层向下层施益，这种做法光明正大，有利于行动，中正的行为会带来吉祥。卦辞还提到“利涉大川，木道乃行”，意味着在面对重大困难时，采取适当的策略和方法，可以顺利渡过难关。益卦的动态是“益动而巽”，即在增益的同时保持谦逊，这样可以不断进步，没有止境。最后，“天施地生，其益无方”，表示天地之间的增益是无边无际的，而增益之道在于顺应时势，与时代同行。"},
  {"id":"an_dk_622","sentenceId":"s_dk_622","level":"sentence","content":"【自然與品德】此大象辞出自《周易》益卦，以自然界的风雷相益为喻，说明君子应当效法自然，见到善行就积极学习，有了过失就立即改正，以此不断提升自身的品德修养。"},
  {"id":"an_dk_623","sentenceId":"s_dk_623","level":"sentence","content":"【吉兆】初九爻辞表示，在开始阶段，如果能够充分利用现有的资源和条件，进行大规模的行动或创作，将会获得非常吉祥的结果，不会有灾祸。这说明了在行动之初，积极主动、把握机会的重要性。"},
  {"id":"an_dk_624","sentenceId":"s_dk_624","level":"sentence","content":"【吉兆】六二爻辞表示，有人会给予帮助或增益，这种增益如同价值连城的十朋之龟一样珍贵，无法拒绝。如果能够长久地保持正直和坚定，就会得到吉祥的结果。此外，君王如果能够用这种增益来祭祀天帝，也会得到吉祥的回应。整体而言，这是一个非常积极和吉祥的爻辞，预示着在得到帮助和支持的情况下，通过保持正直和虔诚，可以达到成功和吉祥的境地。"},
  {"id":"an_dk_625","sentenceId":"s_dk_625","level":"sentence","content":"【吉凶】此爻辞表示在面临凶险之事时，通过增加或补充某种力量或资源，可以避免灾祸，不会有咎责。同时，爻辞中提到“有孚中行，告公用圭”，意味着在处理事情时，应当保持诚信，采取中庸之道，并且在必要时向权威人士报告，使用正式的礼仪（如圭，古代的一种玉制礼器）来表达诚意和尊重。这表明在面对困难时，诚信、中庸和尊重权威是解决问题的重要原则。"},
  {"id":"an_dk_626","sentenceId":"s_dk_626","level":"sentence","content":"【中正、遷徙、依附】六四爻辞描述了一种中正的行为，即在行动中保持中庸之道。爻辞中的“告公从”意味着向公众或权威报告并得到支持和跟随。而“利用为依迁国”则表示在这种情况下，适宜采取依附或迁徙的行动，可能是为了国家或集体的利益而进行迁移。整体来看，六四爻辞强调了在行动中保持中正、获得支持，并在必要时采取适当的迁徙或依附策略。"},
  {"id":"an_dk_627","sentenceId":"s_dk_627","level":"sentence","content":"【吉兆】九五爻辞表示内心充满诚信与仁惠，无需多问，大吉大利。同时，这种诚信与仁惠也得到了他人的认可与回报，体现了德行的相互感应。"},
  {"id":"an_dk_628","sentenceId":"s_dk_628","level":"sentence","content":"【凶险】上九爻辞表示在最高位的人没有得到任何帮助，反而可能遭受攻击，这是因为其内心缺乏恒心和坚定的意志，导致了凶险的局面。这说明在面对困难和挑战时，必须保持坚定的信念和恒心，否则容易陷入不利的境地。"},
  {"id":"an_dk_629","sentenceId":"s_dk_629","level":"sentence","content":"【吉兆】此辞表示大吉大利，没有灾祸。意味着在当前的情境下，不必过于担忧或承担过重的责任，可以保持轻松的心态，顺其自然。"},
  {"id":"an_dk_630","sentenceId":"s_dk_630","level":"sentence","content":"【外部影响】这句话意味着可能会有外部的助力或增益，这种益处并非来自自身内部，而是由外界因素带来的。"},
  {"id":"an_dk_631","sentenceId":"s_dk_631","level":"sentence","content":"【凶险】此句意为在有益的事情中也可能遭遇凶险，这是固有的现象。表明在任何有利的情况下，都可能存在潜在的风险和不利因素。"},
  {"id":"an_dk_632","sentenceId":"s_dk_632","level":"sentence","content":"【建議】这句话的意思是告诉公卿要跟随，以此来增强自己的志向。这里的“告公从”是指建议公卿应该跟随某个方向或决策，而“以益志也”则表示这样做可以增强个人的志向和决心。因此，整个句子可以理解为一种建议，旨在鼓励公卿通过跟随正确的方向来提升自己的志向。"},
  {"id":"an_dk_633","sentenceId":"s_dk_633","level":"sentence","content":"【吉】此辞表示心中充满诚信与仁惠，无需多问，自然会得到好的结果。他人以德惠待我，我亦因此而大展志向，成就一番事业。整体寓意吉祥，表明诚信与仁惠是成功的基石。"},
  {"id":"an_dk_634","sentenceId":"s_dk_634","level":"sentence","content":"【警示】此辞意为不要轻易给予帮助，因为这可能是一种偏颇的请求。同时，可能会遭受来自外部的攻击或打击。整体上，这是一种警示，提醒人们在面对请求时要谨慎，同时也要警惕外界可能带来的不利影响。"},
  {"id":"an_dk_635","sentenceId":"s_dk_635","level":"sentence","content":"【决策與行動】夬卦象征决断和行动。卦辞中的“扬于王庭，孚号，有厉”表示在王庭中公开宣布，诚信地发出警告，表明当前形势严峻。“告自邑，不利即戎”意味着从自己的领地发出警告，不宜立即采取军事行动。“利有攸往”则表示在这种情况下，适宜采取行动，但需要谨慎选择方向和方法。整体来看，夬卦强调在面对危机时，需要果断决策并采取行动，但同时要保持谨慎，避免鲁莽行事。"},
  {"id":"an_dk_636","sentenceId":"s_dk_636","level":"sentence","content":"【决策與行動】夬卦象征决断，强调刚强的力量能够克服柔弱的阻碍。夬卦由乾（健）和兑（悦）组成，表示在决断时既要有坚定的意志，也要保持和悦的态度。卦辞提到“扬于王庭”，意味着在公开场合表达决断，但同时也指出“柔乘五刚”，即柔弱的力量可能会暂时占据上风。然而，通过诚信的号召和对危险的警觉，最终能够克服危机，使局面更加光明。卦辞还告诫不要轻率地采取军事行动，因为这可能导致不利的结果。最后，卦辞指出，只有在刚强的力量逐渐增长并最终占据主导地位时，才会有利于采取行动。"},
  {"id":"an_dk_637","sentenceId":"s_dk_637","level":"sentence","content":"【天泽夬】此句出自《周易》中的夬卦。夬卦的象辞描述了泽水升腾至天的景象，象征着决断和清除障碍的力量。君子观此象，应当效仿天泽之德，广施恩惠，将福禄惠及下属，但同时要避免自居功德，以免招致忌妒和非议。"},
  {"id":"an_dk_638","sentenceId":"s_dk_638","level":"sentence","content":"【行動與决策】初九爻辞描述了一种急于行动但力量不足的情况。\"壮于前趾\"意味着行动的欲望强烈，但仅限于初步的尝试或准备阶段。\"往不胜为咎\"则告诫说，如果在这种力量不足的情况下贸然前进，将会遭遇失败并带来咎责。整体来看，爻辞强调了在行动之前应充分准备，避免因急于求成而失败。"},
  {"id":"an_dk_639","sentenceId":"s_dk_639","level":"sentence","content":"【警戒】九二爻辞的意思是在夜晚时分要保持警惕，可能会有敌人的侵扰，但不必过于忧虑。这表明在面对潜在的危险时，应当提高警觉，做好防范措施，但同时也要保持冷静，不要过度恐慌。"},
  {"id":"an_dk_640","sentenceId":"s_dk_640","level":"sentence","content":"【凶险與化解】九三爻辞描述了一种处于不利境地的情况，即“壮于頄，有凶”，意味着力量用在了错误的地方，可能会招致凶险。然而，对于君子而言，应当果断而坚定地行动，即使独自前行，遭遇困难（如遇雨被淋湿），心中虽有不满，但最终不会有灾祸。这表明在面对困境时，保持坚定的意志和正确的态度是化解危机的关键。"},
  {"id":"an_dk_641","sentenceId":"s_dk_641","level":"sentence","content":"【困頓與解脱】九四爻辞描述了一种处于困境中的状态，臀部失去了皮肤，行走时感到困难和迟缓。然而，通过牵羊（象征着依靠他人或借助外力）可以消除悔恨，但听到的建议却不被信任。整体上，爻辞表达了在困境中寻求帮助的重要性，同时也提醒了对他人建议保持审慎的态度。"},
  {"id":"an_dk_642","sentenceId":"s_dk_642","level":"sentence","content":"【吉】九五爻辞表示在处理事情时，能够果断而坚定，但同时保持中庸之道，这样行事不会招致灾祸。\"苋陆夬夬\"形容行动果决，\"中行无咎\"则强调在果决的同时保持中庸，避免过激，从而不会带来咎害。"},
  {"id":"an_dk_643","sentenceId":"s_dk_643","level":"sentence","content":"【凶险】上六爻辞表示在最终阶段，由于没有及时的警示或呼号，最终将遭遇凶险。这提示我们在事情发展的过程中，应当保持警惕，及时发现问题并采取措施，避免最终的灾难。"},
  {"id":"an_dk_644","sentenceId":"s_dk_644","level":"sentence","content":"【不利】此辞意指在没有胜算的情况下贸然前往，将会招致咎责或不利的后果。提示在行动前应审时度势，不可轻举妄动。"},
  {"id":"an_dk_645","sentenceId":"s_dk_645","level":"sentence","content":"【平安】此句意为在夜晚的危险中，能够得到中庸之道的指引，意味着在危难时刻能够保持冷静，遵循正道，最终能够化险为夷，获得平安。"},
  {"id":"an_dk_646","sentenceId":"s_dk_646","level":"sentence","content":"【决策與行動】此句出自《周易》夬卦的爻辞，意指君子在面对决断时，能够果断行事，最终不会招致灾祸。这里的“夬夬”形容君子在做决定时的坚定与果断，而“终无咎”则表示最终的结果是好的，没有过失或灾难。这反映了在面对重要决策时，应当有明确的目标和坚定的意志，同时也要注意方法和时机，以达到预期的目标。"},
  {"id":"an_dk_647","sentenceId":"s_dk_647","level":"sentence","content":"【困頓】此句描述了一种处境艰难、行动迟缓的状态（“其行次且”），表明所处的位置或环境并不适宜（“位不当也”）。同时，听闻事情却不能相信，暗示判断力和洞察力有所欠缺（“闻言不信，聪不明也”）。整体表达了在不利条件下，个人智慧和能力受到限制的情境。"},
  {"id":"an_dk_648","sentenceId":"s_dk_648","level":"sentence","content":"【中庸】此句意为在行为上保持中庸之道，可以避免灾祸，但若仅停留在中庸而没有进一步发扬光大，其德行和智慧则未能达到光辉灿烂的境界。这表明了中庸之道的重要性，同时也指出了仅仅满足于中庸的局限性。"},
  {"id":"an_dk_649","sentenceId":"s_dk_649","level":"sentence","content":"【凶兆】此辞表示一种不吉利的预兆，意味着事情的发展最终不会长久，可能会遭遇挫折或失败。\"无号之凶\"指的是没有明显的征兆，但内在却隐藏着凶险；\"终不可长\"则强调这种状态或趋势无法持续，暗示需要及时调整或改变现状以避免不利后果。"},
  {"id":"an_dk_650","sentenceId":"s_dk_650","level":"sentence","content":"【婚姻】姤卦象征着相遇，但在此卦辞中，强调的是“女壮，勿用取女”，意味着女性过于强势或刚烈，不适宜娶为妻室。这反映了古代对于婚姻中女性角色的期待和选择标准，即女性应温柔贤淑，过于刚强的女性可能会给家庭带来不利影响。在现代社会，这一观点可能需要结合时代背景和个人情况灵活理解。"},
  {"id":"an_dk_651","sentenceId":"s_dk_651","level":"sentence","content":"【卦辭】姤卦象征相遇，柔顺者与刚强者相遇。卦辞告诫不要娶这样的女子，因为不能与她长久相处。天地相遇，万物皆显其美。刚强者遇到中正之位，天下之事得以顺利进行。姤卦所代表的相遇之时的意义非常重大。"},
  {"id":"an_dk_652","sentenceId":"s_dk_652","level":"sentence","content":"【自然與政治】此句出自《周易》的姤卦。\"天下有风，姤\"描述了自然界中风的普遍存在，象征着变化和新的开始。\"后以施命诰四方\"则表示君主或领导者应当顺应这种变化，发布命令，指导四方，以应对新的形势。整体上，这句话反映了自然界的变化与人类社会政治活动之间的关系，强调了顺应自然、适时而动的重要性。"},
  {"id":"an_dk_653","sentenceId":"s_dk_653","level":"sentence","content":"【初爻】初六爻辞描述了一种需要谨慎行事的情境。\"系于金柅\"意味着要像用金属制动器固定住车轮一样，保持稳定和克制。\"贞吉\"表示在这种情况下，保持正直和坚定是吉祥的。\"有攸往，见凶\"则提示如果有所行动，可能会遇到凶险。\"羸豕孚踟躅\"比喻像瘦弱的猪一样犹豫不决，暗示在行动前应深思熟虑，避免轻率行事。整体而言，此爻强调了在不确定的环境中保持谨慎和坚定的重要性。"},
  {"id":"an_dk_654","sentenceId":"s_dk_654","level":"sentence","content":"【吉凶】九二爻辞表示，这一爻象征着拥有丰富的资源或机会（如鱼），不会带来灾祸。但同时提示，这种资源或机会并不适合与他人分享，可能是因为资源有限，或者分享会带来不必要的麻烦。因此，这一爻辞整体上是吉利的，但需要注意处理好个人与他人的关系，避免不必要的纷争。"},
  {"id":"an_dk_655","sentenceId":"s_dk_655","level":"sentence","content":"【困難與挑戰】九三爻辞描述了一种处于困境中的状态，如同臀部失去了皮肤，行走时感到艰难和疼痛。这象征着在前进的过程中遇到了较大的困难和挑战，但尽管如此，只要能够谨慎应对，就不会有大的过失或灾难。此爻提示我们在面对艰难险阻时，要保持冷静和坚韧，避免因急躁而犯下大错。"},
  {"id":"an_dk_656","sentenceId":"s_dk_656","level":"sentence","content":"【凶险】九四爻辞中的“包无鱼，起凶”意味着在寻求合作或解决问题的过程中，未能获得预期的成果或支持，反而可能引发不利的局面或遭遇挫折。此爻提示在行动前应谨慎评估形势，避免盲目行动导致不良后果。"},
  {"id":"an_dk_657","sentenceId":"s_dk_657","level":"sentence","content":"【吉祥】九五爻辞描述了一种吉祥的景象。以杞树的叶子包裹瓜果，象征着保护和孕育。\"含章\"意味着内在的美好品质或计划已经成熟，即将展现出来。\"有陨自天\"则比喻意外的喜事或好运从天而降，暗示着在九五这个尊贵的位置上，能够得到上天的眷顾，获得成功和荣誉。整体来看，这一爻辞表达了在适当的时机和条件下，通过自身的努力和积累，可以迎来意想不到的好运。"},
  {"id":"an_dk_658","sentenceId":"s_dk_658","level":"sentence","content":"【上九】姤其角，吝，无咎。此爻辞意为在姤卦中，上九爻处于卦之极，象征事物发展到极端，如同角之尖锐，难以持久。此爻辞表明在姤卦的情境下，虽然遇到了困难或阻碍（吝），但只要能够保持谨慎和谦逊，不强行追求极端，便不会有大的过失或灾难（无咎）。"},
  {"id":"an_dk_659","sentenceId":"s_dk_659","level":"sentence","content":"【柔順】此句小象辞描述的是以柔顺之道来牵引和影响他人。\"系于金柅\"比喻用柔和的方式与人相处，\"柔道牵也\"则直接表达了通过柔顺的方法来引导和影响他人的意思。在实际应用中，这可以理解为在处理人际关系或解决问题时，采取温和、耐心的态度，以达到更好的沟通效果。"},
  {"id":"an_dk_660","sentenceId":"s_dk_660","level":"sentence","content":"【象征】此句小象辞意在通过“包有鱼”这一象征性表达，说明事物的内涵或本质未能充分展现或传达给外界（“义不及宾”）。即事物的内在价值或意义没有被充分理解和接受。"},
  {"id":"an_dk_661","sentenceId":"s_dk_661","level":"sentence","content":"【行動】小象辞描述了行动时的犹豫不决和谨慎，但最终并未受到阻碍或牵制。这表明在行动过程中虽然有迟疑，但最终能够独立前行，不受外界因素的干扰。"},
  {"id":"an_dk_662","sentenceId":"s_dk_662","level":"sentence","content":"【凶】此辞意指没有鱼的凶险，象征远离民众或失去民众支持的危险。在古代，鱼常被用来比喻民众，因此“无鱼”意味着失去了民众的基础，可能会导致不利的局面。"},
  {"id":"an_dk_663","sentenceId":"s_dk_663","level":"sentence","content":"【中正與天命】九五爻辞中的“含章，中正也”表示处于尊位的君子内心怀有美好的德行，能够保持中庸正直的态度。而“有陨自天，志不舍命也”则意味着虽然遭遇了从天而降的灾难或打击，但君子仍然不放弃自己的使命和志向，坚持履行自己的职责。整体上，这段爻辞强调了在逆境中保持正直品德和坚定意志的重要性。"},
  {"id":"an_dk_664","sentenceId":"s_dk_664","level":"sentence","content":"【困頓】此句出自《周易》姤卦的上九爻辞，意为姤卦发展到极点，如同角被卡住，无法前进，处于穷途末路的困境，象征着事物发展到极端，失去了继续前进的可能性，处境艰难，行动受阻。"},
  {"id":"an_dk_665","sentenceId":"s_dk_665","level":"sentence","content":"【吉】萃卦象征聚集、会合。卦辞表示亨通，君王到宗庙祭祀，有利于见到德高望重的人，亨通，利于守正。使用大的牲畜祭祀吉祥，利于有所前往。整体上是一个吉利的卦象，表明在聚集、会合的场合中，应当保持正直、虔诚的态度，以获得吉祥的结果。"},
  {"id":"an_dk_666","sentenceId":"s_dk_666","level":"sentence","content":"【聚】此卦辞描述了“萃”卦的含义，即聚集、会合。它强调了顺从和愉悦的态度，以及刚毅中正的品质，这些都是促成聚集的原因。提到“王假有庙，致孝享也”，意味着通过聚集可以表达对祖先的尊敬和祭祀，体现了聚集的正面价值。接着，“利见大人亨，聚以正也”说明了聚集应当遵循正道，这样才能得到好的结果。使用大牲祭祀吉祥，表明了顺应天命的重要性。最后，“观其所聚，而天地万物之情可见矣”则表达了通过观察聚集的现象，可以理解天地万物的本质和情感。整体上，这段卦辞强调了聚集的积极意义，以及在聚集过程中应当遵循的原则。"},
  {"id":"an_dk_667","sentenceId":"s_dk_667","level":"sentence","content":"【卦象】此句出自《周易》中的萃卦。萃卦的卦象是泽（兑）上于地（坤），象征着聚集。君子观此卦象，应当修缮兵器，以防不测。这里的“除戎器”意为修整武器装备，“戒不虞”则是指警惕意外之事，做好防范准备。整体而言，这句话强调了在聚集之时，应当保持警惕，做好应对突发状况的准备。"},
  {"id":"an_dk_668","sentenceId":"s_dk_668","level":"sentence","content":"【初爻】初六爻辞描述了一种开始时充满信心但未能坚持到底的情况，导致混乱和聚集。如果能够像婴儿哭泣后被安抚一样，迅速恢复平静，不必过分忧虑，继续前行则不会有灾难。这表明在遇到困难时，保持镇定和积极的态度，及时调整自己，可以避免不利的局面。"},
  {"id":"an_dk_669","sentenceId":"s_dk_669","level":"sentence","content":"【吉兆】六二爻辞表示，通过引导可以获得吉祥，没有灾难，诚信可以使得祭祀活动更加有效。这说明在适当的时候，通过正确的引导和诚信的态度，可以达到好的结果。"},
  {"id":"an_dk_670","sentenceId":"s_dk_670","level":"sentence","content":"【不利】此爻辞表示聚集时有叹息之声，表明处境不利，没有好处。但若前往行动则不会有灾祸，只是会有小的遗憾。整体来看，此爻象征着在不利的环境中，虽有困难，但通过积极行动仍可避免更大的损失。"},
  {"id":"an_dk_671","sentenceId":"s_dk_671","level":"sentence","content":"【吉兆】九四爻辞表示处于高位但未至极点，能够保持谦逊和谨慎，因此能够获得大吉的结果，没有灾祸。这说明在处理事务时，保持低调和谨慎的态度，可以避免不必要的麻烦，达到良好的结果。"},
  {"id":"an_dk_672","sentenceId":"s_dk_672","level":"sentence","content":"【吉】九五爻辞表示在萃卦中处于尊贵的位置，没有灾难。虽然没有得到广泛的信任，但如果能够坚持正道，保持长久的正直，悔恨就会消失。这说明在高位者应当以诚信和正直来赢得他人的信任，这样才能避免灾祸。"},
  {"id":"an_dk_673","sentenceId":"s_dk_673","level":"sentence","content":"【忧患】上六爻辞描述了一个人在面临困境时表现出极度的忧虑和悲伤，但最终能够避免灾祸。\"赍咨涕洟\"形容人因忧愁而哭泣，\"无咎\"则表示虽然遭遇困难，但最终没有招致灾祸，可能是因为及时采取了正确的应对措施。这提示我们在面对问题时，虽然情绪上可能会感到非常沉重，但只要能够妥善处理，仍然可以化险为夷。"},
  {"id":"an_dk_674","sentenceId":"s_dk_674","level":"sentence","content":"【混亂】此句描述了一种混乱无序的状态，其中“乃乱乃萃”表示聚集在一起却显得杂乱无章，“其志乱也”则进一步说明了这种混乱不仅表现在外在的行为上，更体现在内在的意志和目标上，整体呈现出一种缺乏明确方向和秩序的情景。"},
  {"id":"an_dk_675","sentenceId":"s_dk_675","level":"sentence","content":"【吉兆】此辞表示事情的发展是吉祥的，没有灾难或错误。处于中间状态，尚未发生改变，但趋势是积极向上的。"},
  {"id":"an_dk_676","sentenceId":"s_dk_676","level":"sentence","content":"【吉兆】此句意为前往不会有灾祸，上卦为巽（风），象征着顺从和谦逊。在行动中保持谦逊和顺应的态度，可以避免灾祸，获得吉祥。"},
  {"id":"an_dk_677","sentenceId":"s_dk_677","level":"sentence","content":"【吉凶】此句小象辞表示事情的结果非常吉祥，没有灾难或过失，但同时也指出所处的位置并不恰当。这说明虽然结果是好的，但可能是因为某些外部因素或偶然性导致的，而不是因为所处的位置或自身的条件最适合。"},
  {"id":"an_dk_678","sentenceId":"s_dk_678","level":"sentence","content":"【人事】此句出自《周易》萃卦的象辞，意指萃卦中有人居于高位，但其志向尚未完全实现或彰显。这反映了在人事关系中，虽然某人已经获得了较高的地位，但其理想或目标还未完全达成，需要继续努力。"},
  {"id":"an_dk_679","sentenceId":"s_dk_679","level":"sentence","content":"【情感】这句话表达了深切的忧虑和悲伤，其中“赍咨涕洟”形容极度哀伤、泪流满面的样子，“未安上也”则表示对上位者或现状的不安和担忧。整体上，这句话反映了对当前处境的不满和对未来的忧虑。"},
  {"id":"an_dk_680","sentenceId":"s_dk_680","level":"sentence","content":"【吉兆】升卦象征着上升、发展和进步。卦辞中的“元亨”表示大为亨通，意味着事情进展顺利，有良好的开端和发展。\"用见大人\"意味着此时适宜与德高望重的人交往，可以获得支持和帮助。\"勿恤\"表示无需忧虑，一切都会顺利。\"南征吉\"则意味着向南行动或发展会有吉祥的结果，象征着在正确的方向上努力会有好的收获。整体来看，这是一个非常积极的卦辞，预示着上升和发展的良好机遇。"},
  {"id":"an_dk_681","sentenceId":"s_dk_681","level":"sentence","content":"【升卦】升卦的彖辞描述了一种柔顺而适时上升的状态，象征着事物在和谐与顺应中逐渐发展和提升。其中，“柔以时升”表示柔顺地顺应时势而上升；“巽而顺，刚中而应”表示谦逊顺从，内心刚毅且能相应而动，因此能够达到“大亨”的境界。接着，“用见大人，勿恤；有庆也”意味着在这种状态下，可以见到德高望重的人，不必忧虑，因为会有吉祥的事情发生。最后，“南征吉，志行也”表示向南行进是吉祥的，因为这符合内心的志向和行动。整体而言，升卦的彖辞强调了顺应时势、谦逊顺从、内心刚毅的重要性，以及在这种状态下能够获得吉祥和成功。"},
  {"id":"an_dk_682","sentenceId":"s_dk_682","level":"sentence","content":"【自然與人文】此大象辞描述了自然界中地与木的关系，即地能生木，象征着事物的生长和发展。同时，它也寓意着君子应当效法自然界的这种生长规律，顺应道德，通过不断积累小的善行，最终达到高尚的品德和伟大的成就。这里的“升”字，既指树木的生长，也象征着个人品德的提升。"},
  {"id":"an_dk_683","sentenceId":"s_dk_683","level":"sentence","content":"【吉兆】初六爻辞表示，如果事情能够得到允诺和支持，那么就会有上升和发展的趋势，这是非常吉祥的预兆。意味着在事情的开始阶段，如果能够获得他人的认可和支持，那么后续的发展将会非常顺利。"},
  {"id":"an_dk_684","sentenceId":"s_dk_684","level":"sentence","content":"【誠信與祭祀】九二爻辞强调了诚信的重要性，指出在进行祭祀时，真诚的态度比丰厚的祭品更为重要。只要心存诚信，即使祭品简单（如禴祭，即春祭，古代一种较为简朴的祭祀形式），也能得到神明的垂青，不会招致灾祸。这反映了在人际关系和与神明沟通时，真诚的态度是获得信任和福佑的关键。"},
  {"id":"an_dk_685","sentenceId":"s_dk_685","level":"sentence","content":"【進展】九三爻辞“升虚邑”意味着在上升的过程中，到达了一个空旷或虚无的地方。这可以理解为在事业或个人发展中，遇到了一个看似有希望但实际上缺乏实质内容或支持的阶段。此时，需要保持警惕，不要被表面现象所迷惑，应谨慎行事，寻找真正有价值的机会。"},
  {"id":"an_dk_686","sentenceId":"s_dk_686","level":"sentence","content":"【祭祀】六四爻辞描述了周王在岐山进行祭祀活动，得到了吉祥的结果，没有灾祸。这表明通过虔诚的祭祀，可以得到神灵的保佑和庇护，使国家和人民获得安宁和繁荣。"},
  {"id":"an_dk_687","sentenceId":"s_dk_687","level":"sentence","content":"【吉祥】六五爻辞表示坚守正道则吉祥，有逐步上升、晋升的含义。此爻象征着在事业或地位上的稳步提升，但需保持谦逊和正直，不可急功近利。"},
  {"id":"an_dk_688","sentenceId":"s_dk_688","level":"sentence","content":"【上六】爻辞“冥升，利于不息之贞”意味着事物发展到了极点，如同在昏暗中上升，但仍然有利于坚持不断的努力和正直的品德。这表明在困难或不利的环境中，持续的正直和不懈的努力是重要的。"},
  {"id":"an_dk_689","sentenceId":"s_dk_689","level":"sentence","content":"【吉兆】此辞表示事情发展顺利，有上升的趋势，非常吉利。同时，也意味着上层或高级别的意志与个人的志向相符合，预示着得到支持和认可。"},
  {"id":"an_dk_690","sentenceId":"s_dk_690","level":"sentence","content":"【吉兆】九二爻的诚信带来了吉祥和喜悦，意味着在坚持正道和诚信的基础上，会有好的结果和喜事发生。"},
  {"id":"an_dk_691","sentenceId":"s_dk_691","level":"sentence","content":"【吉兆】升虚邑，无所疑也，意味着上升到一个空虚的邑镇，没有任何疑虑。这表示在前进的过程中，虽然可能会遇到一些看似空虚或不实的情况，但整体趋势是积极向上的，无需担心或怀疑，可以顺利前行。"},
  {"id":"an_dk_692","sentenceId":"s_dk_692","level":"sentence","content":"【祭祀】这句话出自《周易》中的小象辞，描述了周王在岐山进行祭祀活动，以示对天地神明的尊敬和顺从。这里的“亨”指的是祭祀仪式，而“顺事”则表示这种行为是符合天意和礼法的。"},
  {"id":"an_dk_693","sentenceId":"s_dk_693","level":"sentence","content":"【吉兆】此辞表示占卜的结果是吉祥的，象征着事情会顺利发展，如同逐步升阶，最终能够实现大的志向和目标。"},
  {"id":"an_dk_694","sentenceId":"s_dk_694","level":"sentence","content":"【吉凶】此句小象辞“冥升在上，消不富也”出自《周易》升卦。其中，“冥升”指的是事物上升到极点，但已经进入了一个模糊不清、难以辨别的状态；“在上”表示位置或状态已经达到了顶点；“消不富也”意味着这种状态虽然达到了顶点，但并不意味着富有或吉祥，反而可能预示着衰落或消亡。整体来看，这句话表达了一种事物发展到极致后可能出现的负面结果，提示人们要警惕事物发展到顶点后的潜在风险。"},
  {"id":"an_dk_695","sentenceId":"s_dk_695","level":"sentence","content":"【困卦】困卦象征着困难和困境，但卦辞中提到“亨，贞，大人吉，无咎”，意味着在困境中仍然有亨通的可能，只要坚守正道，大人物或有德行的人能够获得吉祥，不会有过失。而“有言不信”则表示在这样的情况下，言语可能不会被信任，需要通过实际行动来证明自己。"},
  {"id":"an_dk_696","sentenceId":"s_dk_696","level":"sentence","content":"【困卦】困卦象征着困境或困难。其彖辞解释为：在困境中，刚强被掩盖。虽然处于险境但能保持愉悦，即使在困境中也不失其正道，最终能够亨通，这难道不是君子的行为吗？占卜得到大人（指有德行的人）吉利，是因为他能够坚守刚正中庸之道。言语不诚实，过分依赖口才反而会陷入困境。"},
  {"id":"an_dk_697","sentenceId":"s_dk_697","level":"sentence","content":"【困卦】此句出自《周易》困卦的象辞，意为水泽干涸，象征着困顿、艰难的处境。君子在这样的困境中，应当坚定信念，不惜牺牲生命以实现自己的志向。这里的“致命遂志”表达了在逆境中坚持理想、不屈不挠的精神。"},
  {"id":"an_dk_698","sentenceId":"s_dk_698","level":"sentence","content":"【困頓】初六爻辞描述了一种困顿的状态，象征着处于不利的环境之中，如同臀部被树根缠绕，无法自由行动，只能进入幽暗的山谷中，长时间无法见到光明。这表示在当前的处境中，可能会遇到阻碍和困难，需要耐心等待时机，不可轻举妄动。"},
  {"id":"an_dk_699","sentenceId":"s_dk_699","level":"sentence","content":"【困卦】九二爻辞描述了一种处于困境中的状态，但有希望得到解决。具体来说，“困于酒食”表示被物质生活所困，生活条件虽然不错，但精神上却感到束缚。“朱绂方来”意味着有贵人或好的机会即将到来，可以带来帮助。“利用享祀”表示在这种情况下，适宜进行祭祀或祈求，以求得神灵的保佑。“征凶，无咎”则提醒在行动时可能会遇到凶险，但只要谨慎行事，最终不会有大的过失。整体来看，九二爻辞强调在困境中保持积极态度，寻求外部帮助，并谨慎行事。"},
  {"id":"an_dk_700","sentenceId":"s_dk_700","level":"sentence","content":"【困厄】此爻辞描述了一种极为不利的处境，六三爻处于下卦的最高位，象征着在困境中挣扎。爻辞中的“困于石，据于蒺藜”比喻身处险恶环境，难以脱身；“入于其宫，不见其妻”则表示即使回到家中，也得不到安慰和支持，象征着内外交困，孤立无援，预示着凶险。"},
  {"id":"an_dk_701","sentenceId":"s_dk_701","level":"sentence","content":"【困頓】九四爻辞描述了一种缓慢前进、受到阻碍的状态。\"来徐徐\"表示行动迟缓，\"困于金车\"比喻受到物质或外在条件的限制，行动不自由。\"吝\"表示这种状态是不理想的，但\"有终\"则预示着最终能够克服困难，达到目标。整体上，爻辞反映了在困境中坚持努力，最终能够有所成就的过程。"},
  {"id":"an_dk_702","sentenceId":"s_dk_702","level":"sentence","content":"【困卦】九五爻辞描述了一种困境中的转变。\"劓刖\"指的是受到刑罚或遭遇挫折，\"困于赤绂\"意味着被束缚或限制，\"乃徐有说\"表示经过一段时间后逐渐有了转机，\"利用祭祀\"则意味着在这种情况下，通过祭祀或祈求神灵的帮助可以得到有利的结果。整体上，九五爻辞表达了在困境中通过耐心等待和寻求外部帮助，最终能够获得解脱和转机的含义。"},
  {"id":"an_dk_703","sentenceId":"s_dk_703","level":"sentence","content":"【困卦】上六爻辞描述了一种被束缚和处于危险境地的状态，如果有所行动则会后悔。但是，如果能够认识到自己的错误并进行改正，那么前进就会吉祥。这里的“困于葛藟，于臲卼”形象地表达了身处困境、危机四伏的情境；“曰动悔”则告诫在这样的情况下轻举妄动可能会带来更多的麻烦；而“有悔，征吉”则说明了通过反思和改正错误，最终能够摆脱困境，走向好的结果。"},
  {"id":"an_dk_704","sentenceId":"s_dk_704","level":"sentence","content":"【困境】此句描述了一种进入幽暗山谷的情境，象征着陷入了一种不明朗、难以见光的困境或挑战。在这种环境中，前行的道路不清晰，四周充满了未知和不确定性，需要谨慎应对。"},
  {"id":"an_dk_705","sentenceId":"s_dk_705","level":"sentence","content":"【吉凶未定】此辞意指在酒食之中虽然有所困顿，但其中却有喜庆之事。这表示在当前的困境中，可能会有意外的好事发生，因此吉凶未定，需要谨慎行事，同时保持乐观态度。"},
  {"id":"an_dk_706","sentenceId":"s_dk_706","level":"sentence","content":"【凶险】此辞意指处于危险的境地（据于蒺藜），且行事过于刚强（乘刚也），结果回到家中却不见妻子（入于其宫，不见其妻），象征着不吉利的情况发生，预示着可能会有不幸或损失。"},
  {"id":"an_dk_707","sentenceId":"s_dk_707","level":"sentence","content":"【謙遜】此句小象辞描述了一种谦逊的态度。\"来徐徐，志在下也\"意味着行动缓慢而稳重，心态谦卑，不急于求成。\"虽不当位，有与也\"则表示虽然所处的位置或角色并不理想，但仍然能够与他人合作，得到他人的支持和帮助。整体上，这段话强调了谦逊和合作的重要性，即使在不利的情况下也能获得成功。"},
  {"id":"an_dk_708","sentenceId":"s_dk_708","level":"sentence","content":"【吉凶未定】此辞描述了一种处于不利境地但有望逐渐好转的情况。\"劓刖\"指的是遭受了严重的刑罚或损失，象征着当前的困境和挫折。\"志未得也\"表示目标尚未实现，理想未能达成。然而，\"乃徐有说，以中直也\"意味着随着时间的推移，通过正直和坚持，情况会逐渐好转。\"利用祭祀，受福也\"则建议在这种情况下，通过虔诚的祭祀或积极的行动，可以得到神灵的保佑或好运。整体来看，这是一个吉凶未定的卦象，提示在困境中保持正直和耐心，最终会有所转机。"},
  {"id":"an_dk_709","sentenceId":"s_dk_709","level":"sentence","content":"【困境與轉变】此辞描述了一种被束缚的状态，即“困于葛藟”，象征着当前处境艰难，不适宜行动。然而，“动悔，有悔吉，行也”则意味着如果能够反思并调整自己的行为，就能摆脱困境，走向吉祥。整体来看，这段辞强调了在面对困难时，通过自我反省和积极行动来实现转变的重要性。"},
  {"id":"an_dk_710","sentenceId":"s_dk_710","level":"sentence","content":"【穩定與变革】此卦辞描述了井的特性，象征着稳定与不变。即使周围环境（邑）发生变化，井本身（核心资源或原则）依然保持不变，不会因此失去或获得什么。人们来来往往，井水依然清澈，象征着持续的供给和不变的资源。然而，当井水快要干涸时，如果未能及时采取措施（未繘井），反而使汲水的瓶子受损（羸其瓶），则会有凶险。这提示我们在面对变革时，应保持核心价值的稳定，同时也要注意适时调整，避免因疏忽而导致损失。"},
  {"id":"an_dk_711","sentenceId":"s_dk_711","level":"sentence","content":"【井卦】此彖辞出自《周易》中的井卦。井卦的卦象是巽（风）下坎（水）上，象征着从地下取水的井。\"巽乎水而上水\"表示风（巽）在水上吹动，使水上升，形象地描述了井的运作。\"井养而不穷也\"意味着井水不断，可以持续供给，象征着资源的不断供应和滋养。\"改邑不改井，乃以刚中也\"表示即使城邑变迁，但井的位置不变，因为井的位置是固定的，象征着稳定和中心。\"汔至亦未繘井，未有功也\"表示水已经接近井口，但还没有被汲出，意味着事情接近成功但尚未完成。\"羸其瓶，是以凶也\"表示瓶子破损，导致水漏出，象征着因疏忽或不当操作导致的失败和凶险。整体上，井卦强调了稳定、持续供给和谨慎操作的重要性。"},
  {"id":"an_dk_712","sentenceId":"s_dk_712","level":"sentence","content":"【自然與人文】此大象辞描述了自然景象与人文行为的结合。\"木上有水，井\"描绘了一种自然状态，即树木之上有水，形成了井的景象，象征着自然界中资源的丰富与和谐。\"君子以劳民劝相\"则转向了人文层面，意味着君子通过自身的辛勤劳动来鼓励和引导民众，体现了领导者以身作则、积极向上的精神。整体而言，这段大象辞强调了自然与人文的和谐共生，以及领导者在社会中的表率作用。"},
  {"id":"an_dk_713","sentenceId":"s_dk_713","level":"sentence","content":"【困頓】初六爻辞描述的是一种困顿、无用的状态。井底的泥水无法饮用，象征着资源或能力无法被有效利用；而旧井中没有禽鸟，进一步说明了这种状态的荒废与冷清，暗示着当前的环境或局势缺乏生机与活力，需要寻找新的出路或变革。"},
  {"id":"an_dk_714","sentenceId":"s_dk_714","level":"sentence","content":"【困頓】此爻辞描述了一种困顿的局面，井谷中的小鱼难以射中，而汲水的瓮又破漏，象征着资源匮乏、行动受阻，处于不利的境地。九二爻居中得正，但力量不足，难以有所作为，需要耐心等待时机，不可轻举妄动。"},
  {"id":"an_dk_715","sentenceId":"s_dk_715","level":"sentence","content":"【困境與希望】此爻辞描述了一种困境中的希望。井渫不食，意味着井已经清理干净，但还没有人来汲水饮用，这让人感到心痛。然而，这种状况是可以改变的，井水可以被使用，只要有人来汲水。如果君王英明，他将认识到这一点，并与民众共享井水带来的福祉。这象征着在困境中，只要有人能够认识到问题并采取行动，就能带来希望和福祉。"},
  {"id":"an_dk_716","sentenceId":"s_dk_716","level":"sentence","content":"【穩定】此爻表示在井的建设或修缮过程中，四爻的位置象征着工作进行到了一个相对稳定的阶段。\"井甃\"指的是用砖石等材料加固井壁，以防止坍塌，确保井水的清洁与安全。\"无咎\"意味着在这个过程中，只要按照正确的方法和步骤进行，就不会出现错误或灾难。这暗示了在处理事务时，如果能够遵循正确的原则和方法，即使处于较为复杂或困难的环境中，也能够保持稳定，避免出现问题。"},
  {"id":"an_dk_717","sentenceId":"s_dk_717","level":"sentence","content":"【吉】九五爻辞描述的是井水清澈甘甜，如同寒冷的泉水一样适合饮用。这象征着事物达到了纯净和完美的状态，也意味着领导者或事物处于一个非常良好的状态，能够为周围的人或环境提供滋养和帮助。此爻为吉，表明当前的形势非常有利，应当珍惜并充分利用这一时机。"},
  {"id":"an_dk_718","sentenceId":"s_dk_718","level":"sentence","content":"【吉兆】此爻辞表示在最高位的上六爻，象征着井水已经满溢，不需要再用幕布覆盖。这预示着诚信和正直能够带来最吉祥的结果。爻辞中的“有孚元吉”强调了诚信的重要性，意味着只要保持真诚和信任，就能获得最好的结果。"},
  {"id":"an_dk_719","sentenceId":"s_dk_719","level":"sentence","content":"【困頓】此句出自《周易》井卦的爻辞，描述了一种困顿的状态。井泥不食，意味着井中的水混浊不堪，无法饮用，象征着环境恶劣，资源无法利用；旧井无禽，意味着连鸟兽也不来饮水，象征着被时代所抛弃，无人问津。整体表达了处于不利环境中的困境和被忽视的状态。"},
  {"id":"an_dk_720","sentenceId":"s_dk_720","level":"sentence","content":"【困境】此句出自《周易》井卦的爻辞，意为在井底的谷物上射杀小鱼，比喻处于极其不利的环境或困境中，无法得到帮助和支持。"},
  {"id":"an_dk_721","sentenceId":"s_dk_721","level":"sentence","content":"【困境與希望】此句小象辞描述了一种困境中的状态，即井已经清理干净但仍然无人饮用，象征着个人或事物处于一种被忽视或未被充分利用的境地，令人感到同情（行恻也）。然而，通过寻求明智的领导或指导（求王明），可以得到帮助和支持，从而摆脱困境，获得好的结果（受福也）。这表达了在逆境中寻求光明和希望的主题。"},
  {"id":"an_dk_722","sentenceId":"s_dk_722","level":"sentence","content":"【吉兆】此辞意为修缮井壁不会有灾祸，象征着通过努力改善和修缮，可以避免不利的情况发生，达到吉祥的结果。"},
  {"id":"an_dk_723","sentenceId":"s_dk_723","level":"sentence","content":"【中正】此句小象辞描述的是在寒泉中取食的行为，象征着在艰难困苦的环境中仍能保持中庸正直的态度。中正，即行为符合中庸之道，不偏不倚，保持正直。"},
  {"id":"an_dk_724","sentenceId":"s_dk_724","level":"sentence","content":"【吉兆】此句小象辞表示最上等的吉祥，意味着事情已经达到了非常完美的状态，大功告成，一切顺利。"},
  {"id":"an_dk_725","sentenceId":"s_dk_725","level":"sentence","content":"【变革】革卦象征变革，巳日乃孚，意味着在适当的时候进行变革，才能获得信任。元亨利贞，表示变革应当遵循正道，才能达到亨通、有利、贞正的结果。悔亡，说明如果能够及时变革，就可以消除过去的悔恨。"},
  {"id":"an_dk_726","sentenceId":"s_dk_726","level":"sentence","content":"【变革】这段彖辞出自《周易》革卦，描述了变革的必要性和正当性。其中，“水火相息，二女同居，其志不相得”比喻事物之间的矛盾和冲突，需要通过变革来解决。“巳日乃孚；革而信也”表示变革需要在适当的时候进行，才能获得信任。“文明以说，大亨以正，革而当，其悔乃亡”强调了变革应当符合正道，才能带来亨通和消除悔恨。“天地革而四时成，汤武革命，顺乎天而应乎人，革之时义大矣哉”则进一步说明了变革的深远意义，指出变革是顺应天道、符合民意的必然选择。"},
  {"id":"an_dk_727","sentenceId":"s_dk_727","level":"sentence","content":"【自然與人文】此句出自《周易》革卦的象辞，意为沼泽中有火燃烧，象征变革。君子观此象，应当效法自然界的变革，通过制定历法来明确时令，以顺应自然规律，指导社会生活。这里体现了古人对自然现象的观察与人文社会活动的结合。"},
  {"id":"an_dk_728","sentenceId":"s_dk_728","level":"sentence","content":"【固守】此爻辞意在强调稳固和坚守。使用黄牛之革来加固，象征着用坚实可靠的方法来巩固基础或现状，防止变动或流失。黄牛之革坚固耐用，比喻采取切实有效的措施来维护稳定。初九处于事物的初始阶段，此时应当注重打下坚实的基础，避免急躁冒进。"},
  {"id":"an_dk_729","sentenceId":"s_dk_729","level":"sentence","content":"【变革】在适当的时候进行变革，出征会吉祥，没有灾祸。这表示在变革的过程中，选择正确的时机是非常重要的，如果时机成熟，进行变革就会顺利，不会有不好的后果。"},
  {"id":"an_dk_730","sentenceId":"s_dk_730","level":"sentence","content":"【警示】九三爻辞表示，如果贸然行动会有凶险，需要坚守正道以应对艰难险阻。同时，变革的言论需要得到三次认同，表明变革需要广泛的支持和共识，才能取得成功。此外，“有孚”意味着在变革过程中需要保持诚信，以获得他人的信任和支持。"},
  {"id":"an_dk_731","sentenceId":"s_dk_731","level":"sentence","content":"【变化與信任】九四爻辞表示在这一阶段，之前的悔恨可以消除，通过建立信任并顺应变化，可以带来吉祥的结果。这说明在面临困境时，通过调整态度和行为，增强对他人的信任，可以改变命运，获得好的结果。"},
  {"id":"an_dk_732","sentenceId":"s_dk_732","level":"sentence","content":"【吉】九五爻辞表示，处于尊位的大人如虎般威猛变化，即使不占卜也能够获得信任。这象征着领导者或决策者在关键时刻能够凭借自身的威望和能力，做出正确的决策，得到众人的支持和信任。"},
  {"id":"an_dk_733","sentenceId":"s_dk_733","level":"sentence","content":"【变革】上六爻辞描述了君子如同豹子般迅速而彻底地改变，而小人也改变了自己的面貌。在这种变革的环境中，如果贸然行动会有凶险，但若能安守本分，保持正直，则会吉祥。这说明在变革时期，应当审时度势，谨慎行事，不可轻举妄动。"},
  {"id":"an_dk_734","sentenceId":"s_dk_734","level":"sentence","content":"【謹慎】此句意为应当像用黄牛一样稳固和谨慎，不可轻举妄动，意味着在行动或决策时需要保持稳重和谨慎，不可贸然行事。"},
  {"id":"an_dk_735","sentenceId":"s_dk_735","level":"sentence","content":"【变革】在巳日进行变革，行动会有好的结果。这里的“巳日”通常指代一个适宜变革的时间点，而“革之”则意味着进行变革或改革。整体上，这句话预示着在合适的时机进行变革，将会带来积极的结果和嘉奖。"},
  {"id":"an_dk_736","sentenceId":"s_dk_736","level":"sentence","content":"【变革】此句出自《易经》革卦的爻辞，意为在变革之时，言论需要经过三次审慎考虑才能确定，表明在变革过程中需要谨慎行事，深思熟虑，不可轻率。\"又何之矣\"则表示在经过深思熟虑后，变革的方向和目标已经明确，无需再犹豫不决。整体上，这句话强调了变革过程中审慎决策的重要性。"},
  {"id":"an_dk_737","sentenceId":"s_dk_737","level":"sentence","content":"【吉兆】此辞表示通过改变命运而获得吉祥，是因为坚信并遵循自己的志向和目标。这意味着在面对困难和挑战时，保持坚定的信念和明确的方向，能够带来积极的结果和好运。"},
  {"id":"an_dk_738","sentenceId":"s_dk_738","level":"sentence","content":"【变化與成長】此句出自《易经》中的象辞，意指大人（指有德行、有地位的人）如同老虎改变其斑纹一样，展现出鲜明的文采和德行。这里的“虎变”比喻人的内在品质和外在表现发生了显著的变化，这种变化是积极的、向上的，象征着个人的成长和提升。"},
  {"id":"an_dk_739","sentenceId":"s_dk_739","level":"sentence","content":"【变革】君子如同豹子换毛，其文采更加灿烂。小人改变面貌，顺应君子的领导。此句意在说明，无论是君子还是小人，在变革之时，都会展现出新的面貌，但君子的变革是内在品质的提升，而小人的变革则更多是外在的顺从。"},
  {"id":"an_dk_740","sentenceId":"s_dk_740","level":"sentence","content":"【吉兆】鼎卦象征着变革与更新，\"元吉，亨\"表示此卦预示着大吉大利，亨通顺利。在进行重大变革或创新时，能够得到良好的结果，事物的发展将呈现出积极向上的态势。"},
  {"id":"an_dk_741","sentenceId":"s_dk_741","level":"sentence","content":"【卦象與象征】这段彖辞描述了鼎卦的象征意义及其内在的动态关系。鼎作为古代烹饪器具，象征着变革与更新。通过木（巽）与火的结合，鼎可以烹煮食物，象征着圣人通过祭祀来与上帝沟通，并通过丰盛的宴席来供养圣贤。巽卦的柔顺和灵动，使耳目更加敏锐，柔顺的力量逐渐上升，最终达到中位并与刚健的力量相呼应，因此能够实现大亨通。"},
  {"id":"an_dk_742","sentenceId":"s_dk_742","level":"sentence","content":"【卦象】此句出自《周易》中的鼎卦。鼎卦的卦象是下巽上离，巽为木，离为火，故曰“木上有火，鼎”。鼎象征着烹饪的器具，也象征着国家的政权和秩序。君子观此卦象，应当效法鼎的稳固与正直，端正自己的位置，坚定自己的使命，以正直的态度和坚定的意志来治理国家或管理事务，使一切井然有序，达到和谐稳定的状态。"},
  {"id":"an_dk_743","sentenceId":"s_dk_743","level":"sentence","content":"【变化與調整】初六爻辞描述了鼎的脚被颠倒，象征着事物的初始阶段可能会出现一些不稳定的状况。然而，这种变化有利于排除不好的因素，正如鼎脚颠倒可以倒出不好的东西一样。爻辞中提到“得妾以其子，无咎”，意味着通过这种变化，可能会获得新的助力或支持，最终不会带来灾祸。整体上，这一爻强调了在变化中寻找机会，调整方向以达到更好的结果。"},
  {"id":"an_dk_744","sentenceId":"s_dk_744","level":"sentence","content":"【吉兆】九二爻辞描述了一种吉祥的情境。鼎有实，意味着容器中装满了食物，象征着丰盛和富足。我仇有疾，不我能即，表示敌人或对手处于不利状态，无法对我构成威胁。整体来看，这一爻辞预示着在当前的情境下，自己处于有利地位，能够获得成功和吉祥。"},
  {"id":"an_dk_745","sentenceId":"s_dk_745","level":"sentence","content":"【变革與調整】九三爻辞描述了鼎的耳部发生了变化，导致行动受阻，珍贵的食物也无法享用。然而，正当此时，天降甘霖，缓解了困境，最终带来了吉祥的结果。这表明在变革过程中，虽然会遇到一些阻碍和困难，但只要能够适时调整，最终会迎来好的结果。"},
  {"id":"an_dk_746","sentenceId":"s_dk_746","level":"sentence","content":"【凶险】九四爻辞描述了一种不吉利的情况，鼎的脚折断了，导致公家的美食倾覆，形象十分狼狈，预示着事情的发展出现了严重的失误，结果非常糟糕。这表明在处理事务时，如果基础不稳固或者决策失误，将会导致严重的后果。"},
  {"id":"an_dk_747","sentenceId":"s_dk_747","level":"sentence","content":"【吉祥】六五爻辞描述了鼎的黄色耳朵和金色的铉，象征着尊贵、中正和吉祥。黄色为中色，代表中庸之道；金铉则象征坚固和珍贵。此爻处于鼎卦的尊位，意味着处于领导或重要位置的人应当秉持中正、公正的原则，这样才会有利于坚守正道，获得吉祥的结果。"},
  {"id":"an_dk_748","sentenceId":"s_dk_748","level":"sentence","content":"【吉祥】上九爻辞描述了鼎的最上部分装饰着珍贵的玉铉，象征着极高的地位和荣誉，也意味着达到了鼎盛时期。此爻辞预示着大吉大利，没有任何不利的因素，一切事情都会顺利进行。"},
  {"id":"an_dk_749","sentenceId":"s_dk_749","level":"sentence","content":"【吉凶】此辞意为鼎翻转而脚朝上，但并未违背常理。有利于排除不好的事物，以顺从尊贵之人。整体来看，这是一个较为积极的卦象，提示在某些看似不利的情况下，实际上并没有偏离正道，反而有机会摆脱困境，顺应上级或更有权势的人。"},
  {"id":"an_dk_750","sentenceId":"s_dk_750","level":"sentence","content":"【謹慎行事】此辞意为鼎中已盛满食物，但需谨慎选择去向。我的伴侣或对手虽然有缺点或疾病，但最终不会带来大的过失或怨恨。这提示我们在行动时要小心谨慎，即使面对有缺陷的人或事，只要处理得当，也能避免不良后果。"},
  {"id":"an_dk_751","sentenceId":"s_dk_751","level":"sentence","content":"【变卦】此句出自《周易》鼎卦的爻辞，意为鼎的耳朵被皮革所缠绕，失去了它原有的功能和意义。在变卦中，这表示事物的某些部分或功能发生了变化，导致其原有的作用和价值丧失。"},
  {"id":"an_dk_752","sentenceId":"s_dk_752","level":"sentence","content":"【凶】此辞意为倾覆了公家的饮食，如何能够取信于人？表示行为不当，导致严重的后果，难以获得他人的信任，故为凶。"},
  {"id":"an_dk_753","sentenceId":"s_dk_753","level":"sentence","content":"【卦象】此句出自《周易》中的鼎卦。鼎黄耳，指的是鼎的黄色耳朵，象征着中正、温和与和谐。中以为实也，意味着鼎的内部充实，象征着内心充实、诚信和中庸之道。整体而言，这句话表达了内在充实与外在和谐的统一。"},
  {"id":"an_dk_754","sentenceId":"s_dk_754","level":"sentence","content":"【卦象】此句出自《周易》中的卦象描述。\"玉铉在上\"指的是卦象中上爻的爻辞，\"玉铉\"象征着珍贵和高洁，\"在上\"表示处于卦的最上方，意味着最高的位置或最终的状态。\"刚柔节也\"则是对整个卦象的总结，\"刚柔\"指阴阳、刚柔的相互作用，\"节\"意味着节制、调节，整个句子表达了在最高位置上，需要通过调节刚柔来达到和谐与平衡的状态。"},
  {"id":"an_dk_755","sentenceId":"s_dk_755","level":"sentence","content":"【震卦】震卦象征雷，其卦辞表示事物在震动中亨通。\"震来虩虩\"描述了震动来临时的恐惧感，\"笑言哑哑\"则表示震动过后恢复平静，人们重新欢笑。\"震惊百里\"形容震动的范围和力量之大，\"不丧匕鬯\"意味着在巨大的震动中仍能保持镇定，不失礼仪，象征着在危机中保持冷静和坚定。"},
  {"id":"an_dk_756","sentenceId":"s_dk_756","level":"sentence","content":"【震卦】震卦象征震动、惊雷。卦辞说“震，亨”，意味着震动可以带来亨通。接着“震来虩虩，恐致福也”，表示当震动来临时，虽然会使人感到恐惧，但这种恐惧可以促使人们谨慎行事，从而带来福气。“笑言哑哑，后有则也”，意味着在经历震动之后，人们会变得更为谨慎和有规则，从而能够笑言自若。“震惊百里，惊远而惧迩也”，表示震动的影响不仅及于远处，也能使近处的人感到恐惧。“出可以守宗庙社稷，以为祭主也”，意味着在震动之后，能够出面主持宗庙社稷的祭祀，表明其地位和责任的重大。"},
  {"id":"an_dk_757","sentenceId":"s_dk_757","level":"sentence","content":"【自然現象與人生態度】虩雷，即震雷，象征着自然界中的强烈震动和震撼。君子在面对这样的自然现象时，应当心存敬畏，以此为契机，反思自身行为，加强个人品德修养，提升自我。这体现了古人对于自然现象的敬畏之心，以及将自然现象与个人修养相结合的智慧。"},
  {"id":"an_dk_758","sentenceId":"s_dk_758","level":"sentence","content":"【吉兆】初九爻辞描述了一种从惊恐不安到最终平安喜乐的变化过程。起初，由于突如其来的震动或变故，人们感到害怕和紧张（“震来虩虩”），但随着时间的推移，情况逐渐好转，最终大家能够安心地笑谈（“后笑言哑哑”），预示着事情的结果是吉祥的。这表明在面对突如其来的困难或挑战时，保持镇定并积极应对，最终能够化险为夷，迎来好的结局。"},
  {"id":"an_dk_759","sentenceId":"s_dk_759","level":"sentence","content":"【凶险與轉機】六二爻辞描述了一种遭遇重大危险和损失的情境，但最终能够化险为夷。具体来说，“震来厉”表示突然遭遇了严重的威胁或灾难；“亿丧贝”意味着损失惨重，可能失去了大量的财富或资源；“跻于九陵”则比喻在困境中被迫退守到极其不利的位置；然而，“勿逐，七日得”则预示着不要急于追回损失，经过一段时间（七日）后，损失会自然恢复或重新获得。整体来看，这一爻辞传达了在面临巨大困难时，保持冷静、耐心等待转机的重要性。"},
  {"id":"an_dk_760","sentenceId":"s_dk_760","level":"sentence","content":"【变動】六三爻辞描述了一种在震动中感到不安的状态，但若能顺应震动而行动，则可以避免灾祸。这表明在面对变化和挑战时，保持灵活和适应性是重要的。"},
  {"id":"an_dk_761","sentenceId":"s_dk_761","level":"sentence","content":"【困頓】九四爻辞“震遂泥”意味着在震动或行动中陷入了困境，如同陷入泥潭一般难以自拔。这表示在当前的情境下，虽然有行动的意愿和力量，但可能会遇到阻碍或困难，需要谨慎行事，避免盲目冲动。"},
  {"id":"an_dk_762","sentenceId":"s_dk_762","level":"sentence","content":"【震動與危機】六五爻辞描述了一种在动荡和危机中保持镇定和谨慎的态度。\"震往来厉\"表示在震动和危机中，无论是前进还是后退，都充满了危险。\"亿无丧\"意味着在这种情况下，应当保持内心的坚定，不失去信心和希望。\"有事\"则暗示在这种危机中，应当有所作为，积极应对，而不是消极等待。整体而言，六五爻辞强调了在动荡不安的环境中保持冷静、坚定，并采取适当行动的重要性。"},
  {"id":"an_dk_763","sentenceId":"s_dk_763","level":"sentence","content":"【凶险與警示】上六爻辞描述了一种内心极度不安和恐惧的状态，行动时显得犹豫不决，目光闪烁，如果在这种状态下贸然行动，将会遭遇凶险。然而，如果这种震动和不安不是发生在自己身上，而是发生在身边的人身上，那么就不会有灾祸。同时，爻辞还提到了婚姻关系中可能会出现言语上的争执。整体来看，这一爻强调了在面对外界变化时，保持内心的平静和理智的重要性，以及在人际关系中沟通的重要性。"},
  {"id":"an_dk_764","sentenceId":"s_dk_764","level":"sentence","content":"【吉凶】此辞描述了一种先恐惧后喜悦的情境。起初，震来虩虩，表示突然的震动或惊吓，使人感到恐惧，但这种恐惧实际上是为了避免更大的灾难，因此“恐致福也”。随后，笑言哑哑，表示事情过后，人们开始欢笑交谈，这表明事情有了好的结果，且这种结果是可以作为后来行事的准则，即“后有则也”。整体来看，这段辞语带有一种从危机中找到转机的意味，预示着吉凶之间的转换。"},
  {"id":"an_dk_765","sentenceId":"s_dk_765","level":"sentence","content":"【危险】此句出自《周易》中的震卦。震来厉，意味着震动、惊吓带来危险，乘刚也，表示这种危险是由于刚强过度、急躁冒进而引起的。整体上，这句话警示人们在面对变化和挑战时，要谨慎行事，避免因过于刚猛而招致危险。"},
  {"id":"an_dk_766","sentenceId":"s_dk_766","level":"sentence","content":"【不利】此句出自《易经》震卦的爻辞，意为震动而心神不定，处于不适当的位置。表明当前的处境或行为并不适宜，可能会带来不利的影响或结果。"},
  {"id":"an_dk_767","sentenceId":"s_dk_767","level":"sentence","content":"【困頓】此句出自《周易》中的震卦，震卦象征雷，这里描述的是雷陷入泥中，无法发挥其应有的威力和光明。比喻人或事物处于困境中，无法展现其才能或光明前景。"},
  {"id":"an_dk_768","sentenceId":"s_dk_768","level":"sentence","content":"【危险與謹慎】这段小象辞描述了一种处于危险中但通过谨慎行事可以避免大损失的情况。\"震往来厉\"表示在震动或变动中存在危险，\"危行也\"强调了在这种情况下行动需要格外小心。\"其事在中\"意味着事情的关键在于保持中庸、平衡，\"大无丧也\"则表示如果能够做到这一点，就不会有大的损失或失败。整体而言，这段话提醒人们在面对不确定性和风险时，应保持谨慎和平衡的态度。"},
  {"id":"an_dk_769","sentenceId":"s_dk_769","level":"sentence","content":"【警示】此辞表示处于震动不安的状态，内心尚未安定。虽然可能会遭遇凶险，但不会有大的灾祸，需要警惕周围环境，避免因恐惧而做出过激行为。"},
  {"id":"an_dk_770","sentenceId":"s_dk_770","level":"sentence","content":"【止於所當止】艮卦象征着山的静止，卦辞描述了一种内敛、静止的状态。\"艮其背，不获其身\"意味着专注于自己的内心，不被外界所干扰；\"行其庭，不见其人\"则表示在自己的领域内行动，不与他人发生不必要的交往。整体而言，卦辞传达了在适当的时候停止、保持内心宁静的信息，这样就不会有咎害。"},
  {"id":"an_dk_771","sentenceId":"s_dk_771","level":"sentence","content":"【時宜】这段彖辞出自《周易》艮卦，强调了“时止则止，时行则行”的时宜原则。艮卦象征“止”，但并不是一味地停止，而是在适当的时候停止，在适当的时候行动，动静皆能顺应时势，不失其时，因此其道光明。艮卦还强调了“止其所”，即在适当的位置上停止，不越位，不乱动。卦中提到的“上下敌应，不相与也”，说明上下之间没有相互配合，因此“不获其身，行其庭不见其人”，但只要遵循时宜的原则，就不会有咎。整体而言，这段彖辞强调了顺应时势、适得其所的重要性。"},
  {"id":"an_dk_772","sentenceId":"s_dk_772","level":"sentence","content":"【君子行為】此句出自《周易》艮卦的象辞，意为君子应当思考和行动都不超出自己的本分和位置。艮卦象征山，山静止不动，因此引申出君子应当安守本分，不妄动，不越位，保持内心的宁静和稳定。"},
  {"id":"an_dk_773","sentenceId":"s_dk_773","level":"sentence","content":"【初爻】初六爻辞中的“艮其趾”意味着在行动之初要谨慎，如同脚趾刚触地时的小心。此爻辞表示在事情的开始阶段，保持谨慎和克制，不要轻举妄动，这样就不会有咎害。同时，爻辞中的“利永贞”意味着在长期的坚持和正直中会有利，强调了持之以恒和坚守正道的重要性。"},
  {"id":"an_dk_774","sentenceId":"s_dk_774","level":"sentence","content":"【柔順中正】六二爻处于艮卦中，象征着柔顺与中正。艮其腓，意味着脚背被阻碍，行动受到限制。不拯其随，表示不能及时调整或改变跟随的状态。其心不快，说明在这种情况下，内心感到不愉快或不满。整体而言，此爻暗示在柔顺中正的态度下，仍可能遇到行动上的阻碍，导致内心的不快。"},
  {"id":"an_dk_775","sentenceId":"s_dk_775","level":"sentence","content":"【困難與挑戰】九三爻辞描述了一种处于困境中的状态，艮其限，意味着行动受到了限制；列其夤，表示在困境中挣扎；厉薰心，形容内心的焦虑和痛苦如同被烈火熏烤。整体表达了在面对困难和挑战时，内心承受的巨大压力和痛苦。"},
  {"id":"an_dk_776","sentenceId":"s_dk_776","level":"sentence","content":"【止於自身】此爻辞意为在行动上应当有所节制，专注于自身的行为和修养，不要过度干涉或涉及他人的事务。这样可以避免不必要的麻烦和错误，保持自身的安全和稳定。"},
  {"id":"an_dk_777","sentenceId":"s_dk_777","level":"sentence","content":"【言語謹慎】六五爻辞的意思是，要控制好自己的言语，说话要有条理和秩序，这样可以避免后悔。这里的“艮其辅”指的是控制自己的言语，“言有序”则强调说话要有逻辑性和条理性，这样才能避免因言语不当而带来的麻烦和后悔。"},
  {"id":"an_dk_778","sentenceId":"s_dk_778","level":"sentence","content":"【上九】敦艮，吉。意为在事物的最高阶段，保持敦厚、谦逊和坚定的品德，将会获得吉祥的结果。敦，表示敦厚、诚恳；艮，代表止、静止，也象征着山的稳固。此爻辞强调在达到顶峰时，仍需保持谦逊和坚定，不要骄傲自满，这样才能保持吉祥。"},
  {"id":"an_dk_779","sentenceId":"s_dk_779","level":"sentence","content":"【初六】初六爻的爻辞，表示在事物的初始阶段，应当谨慎行事，如同脚趾刚刚迈步，尚未偏离正道。这里的“艮其趾”意味着要控制好自己的行动，不要轻举妄动；“未失正也”则表示虽然处于初始阶段，但还没有偏离正确的方向。"},
  {"id":"an_dk_780","sentenceId":"s_dk_780","level":"sentence","content":"【行為態度】这句话的意思是，不救助那些跟随的人，是因为没有退一步倾听和理解他们的需求或情况。这反映了在处理人际关系或团队协作时，缺乏同理心和沟通的态度。"},
  {"id":"an_dk_781","sentenceId":"s_dk_781","level":"sentence","content":"【困境】此句出自《周易》艮卦的象辞，意为在限制中处于危险的境地，内心感到焦虑不安。艮卦象征山，有停止、阻碍之意，此处描述了人在面临困境时的心理状态。"},
  {"id":"an_dk_782","sentenceId":"s_dk_782","level":"sentence","content":"【自我約束】这句话出自《周易》的艮卦，意思是说要约束自己的行为，对自己的身体和行动有所节制。艮卦象征山，山静止不动，因此引申为停止、静止的意思。在这里，艮其身指的是通过自我约束来达到内心的平静和行为的稳重。"},
  {"id":"an_dk_783","sentenceId":"s_dk_783","level":"sentence","content":"【卦象】此句出自《周易》艮卦的象辞，意为“艮卦象征着山，其卦象为山下有山，象征着停止和静止。艮其辅，以中正也”意味着在艮卦中，应当以中正的态度来辅助事物的停止和静止，保持内心的平和与稳定，不偏不倚，以达到内外的和谐。"},
  {"id":"an_dk_784","sentenceId":"s_dk_784","level":"sentence","content":"【吉兆】此句出自《周易》艮卦的象辞，意为敦厚而止于艮（山），象征着吉祥，因为这种敦厚的品质能够使人或事物有一个良好的结局。艮卦象征山，有静止、停止之意，而敦厚则代表了稳重、诚实的美德，二者结合，预示着通过保持稳重和诚实，可以达到吉祥的结果。"},
  {"id":"an_dk_785","sentenceId":"s_dk_785","level":"sentence","content":"【婚姻】此卦辞表示女子出嫁将会吉祥，适宜坚守正道。渐卦象征着事物逐渐发展变化的过程，这里特指女子出嫁，逐渐适应新的家庭生活，只要保持贞洁和正直，就能获得吉祥的结果。"},
  {"id":"an_dk_786","sentenceId":"s_dk_786","level":"sentence","content":"【漸卦】渐卦象征着逐步前进，如同女子出嫁时的吉祥。逐步前进能够获得适当的位置，前往会有成就。以正道前进，可以治理国家。其位置刚健，处于中正之位。停止而谦逊，行动不会穷尽。"},
  {"id":"an_dk_787","sentenceId":"s_dk_787","level":"sentence","content":"【君子修身】此句大象辞意为山上有树木逐渐生长，象征君子应居住在有贤德之人的地方，以培养良好的风俗习惯。这里的“渐”表示逐渐、慢慢的过程，强调了君子修身养性、逐渐提升品德的过程。"},
  {"id":"an_dk_788","sentenceId":"s_dk_788","level":"sentence","content":"【初爻】初六爻辞描述了一只鸿雁逐渐飞到水边的干地上，象征着事物开始阶段的谨慎与艰难。爻辞中的“小子厉”指的是年轻人或初学者在面对困难时可能会受到责备或批评，但只要能够保持谦逊和谨慎，最终不会有大的过失或灾难。整体上，此爻辞提醒人们在事情的初始阶段要小心行事，即使遇到困难和批评，也不要气馁，坚持下去就会有好的结果。"},
  {"id":"an_dk_789","sentenceId":"s_dk_789","level":"sentence","content":"【吉祥】六二爻辞描述了一种吉祥的情境，鸿雁逐渐飞到磐石之上，象征着事情进展顺利，饮食愉快，心情舒畅，最终结果吉祥。"},
  {"id":"an_dk_790","sentenceId":"s_dk_790","level":"sentence","content":"【凶险】九三爻辞描述了一种不稳定的状况，鸿雁逐渐飞向陆地，象征着事物的发展逐渐偏离了正道。丈夫出征后不再返回，妻子怀孕却不能生育，这些都是不吉利的征兆，表明当前的形势非常凶险。然而，在这种情况下，有利于抵御外来的侵扰，即在不利的环境中，保持警惕和防御姿态是明智的选择。"},
  {"id":"an_dk_791","sentenceId":"s_dk_791","level":"sentence","content":"【吉祥】六四爻辞描述了一只大雁逐渐飞到了树上，可能会找到一个合适的栖息之处，这象征着事情在发展过程中找到了一个稳妥的立足点，没有灾难。此爻暗示在前进的过程中，虽然可能会遇到一些不确定的因素，但最终能够找到合适的位置，避免了危险。"},
  {"id":"an_dk_792","sentenceId":"s_dk_792","level":"sentence","content":"【吉祥】九五爻辞描述了一种逐渐上升至高位的情景，如同大雁飞至山陵之上。虽然在此过程中可能会遇到一些困难，比如“妇三岁不孕”，意味着可能在一段时间内无法取得预期的成果或进展，但最终这些困难都无法战胜你，结果是吉祥的。这表明只要坚持正道，即使面临挑战，最终也能获得成功和吉祥。"},
  {"id":"an_dk_793","sentenceId":"s_dk_793","level":"sentence","content":"【吉祥】上九爻辞描述了鸿雁逐渐飞到了陆地上，它的羽毛可以作为仪仗之用，象征着事物发展到了一个较高的阶段，达到了吉祥的结果。这里强调的是经过逐步积累和发展，最终能够达到一个理想的状态，获得吉祥的结局。"},
  {"id":"an_dk_794","sentenceId":"s_dk_794","level":"sentence","content":"【小象辭】此句出自《周易》中的小象辞，意为“小儿子遇到危险，但因其行为合乎道义，故不会有过失或灾祸”。这里强调了在面临困难时，只要行为正当，就能避免不利的后果。"},
  {"id":"an_dk_795","sentenceId":"s_dk_795","level":"sentence","content":"【飲食】此句意为饮食愉快，吉祥，不是无功受禄，而是因为有所作为和贡献，所以能够享受美食。说明了享受生活的同时，也要有相应的付出和努力。"},
  {"id":"an_dk_796","sentenceId":"s_dk_796","level":"sentence","content":"【象辭】这段文字是《周易》中的一段象辞，解释了某个卦象的象征意义。具体来说，“夫征不复，离群丑也”表示出征后不再返回，是因为离开了群体；“妇孕不育，失其道也”表示妇女怀孕但不能生育，是因为失去了正道；“利用御寇，顺相保也”表示利用防御敌人，是为了顺从并保护自己。整体上，这段象辞强调了群体的重要性、遵循正道的必要性以及自我保护的策略。"},
  {"id":"an_dk_797","sentenceId":"s_dk_797","level":"sentence","content":"【吉祥】此句出自《易经》中的小象辞，意为“或许能够得到屋梁的木材，是因为顺应了谦逊的原则”。这里的“桷”指的是屋梁的木材，象征着重要的资源或支持。整句话表达了一种通过谦逊和顺应自然规律而获得吉祥和成功的含义。"},
  {"id":"an_dk_798","sentenceId":"s_dk_798","level":"sentence","content":"【吉祥】最终没有人能够战胜它，吉祥；意味着能够实现自己的愿望。"},
  {"id":"an_dk_799","sentenceId":"s_dk_799","level":"sentence","content":"【吉祥】这句话出自《易经》中的小象辞，意思是说，鸟的羽毛可以用来作为礼仪的装饰，这是吉祥的象征；但同时提醒人们不可随意乱用，要保持庄重和尊重。这里强调了在使用资源时应遵循一定的规范和秩序，不可滥用。"},
  {"id":"an_dk_800","sentenceId":"s_dk_800","level":"sentence","content":"【凶险】归妹卦象征着少女出嫁，但卦辞中的“征凶，无攸利”意味着在行动上会有凶险，没有任何利益。这提示我们在当前的情境下，不宜轻举妄动，需要谨慎行事，避免冒险。"},
  {"id":"an_dk_801","sentenceId":"s_dk_801","level":"sentence","content":"【卦辭】归妹卦象征着男女婚配，是天地间的大道理。如果天地不相交合，万物便不能生长繁衍，归妹卦揭示了人类婚姻的始末。下卦为兑（泽），象征喜悦；上卦为震（雷），象征震动。喜悦与行动相结合，象征着男女因喜悦而结合。然而，如果轻率地采取行动，将会遭遇凶险，因为此时的位置不适当。此外，卦象中阴柔凌驾于阳刚之上，表明柔弱者占据了主导地位，这是不利的。"},
  {"id":"an_dk_802","sentenceId":"s_dk_802","level":"sentence","content":"【自然現象與人文啟示】此句出自《周易》中的归妹卦。上卦为泽，下卦为雷，象征着泽上有雷鸣。这种自然现象给人以启示，君子从中领悟到应当追求长久的终结，即在事物发展到一定阶段时，应当懂得适时结束，避免过度追求而带来的损害。同时，也应当认识到任何事物都有其衰败之时，应当提前做好准备，以应对可能的变化。"},
  {"id":"an_dk_803","sentenceId":"s_dk_803","level":"sentence","content":"【婚姻家庭】初九爻辞描述了嫁女为妾的情景，虽然地位不高，但能够和睦相处，如同跛足之人也能行走，出征则吉祥。这表明在不利的条件下，通过自身的努力和适应，仍然可以达到好的结果。在婚姻家庭中，即使遇到困难，只要双方能够相互理解和支持，也能获得幸福。"},
  {"id":"an_dk_804","sentenceId":"s_dk_804","level":"sentence","content":"【吉凶未定】九二爻辞描述的是一个视力有缺陷但仍然能够看见的人，这象征着在某种程度上存在不足或限制，但仍然具备一定的能力或机会。\"利幽人之贞\"意味着在这种情况下，有利于那些处于隐秘、不利地位的人保持正直和坚定。整体来看，这一爻辞提示我们在面对自身不足或外部环境不利时，应保持内心的坚定与正直，这样才有可能转危为安。"},
  {"id":"an_dk_805","sentenceId":"s_dk_805","level":"sentence","content":"【婚姻】六三爻辞描述了一种婚姻状况，其中“归妹以须”意味着女子出嫁时，需要等待适当的时机或条件；“反归以娣”则表示女子可能最终会以妾的身份回到娘家或另嫁他人。这反映了古代社会中女性在婚姻中的被动地位和复杂的人际关系。"},
  {"id":"an_dk_806","sentenceId":"s_dk_806","level":"sentence","content":"【婚姻】九四爻辞描述了归妹（即女子出嫁）的情况，其中“愆期”意味着超过了预期的时间，而“迟归有时”则表示虽然延迟，但最终会有合适的时间。整体来看，这爻辞暗示了婚姻或重要的事情可能会有延误，但最终会有一个合适的结果。在实际应用中，可以理解为在面对婚姻或其他重要决策时，即使出现延误也不必过于焦虑，耐心等待，最终会有好的结果。"},
  {"id":"an_dk_807","sentenceId":"s_dk_807","level":"sentence","content":"【婚姻】这爻辞描述了帝乙嫁妹的情景，其中提到妹妹的嫁衣比姐姐的还要好，象征着婚姻中的谦逊和礼让。同时，\"月几望\"表示月亮接近满月，象征着事情接近圆满，预示着吉祥。整体上，这爻辞强调了在婚姻中保持谦逊和礼让的重要性，以及事情接近圆满时的吉祥预兆。"},
  {"id":"an_dk_808","sentenceId":"s_dk_808","level":"sentence","content":"【不利】上六爻辞描述了一种不吉利的情景，女子提着篮子却没有收获，男子宰羊却不见血，象征着努力却无成果，行动没有收获，处于不利的局面。"},
  {"id":"an_dk_809","sentenceId":"s_dk_809","level":"sentence","content":"【婚姻與家庭】这段小象辞描述了女子出嫁成为娣（即妾室）的情况，这是出于长久的考虑。虽然地位较低，但能够得到家庭的接纳和尊重，象征着即使处于不利的位置，也能够通过自身的努力和适应，获得吉祥和和谐。"},
  {"id":"an_dk_810","sentenceId":"s_dk_810","level":"sentence","content":"【吉凶】这句话出自《周易》中的卦辞，意思是有利于幽居之人的贞正，没有改变常态。这里“幽人”指的是隐居或处于困境中的人，“未变常”表示没有改变常态或原则。整体上，这句话表达了一种在困境中保持贞正、不改变常态的积极态度，属于吉兆。"},
  {"id":"an_dk_811","sentenceId":"s_dk_811","level":"sentence","content":"【未成熟】此句出自《周易》归妹卦，意指小象处于未成熟、未达到适当状态的情况。归妹卦象征少女出嫁，以须表示等待，未当则表示时机未到或条件不成熟。整体表达了一种需要等待和准备的状态。"},
  {"id":"an_dk_812","sentenceId":"s_dk_812","level":"sentence","content":"【等待時機】此句意指有未按时实现的志向，需要等待适当的时机才能付诸行动。表明了在面对未能如愿的情况时，应当保持耐心，等待最佳的行动时刻。"},
  {"id":"an_dk_813","sentenceId":"s_dk_813","level":"sentence","content":"【婚姻】此卦象描述的是帝乙嫁女的情景，但强调的是陪嫁的娣（即陪嫁的女子）的衣裳比新娘的还要好。这实际上是在说明，虽然新娘的地位尊贵，但有时候陪嫁的人或事物也可能显得更加出色。卦象中的“其位在中，以贵行也”则表示新娘虽然地位尊贵，但行事应当保持谦逊，不可过于张扬。整体来看，这段卦辞主要是在谈论婚姻中的地位与谦逊的问题。"},
  {"id":"an_dk_814","sentenceId":"s_dk_814","level":"sentence","content":"【象征】上六爻的爻辞描述了一种象征性的场景，即“无实，承虚筐也”。这表示在这一爻的位置上，虽然表面上看似有所承载，但实际上却是空无一物的，象征着虚幻、不实或空洞的状态。这种状态可能暗示着在实际操作或追求目标时，可能会遇到看似有希望但实际上却无法实现的情况。"},
  {"id":"an_dk_815","sentenceId":"s_dk_815","level":"sentence","content":"【吉】丰卦象征着丰收和成功，亨通顺利。君王能够得到上天的庇佑，无需忧虑，适宜在正午时分进行祭祀或重要活动，以达到最佳效果。这表明在当前形势下，应当抓住时机，积极行动，以实现更大的成就。"},
  {"id":"an_dk_816","sentenceId":"s_dk_816","level":"sentence","content":"【哲學與自然規律】这段彖辞出自《周易》中的丰卦，强调了“大”和“光明”的主题。其中，“明以动，故丰”表示通过光明和行动可以达到丰盛的状态。而“王假之，尚大也”则表示君王应当效仿这种大而光明的状态。接下来，“勿忧宜日中，宜照天下也”意味着在最光明的时候，应当无所忧虑，普照天下。然而，“日中则昃，月盈则食，天地盈虚，与时消息”则揭示了自然界的规律，即任何事物都有盛衰变化，不能永远处于顶峰。最后，“而况人于人乎？况于鬼神乎？”进一步强调了这一规律不仅适用于自然界，也适用于人类社会和鬼神世界。整体来看，这段彖辞探讨了光明与行动的关系，以及自然和社会的盛衰变化规律。"},
  {"id":"an_dk_817","sentenceId":"s_dk_817","level":"sentence","content":"【自然現象與社會行為】此句大象辞描述了雷电同时到来的自然现象，象征着丰盛和充沛的能量。在社会行为层面上，君子应当效仿这种自然界的明确和果断，公正地处理案件，执行法律，以达到社会的和谐与秩序。"},
  {"id":"an_dk_818","sentenceId":"s_dk_818","level":"sentence","content":"【相遇】初九爻辞描述了与合适的伴侣或合作伙伴相遇的情景。虽然在短时间内（旬，指十天）可能会遇到一些小的困难或挑战，但总体上不会有大的问题。如果继续前行，将会受到赞赏和尊重。这表明在人际关系或合作中，找到合适的伙伴是非常重要的，即使过程中会有一些波折，但最终会有好的结果。"},
  {"id":"an_dk_819","sentenceId":"s_dk_819","level":"sentence","content":"【光明受阻】此爻辞描述了一种光明被遮蔽的情景，即在正午时分，太阳高照，却能看到北斗星，象征着光明被遮蔽，真相被掩盖。在这种情况下，如果前往行动，可能会受到猜疑和阻碍。然而，只要内心诚信，能够坦诚相待，最终会得到吉祥的结果。此爻提示在遇到困难和阻碍时，应保持诚信和正直，以化解猜疑，获得他人的信任和支持。"},
  {"id":"an_dk_820","sentenceId":"s_dk_820","level":"sentence","content":"【凶险與警示】此爻辞描述了一种充满危险和挑战的情境。\"丰其沛\"意味着资源丰富，但\"日中见沫\"则暗示了在最光明的时刻出现了不祥之兆，如同太阳中出现了泡沫。\"折其右肱\"表示力量受到了严重的削弱，右臂是人的主要力量来源之一，折断右臂意味着失去了重要的支撑。然而，\"无咎\"则表明尽管遭遇了这些困难，但最终不会有大的过失或灾难。整体来看，此爻辞告诫人们在顺境中要保持警惕，防止因疏忽大意而遭受损失。"},
  {"id":"an_dk_821","sentenceId":"s_dk_821","level":"sentence","content":"【吉兆】九四爻辞描述了一种看似不利但最终吉祥的情境。丰其蔀，意味着遮蔽物非常厚重，暗示环境或情况的阴暗与困难；日中见斗，表示在最光明的时候却出现了异常的现象，如斗星在白天出现，象征着异常或不寻常的情况；遇其夷主，意味着在这种异常的情况下遇到了平易近人的主人或朋友，最终结果是吉祥的。这表明在困境中遇到贵人相助，能够化险为夷，转危为安。"},
  {"id":"an_dk_822","sentenceId":"s_dk_822","level":"sentence","content":"【吉祥】六五爻辞表示，当有美好的德行或功绩（章）到来时，会带来庆祝和赞誉，这是吉祥的预兆。说明此时应当保持谦逊，继续行善积德，以获得更多的福报。"},
  {"id":"an_dk_823","sentenceId":"s_dk_823","level":"sentence","content":"【凶险】上六爻辞描述了一种极端的孤立和衰败的状态。\"丰其屋，蔀其家\"意味着虽然外表看起来很富裕，但内部已经衰败不堪。\"闚其户，阒其无人\"表示即使窥视其门户，也见不到人影，暗示家庭或组织已经空虚。\"三岁不觌\"则进一步强调了这种状态持续了很长时间，三年都没有见到人。整体来看，这是一幅非常不吉利的画面，预示着严重的孤立、衰败和凶险。"},
  {"id":"an_dk_824","sentenceId":"s_dk_824","level":"sentence","content":"【時間】此句意为在十天之内（一旬）不会有灾祸，但超过十天则会有灾祸。这反映了时间上的一个转折点，提醒人们在特定的时间范围内行事要谨慎，以免招致不测。"},
  {"id":"an_dk_825","sentenceId":"s_dk_825","level":"sentence","content":"【誠信】此句意为通过真诚和信任来激发和表达自己的志向。强调了诚信在个人发展和人际交往中的重要性，表明了诚信能够激发人的内在动力，使人的志向得以实现。"},
  {"id":"an_dk_826","sentenceId":"s_dk_826","level":"sentence","content":"【凶】此辞意指虽然外表看似丰满充实，但实际上力量不足，难以承担大事。如同右臂折断，最终无法使用。象征着虚有其表而无实际能力，处于不利的境地。"},
  {"id":"an_dk_827","sentenceId":"s_dk_827","level":"sentence","content":"【困頓與機遇】此辞描述了一种处于困境但有望得到解决的情境。“丰其蔀，位不当也”意味着当前的环境或地位并不理想，如同被遮蔽的光明。“日中见斗，幽不明也”进一步说明了即使在最光明的时刻（日中），也出现了异常的现象（见斗），暗示了环境的不明朗和困难。“遇其夷主，吉；行也”则表示在这种情况下，如果能够遇到平易近人的领导者或朋友，将会带来吉祥的结果，同时也暗示了行动的重要性，即在这种困境中，积极的行动和正确的选择能够带来转机。"},
  {"id":"an_dk_828","sentenceId":"s_dk_828","level":"sentence","content":"【吉祥】六五爻的吉祥，是因为有喜庆之事发生。在《易经》中，六五爻通常代表中正、柔和的位置，能够得到上天的保佑和人们的拥戴，因此会有吉祥和喜庆的结果。"},
  {"id":"an_dk_829","sentenceId":"s_dk_829","level":"sentence","content":"【隱居】此句描述了一座丰盛华丽的房屋，仿佛高飞于天际，然而窥视其门户，却空无一人，暗示主人已经隐居，不为外人所知。这反映了主人的隐逸生活态度，不愿与世俗交往，选择自我隐藏。"},
  {"id":"an_dk_830","sentenceId":"s_dk_830","level":"sentence","content":"【旅行/外出】此卦辞表示在旅行或外出时，虽有小的亨通，但需坚守正道，保持谨慎和正直，这样才会吉祥。旅卦强调在外时要保持良好的品德和行为，不要偏离正道。"},
  {"id":"an_dk_831","sentenceId":"s_dk_831","level":"sentence","content":"【卦辭】这段文字是《周易》中关于“旅”卦的彖辞。它解释了“旅”卦的基本含义和象征意义。其中，“小亨”表示在旅途中或异乡时，虽然条件有限，但仍然可以达到小的亨通；“柔得中乎外，而顺乎刚”表示柔顺的德行在外在环境中得到中正的位置，并且顺应刚强的力量；“止而丽乎明”表示在旅途中要懂得停止，同时保持内心的光明和清晰；“旅贞吉”表示在旅途中保持正直和吉祥；“旅之时义大矣哉”则强调了在旅途中遵循时宜的重要性，认为其意义重大。整体上，这段彖辞强调了在旅途中保持柔顺、中正、光明、正直和适时的重要性。"},
  {"id":"an_dk_832","sentenceId":"s_dk_832","level":"sentence","content":"【象辭】此句出自《周易》的象辞部分，描述了“旅”卦的象征意义。其中，“山上有火”形象地描绘了“旅”卦的上下卦结构，上为离（火），下为艮（山）。君子观此象，应当明白在处理刑罚时要明智谨慎，同时不应让案件久拖不决，以体现公正与效率。"},
  {"id":"an_dk_833","sentenceId":"s_dk_833","level":"sentence","content":"【凶】初六爻辞描述了旅行或外出时，因为琐碎小事而招致灾祸。这表明在处理事情时，如果过于拘泥于细节，忽视了大局，可能会带来不必要的麻烦和损失。此爻提示人们在行动时应有远见，不要被琐事牵绊，以免自取其咎。"},
  {"id":"an_dk_834","sentenceId":"s_dk_834","level":"sentence","content":"【安定】六二爻辞描述了旅行者找到了一个可以暂时安身的地方，怀抱着自己的财物，得到了忠诚的童仆的帮助。这表明在旅途中找到了暂时的安定和帮助，是一个吉祥的象征。"},
  {"id":"an_dk_835","sentenceId":"s_dk_835","level":"sentence","content":"【凶险】九三爻辞描述了一种旅行中遭遇火灾，失去住所和童仆的困境，预示着在艰难的环境中可能会遭受损失和挫折。\"贞厉\"意味着在这样的情况下，即使保持正直和坚定，也难以避免危险和困难。这表明在当前的处境中，需要特别谨慎，以防不测。"},
  {"id":"an_dk_836","sentenceId":"s_dk_836","level":"sentence","content":"【旅卦】九四爻辞描述了在旅途中停留，虽然得到了一些生活必需品（如斧头），但内心仍然感到不快。这反映了在异乡漂泊时，即使物质条件得到满足，精神上的孤独和不安仍然难以消除。"},
  {"id":"an_dk_837","sentenceId":"s_dk_837","level":"sentence","content":"【吉凶】此爻辞描述了射猎野鸡的情景，虽然只射出了一箭，但最终却得到了荣誉和使命。这表明在某些情况下，即使付出不多，也可能获得意想不到的好结果。然而，这也可能暗示着在追求目标的过程中，可能会有小的损失或牺牲，但最终的结果是积极的。整体来看，这是一个较为吉祥的爻辞，预示着最终会得到好的评价和认可。"},
  {"id":"an_dk_838","sentenceId":"s_dk_838","level":"sentence","content":"【凶险】上九爻辞描述了一种极端不利的情况。\"鸟焚其巢\"象征着家园或根基被破坏；\"旅人先笑后号啕\"表示开始时可能有短暂的喜悦，但最终会遭遇极大的悲痛；\"丧牛于易\"意味着在容易的地方或情况下失去了重要的依靠或财富，整体预示着凶险和不吉。"},
  {"id":"an_dk_839","sentenceId":"s_dk_839","level":"sentence","content":"【困頓】此句意指旅行中遇到微小琐碎的困难，导致志向无法实现，最终招致灾祸。表明在追求目标的过程中，如果被琐事所困，可能会导致更大的失败。"},
  {"id":"an_dk_840","sentenceId":"s_dk_840","level":"sentence","content":"【人事】此句意为得到忠诚的童仆，最终不会有怨尤。说明在人际关系中，找到可靠、忠诚的助手或伙伴，能够避免许多麻烦和纠纷，最终达到和谐的状态。"},
  {"id":"an_dk_841","sentenceId":"s_dk_841","level":"sentence","content":"【旅行與困難】这段小象辞描述了旅行中遭遇的困境和损失。\"旅焚其次，亦以伤矣\"意味着旅行者在途中遭遇火灾，不仅财物受损，身心也受到伤害。\"以旅与下，其义丧也\"则表示在这种艰难的旅行中，与下属或同伴的关系也可能因此受损，失去了原本的意义和价值。整体来看，这段小象辞强调了旅行中可能遇到的种种不利和挑战。"},
  {"id":"an_dk_842","sentenceId":"s_dk_842","level":"sentence","content":"【旅行】此辞描述了一种旅行的状态，但旅行者尚未到达理想的位置或状态，虽然获得了一些物质上的帮助或支持（资斧），但内心仍然感到不满足或不快乐。这反映了旅行者在追求目标的过程中，虽然得到了一些外部的帮助，但内心的目标尚未实现，因此心情并不愉快。"},
  {"id":"an_dk_843","sentenceId":"s_dk_843","level":"sentence","content":"【吉兆】最终获得荣誉和使命，意味着地位和声望的提升，这是一种积极向上的发展趋势。"},
  {"id":"an_dk_844","sentenceId":"s_dk_844","level":"sentence","content":"【旅行與損失】这段小象辞描述了一种旅行中的困境和损失。\"以旅在上，其义焚也\"意味着在旅行的最高阶段，可能会遭遇灾难或困境，如同被火烧毁。\"丧牛于易，终莫之闻也\"则表示在交易或交换中失去了重要的资源（如牛），但这种损失并没有引起他人的注意或同情。整体来看，这段小象辞警示人们在旅行或外出时要小心谨慎，避免不必要的损失。"},
  {"id":"an_dk_845","sentenceId":"s_dk_845","level":"sentence","content":"【風】巽卦象征风，其卦辞“小亨，利攸往，利见大人”意味着在小事上亨通顺利，适宜前往行动，也有利于拜见德高望重的人。巽卦的特性是柔和而能深入，如同风无孔不入，因此在处理事情时应采取温和而灵活的态度，以达到更好的效果。"},
  {"id":"an_dk_846","sentenceId":"s_dk_846","level":"sentence","content":"【巽卦】此彖辞出自《周易》巽卦。巽卦象征顺从、进入。卦辞中的“重巽以申命”表示再次强调顺从的命令或教诲；“刚巽乎中正而志行”意味着刚强而能顺应中正之道，其志向得以实现；“柔皆顺乎刚”表示柔弱者皆顺从于刚强者；“是以小亨，利有攸往，利见大人”则说明在这种情况下，虽小有亨通，但行动有利，且适宜见贤人或有权势的人。整体而言，此卦强调了顺应与和谐的重要性。"},
  {"id":"an_dk_847","sentenceId":"s_dk_847","level":"sentence","content":"【自然與行為准則】这句话出自《周易》中的大象传，巽卦。巽代表风，象征着柔和、顺从和渗透。君子应当效法风的特性，以柔和、顺从的态度来传达和执行命令，使自己的行为符合天道和人道的要求。这里的“申命”指的是反复申明、传达命令，而“行事”则指具体的行为和行动。整体上，这句话强调了在行为和决策中应具备柔和、顺从和渗透的品质。"},
  {"id":"an_dk_848","sentenceId":"s_dk_848","level":"sentence","content":"【决策與行動】初六爻辞描述了一种进退两难的境地，但最终建议采取果断的行动。这里的“利武人之贞”意味着在这种情况下，坚定而果断的行动（如武人般的决断）是有利的。这表明在面对不确定性和困难时，勇敢和坚定的态度能够带来成功。"},
  {"id":"an_dk_849","sentenceId":"s_dk_849","level":"sentence","content":"【吉兆】九二爻辞描述了一种谦逊和顺从的态度，处于低位而能保持内心的宁静和敬畏。\"巽在床下\"象征着谦卑和顺从，\"用史巫纷若\"则表示通过祭祀和祈祷来寻求神灵的保佑，这种虔诚的态度能够带来吉祥和避免灾祸。整体上，这一爻辞传达了在面对困难或挑战时，保持谦逊、敬畏和虔诚的心态，能够获得吉祥的结果。"},
  {"id":"an_dk_850","sentenceId":"s_dk_850","level":"sentence","content":"【困難】九三爻辞“频巽，吝”意味着在频繁的顺从或谦卑中，可能会遇到困难或不利的情况。这表明在某些情况下，过度的顺从或谦卑可能不会带来好的结果，反而可能导致不利的局面。"},
  {"id":"an_dk_851","sentenceId":"s_dk_851","level":"sentence","content":"【吉兆】六四爻辞表示悔恨消失，打猎时获得了三种不同的猎物，象征着在努力之后得到了丰富的收获和多方面的成功。这通常预示着事情会朝着好的方向发展，之前的困扰或遗憾将会消除。"},
  {"id":"an_dk_852","sentenceId":"s_dk_852","level":"sentence","content":"【吉兆】九五爻辞表示坚守正道则吉祥，悔恨将消失，没有不利。虽然开始时可能没有迹象，但最终会有好的结果。在行动前要像在庚日前三天和庚日后三天一样，做好充分的准备和总结，这样才会吉祥。此爻辞强调了正直、坚持和准备的重要性。"},
  {"id":"an_dk_853","sentenceId":"s_dk_853","level":"sentence","content":"【凶险】上九爻的爻辞描述了一种极其不利的情况，巽（象征谦逊、顺从）位于床下，意味着处于极其卑微和被动的位置。丧失了资斧（比喻生活或工作的基本工具和资源），表明失去了生存和发展的基本条件。在这种情况下，坚持正道也会遭遇凶险，暗示了在极端不利的环境中，即使保持正直也可能难以避免灾难。"},
  {"id":"an_dk_854","sentenceId":"s_dk_854","level":"sentence","content":"【决策與行動】此辞意指在进退之间犹豫不决，是因为内心存有疑虑。而“利武人之贞，志治也”则表明，在这种情况下，适宜像武人一样坚定意志，明确目标，以达到治理和整顿的目的。整体来看，这段辞强调了在面对选择时，应当克服内心的疑惑，坚定决心，采取行动。"},
  {"id":"an_dk_855","sentenceId":"s_dk_855","level":"sentence","content":"【吉祥】纷若之吉，得中也，意味着在纷繁复杂的情况下，能够保持中庸之道，从而获得吉祥的结果。这里的“得中”是指行为或决策符合中庸的原则，不偏不倚，恰到好处。"},
  {"id":"an_dk_856","sentenceId":"s_dk_856","level":"sentence","content":"【困頓】频繁地遭遇困难和阻碍，导致志向和能力都受到了极大的限制，处于一种进退两难的困境之中。"},
  {"id":"an_dk_857","sentenceId":"s_dk_857","level":"sentence","content":"【收獲】在田地里获得了三种不同的作物或猎物，象征着努力之后的丰富收获和成功。"},
  {"id":"an_dk_858","sentenceId":"s_dk_858","level":"sentence","content":"【吉兆】九五之吉表示处于非常有利的位置，位正中也意味着处于中心或正确的位置，象征着吉祥和顺利。"},
  {"id":"an_dk_859","sentenceId":"s_dk_859","level":"sentence","content":"【凶险】此卦象表示处于不利的位置，如同巽（风）在床下，象征着处境艰难，资源匮乏。\"上穷也\"意味着已经到了极限，无法再进一步。\"丧其资斧\"意味着失去了生存的工具或资源，这预示着可能会遭遇严重的困难或损失。整体来看，这是一个不吉利的卦象，提示人们在当前的处境中需要谨慎行事，避免冒险。"},
  {"id":"an_dk_860","sentenceId":"s_dk_860","level":"sentence","content":"【吉卦】兑卦象征着喜悦与和顺，卦辞“亨，利贞”表明此卦预示着亨通顺利，但同时强调在喜悦中要保持正直和谨慎，利于坚守正道。"},
  {"id":"an_dk_861","sentenceId":"s_dk_861","level":"sentence","content":"【卦辭】这段文字是《周易》中兑卦的彖辞。兑卦象征喜悦、和悦。卦象为下兑上兑，内卦和外卦都是兑，兑为泽，泽水相连，相互滋润，象征着喜悦和沟通。卦辞中提到“刚中而柔外”，指的是内卦为兑（泽），外卦也为兑（泽），内刚外柔，刚柔相济，象征着内心坚定而外表柔和。这种和悦的态度能够使人们在遵循天道的同时，顺应民心，从而得到民众的支持和响应。进一步解释说，当领导者以和悦的态度对待民众时，民众会忘记劳苦；当领导者以和悦的态度面对困难时，民众也会勇于面对，甚至不惜牺牲生命。这种和悦的力量是巨大的，能够激励民众奋发向前。"},
  {"id":"an_dk_862","sentenceId":"s_dk_862","level":"sentence","content":"【人际關系】此句出自《周易》中的兑卦，兑卦象征着喜悦与沟通。\"丽泽，兑\"描述的是两个泽水相连，相互映照，象征着人与人之间的交流与互动。\"君子以朋友讲习\"则意味着君子通过与朋友的交往和学习，增进彼此的了解和友谊，共同提升自我。这反映了在良好的人际关系中，通过交流和学习可以达到共同进步的目的。"},
  {"id":"an_dk_863","sentenceId":"s_dk_863","level":"sentence","content":"【吉兆】初九爻辞表示以平和的心态去交往或应对事务，能够获得吉祥的结果。这说明在处理问题时，保持内心的平和与真诚，不急功近利，不争强好胜，往往能够得到好的结局。"},
  {"id":"an_dk_864","sentenceId":"s_dk_864","level":"sentence","content":"【吉兆】九二爻辞表示以诚信相待，和悦相处，可以获得吉祥，内心的悔恨也会消失。这说明在人际交往中，真诚和友善是非常重要的品质，能够带来积极的结果。"},
  {"id":"an_dk_865","sentenceId":"s_dk_865","level":"sentence","content":"【凶险】六三爻辞中的“来兑，凶”意味着主动前来寻求欢悦或交换，将会遭遇凶险。这提示人们在某些情况下，不应过于主动或轻率地追求表面的和谐与欢悦，而应谨慎行事，以免招致不利。"},
  {"id":"an_dk_866","sentenceId":"s_dk_866","level":"sentence","content":"【变化與調整】九四爻辞中的“商兑”意味着在交流和协商中寻求变化和调整。“未宁”表示这种变化和调整尚未达到稳定状态，存在一定的不确定性。“介疾有喜”则暗示在这一过程中，虽然会遇到一些障碍或困难，但最终会有好的结果，带来喜悦。整体来看，这一爻辞强调在变化中寻求平衡与和谐的重要性。"},
  {"id":"an_dk_867","sentenceId":"s_dk_867","level":"sentence","content":"【凶险】九五爻辞表示在信任或诚信方面出现了严重的问题，处于被剥夺或削弱的状态，预示着有危险或不利的情况。这通常意味着在高位者失去了他人的信任，或者自身处于一种孤立无援的境地，需要谨慎行事，以防不测。"},
  {"id":"an_dk_868","sentenceId":"s_dk_868","level":"sentence","content":"【上六】引兑，表示在最上方的爻，象征着引导和交流。此爻提示在处理事务时，应当注重沟通与协调，通过恰当的引导来达成共识，解决矛盾。同时，也暗示着在高位者应当以身作则，引领正道。"},
  {"id":"an_dk_869","sentenceId":"s_dk_869","level":"sentence","content":"【和諧】此句出自《易经》中的兑卦，意为以和顺的态度交往能够带来吉祥，因为这种行为没有引起任何怀疑或猜忌，体现了人与人之间的信任与和谐。"},
  {"id":"an_dk_870","sentenceId":"s_dk_870","level":"sentence","content":"【誠信】孚兑之吉，信志也，意味着以诚信的态度去交流和交往，能够带来吉祥的结果。这里的“孚”指的是诚信、信任，“兑”则有交流、交往之意，“信志”则是指坚定的诚信意志。整体表达的是在人际交往中，保持诚信和真诚的态度，能够获得好的结果。"},
  {"id":"an_dk_871","sentenceId":"s_dk_871","level":"sentence","content":"【不利】此句小象辞意指处于不当的位置或时机，采取迎合或喜悦的态度将会招致凶险。提示在不适宜的情境下，不应盲目追求表面的和谐或迎合，需谨慎行事。"},
  {"id":"an_dk_872","sentenceId":"s_dk_872","level":"sentence","content":"【吉兆】九四之喜，表示在这一爻位上出现了喜庆之事，象征着吉祥和庆祝。在《易经》中，九四通常代表事物发展到一个较为顺利的阶段，此时出现的喜庆之事，预示着好的变化和积极的结果。"},
  {"id":"an_dk_873","sentenceId":"s_dk_873","level":"sentence","content":"【正位】此句出自《易经》中的剥卦。剥卦象征着事物的衰落或剥落，而“孚于剥，位正当也”意味着在剥落的过程中，仍然保持了正直和正当的位置。这里的“孚”表示诚信、信任，意味着在不利的环境中依然能够坚守正道，保持自己的位置和原则。因此，标签为“正位”，表示在困难中保持正直和正当的位置。"},
  {"id":"an_dk_874","sentenceId":"s_dk_874","level":"sentence","content":"【上六】上六爻的位置在卦的最上方，表示事物发展到了极点或末尾。\"引兑，未光也\"意味着在这一阶段，虽然有吸引或交流（引兑）的行为，但其效果并不明显或未能达到预期的光明和成功（未光）。这可能是因为时机未到，或者是因为力量不足，需要等待或调整策略。"},
  {"id":"an_dk_875","sentenceId":"s_dk_875","level":"sentence","content":"【亨通】涣卦象征着分散、离散，但卦辞中提到“亨”，意味着在分散的情况下仍然能够亨通。接着，“王假有庙”表示君王能够借助宗庙的力量，得到祖先的庇佑，这象征着在困难时期能够得到外部力量的支持。而“利涉大川”则意味着在这种情况下，适合进行大的行动或跨越障碍，表明虽然面临挑战，但有克服困难的可能。最后，“利贞”强调了在这一过程中，保持正直和坚定的重要性，只有这样，才能真正实现亨通。"},
  {"id":"an_dk_876","sentenceId":"s_dk_876","level":"sentence","content":"【卦辭】涣卦象征着分散、离散，但最终能够亨通。这是因为刚爻（代表阳刚、坚定的力量）从下而来，不会陷入困境；柔爻（代表阴柔、顺应的力量）在外卦中得位，能够与上方的爻和谐相处。君王在宗庙中举行祭祀，象征着君王处于中心位置，能够统领全局。利于渡过大河，象征着借助木制的船只能够成功渡过难关，达成目标。"},
  {"id":"an_dk_877","sentenceId":"s_dk_877","level":"sentence","content":"【自然現象與人文活動】此句大象辞描述了自然现象与人文活动的结合。\"风行水上，涣\"，象征着风在水面上吹拂，形成扩散、分散的状态，暗示着变化与流动。\"先王以享于帝立庙\"，则表达了古代帝王为了祭祀天地、祖先而建立庙宇，体现了对自然和先祖的崇敬与纪念。整体上，这句话反映了古人对自然现象的观察与人文活动的结合，强调了人与自然和谐共处的理念。"},
  {"id":"an_dk_878","sentenceId":"s_dk_878","level":"sentence","content":"【行動】初六爻辞中的“用拯马壮，吉”意味着在遇到困难或需要救援时，采取积极的行动，如使用强壮的马匹进行救援，将会带来吉祥的结果。这表明在面对挑战时，积极主动地寻求解决办法，利用可用资源，能够克服困难，达到好的结果。"},
  {"id":"an_dk_879","sentenceId":"s_dk_879","level":"sentence","content":"【变動與適應】九二爻辞描述了在涣散的局面中，迅速采取行动，找到稳固的立足点，可以避免后悔。这里的“涣奔其机”意味着在混乱中寻找机会，快速行动；“悔亡”则表示通过这样的行动，可以消除可能的遗憾。整体上，这一爻强调了在变动中寻找稳定，及时适应环境的重要性。"},
  {"id":"an_dk_880","sentenceId":"s_dk_880","level":"sentence","content":"【个人修養】此爻辞意指通过自我反省和调整，使自身涣散的状态得以改善，从而避免了悔恨。这表明在面对困难或问题时，首先应当从自身寻找原因并进行改正，这样才能达到内心的平和与稳定。"},
  {"id":"an_dk_881","sentenceId":"s_dk_881","level":"sentence","content":"【群體解散與重新聚合】六四爻辞描述了一种群体解散后重新聚合的情景，这种聚合带来了极大的吉祥。爻辞中的“涣其群”意味着原本紧密的群体出现了分散或解散的现象，但随后的“元吉”则表明这种解散并非坏事，反而为新的、更积极的聚合创造了条件。而“涣有丘，匪夷所思”则进一步说明了这种新的聚合形式是出乎意料的，可能是在一个意想不到的地方或以一种意想不到的方式实现了群体的重新凝聚。整体来看，六四爻辞强调了变化中的积极面，即通过解散旧的结构，可以迎来更加和谐、更有活力的新局面。"},
  {"id":"an_dk_882","sentenceId":"s_dk_882","level":"sentence","content":"【君王之象】九五爻辞描述了君王发布重要命令或公告的情景，如同汗水般迅速传播，君王的命令能够涣散并解决当前的困境，使王居得以安定，没有灾咎。这表明在关键时刻，君王的决策和行动能够起到稳定局势的作用。"},
  {"id":"an_dk_883","sentenceId":"s_dk_883","level":"sentence","content":"【解困】上九爻辞表示在涣散的局面中，能够摆脱困境，远离危险，从而避免灾祸。\"涣其血\"意味着化解了流血冲突或危险；\"去逖出\"表示远离了远方的麻烦或危险；\"无咎\"则表明最终没有招致灾祸。这一爻辞鼓励人们在面对困难时，要积极寻求解决之道，勇敢地摆脱困境。"},
  {"id":"an_dk_884","sentenceId":"s_dk_884","level":"sentence","content":"【吉兆】初六之吉，意味着在事情的开始阶段就遇到了吉祥的征兆，这表明只要顺从自然的规律和正确的方向，就能获得好的结果。"},
  {"id":"an_dk_885","sentenceId":"s_dk_885","level":"sentence","content":"【吉】此句意为小象在奔向其目标或位置时，能够顺利达成所愿，象征着行动顺利，愿望得以实现，是一个吉祥的预兆。"},
  {"id":"an_dk_886","sentenceId":"s_dk_886","level":"sentence","content":"【个人修養】这句话出自《周易》涣卦的爻辞，意为“涣散自身，志向在于外部”。这里的“涣其躬”指的是个人的内在状态处于一种涣散、不集中的状态，而“志在外也”则表明尽管内在涣散，但其志向和目标仍然指向外部世界。从个人修养的角度来看，这句话提醒人们在面对内在的混乱或困惑时，仍应保持对外部世界的关注和追求，不应因个人的困境而放弃对理想的追求。"},
  {"id":"an_dk_887","sentenceId":"s_dk_887","level":"sentence","content":"【团結】涣散的群体重新团结起来，是非常吉祥的；这象征着光明和壮大。"},
  {"id":"an_dk_888","sentenceId":"s_dk_888","level":"sentence","content":"【吉兆】此句小象辞“王居无咎，正位也”意味着君王处于其应有的位置上，没有过失，象征着秩序井然、国泰民安的吉兆。"},
  {"id":"an_dk_889","sentenceId":"s_dk_889","level":"sentence","content":"【避险】这句话出自《易经》涣卦的爻辞，意为通过分散或化解某种紧张局势，从而远离危险和伤害。在实际应用中，可以理解为采取措施避免潜在的风险和危害。"},
  {"id":"an_dk_890","sentenceId":"s_dk_890","level":"sentence","content":"【節製】此卦辞表示在节制的情况下可以亨通，但如果过度节制，导致自己或他人感到痛苦，则不可坚持这种极端的节制。应当适时调整，保持中庸之道。"},
  {"id":"an_dk_891","sentenceId":"s_dk_891","level":"sentence","content":"【節製】此卦辞强调了节制的重要性。亨通是因为刚柔分明，而刚爻处于中位，象征着节制得当。若过度节制则不可长久，因为这样会导致道路穷尽。在行动中保持愉悦的态度面对险境，处于适当的位置进行节制，保持中正以达到亨通。天地通过节制形成了四季，人类社会也应通过制度来节制，避免浪费资源，不伤害民众。"},
  {"id":"an_dk_892","sentenceId":"s_dk_892","level":"sentence","content":"【卦象】此句出自《周易》中的节卦。泽上有水，形象地描述了节卦的卦象，上卦为泽（兑），下卦为水（坎）。君子观此卦象，应当效法自然界的节制之道，制定合理的制度和规范，同时讨论和培养个人的品德与行为，以达到内外兼修的境界。"},
  {"id":"an_dk_893","sentenceId":"s_dk_893","level":"sentence","content":"【隱忍】初九爻辞表示在事情的初始阶段，应当保持低调，不急于行动，如同不走出家门一样，这样可以避免不必要的麻烦和错误。在这种情况下，保持谨慎和耐心，等待时机成熟再行动，是不会有过失的。"},
  {"id":"an_dk_894","sentenceId":"s_dk_894","level":"sentence","content":"【凶险】九二爻辞表示处于这个位置的人应当谨慎行事，不宜轻举妄动。爻辞中的“不出门庭”意味着应当保持低调，不要轻易出门或采取行动，否则可能会遭遇凶险。这通常是因为当前的环境或形势不利于外出或行动，需要静观其变，等待时机。"},
  {"id":"an_dk_895","sentenceId":"s_dk_895","level":"sentence","content":"【節製】六三爻辞的意思是，如果不能节制自己的行为，就会导致后悔和叹息，但最终不会有大的灾祸。这说明在面对诱惑或困难时，应当保持节制，避免过度放纵或冲动行事，这样才能避免不必要的麻烦和损失。"},
  {"id":"an_dk_896","sentenceId":"s_dk_896","level":"sentence","content":"【吉祥】六四爻辞“安节，亨”意味着在节制和守持中保持安定，能够获得亨通。此爻提示在面对各种情况时，保持内心的平静和节制，不急躁、不过度，能够使事情顺利发展。"},
  {"id":"an_dk_897","sentenceId":"s_dk_897","level":"sentence","content":"【中正吉祥】九五爻辞表示处于中正之位，能够保持适度的节制，吉祥；前往会有好的结果，受到尊重和推崇。这说明在适当的时候保持节制，不仅能够获得吉祥，还能得到他人的认可和支持。"},
  {"id":"an_dk_898","sentenceId":"s_dk_898","level":"sentence","content":"【上六】处于节卦的最高位，象征着过度的节制或苦行。坚持这种极端的节制会导致凶险，但如果能反思并调整，悔恨可以消除。这提示人们在节制的同时，也要注意适度，避免走向极端。"},
  {"id":"an_dk_899","sentenceId":"s_dk_899","level":"sentence","content":"【智慧】这句话出自《易经》中的小象辞，意为不需出门，就能知道事情的通达与阻塞。这体现了通过内在的智慧和洞察力，可以了解外界的情况，无需亲身经历或亲眼所见。"},
  {"id":"an_dk_900","sentenceId":"s_dk_900","level":"sentence","content":"【隱居】这句话出自《易经》中的小象辞，意为不走出家门，错过了时机，达到了极端。这里“不出门庭”象征着隐居或不参与外界事务，而“失时极也”则表示因为隐居而错过了适当的时机，达到了极端的状态。"},
  {"id":"an_dk_901","sentenceId":"s_dk_901","level":"sentence","content":"【悔恨】这句话的意思是，因为没有节制而产生的叹息和悔恨，这种结果只能归咎于自己。这表示一个人如果不能自我约束，导致了不良的后果，那么责任只能由自己承担。"},
  {"id":"an_dk_902","sentenceId":"s_dk_902","level":"sentence","content":"【吉祥】此句小象辞意为在保持节制和谦逊的态度下，能够获得亨通，这是因为遵循了上天的正道。表明行事应当有所节制，不可过度，这样才能得到好的结果。"},
  {"id":"an_dk_903","sentenceId":"s_dk_903","level":"sentence","content":"【中庸】此句出自《周易》中的小象辞，意为甘于节制而获得吉祥，是因为处于中庸的位置。中庸之道主张不偏不倚，适得其中，是一种理想的行为准则。在这里，甘于节制的行为符合中庸之道，因此能够带来吉祥的结果。"},
  {"id":"an_dk_904","sentenceId":"s_dk_904","level":"sentence","content":"【凶险】坚守苦行和节操到了极端，会导致凶险，因为这种做法已经走到了尽头，无法持续。"},
  {"id":"an_dk_905","sentenceId":"s_dk_905","level":"sentence","content":"【吉兆】中孚卦象征诚信，卦辞中的“豚鱼吉”意味着即使是像豚鱼这样微小的事物也能得到吉祥，表示诚信可以感化万物。\"利涉大川\"则表示在诚信的基础上，可以顺利渡过难关，克服重大障碍。\"利贞\"则强调了在诚信的基础上，坚持正道，保持贞洁，会有利于事情的发展。整体来看，这是一个吉兆，预示着只要保持诚信，坚持正道，就能获得吉祥，克服困难。"},
  {"id":"an_dk_906","sentenceId":"s_dk_906","level":"sentence","content":"【中孚】中孚卦象征诚信。内卦为兑（泽），外卦为巽（风），兑为柔，巽为刚，柔在内而刚得中，象征内心柔顺而外表刚毅。兑为喜悦，巽为顺从，喜悦而顺从，象征诚信可以感化邦国。豚鱼吉，表示诚信可以普及到最微小的事物，如豚鱼。利涉大川，象征诚信可以克服大的困难，如乘木舟虚渡过大河。中孚以利贞，表示诚信应当以正直为本，才能应乎天道。"},
  {"id":"an_dk_907","sentenceId":"s_dk_907","level":"sentence","content":"【哲學與倫理】此句出自《周易》中的中孚卦。中孚卦的象辞描述了泽上有风的情景，象征着诚信与和顺。君子观此象，应当以宽厚之心对待狱讼，慎重考虑生死判决，体现出对生命的尊重和对公正的追求。这反映了古代中国哲学中重视道德伦理和人文关怀的思想。"},
  {"id":"an_dk_908","sentenceId":"s_dk_908","level":"sentence","content":"【吉凶】初九爻辞中的“虞吉”意味着在安详、平静的状态下是吉祥的；“有它不燕”则表示如果有其他事情发生，则不能安享宁静。整体而言，此爻辞强调在没有外界干扰的情况下，保持内心的平静和安详是吉祥的，但若出现变故，则需要警惕，不可过于安逸。"},
  {"id":"an_dk_909","sentenceId":"s_dk_909","level":"sentence","content":"【吉】此爻辞描绘了一幅和谐美好的景象，鹤在树荫下鸣叫，其子随之应和，象征着上下和睦、父子相亲。后半句“我有好爵，吾与尔靡之”则表达了主人愿意与他人共享美好事物的心愿，意味着拥有财富或地位的人愿意与他人分享，共同享受。整体上，此爻辞预示着吉祥和谐的局面。"},
  {"id":"an_dk_910","sentenceId":"s_dk_910","level":"sentence","content":"【冲突與变化】此爻辞描述了一种处于敌对或竞争状态的情境，其中充满了不确定性和情绪的波动。\"得敌\"表示遇到了对手或困难，\"或鼓或罢\"意味着在面对挑战时，可能会选择积极应对（鼓）或选择放弃（罢）。\"或泣或歌\"则反映了在这种不确定的情况下，情绪可能会从悲伤（泣）转变为喜悦（歌），或者反之。整体上，这爻辞强调了在冲突中情绪和态度的变化无常，以及如何应对这些变化的重要性。"},
  {"id":"an_dk_911","sentenceId":"s_dk_911","level":"sentence","content":"【時運/变動】六四爻辞中的“月几望”意味着月亮接近满月，象征着事物接近顶峰或成熟阶段，但尚未达到极致。此时，可能会出现一些小的变动或损失，如“马匹亡”所示，但这并不会带来大的灾难或咎责，即“无咎”。整体上，这一爻辞提示人们在接近成功或目标时，要保持谨慎，注意小的变动，但不必过于担忧，因为这些变动不会对大局产生负面影响。"},
  {"id":"an_dk_912","sentenceId":"s_dk_912","level":"sentence","content":"【吉兆】九五爻辞表示诚信和紧密的联系，没有灾难。这一爻象征着领导者的诚信和团结，能够获得他人的信任和支持，从而避免了可能的灾难。在实际应用中，意味着只要保持诚信和紧密的合作关系，就能克服困难，达到成功。"},
  {"id":"an_dk_913","sentenceId":"s_dk_913","level":"sentence","content":"【上九】上九爻辞“翰音登于天，贞凶”意味着高位者的言论或行为过于高调，虽然表面上看起来很辉煌，但实质上却可能带来凶险。这里的“翰音”指的是高亢的声音，象征着高位者的言论或行为；“登于天”则表示这种言论或行为达到了极高的程度，几乎到了不可控制的地步。然而，这种高调的行为往往会导致失去根基，最终带来凶险的结果。因此，此爻辞告诫人们在高位时要保持谦逊，不要过于张扬，以免招致灾祸。"},
  {"id":"an_dk_914","sentenceId":"s_dk_914","level":"sentence","content":"【吉兆】初九爻辞中的“虞吉”意味着在初始阶段，通过谨慎和计划可以得到吉祥的结果。而“志未变也”则表示在这个过程中，保持初心和目标不变是非常重要的。整体来看，这条爻辞鼓励在行动之初保持坚定的意志和正确的方向，这样就能获得好的结果。"},
  {"id":"an_dk_915","sentenceId":"s_dk_915","level":"sentence","content":"【家庭和諧】这句话表达了家庭成员之间的和睦相处，特别是子女能够与父母或家庭成员和谐共处，这是家庭幸福的核心愿望。"},
  {"id":"an_dk_916","sentenceId":"s_dk_916","level":"sentence","content":"【决策猶豫】此句小象辞意指在决策时处于犹豫不决的状态，可能是因为所处的位置或环境并不适合做出明确的决定，或者决策者自身的能力和地位不足以应对当前的局势。在这种情况下，既可以采取行动（鼓），也可以选择不采取行动（罢），但都需要谨慎考虑。"},
  {"id":"an_dk_917","sentenceId":"s_dk_917","level":"sentence","content":"【凶兆】此句小象辞意为马匹死亡，象征着同类中的上等者也遭遇了绝境。这是一种不吉利的预兆，暗示着可能会有重要的损失或不幸的事情发生。"},
  {"id":"an_dk_918","sentenceId":"s_dk_918","level":"sentence","content":"【正固】此句小象辞“有孚挛如，位正当也”出自《周易》。其中，“有孚”表示诚信、信任，“挛如”形容紧密相连、团结一致的状态，“位正当也”则指所处的位置恰当、合适。整体含义为：因为诚信和团结，所以处于正当的位置，象征着正直稳固的状态。"},
  {"id":"an_dk_919","sentenceId":"s_dk_919","level":"sentence","content":"【警示】这句话出自《周易》的象辞，意为高声呼唤的声音传到了天上，但这种声音不可能长久持续。这里用来警示人们，任何过分张扬、高调的行为都难以持久，应当保持谦逊和低调。"},
  {"id":"an_dk_920","sentenceId":"s_dk_920","level":"sentence","content":"【小過】小过卦象征着小事亨通，利于坚守正道。在小事上可以有所作为，但在大事上则不宜轻举妄动。如同飞鸟留下声音，提示我们不宜向上追求过高目标，而应向下关注基础和根本，这样可以获得大的吉祥。"},
  {"id":"an_dk_921","sentenceId":"s_dk_921","level":"sentence","content":"【小過】小过卦象征着小事过度而亨通。过度的行为应当利于正直，顺应时势而行。柔爻居中，因此在小事上吉利。刚爻失位且不居中，因此不适合处理大事。卦象中有飞鸟的象征，飞鸟留下声音，不宜向上飞而宜向下飞，大吉；向上飞则违背时势，向下飞则顺应时势。"},
  {"id":"an_dk_922","sentenceId":"s_dk_922","level":"sentence","content":"【象辭】此句出自《周易》小过卦的象辞。象辞是对卦象的象征意义进行解释的文字。小过卦的上卦为震（雷），下卦为艮（山），象征着山上有雷。君子观此象，应当效法其精神，在行为上过于恭敬，在丧事上过于哀伤，在使用上过于节俭，以此来修身养性，避免过失。"},
  {"id":"an_dk_923","sentenceId":"s_dk_923","level":"sentence","content":"【凶险】初六爻辞中的“飞鸟以凶”意味着事物处于初始阶段，就像鸟儿刚起飞时容易遭遇危险，暗示着行动或计划在开始时可能会遇到不利的情况或遭遇挫折。此爻提示人们在新事物的起步阶段要谨慎行事，注意潜在的风险。"},
  {"id":"an_dk_924","sentenceId":"s_dk_924","level":"sentence","content":"【吉凶】六二爻辞描述了一种超越常规的情况，即“过其祖，遇其妣；不及其君，遇其臣”。这表示在某些情况下，可以超越前辈（祖）而遇到先辈（妣），但不能达到君主的高度，只能遇到臣子。这种情况下，虽然有一定的局限性，但并不会带来灾祸，即“无咎”。整体来看，此爻辞表达了一种在特定情境下的适度超越和适应，不会招致不利的结果。"},
  {"id":"an_dk_925","sentenceId":"s_dk_925","level":"sentence","content":"【警示】九三爻辞的意思是，不要过分地去防范别人，如果过分地防范，可能会导致跟随你的人产生怨恨，甚至可能会有人加害于你，这样就会有凶险。这说明了在处理人际关系时，应该保持适度的信任，不要过度防范，否则可能会适得其反。"},
  {"id":"an_dk_926","sentenceId":"s_dk_926","level":"sentence","content":"【謹慎行事】九四爻辞表明在这一位置上，虽然没有过失，但也不可过于自信或轻率。与人交往时应保持谨慎，避免不必要的冲突或危险。若要前行，必须提高警惕，不可轻举妄动。在这一阶段，不宜做出长期的决定或承诺，应当保持灵活，随时准备应对可能出现的变化。"},
  {"id":"an_dk_927","sentenceId":"s_dk_927","level":"sentence","content":"【自然現象與行動】爻辞描述了一种自然现象与人的行动相结合的情景。\"密云不雨\"表示天空乌云密布但没有下雨，暗示了一种压抑或期待的状态；\"自我西郊\"表明这种现象发生在自己的西郊，可能暗示了某种特定的环境或背景；\"公弋取彼在穴\"则描述了公侯用弋（一种带有绳子的箭）捕猎藏在洞穴中的动物，这可能象征着在困境中采取行动或解决问题的方式。整体来看，爻辞可能寓意在面对困境或挑战时，需要采取积极的行动来解决问题。"},
  {"id":"an_dk_928","sentenceId":"s_dk_928","level":"sentence","content":"【凶险】上六爻辞描述了一种不吉利的情况，即没有遇到好的时机或人，反而遭遇了过失或错误，如同飞鸟不慎触网，结果非常凶险，预示着灾难或不幸的发生。这表明在当前的情境下，行动或决策可能会带来负面的后果，需要谨慎对待。"},
  {"id":"an_dk_929","sentenceId":"s_dk_929","level":"sentence","content":"【凶险】此句小象辞意指飞鸟遭遇凶险，象征着事情发展遇到了不可逆转的困难或危险，提醒人们在面对类似情况时，应当谨慎行事，避免强行推进，以免造成更大的损失。"},
  {"id":"an_dk_930","sentenceId":"s_dk_930","level":"sentence","content":"【人际關系】这句话出自《易经》中的小象辞，意思是说在君主面前，臣子的行为和言语不能超过君主。这反映了古代社会中君臣之间的等级关系和行为规范，强调了臣子应当保持谦逊，不可僭越君主的权威。在现代语境中，可以理解为在上下级关系中，下级应当尊重上级，不可越权行事。"},
  {"id":"an_dk_931","sentenceId":"s_dk_931","level":"sentence","content":"【凶险】此句意为，如果有人伤害小象，那么凶险将会如何降临。这表示如果对弱小者施加伤害，将会招致不好的后果，预示着凶险。"},
  {"id":"an_dk_932","sentenceId":"s_dk_932","level":"sentence","content":"【警示】此句出自《周易》中的小象辞，意为不要过分追求不切实际的机遇，因为所处的位置并不适合。如果一意孤行，将会遇到危险，必须警惕，这样的情况最终是不能长久的。这是一条警示性的建议，提醒人们要量力而行，不可盲目冒进。"},
  {"id":"an_dk_933","sentenceId":"s_dk_933","level":"sentence","content":"【自然現象】这句话出自《易经》中的小象辞，意为天空密布乌云却不下雨，象征着事情已经到了一定的程度或阶段，但还没有产生实际的结果或影响。这里的“已上”表示事情已经达到了某个高度或阶段。"},
  {"id":"an_dk_934","sentenceId":"s_dk_934","level":"sentence","content":"【不利】此句出自《周易》的象辞，意为没有遇到应当遇到的人或事，已经到了极端不利的地步。说明当前的形势非常不利，可能是因为错过了最佳时机或因为自身的位置已经过高而无法继续前进。"},
  {"id":"an_dk_935","sentenceId":"s_dk_935","level":"sentence","content":"【完成與变亂】既济卦象征事物已经完成或成功，亨通但只在小事上利于坚持正道。开始时吉祥，但最终可能会出现混乱。此卦提醒人们在成功之后不可掉以轻心，应继续保持谨慎和正直，以防变乱的发生。"},
  {"id":"an_dk_936","sentenceId":"s_dk_936","level":"sentence","content":"【既濟卦】既济卦象征事物已经完成或成功。亨通，但仅限于小事亨通。利于坚守正道，因为刚柔相济且各爻位置恰当。开始时吉祥，因为柔爻居中。但如果终止不前，则会导致混乱，其道路将走到尽头。"},
  {"id":"an_dk_937","sentenceId":"s_dk_937","level":"sentence","content":"【預防】此句出自《周易》的象辞，描述的是水在火上的既济卦象，象征事物已经成功或完成的状态。但即便是在成功之时，君子也应当居安思危，思考可能发生的祸患并提前做好防范措施，以确保长久的稳定与安全。"},
  {"id":"an_dk_938","sentenceId":"s_dk_938","level":"sentence","content":"【謹慎行事】初九爻辞中的“曳其轮，濡其尾”形象地描述了在行动时应当小心谨慎，不要急于求成。如同车轮被拖住，狐狸的尾巴被水打湿，暗示在行动中遇到了阻碍或困难，但只要保持谨慎，不轻举妄动，就能够避免灾祸，因此“无咎”。这表明在面对困难时，应当采取稳健的态度，避免冒进，以确保安全。"},
  {"id":"an_dk_939","sentenceId":"s_dk_939","level":"sentence","content":"【家庭與婚姻】六二爻辞描述了一个妇女失去了她的茀（古代妇女佩戴的一种装饰品），但不必去追寻，七天后会失而复得。这象征着在家庭或婚姻中，有时会遇到一些小的损失或困扰，但不必过于焦虑或采取过激行动，因为这些问题往往会自行解决，恢复平静。"},
  {"id":"an_dk_940","sentenceId":"s_dk_940","level":"sentence","content":"【戰爭與决策】此爻辞描述了高宗（商朝的君主）讨伐鬼方（古代的一个部落）的战争，经过三年的时间最终取得了胜利。爻辞中的“小人勿用”意味着在进行重大决策或战争时，应谨慎选择助手和顾问，避免任用那些品行不端或能力不足的人。这反映了在关键时刻，领导者的决策和团队的选择至关重要。"},
  {"id":"an_dk_941","sentenceId":"s_dk_941","level":"sentence","content":"【謹慎】六四爻辞中的“繻有衣袽，终日戒”意味着在处理事情时要保持高度的警觉和谨慎。这里的“繻有衣袽”比喻虽然外表看似光鲜，但内部可能存在问题，需要时刻保持警惕，不可掉以轻心。“终日戒”则强调了这种谨慎的态度需要贯穿始终，不可有一刻松懈。整体而言，这一爻辞提醒人们在面对复杂多变的环境时，要保持清醒的头脑，谨慎行事，以防不测。"},
  {"id":"an_dk_942","sentenceId":"s_dk_942","level":"sentence","content":"【吉凶】此爻辞意在说明，真正的福气并不在于外在的盛大仪式或物质的丰厚，而在于内心的真诚与实际的德行。东邻虽然杀牛举行盛大的祭祀，但不如西邻以简朴的禴祭（春祭）来表达真诚的心意，后者反而得到了真正的福报。这表明，真诚的态度和实际的行动比形式上的奢华更为重要。"},
  {"id":"an_dk_943","sentenceId":"s_dk_943","level":"sentence","content":"【凶险】上六爻辞“濡其首，厉”意味着处于最高位的人或事物，其头部（象征领导或核心部分）被水所濡湿，象征着面临严重的危机或危险。这通常表示决策者或领导者在处理事务时遇到了极大的困难，可能是因为过度自信、决策失误或环境的不利影响，导致自身陷入了危险的境地。此爻辞告诫人们在高位时要谨慎行事，避免因轻率或疏忽而招致灾祸。"},
  {"id":"an_dk_944","sentenceId":"s_dk_944","level":"sentence","content":"【無咎】此句意为虽然行动有所阻碍（曳其轮），但行为合乎道义，因此不会招致灾祸或咎责。在《易经》中，“无咎”通常表示行为虽然不完全顺利，但因为合乎正道，所以不会有不良后果。"},
  {"id":"an_dk_945","sentenceId":"s_dk_945","level":"sentence","content":"【時間】此句意为在七天内能够获得所求，是因为行事符合中庸之道，不偏不倚，恰到好处。"},
  {"id":"an_dk_946","sentenceId":"s_dk_946","level":"sentence","content":"【困難與挑戰】此句小象辞意指经过三年的努力才克服了困难，达到了目标，但过程中非常疲惫。这表明在实现目标的过程中遇到了长期且艰巨的挑战，需要坚持不懈的努力才能最终成功。"},
  {"id":"an_dk_947","sentenceId":"s_dk_947","level":"sentence","content":"【謹慎】这句话意味着在一天中始终保持警觉和谨慎，因为心中有所疑虑。这表明在面对不确定的情况时，需要保持高度的警惕，以免犯错或遭受损失。"},
  {"id":"an_dk_948","sentenceId":"s_dk_948","level":"sentence","content":"【吉】此辞意为东边的邻居杀牛祭祀，不如西边的邻居适时而行。实际上，西邻因此受到了福报，预示着大的吉祥将至。这说明做事要顺应时宜，才能获得好的结果。"},
  {"id":"an_dk_949","sentenceId":"s_dk_949","level":"sentence","content":"【凶险】这句话出自《周易》的《噬嗑》卦，意思是“濡湿了头，有危险，怎么可以长久呢？”这里描述的是一种处于危险境地，难以持久的状态，提示人们在面临类似情况时，应当及时调整策略，避免长期处于不利的环境中。"},
  {"id":"an_dk_950","sentenceId":"s_dk_950","level":"sentence","content":"【未完成/小成】未济卦象征事情尚未完成，但仍有亨通的可能。卦辞中的“小狐汔济，濡其尾，无攸利”比喻在事情接近成功时，若过于急躁或轻率，可能会导致前功尽弃，如同小狐狸过河时，因急于求成而打湿了尾巴，最终无利可图。此卦提示我们在接近目标时应保持谨慎，不可掉以轻心。"},
  {"id":"an_dk_951","sentenceId":"s_dk_951","level":"sentence","content":"【未濟卦】未济卦象征事情尚未完成，但亨通；因为柔爻居中位。小狐狸几乎渡过河，但未能完全脱离危险。尾巴被水打湿，没有好处；因为不能坚持到底。虽然各爻位置不当，但刚爻与柔爻相互呼应。"},
  {"id":"an_dk_952","sentenceId":"s_dk_952","level":"sentence","content":"【卦象】此句出自《周易》中的未济卦。未济卦的卦象是火在水上，象征事物尚未完成，处于未济的状态。君子应当谨慎地辨别事物的性质，合理地安排和处置，以达到最终的完成和成功。"},
  {"id":"an_dk_953","sentenceId":"s_dk_953","level":"sentence","content":"【凶险】初六爻辞“濡其尾，吝”意味着在行动的开始阶段，如果过于急躁或轻率，就像尾巴被水打湿一样，会带来不利和困难。这提示我们在做事时要谨慎，不可冒进，以免陷入困境。"},
  {"id":"an_dk_954","sentenceId":"s_dk_954","level":"sentence","content":"【行動與調整】九二爻辞中的“曳其轮，贞吉”意味着在行动中需要适当调整方向或速度，保持正直和谨慎的态度，这样才会吉祥。具体来说，就像驾车时需要适时调整车轮的方向，以确保车辆平稳前行，避免偏离道路或发生危险。在实际生活中，这提示我们在面对问题或挑战时，要灵活应对，适时调整策略，同时保持正直和坚定的信念，这样才能取得好的结果。"},
  {"id":"an_dk_955","sentenceId":"s_dk_955","level":"sentence","content":"【凶险】六三爻处于未济卦中，象征事情尚未成功，处于不稳定的状态。爻辞中的“征凶”意味着此时如果贸然行动或出征，将会遭遇凶险。然而，“利涉大川”则表示在某些特定的情况下，如需要渡过大河，采取行动反而有利。这暗示在未济之时，应当谨慎行事，但也不可过于保守，遇到必须面对的挑战时，应果断行动。"},
  {"id":"an_dk_956","sentenceId":"s_dk_956","level":"sentence","content":"【吉兆】九四爻辞表示坚守正道则吉祥，悔恨将消失。象征着以雷霆万钧之势讨伐远方的敌人（鬼方），经过三年的艰苦努力，最终会得到大国的赏赐或认可。这预示着在面对困难和挑战时，只要坚持正义，勇往直前，最终能够取得胜利并获得荣誉。"},
  {"id":"an_dk_957","sentenceId":"s_dk_957","level":"sentence","content":"【吉祥】六五爻辞表示坚守正道则吉祥，没有悔恨，象征着君子的光辉，心怀诚信，最终会获得吉祥的结果。"},
  {"id":"an_dk_958","sentenceId":"s_dk_958","level":"sentence","content":"【吉凶併存】上九爻辞描述了一种充满信心和享受的状态，但同时也警告过度放纵可能导致的危险。爻辞中的“有孚于饮酒，无咎”意味着在信任和享受中没有过错，但紧接着的“濡其首，有孚失是”则表示如果过分沉溺，甚至头部都被濡湿，那么这种信任和自信就会失去其应有的价值和方向。整体来看，此爻辞强调了在享受和自信的同时，也要保持适度和警惕，避免因过度而带来的负面影响。"},
  {"id":"an_dk_959","sentenceId":"s_dk_959","level":"sentence","content":"【困頓】此句出自《易经》中的困卦，意为小象的尾巴被水濡湿，象征着行动受阻，处于困境之中，且未能认识到极限或边界，暗示着在困难中迷失方向，不知如何摆脱困境。"},
  {"id":"an_dk_960","sentenceId":"s_dk_960","level":"sentence","content":"【吉兆】九二爻辞表示坚守正道会带来吉祥的结果，处于中位能够行正道。这意味着在决策和行动中保持中庸和正直的态度，能够获得好的结果。"},
  {"id":"an_dk_961","sentenceId":"s_dk_961","level":"sentence","content":"【不利】此句出自《周易》未济卦，意指在未济卦的征兆下，行动会有凶险，因为所处的位置不适当。未济卦象征事情尚未完成，处于不稳定的状态，此时如果贸然行动，可能会遭遇不利的局面。"},
  {"id":"an_dk_962","sentenceId":"s_dk_962","level":"sentence","content":"【吉兆】此辞表示占卜的结果是吉祥的，没有悔恨，意味着所求之事能够顺利进行，志向可以实现。"},
  {"id":"an_dk_963","sentenceId":"s_dk_963","level":"sentence","content":"【吉祥】这句话出自《周易》的象辞，意为君子的光辉如同阳光普照，能够带来吉祥和福祉。这里的“君子之光”象征着品德高尚的人所散发出的正面影响力，能够照亮周围的人和事，带来吉祥的结果。"},
  {"id":"an_dk_964","sentenceId":"s_dk_964","level":"sentence","content":"【過度】这句话出自《周易》的象辞，描述了饮酒过度以至于头部都被酒液沾湿，比喻人做事没有节制，过度放纵自己。"}
];

export const dkOverrides: Record<string, Record<string, [string, string, string]>> = {};
